import * as OSB from './bridge.js';
/* ---------- Renovion OS: de staat komt van de server, de gebruiker is wie er ingelogd is ---------- */
const OS_STATE = await OSB.boot();
const ME = OSB.me.person || '';
const ME_ROL = OSB.me.rol || 'Uitvoerder';
const ME_NAME = OSB.me.naam || '';
const IS_EXTERNAL = ME_ROL==='Klant'||ME_ROL==='Onderaannemer';
const CAN_PREVIEW = ME_ROL==='Superadmin'||ME_ROL==='Directie';
function myName(){ const e=S&&S.emps&&S.emps.find(x=>x.id===ME); return (e&&e.naam)||ME_NAME||'Renovion'; }
function myFirst(){ return myName().split(' ')[0]; }
function osPeople(){ return [...(S.emps||[]),...(S.extraUsers||[])].filter(x=>x.status!=='gedeactiveerd'); }
function rolNaam(r){ if(r===ME_ROL) return myName(); const e=osPeople().find(x=>x.sysrol===r); return e?e.naam:r; }
function osActor(){ const r=curRol(); if(r===ME_ROL) return ME; const e=osPeople().find(x=>x.sysrol===r); return e?e.id:ME; }
function whoRole(...roles){ for(const r of roles){ const e=(S.emps||[]).find(x=>x.sysrol===r&&x.status!=='gedeactiveerd'); if(e) return e.id; } return ME; }
const osSales=()=>whoRole('Sales','Directie','Superadmin');
const osCalc=()=>whoRole('Calculator','Directie','Superadmin');
const osWvb=()=>whoRole('Werkvoorbereider','Projectleider','Directie','Superadmin');
const osPL=()=>whoRole('Projectleider','Directie','Superadmin');
const osInkoop=()=>whoRole('Inkoper','Werkvoorbereider','Directie','Superadmin');
const osField=()=>((S.emps||[]).find(e=>e.type!=='kantoor'&&e.status!=='gedeactiveerd')||{}).id||ME;
const osOwner=p=>{ const e=emp(p.leider); return e&&e.type==='kantoor'?p.leider:(p.sales||osSales()); };
function odVk(){ return (S.emps||[]).filter(e=>['Sales','Directie','Superadmin','Calculator'].includes(e.sysrol)).map(e=>e.id); }
/* Een klant ziet zijn eigen project (scope), een onderaannemer zijn eigen bedrijf. */
function osMyProject(){ const u=(S.extraUsers||[]).find(x=>x.id===ME)||(S.emps||[]).find(x=>x.id===ME); const pid=u&&u.scope&&String(u.scope).startsWith('PD-')?u.scope:''; return proj(pid)||S.projects.find(p=>p.phase>=4)||S.projects[0]; }
function osMySub(){ const me=(S.emps||[]).find(e=>e.id===ME); const s=(S.subs||[]).find(x=>x.id===ME||x.empId===ME||(me&&x.mail&&me.mail&&String(x.mail).toLowerCase()===String(me.mail).toLowerCase())); return s?s.id:''; }
