/* ---------- Helpers ---------- */
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EUR = new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR'});
const EUR0 = new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const NUM = new Intl.NumberFormat('nl-NL',{maximumFractionDigits:2});
const eur = v => EUR.format(Math.round((v||0)*100)/100);
const eur0 = v => EUR0.format(v||0);
const pct = (v,d=1) => (isFinite(v)?v:0).toLocaleString('nl-NL',{minimumFractionDigits:d,maximumFractionDigits:d})+'%';
const r2 = v => Math.round(v*100)/100;
const D = s => new Date(s+'T12:00:00');
const iso = d => { const z=n=>String(n).padStart(2,'0'); return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}`; };
const addDays = (s,n) => { const d=D(s); d.setDate(d.getDate()+n); return iso(d); };
const diffDays = (a,b) => Math.round((D(b)-D(a))/864e5);
const monday = s => { const d=D(s); const w=(d.getDay()+6)%7; d.setDate(d.getDate()-w); return iso(d); };
const fmtD = s => s ? D(s).toLocaleDateString('nl-NL',{day:'numeric',month:'short'}) : '—';
const fmtDL = s => D(s).toLocaleDateString('nl-NL',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const fmtDY = s => s ? D(s).toLocaleDateString('nl-NL',{day:'numeric',month:'short',year:'numeric'}) : '—';
const dayName = s => D(s).toLocaleDateString('nl-NL',{weekday:'short'});
const isWeekend = s => { const g=D(s).getDay(); return g===0||g===6; };
const workdays = (a,b) => { let n=0; for(let s=a; s<=b; s=addDays(s,1)) if(!isWeekend(s)) n++; return n; };
const uid = p => p+Math.random().toString(36).slice(2,8);
const cap = s => s.charAt(0).toUpperCase()+s.slice(1);
const AVC = ['#FF580A','#0D1B2E','#3767D6','#19875B','#7553D9','#C2410C','#2E9C9C','#B45309','#D9637C','#475569'];
function avatar(name, cls=''){ const n=name||'?'; const ini=n.split(/\s+/).filter(Boolean).map(w=>w[0]).slice(0,2).join('').toUpperCase(); let h=0; for(const c of n) h=(h*31+c.charCodeAt(0))>>>0; return `<span class="av ${cls}" style="background:${AVC[h%AVC.length]}" title="${esc(n)}">${esc(ini)}</span>`; }
function dueLabel(s){ if(!s) return '—'; const d=diffDays(TODAY,s); if(d===0) return '<span class="dn">Vandaag</span>'; if(d===1) return 'Morgen'; if(d<0) return `<span class="dn">Verlopen · ${fmtD(s)}</span>`; return fmtD(s); }

