/* ---------- Central calculations ---------- */
/* Rekenregels zijn identiek aan de begrotingstool (calcAll), zodat OS en tool altijd hetzelfde bedrag tonen. */
const parseNL = s => { s=String(s??'').trim().replace(/[\s€%]/g,''); if(!s) return 0; if(s.includes(',')) s=s.replace(/\./g,'').replace(',','.'); const n=parseFloat(s); return isNaN(n)?0:n; };
function calcLine(l,rate){
  const r=(l.r==null||l.r==='')?rate:+l.r, q=+l.q||0, uren=q*(+l.n||0);
  const c={uren,arbeid:uren*r,mat:q*(+l.m||0),mt:q*(+l.e||0),oa:q*(+l.o||0),ov:q*(+l.v||0)}; c.totaal=c.arbeid+c.mat+c.mt+c.oa+c.ov; return c;
}
const isLine = l => l && l.t!=='text';
const lineMissing = l => isLine(l) && (+l.q>0) && !(+l.n||+l.m||+l.e||+l.o||+l.v);
function eachLine(m,fn){ for(const ch of m.chapters||[]) for(const p of ch.pars||[]){ let i=0; for(const l of p.lines||[]){ if(!isLine(l)) continue; i++; fn(l,`${ch.code}${p.code}.${String(i).padStart(2,'0')}`,ch,p); } } }
function staartFactor(m){ let f=1; for(const s of m.staart||[]) f*=1+(+s.pct||0)/100; return f; }
function optPrice(o,m){ return (+o.q||0)*(+o.p||0)*staartFactor(m); }
function calcB(m){
  const rate=+m.rate||55, btwP=m.btw==null?21:+m.btw;
  const cat={arbeid:0,mat:0,mt:0,oa:0,ov:0}; let uren=0, regels=0, missing=0;
  const chapters=(m.chapters||[]).map(ch=>{ let t=0; for(const p of ch.pars||[]) for(const l of p.lines||[]){ if(!isLine(l)) continue; const c=calcLine(l,rate); t+=c.totaal; uren+=c.uren; cat.arbeid+=c.arbeid; cat.mat+=c.mat; cat.mt+=c.mt; cat.oa+=c.oa; cat.ov+=c.ov; regels++; if(lineMissing(l)) missing++; } return {nr:ch.code,naam:ch.name,totaal:t}; });
  const direct=cat.arbeid+cat.mat+cat.mt+cat.oa+cat.ov;
  let cum=0; const staart=(m.staart||[]).map(s=>{ const base=direct+cum, amt=base*(+s.pct||0)/100; cum+=amt; return {naam:s.name,pct:+s.pct||0,base,amt}; });
  const totalExcl=Math.round((direct+cum)*100)/100, btw=Math.round(totalExcl*btwP)/100;
  const opts=m.options||[]; const f=staartFactor(m);
  const meerwerk=opts.filter(o=>o.s==='akkoord').reduce((s,o)=>s+optPrice(o,m),0);
  const openOpt=opts.filter(o=>o.s==='optie');
  const bvo=parseNL(m.meta&&m.meta.bvo);
  return {chapters,cat,direct,uren,regels,missing,staart,staartTot:cum,totalExcl,btw,btwP,totalIncl:totalExcl+btw,meerwerk,openOpt,openOptSum:openOpt.reduce((s,o)=>s+optPrice(o,m),0),f,
    marge: totalExcl?(totalExcl-direct)/totalExcl*100:0, opslagPct: direct?(totalExcl-direct)/direct*100:0, bvo, perM2: bvo?totalExcl/bvo:0};
}
const margeFromOpslag = o => o/(100+o)*100;
const opslagFromMarge = m => m>=100?Infinity:m/(100-m)*100;

