const empName = id => (emp(id)||{naam:'—'}).naam;
const firstName = id => empName(id).split(' ')[0];
function projectValue(p){ if(p.offerte&&p.offerte.status==='geaccepteerd'){ return p.offerte.basis + (p.begroting?calcB(p.begroting).meerwerk:0); } if(p.begroting) return calcB(p.begroting).totalExcl; return p.waarde||0; }
function projectFin(p){
  const inv=S.invoices.filter(i=>i.pid===p.id);
  const gefact=inv.filter(i=>i.status!=='concept').reduce((s,i)=>s+i.bedrag,0);
  const betaald=inv.filter(i=>i.status==='betaald').reduce((s,i)=>s+i.bedrag,0);
  const val=projectValue(p); const begroot = p.begroting? calcB(p.begroting).direct : val*0.82;
  const pc=paCommitments(p.id); // gegunde partnerprijzen: verplichting + verschil met budget
  const verwachtKost = Math.max(begroot+pc.delta, (p.kosten||0) + begroot*(1-(p.progress||0)/100) + pc.delta);
  return {val,gefact,betaald,open:gefact-betaald,begroot,werkelijk:p.kosten||0,verpl:pc.verpl,delta:pc.delta,uren:projHours(p.id),verwacht:verwachtKost,marge: val? (val-verwachtKost)/val*100 : 0, inv};
}
function conflicts(){
  const out=[]; const byEmp={};
  for(const b of S.blocks){ (byEmp[b.emp]=byEmp[b.emp]||[]).push(b); }
  for(const e in byEmp){ const arr=byEmp[e].slice().sort((a,b)=>a.start<b.start?-1:1);
    for(let i=0;i<arr.length;i++) for(let j=i+1;j<arr.length;j++){ const a=arr[i], b=arr[j]; if(b.start<=a.end && a.start<=b.end){ const s=a.start>b.start?a.start:b.start; out.push({emp:e,a,b,day:s}); } } }
  return out;
}
const confIds = () => { const s=new Set(); for(const c of conflicts()){ s.add(c.a.id); s.add(c.b.id);} return s; };
function attention(){
  const items=[];
  for(const p of S.projects){
    if(p.offerte&&p.offerte.status==='verzonden'&&diffDays(p.offerte.sent,TODAY)>=3) items.push({k:'or',icon:'file',t:`Offerte ${p.offerte.nr} wacht op opvolging`,s:`${client(p.clientId).naam} · al ${diffDays(p.offerte.sent,TODAY)} dagen geen reactie`,btn:'Bekijk',go:`project-${p.id.toLowerCase()}`,tab:'offerte'});
  }
  for(const i of S.invoices){ if(i.status==='verzonden'&&i.verval<TODAY){ const p=proj(i.pid); items.push({k:'bad',icon:'euro',t:`${i.termijn===0?'Aanbetaling':'Termijn '+(i.termijn+1)} ${p.naam} controleren`,s:`${i.nr} · ${eur(i.bedrag*1.21)} · vervallen op ${fmtD(i.verval)}`,btn:'Controleer',go:`project-${p.id.toLowerCase()}`,tab:'financien'}); } }
  const cf=conflicts(); if(cf.length){ const w=monday(cf[0].day); items.push({k:'bad',icon:'cal',t:`Planning heeft ${cf.length} ${cf.length===1?'conflict':'conflicten'}`,s:`${[...new Set(cf.map(c=>firstName(c.emp)))].join(' en ')} dubbel ingepland`,btn:'Oplossen',go:'planning',week:w}); }
  const od=S.tasks.filter(t=>t.status!=='afgerond'&&t.dl&&t.dl<TODAY); if(od.length) items.push({k:'or',icon:'checksq',t:`${od.length} ${od.length===1?'taak':'taken'} over de deadline`,s:od.slice(0,2).map(t=>t.titel).join(', '),btn:'Bekijk',go:'taken'});
  for(const p of S.projects){ if(p.begroting){ const c=calcB(p.begroting); if(c.missing) items.push({k:'or',icon:'calc',t:`Begroting ${p.naam}: ${c.missing} ${c.missing===1?'regel mist':'regels missen'} een prijs`,s:p.begroting.nr,btn:'Open',go:`begroting-${p.id.toLowerCase()}`}); } }
  const unowned=S.tasks.filter(t=>t.status!=='afgerond'&&!t.eig); if(unowned.length) items.push({k:'mut',icon:'team',t:`${unowned.length} ${unowned.length===1?'taak':'taken'} zonder eigenaar`,s:unowned.map(t=>t.titel+' · '+(proj(t.pid)||{naam:''}).naam).join(', '),btn:'Toewijzen',go:'taken'});
  items.push(...r2Attention());
  return items;
}
function behind(){ return S.projects.filter(p=>p.phase===6 && p.planned-p.progress>=5); }
function addActivity(p,t,k='blue'){ p.activity.unshift({d:TODAY,t,k}); }
function toast(msg,kind='ok'){ const el=document.createElement('div'); el.className='toast '+(kind==='warn'?'warn':''); el.innerHTML=ic(kind==='warn'?'alert':'check')+`<div>${msg}</div>`; $('#toasts').appendChild(el); setTimeout(()=>el.remove(),4200); }
function commit(msg,kind){ save(); render(); if(msg) toast(msg,kind); }

/* ---------- Router ---------- */
const NAV = [
  {g:'Werkdag',items:[['vandaag','Vandaag','sun'],['aandeslag','Aan de slag','rocket'],['aandacht','Aandacht','alert'],['nova','Nova','spark']]},
  {g:'Commercieel',items:[['sales','Aanvragen & Sales','funnel'],['klanten','Klanten / CRM','users'],['m-intake','Intakes & Opnames','clip'],['calculaties','Calculaties','calc'],['m-prijslijst','Prijslijst','tag'],['offertes','Offertes','file']]},
  {g:'Projectmanagement',items:[['projecten','Projecten','folder'],['planning','Planning','cal'],['taken','Taken','checksq'],['werkbonnen','Werkbonnen','wrench'],['m-kwaliteit','Kwaliteit & Oplevering','badge']]},
  {g:'Workforce',items:[['workforce','Workforce','hard'],['onderaannemers','Onderaannemers','handshake'],['partner','Partner Portal','team'],['werkhub','Werkhub / Prijsaanvragen','store']]},
  {g:'Bedrijfsvoering',items:[['m-financieel','Financieel','chart'],['facturatie','Facturatie','receipt'],['m-inkoop','Inkoop','cart'],['m-documenten','Documenten','folder'],['m-marketing','Marketing','mega'],['m-rapportages','Rapportages','report']]},
  {g:'Organisatie',items:[['m-teamchat','Teamchat','chat'],['m-automations','Automations','bolt'],['m-teambeheer','Teambeheer','team'],['instellingen','Instellingen','gear']]},
];
/* ---------- Navigatie met echte adressen: /projecten, /project-pd-2026-0001 (het prototype gebruikte #projecten) ---------- */
const OS_NOT_APP=/^\/(os|inloggen|uitloggen|build|manifest\.webmanifest|storage|up)(\/|$)/;
function route(){ let p=location.pathname.replace(/^\/+|\/+$/g,''); try{ p=decodeURIComponent(p); }catch(e){} return p||'vandaag'; }
function osRouted(){ dispatchEvent(new HashChangeEvent('hashchange')); }
function go(r){ r=String(r||'').replace(/^[#/]+/,''); if(route()===(r||'vandaag')){ $('#side')?.classList.remove('open'); document.querySelector('.scrim')?.remove(); render(); return; } history.pushState(null,'','/'+r); osRouted(); }
window.addEventListener('popstate',()=>osRouted());
/* oude links met een hekje (#projecten) worden het echte adres */
if(/^#[a-z]/i.test(location.hash)) history.replaceState(null,'','/'+location.hash.slice(1));

window.addEventListener('hashchange',()=>{ $('#side').classList.remove('open'); document.querySelector('.scrim')?.remove(); const go=()=>{ render(); window.scrollTo(0,0); }; if(document.startViewTransition&&moOn()&&!document.querySelector('#layer .modal-bg')){ const vt=document.startViewTransition(go); vt.ready.catch(()=>{}); vt.finished.catch(()=>{}); } else go(); });

function renderSide(){
  const r=route(); const att=attention().length;
  const navKey = r.startsWith('project-')||r.startsWith('begroting-') ? 'projecten' : r.startsWith('werkbon-') ? 'werkbonnen' : r.startsWith('prijsaanvraag-') ? 'werkhub' : r;
  let h=`<a class="logo" href="/vandaag" aria-label="Renovion OS, één platform voor hele bouwprojecten">
    <svg viewBox="70 88 470 156" role="img"><path d="M117 205H80V136L140 99L200 136V152" fill="none" stroke="var(--orange)" stroke-width="7"/><text x="124" y="205" textLength="288" lengthAdjust="spacingAndGlyphs" font-family="Outfit, 'Plus Jakarta Sans', sans-serif" font-size="70" font-weight="500" fill="#FFFFFF">Renovion</text><text x="428" y="205" textLength="96" lengthAdjust="spacingAndGlyphs" font-family="Outfit, 'Plus Jakarta Sans', sans-serif" font-size="70" font-weight="700" fill="var(--orange)">OS</text><text x="128" y="236" font-family="'Plus Jakarta Sans', sans-serif" font-size="15" font-weight="500" textLength="396" lengthAdjust="spacing" fill="#A9B5C8">ÉÉN PLATFORM. HELE BOUWPROJECTEN.</text></svg></a><nav class="nav">`;
  for(const g of NAV){ const closed=UI.collapsed[g.g];
    h+=`<div class="ngroup ${closed?'closed':''}"><button data-act="ngroup" data-g="${g.g}">${g.g}${ic('down')}</button><div class="nitems">`;
    for(const [k,label,icn] of g.items){ const soon=k.startsWith('m-'); const cnt=k==='aandacht'&&att?`<span class="cnt">${att}</span>`:'';
      h+=`<a class="nitem ${navKey===k?'active':''}" ${k==='nova'?'data-act="nova" href="#"':`href="/${k}"`}>${ic(icn)}<span>${label}</span>${cnt}${soon?'<span class="soon">ronde 2</span>':''}</a>`; }
    h+=`</div></div>`; }
  h+=`</nav><div class="side-user">${avatar(myName())}<div><div class="nm">${esc(myName())}</div><div class="rl">${esc(ME_ROL)}</div></div><button data-act="usermenu" aria-label="Gebruikersmenu">${ic('gear')}</button></div>`;
  $('#side').innerHTML=h;
}

function render(){
  const r=route(); renderSide(); $('#demodate').textContent=cap(fmtDL(TODAY));
  if(r.startsWith('begroting-')){ const fr=$('#begframe'); if(fr&&fr.dataset.pid===r.slice(10).toUpperCase()&&!UI.begReload){ updBegBar(fr.dataset.pid); if(UI.novaOpen) renderNova(); return; } }
  $('#notifdot').hidden = !S.notifs.length;
  let v='';
  const r2v=r2Route(r);
  if(r2v!==null) v=r2v;
  else if(r==='vandaag') v=vVandaag();
  else if(r==='aandeslag') v=vAanDeSlag();
  else if(r==='aandacht') v=vAandacht();
  else if(r==='projecten') v=vProjecten();
  else if(r.startsWith('project-')) v=vProject(r.slice(8).toUpperCase());
  else if(r.startsWith('begroting-')) v=vBegroting(r.slice(10).toUpperCase());
  else if(r==='planning') v=vPlanning();
  else if(r==='taken') v=vTaken();
  else if(r==='sales') v=vSales();
  else if(r==='klanten') v=vKlanten();
  else if(r==='calculaties') v=vCalculaties();
  else if(r==='offertes') v=vOffertes();
  else if(r==='facturatie') v=vFacturatie();
  else if(r==='instellingen') v=vInstellingen();
  else if(r.startsWith('m-')) v=vModule(r);
  else v=vVandaag();
  $('#view').innerHTML=v;
  afterRender(r);
  if(UI.novaOpen) renderNova();
}

/* ---------- Views: Werkdag ---------- */
function greet(){ const h=new Date().getHours(); return h<12?'Goedemorgen':h<18?'Goedemiddag':'Goedenavond'; }
function vVandaag(){
  const active=S.projects.filter(p=>p.phase>=4&&p.phase<=7);
  const voorraad=active.reduce((s,p)=>s+projectValue(p),0);
  const uitv=S.projects.filter(p=>p.phase===6);
  const nieuw=S.projects.filter(p=>p.phase<=1);
  const openT=S.tasks.filter(t=>t.status!=='afgerond'); const hoog=openT.filter(t=>t.prio==='hoog');
  const att=attention(); const today=S.agenda.filter(a=>a.d===TODAY).sort((a,b)=>a.tijd<b.tijd?-1:1);
  const openOff=S.projects.filter(p=>p.offerte&&p.offerte.status==='verzonden');
  return `<div class="page">
  <div class="band"><img class="bimg" src="${HERO}" alt="" aria-hidden="true">
    <div class="btop"><div style="display:grid;gap:6px"><span class="eyebrow">${cap(fmtDL(TODAY))}</span><h1>${greet()}, <em>${esc(myFirst())}</em></h1><div class="rule"></div></div>
    <div class="acts"><button class="btn onnavy" data-act="newtask">${ic('plus')}Taak</button><button class="btn pri" data-act="newlead">${ic('plus')}Nieuwe aanvraag</button></div></div>
    <p>Van aanvraag tot nazorg, alles in één systeem. Vandaag ${att.length===1?'vraagt 1 punt':'vragen '+att.length+' punten'} je aandacht.</p></div>
  <div class="grid kpis">
    <div class="card kpi dark"><span class="lbl">Werkvoorraad excl. btw</span><span class="v num">${heur(voorraad)}</span><span class="s">${active.length} projecten in opdracht</span></div>
    <div class="card kpi"><span class="lbl">Lopende projecten</span><span class="v num">${active.length}</span><span class="s"><span class="up">${uitv.length}</span> in uitvoering</span></div>
    <div class="card kpi"><span class="lbl">Open offertes</span><span class="v num">${openOff.length}</span><span class="s">${eur0(openOff.reduce((s,p)=>s+projectValue(p),0))} openstaand</span></div>
    <div class="card kpi"><span class="lbl">Nieuwe aanvragen</span><span class="v num">${nieuw.length}</span><span class="s">${S.tasks.filter(t=>t.status!=='afgerond'&&!t.eig).length} nog niet toegewezen</span></div>
  </div>
  <div class="novahero"><div class="novaav">${ic('spark')}</div><div class="t"><h3>Nova · dagbriefing</h3><p>${novaBriefing()}</p></div><button class="btn soft" data-act="nova">Chat met Nova ${ic('chev')}</button></div>
  <div class="grid g-main">
    <div class="card"><div class="card-h"><h3>Acties die jouw <em>aandacht</em> vragen</h3><span class="pill bad">${att.length}</span></div><div class="card-b" style="padding-block:4px">
      ${att.length?att.map((a,i)=>`<div class="li"><span class="ic ${a.k}">${ic(a.icon)}</span><div class="tx"><b>${esc(a.t)}</b><small>${esc(a.s)}</small></div><button class="btn sm" data-act="att" data-i="${i}">${a.btn}</button></div>`).join(''):`<div class="empty">${ic('check')}Alles is bijgewerkt. Geen openstaande signalen.</div>`}
    </div></div>
    <div class="card"><div class="card-h"><h3>Snelle <em>acties</em></h3></div><div class="card-b stack">
      <button class="qa" data-act="newlead">${ic('plus')}Nieuwe aanvraag${ic('chev','chev')}</button>
      <button class="qa" data-act="newtask">${ic('checksq')}Taak aanmaken${ic('chev','chev')}</button>
      <button class="qa" data-act="newappt">${ic('cal')}Afspraak plannen${ic('chev','chev')}</button>
      <button class="qa" data-go="planning">${ic('team')}Team inplannen${ic('chev','chev')}</button>
      <button class="qa" data-go="begroting-pd-2026-0041">${ic('calc')}Begroting Badkamer Jansen${ic('chev','chev')}</button>
    </div></div>
  </div>
  <div class="grid g-main">
    <div class="card"><div class="card-h"><h3>Jouw <em>dag</em></h3><button class="btn sm ghost" data-act="newappt">${ic('plus')}Afspraak</button></div><div class="card-b" style="padding-block:4px">
      ${today.length?today.map(a=>`<div class="li"><b class="num" style="width:48px;flex:none">${a.tijd}</b><div class="tx"><b>${esc(a.titel)}</b><small>${esc(a.sub)}</small></div>${a.pid?`<button class="btn xs" data-go="project-${a.pid.toLowerCase()}">Dossier</button>`:''}</div>`).join(''):`<div class="empty">Geen afspraken vandaag.</div>`}
    </div></div>
    <div class="card"><div class="card-h"><h3>In <em>uitvoering</em></h3><a class="btn xs ghost" href="/projecten">Alle projecten</a></div><div class="card-b stack">
      ${uitv.map(p=>`<div style="cursor:pointer" data-go="project-${p.id.toLowerCase()}"><div class="row between"><b>${esc(p.naam)}</b><span class="num ${p.planned-p.progress>=5?'dn':'muted'}">${p.progress}%</span></div><div class="bar" style="margin-top:6px"><i style="width:${p.progress}%"></i></div><small class="muted">${esc(p.plaats)} · oplevering ${fmtD(p.eind)}${p.planned-p.progress>=5?' · loopt achter op planning':''}</small></div>`).join('')}
    </div></div>
  </div></div>`;
}
function novaBriefing(){
  const off=S.projects.filter(p=>p.offerte&&p.offerte.status==='verzonden'&&diffDays(p.offerte.sent,TODAY)>=3).length;
  const pay=S.invoices.filter(i=>i.status==='verzonden'&&i.verval<TODAY).length;
  const cf=conflicts(); const emps=[...new Set(cf.map(c=>c.emp))].length; const bh=behind().length;
  const parts=[]; if(off) parts.push(`${off===1?'één offerte wacht':off+' offertes wachten'} op opvolging`); if(pay) parts.push(`${pay===1?'een termijnfactuur is':pay+' termijnfacturen zijn'} over de vervaldatum`); if(emps) parts.push(`${emps} ${emps===1?'medewerker is':'medewerkers zijn'} dubbel ingepland`); if(bh) parts.push(`${bh} ${bh===1?'project loopt':'projecten lopen'} achter op planning`);
  if(!parts.length) return 'Alles loopt volgens plan. Er staan geen signalen open.';
  return `${parts.length} ${parts.length===1?'onderwerp vraagt':'onderwerpen vragen'} vandaag aandacht: ${parts.join(', ').replace(/, ([^,]*)$/,' en $1')}.`;
}
function vAanDeSlag(){
  const mine=S.tasks.filter(t=>t.eig===ME&&t.status!=='afgerond').sort((a,b)=>a.dl<b.dl?-1:1);
  return `<div class="page"><div class="ph"><div><h1>Aan de <em>slag</em></h1><p>Jouw eigen taken en afspraken, op volgorde van deadline.</p></div><button class="btn pri" data-act="newtask">${ic('plus')}Taak</button></div>
  <div class="grid g-main"><div class="card"><div class="card-h"><h3>Mijn taken</h3><span class="pill mut">${mine.length}</span></div>${taskTable(mine)}</div>
  <div class="card"><div class="card-h"><h3>Komende afspraken</h3></div><div class="card-b" style="padding-block:4px">${S.agenda.filter(a=>a.d>=TODAY).sort((a,b)=>(a.d+a.tijd)<(b.d+b.tijd)?-1:1).map(a=>`<div class="li"><span class="ic blue">${ic('cal')}</span><div class="tx"><b>${esc(a.titel)}</b><small>${a.d===TODAY?'Vandaag':cap(dayName(a.d))+' '+fmtD(a.d)} · ${a.tijd} · ${esc(a.sub)}</small></div></div>`).join('')}</div></div></div></div>`;
}
function vAandacht(){
  const att=attention();
  return `<div class="page"><div class="ph"><div><h1><em>Aandacht</em></h1><p>Signalen die Nova en de automations uit alle modules verzamelen. Ze verdwijnen zodra de oorzaak is opgelost.</p></div></div>
  <div class="card"><div class="card-b" style="padding-block:4px">${att.length?att.map((a,i)=>`<div class="li"><span class="ic ${a.k}">${ic(a.icon)}</span><div class="tx"><b>${esc(a.t)}</b><small>${esc(a.s)}</small></div><button class="btn sm" data-act="att" data-i="${i}">${a.btn}</button></div>`).join(''):`<div class="empty">${ic('check')}Geen signalen.</div>`}</div></div></div>`;
}

/* ---------- Projects ---------- */
function phasePill(p){ const i=p.phase; const cls=i<=3?'vio':i<=5?'blue':i===6?'or':i===7?'warn':'ok'; return `<span class="pill ${cls}"><span class="d"></span>${PHASES[i]}</span>`; }
function vProjecten(){
  const f=UI.projFilter||'alle';
  const list=S.projects.filter(p=>f==='alle'||(f==='sales'&&p.phase<=3)||(f==='voorb'&&(p.phase===4||p.phase===5))||(f==='uitv'&&p.phase===6)||(f==='afgerond'&&p.phase>=7));
  const tabs=[['alle','Alle'],['sales','Commercieel'],['voorb','Voorbereiding'],['uitv','Uitvoering'],['afgerond','Oplevering en nazorg']];
  return `<div class="page"><div class="ph"><div><h1>Project<em>dossiers</em></h1><p>Elk project is één dossier, van aanvraag tot nazorg.</p></div><button class="btn pri" data-act="newlead">${ic('plus')}Nieuw projectdossier</button></div>
  <div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${f===k?'on':''}" data-act="projf" data-f="${k}">${l}</button>`).join('')}</div>
  <div class="grid g3">${list.map(p=>{ const fin=projectFin(p); return `<div class="card pcard" data-go="project-${p.id.toLowerCase()}">
    <div class="row between"><span class="id">${p.id}</span>${phasePill(p)}</div>
    <div><h4>${esc(p.naam)}</h4><span class="muted">${esc(client(p.clientId).naam)} · ${esc(p.plaats)}</span></div>
    <div class="row between"><span class="muted">${esc(p.type)}</span><b class="num">${eur0(fin.val)}</b></div>
    ${p.phase>=5?`<div><div class="row between" style="font-size:12px"><span class="muted">Voortgang</span><span class="num">${p.progress}%</span></div><div class="bar" style="margin-top:4px"><i style="width:${p.progress}%"></i></div></div>`:`<div class="row" style="font-size:12px">${avatar(empName(p.leider),'sm')}<span class="muted">${esc(empName(p.leider))}</span></div>`}
  </div>`;}).join('')}</div></div>`;
}
const PD_TABS=[['overzicht','Overzicht'],['intake','Aanvraag & intake'],['begroting','Begroting'],['offerte','Offerte'],['planning','Planning'],['taken','Taken'],['werkbonnen','Werkbonnen'],['inkoop','Inkoop & partners'],['financien','Financiën'],['documenten','Documenten'],['activiteiten','Activiteiten']];
function vProject(id){
  const p=proj(id); if(!p) return `<div class="page"><div class="empty">Projectdossier ${esc(id)} niet gevonden. <a class="btn" href="/projecten">Naar projecten</a></div></div>`;
  const c=client(p.clientId); const tab=UI.pdTab[id]||'overzicht';
  return `<div class="page">
  <div class="band"><img class="bimg" src="${HERO}" alt="" aria-hidden="true">
    <div class="btop"><div class="crumb"><a href="/projecten">Projectdossiers</a>${ic('chev')}<span>${p.id}</span></div>
    <div class="acts"><button class="btn onnavy" data-act="nova">${ic('spark')}Vraag Nova</button><button class="btn onnavy" data-act="newtask" data-pid="${p.id}">${ic('plus')}Taak</button><button class="btn pri" data-act="pdtab" data-t="${p.phase<=3?(p.begroting?'offerte':'begroting'):p.phase<=5?'planning':'financien'}" data-pid="${p.id}">${p.phase<=2?'Naar begroting':p.phase===3?'Naar offerte':p.phase<=5?'Naar planning':'Naar financiën'} ${ic('chev')}</button></div></div>
    <div style="display:grid;gap:6px"><span class="eyebrow">Projectdossier · ${esc(p.type)}</span><h1>${esc(p.naam)}</h1><span class="sub">${esc([p.adres,p.plaats].filter(Boolean).join(', ')||'Adres nog onbekend')}</span><div class="rule"></div></div>
    <div class="bmeta"><div><span>Projectnummer</span><b>${p.id}</b></div><div><span>Opdrachtgever</span><b>${esc(c.naam)}</b></div><div><span>Fase</span><b>${PHASES[p.phase]}</b></div><div><span>Projectleider</span><b>${esc(empName(p.leider))}</b></div><div><span>Projectwaarde</span><b class="num">${eur(projectValue(p))}</b></div><div><span>Offerte ${p.offerte?esc(p.offerte.nr):''}</span><b>${p.offerte?({concept:'Concept',verzonden:'Verzonden',geaccepteerd:'Ondertekend'})[p.offerte.status]:'Nog niet'}</b></div></div></div>
  <div class="card card-b"><div class="stepper">${PHASES.map((ph,i)=>`<button class="step ${i<p.phase?'done':i===p.phase?'cur':''}" data-act="phaseclick" data-i="${i}" data-pid="${p.id}"><span class="o">${i<p.phase?ic('check'):i+1}</span><span>${ph}</span></button>`).join('')}</div></div>
  <div class="tabs">${PD_TABS.map(([k,l])=>`<button class="tab ${tab===k?'on':''}" data-act="pdtab" data-t="${k}" data-pid="${p.id}">${l}${k==='taken'?`<span class="c">${S.tasks.filter(t=>t.pid===p.id&&t.status!=='afgerond').length}</span>`:''}</button>`).join('')}</div>
  ${pdTab(p,tab)}</div>`;
}
function pdTab(p,tab){
  if(PD_R2[tab]) return PD_R2[tab](p);
  const c=client(p.clientId); const fin=projectFin(p);
  if(tab==='overzicht'){
    const nextBlocks=S.blocks.filter(b=>b.pid===p.id&&b.end>=TODAY).sort((a,b)=>a.start<b.start?-1:1).slice(0,4);
    return `<div class="grid g3">
    <div class="card"><div class="card-h"><h3>Klantgegevens</h3><span class="pill mut">${esc(c.soort)}</span></div><div class="card-b stack">
      <div><span class="lbl">Contactpersoon</span><div>${esc(c.contact)}</div></div>
      <div><span class="lbl">Telefoon</span><div class="num">${c.tel?esc(c.tel):'<span class="dn">Ontbreekt</span>'}</div></div>
      <div><span class="lbl">E-mail</span><div>${esc(c.mail)}</div></div>
      <div><span class="lbl">Projectadres</span><div>${esc(p.adres)}, ${esc(p.plaats)}</div></div>
      <div class="row"><button class="btn sm" data-act="copy" data-v="${esc(c.tel)}">${ic('phone')}Nummer kopiëren</button><button class="btn sm" data-act="mailklant" data-pid="${p.id}">${ic('mail')}Klant informeren</button></div>
    </div></div>
    <div class="card"><div class="card-h"><h3>Projectstatus</h3>${phasePill(p)}</div><div class="card-b stack">
      <div class="grid g2" style="gap:10px"><div><span class="lbl">Start</span><div>${fmtDY(p.start)}</div></div><div><span class="lbl">Oplevering</span><div>${fmtDY(p.eind)}</div></div><div><span class="lbl">Projectleider</span><div class="row" style="gap:6px">${avatar(empName(p.leider),'sm')}${esc(empName(p.leider))}</div></div><div><span class="lbl">Volgende fase</span><div>${PHASES[Math.min(p.phase+1,8)]}</div></div></div>
      <div><div class="row between"><span class="lbl">Voortgang</span><b class="num">${p.progress}%</b></div><div class="bar" style="margin-top:6px"><i style="width:${p.progress}%"></i></div>${p.phase===6?`<small class="muted">Volgens planning ${p.planned}% · ${p.planned-p.progress>=5?'<span class="dn">loopt achter</span>':'<span class="up">op schema</span>'}</small>`:''}</div>
      ${p.phase>=5&&p.phase<=7?`<div class="row"><button class="btn sm" data-act="progress" data-pid="${p.id}" data-d="-5">−5%</button><button class="btn sm" data-act="progress" data-pid="${p.id}" data-d="5">+5% voortgang</button></div>`:''}
    </div></div>
    <div class="card"><div class="card-h"><h3>Financieel</h3><button class="btn xs ghost" data-act="pdtab" data-t="financien" data-pid="${p.id}">Details</button></div><div class="card-b">
      <div class="sumrow"><span class="muted">Projectwaarde excl. btw</span><b class="num">${eur(fin.val)}</b></div>
      <div class="sumrow"><span class="muted">Begrote directe kosten</span><span class="num">${eur(fin.begroot)}</span></div>
      <div class="sumrow"><span class="muted">Werkelijk geboekt</span><span class="num">${eur(fin.werkelijk)}</span></div>
      ${fin.verpl?`<div class="sumrow"><span class="muted">Vastgelegde verplichtingen</span><span class="num">${eur(fin.verpl)}</span></div>`:''}
      <div class="sumrow"><span class="muted">Gefactureerd</span><span class="num">${eur(fin.gefact)}</span></div>
      <div class="sumrow"><span class="muted">Betaald</span><span class="num up">${eur(fin.betaald)}</span></div>
      <div class="sumrow"><span class="muted">Openstaand</span><span class="num ${fin.open>0?'dn':''}">${eur(fin.open)}</span></div>
      <div class="sumrow sub"><span>Verwachte marge</span><span class="num">${pct(fin.marge)}</span></div>
    </div></div>
    <div class="card"><div class="card-h"><h3>Planning</h3><button class="btn xs" data-act="newblock" data-pid="${p.id}">${ic('plus')}Inplannen</button></div><div class="card-b" style="padding-block:4px">
      ${nextBlocks.length?nextBlocks.map(b=>`<div class="li"><span class="ic blue">${ic('cal')}</span><div class="tx"><b>${esc(b.titel)}</b><small>${esc(empName(b.emp))} · ${fmtD(b.start)}${b.end!==b.start?' t/m '+fmtD(b.end):''}</small></div></div>`).join(''):`<div class="empty">Nog niets ingepland.<button class="btn sm" data-act="newblock" data-pid="${p.id}">Team inplannen</button></div>`}
    </div></div>
    <div class="card"><div class="card-h"><h3>Recente <em>activiteit</em></h3><button class="btn xs ghost" data-act="pdtab" data-t="activiteiten" data-pid="${p.id}">Alles</button></div><div class="card-b">${timeline(p.activity.slice(0,5))}</div></div>
    <div class="card"><div class="card-h"><h3><span class="row" style="gap:8px"><span class="novaav sm">${ic('spark')}</span>Nova-inzichten</span></h3></div><div class="card-b" style="padding-block:4px">${novaInsights(p).map(x=>`<div class="li"><span class="ic ${x.k}">${ic(x.i)}</span><div class="tx"><b>${esc(x.t)}</b>${x.s?`<small>${esc(x.s)}</small>`:''}</div>${x.act?`<button class="btn xs" ${x.act}>${x.btn}</button>`:''}</div>`).join('')}</div></div>
    </div>`;
  }
  if(tab==='intake'){
    const it=p.intake||{}; const F=[['wensen','Wensen en gewenst resultaat','ta'],['situatie','Bestaande situatie','ta'],['afmetingen','Afmetingen'],['aandacht','Bouwkundige aandachtspunten'],['bereikbaarheid','Bereikbaarheid'],['vergunning','Vergunningen / onderzoeken'],['budget','Budgetindicatie'],['startWens','Gewenste start']];
    const miss=F.filter(([k])=>!it[k]).map(f=>f[1]);
    return `<div class="grid g-main"><div class="card"><div class="card-h"><h3>Intake en opname</h3><span class="pill ${miss.length?'warn':'ok'}">${miss.length?miss.length+' velden leeg':'Compleet'}</span></div><form class="card-b fg" data-form="intake" data-pid="${p.id}">
      ${F.map(([k,l,t])=>`<div class="f ${t?'full':''}"><label for="in-${k}">${l}</label>${t?`<textarea class="in" id="in-${k}" name="${k}">${esc(it[k]||'')}</textarea>`:`<input class="in" id="in-${k}" name="${k}" value="${esc(it[k]||'')}">`}</div>`).join('')}
      <div class="full row between"><span class="muted" style="font-size:12px">Deze gegevens worden hergebruikt in begroting, offerte en planning.</span><button class="btn pri" type="submit">Intake opslaan</button></div></form></div>
      <div class="card"><div class="card-h"><h3><span class="row" style="gap:8px"><span class="novaav sm">${ic('spark')}</span>Samenvatting door Nova</span></h3></div><div class="card-b stack"><p style="margin:0;white-space:pre-wrap">${esc(intakeSummary(p))}</p>
      ${miss.length?`<div class="alert warn">${ic('alert')}<div class="grow"><b>Nog uitvragen:</b> ${miss.join(', ')}</div></div>`:''}
      <button class="btn" data-act="pdtab" data-t="begroting" data-pid="${p.id}">Door naar begroting ${ic('chev')}</button></div></div></div>`;
  }
  if(tab==='begroting'){
    if(!p.begroting) return `<div class="card"><div class="empty">${ic('calc')}<div>Voor dit dossier is nog geen begroting gemaakt.<br>De intakegegevens worden automatisch overgenomen.</div><button class="btn pri" data-act="mkbegroting" data-pid="${p.id}">${ic('plus')}Begroting starten vanuit sjabloon</button></div></div>`;
    const b=p.begroting, k=calcB(b); const cats=[['Arbeid','arbeid','--c-arb'],['Materiaal','mat','--c-mat'],['Materieel','mt','--c-mt'],['Onderaanneming','oa','--c-oa'],['Overig','ov','--c-ov']];
    return `<div class="grid kpis"><div class="card kpi dark"><span class="lbl">Totaal excl. btw</span><span class="v num">${heur(k.totalExcl)}</span><span class="s">${esc(b.nr||'')} · versie ${b.versie||1} · incl. ${(b.staart||[]).length} opslagen</span></div><div class="card kpi"><span class="lbl">Totaal incl. btw</span><span class="v num">${eur(k.totalIncl)}</span><span class="s">${NUM.format(k.btwP)}% btw: ${eur(k.btw)}</span></div><div class="card kpi"><span class="lbl">Per m² bvo</span><span class="v num">${k.bvo?eur(k.perM2):'—'}</span><span class="s">${k.bvo?NUM.format(k.bvo)+' m² bvo':'Oppervlakte onbekend'}</span></div><div class="card kpi"><span class="lbl">Directe bouwkosten</span><span class="v num">${eur(k.direct)}</span><span class="s">${k.regels} begrotingsregels</span></div></div>
    ${k.openOpt.length?`<div class="optstrip"><span class="pill or">Opties</span><span class="grow">${k.openOpt.length} open ${k.openOpt.length===1?'optie':'opties'} buiten de begroting · ${eur(k.openOptSum*(1+k.btwP/100))} incl. btw</span></div>`:''}
    ${k.missing?`<div class="alert warn">${ic('alert')}<div class="grow"><b>${k.missing} ${k.missing===1?'regel heeft':'regels hebben'} nog geen prijs.</b> Vul ze aan in de begrotingstool.</div></div>`:''}
    <div class="grid" style="grid-template-columns:minmax(0,1fr) minmax(0,1.6fr)">
      <div class="card"><div class="card-h"><h3>Verdeling directe <em>kosten</em></h3></div><div class="card-b"><div class="stack-bar">${cats.map(([_,key,col])=>`<i style="width:${k.direct?k.cat[key]/k.direct*100:0}%;background:var(${col})"></i>`).join('')}</div>
        <div class="leg">${cats.map(([l,key,col])=>`<span class="sw" style="background:var(${col})"></span><span>${l}</span><b class="num">${eur(k.cat[key])}</b><span class="p num">${pct(k.direct?k.cat[key]/k.direct*100:0)}</span>`).join('')}</div>
        <div class="sumrow" style="margin-top:12px;border-top:1px solid var(--border2)"><span class="muted">Begrote arbeidsuren</span><b class="num">${NUM.format(r2(k.uren))} uur</b></div></div></div>
      <div class="card"><div class="card-h"><h3>Kosten per <em>hoofdstuk</em></h3><a class="btn sm pri" href="/begroting-${p.id.toLowerCase()}">${ic('calc')}Open in begrotingstool</a></div><div class="card-b" style="max-height:420px;overflow:auto">${chapterBars(k)}</div></div>
    </div>
    <div class="grid g2">
      <div class="card"><div class="card-h"><h3>Staartkosten &amp; <em>totaal</em></h3></div><div class="card-b">
        <div class="sumrow sub"><span>Directe bouwkosten</span><span>${eur(k.direct)}</span></div>
        ${k.staart.map(s=>`<div class="sumrow"><span>${esc(s.naam)} <span class="muted">${NUM.format(s.pct)}% over ${eur(s.base)}</span></span><span>${eur(s.amt)}</span></div>`).join('')}
        <div class="sumrow sub"><span>Totaal excl. btw</span><span>${eur(k.totalExcl)}</span></div><div class="sumrow"><span>Btw ${NUM.format(k.btwP)}%</span><span>${eur(k.btw)}</span></div><div class="sumrow big"><span>Totaal incl. btw</span><span>${eur(k.totalIncl)}</span></div>
        <div class="calcbox" style="margin-top:10px"><b>Marge en opslag zijn niet hetzelfde</b>
          <div class="row between"><span>Opslag op kostprijs</span><b class="num">${pct(k.opslagPct,2)}</b></div><div class="row between"><span>Brutomarge op verkoopprijs</span><b class="num">${pct(k.marge,2)}</b></div>
          <div class="row wrap" style="gap:8px;margin-top:4px"><label for="mconv" class="muted">Gewenste marge %</label><input id="mconv" class="in num" type="number" step="0.1" value="${UI.mconv??15}" style="width:84px;height:30px" data-pid="${p.id}"><span class="muted" id="mconvout">${mconvText(UI.mconv??15,k.direct)}</span></div></div>
      </div></div>
      <div class="card"><div class="card-h"><h3>Opties &amp; <em>meerwerk</em></h3><span class="pill mut">Factor staartkosten ${NUM.format(r2(k.f*1000)/1000)}</span></div>${(b.options||[]).length?`<div class="tw"><table class="t"><thead><tr><th>Optie</th><th class="r">Verkoop excl.</th><th>Status</th></tr></thead><tbody>
        ${b.options.map((o,i)=>`<tr><td><b>${esc(o.d)}</b><div class="sub">${NUM.format(+o.q||0)} ${esc(o.u||'')}${o.t?' · '+esc(o.t):''}</div></td><td class="r">${+o.p?eur(optPrice(o,b)):'<span class="pill warn">Prijs volgt</span>'}</td><td><select class="in" style="height:30px;width:124px" data-optst="${i}" data-pid="${p.id}" aria-label="Status optie"><option value="optie" ${o.s==='optie'?'selected':''}>Optie</option><option value="akkoord" ${o.s==='akkoord'?'selected':''}>Akkoord</option><option value="vervallen" ${o.s==='vervallen'?'selected':''}>Vervallen</option></select></td></tr>`).join('')}
      </tbody></table></div><div class="card-b" style="border-top:1px solid var(--border2)"><div class="row between"><span class="muted">Goedgekeurd meerwerk (apart van aanneemsom)</span><b class="num">${eur(k.meerwerk)}</b></div></div>`:`<div class="empty">Geen opties.</div>`}</div>
    </div>`;
  }
  if(tab==='offerte') return offerteTab(p);
  if(tab==='planning'){
    const bl=S.blocks.filter(b=>b.pid===p.id).sort((a,b)=>a.start<b.start?-1:1); const cids=confIds();
    return `<div class="card"><div class="card-h"><h3>Ingeplande werkzaamheden</h3><div class="acts"><button class="btn sm" data-act="novaask" data-q="Maak een conceptplanning">${ic('spark')}Conceptplanning door Nova</button><button class="btn sm pri" data-act="newblock" data-pid="${p.id}">${ic('plus')}Inplannen</button></div></div>
    ${bl.length?`<div class="tw"><table class="t"><thead><tr><th>Werkzaamheden</th><th>Vakman</th><th>Van</th><th>Tot en met</th><th class="r">Werkdagen</th><th></th></tr></thead><tbody>${bl.map(b=>`<tr class="click" data-act="editblock" data-id="${b.id}"><td><b>${esc(b.titel)}</b>${cids.has(b.id)?' <span class="pill bad">Dubbel ingepland</span>':''}</td><td><div class="row" style="gap:8px">${avatar(empName(b.emp),'sm')}${esc(empName(b.emp))}<span class="muted">${esc(emp(b.emp)?.rol||'')}</span></div></td><td>${fmtD(b.start)}</td><td>${fmtD(b.end)}</td><td class="r">${workdays(b.start,b.end)}</td><td class="r">${ic('chev')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nog geen planning.</div>`}</div>`;
  }
  if(tab==='taken'){ const tl=S.tasks.filter(t=>t.pid===p.id).sort((a,b)=>(a.status==='afgerond')-(b.status==='afgerond')||(a.dl<b.dl?-1:1)); return `<div class="card"><div class="card-h"><h3>Taken in dit dossier</h3><button class="btn sm pri" data-act="newtask" data-pid="${p.id}">${ic('plus')}Taak</button></div>${taskTable(tl)}</div>`; }
  if(tab==='financien'){
    const inv=fin.inv; const base=p.offerte&&p.offerte.status==='geaccepteerd'?p.offerte.basis:null;
    return `<div class="grid kpis"><div class="card kpi dark"><span class="lbl">Contractwaarde</span><span class="v num">${heur(fin.val)}</span><span class="s">${base!=null?'Incl. goedgekeurd meerwerk':'Nog geen contract'}</span></div><div class="card kpi"><span class="lbl">Gefactureerd</span><span class="v num">${eur(fin.gefact)}</span><span class="s">${fin.val?pct(fin.gefact/fin.val*100):'0%'} van contract</span></div><div class="card kpi"><span class="lbl">Betaald</span><span class="v num up">${eur(fin.betaald)}</span><span class="s">excl. btw</span></div><div class="card kpi"><span class="lbl">Openstaand</span><span class="v num ${fin.open>0?'dn':''}">${eur(fin.open)}</span><span class="s">excl. btw</span></div></div>
    <div class="card"><div class="card-h"><h3>Betaaltermijnen en facturen</h3></div>${base==null?`<div class="empty">Termijnen worden actief zodra de offerte is ondertekend.</div>`:`<div class="tw"><table class="t"><thead><tr><th>#</th><th>Termijn</th><th class="r">%</th><th class="r">Excl. btw</th><th class="r">Incl. btw</th><th>Factuur</th><th>Status</th><th></th></tr></thead><tbody>
    ${p.termijnen.map((t,i)=>{ const f=inv.find(x=>x.termijn===i); const amt=base*t.pct/100; return `<tr><td>${i+1}</td><td>${esc(t.oms)}</td><td class="r">${pct(t.pct,0)}</td><td class="r">${eur(f?f.bedrag:amt)}</td><td class="r">${eur((f?f.bedrag:amt)*1.21)}</td><td>${f?f.nr:'—'}</td><td>${invPill(f)}</td><td class="r">${!f?`<button class="btn xs" data-act="mkinvoice" data-pid="${p.id}" data-i="${i}">Factuur maken</button>`:f.status==='concept'?`<button class="btn xs" data-act="sendinv" data-nr="${f.nr}">Verzenden</button>`:f.status==='verzonden'?`<button class="btn xs" data-act="payinv" data-nr="${f.nr}">Markeer betaald</button>`:`<span class="muted" style="font-size:12px">${fmtD(f.betaald)}</span>`}</td></tr>`; }).join('')}
    </tbody></table></div>`}</div>`;
  }
  if(tab==='documenten'){
    return `<div class="card"><div class="card-h"><h3>Documenten (${p.docs.length})</h3><label class="btn sm pri" style="cursor:pointer">${ic('upload')}Uploaden<input type="file" hidden multiple data-upload="${p.id}"></label></div>
    ${p.docs.length?`<div class="tw"><table class="t"><thead><tr><th>Naam</th><th>Categorie</th><th>Datum</th><th>Zichtbaar voor klant</th></tr></thead><tbody>${p.docs.map(d=>`<tr><td><div class="row">${ic('file')}<b>${esc(d.naam)}</b></div></td><td><span class="pill mut">${esc(d.cat)}</span></td><td>${fmtDY(d.datum)}</td><td>${['Offerte','Overeenkomst','Tekening','Keuze'].includes(d.cat)?'<span class="pill ok">Ja</span>':'<span class="pill mut">Intern</span>'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nog geen documenten.</div>`}
    <div class="card-b muted" style="font-size:12px;border-top:1px solid var(--border2)">Bestanden worden veilig op de server bewaard en zijn alleen te openen voor wie is ingelogd.</div></div>`;
  }
  if(tab==='activiteiten') return `<div class="card card-b">${timeline(p.activity)}</div>`;
  return '';
}
function invPill(f){ if(!f) return '<span class="pill mut">Nog niet gefactureerd</span>'; if(f.status==='betaald') return '<span class="pill ok">Betaald</span>'; if(f.status==='concept') return '<span class="pill mut">Concept</span>'; return f.verval<TODAY?'<span class="pill bad">Vervallen</span>':'<span class="pill blue">Verzonden</span>'; }
function timeline(a){ const m={ok:['ok','check'],or:['or','spark'],blue:['blue','file'],vio:['vio','clip'],bad:['bad','alert'],mut:['mut','inbox']}; return `<div class="tl">${a.map(e=>{ const [c,i]=m[e.k]||m.blue; return `<div class="e"><span class="dotc ic ${c}">${ic(i==='inbox'?'mail':i)}</span><div><b>${esc(e.t)}</b><small>${fmtDY(e.d)}</small></div></div>`; }).join('')}</div>`; }
function novaInsights(p){
  const out=[]; const c=client(p.clientId);
  if(!c.tel) out.push({k:'bad',i:'phone',t:'Telefoonnummer klant ontbreekt',s:'Nodig voor afspraken en opvolging.'});
  const it=p.intake||{}; const miss=['afmetingen','situatie','aandacht'].filter(k=>!it[k]); if(p.phase<=2&&miss.length) out.push({k:'warn',i:'clip',t:`Intake mist ${miss.length} gegevens`,s:'Vul aan vóór de calculatie.',act:`data-act="pdtab" data-t="intake" data-pid="${p.id}"`,btn:'Aanvullen'});
  if(p.begroting){ const k=calcB(p.begroting); if(k.missing) out.push({k:'or',i:'calc',t:`${k.missing} begrotingsregel zonder prijs`,act:`data-go="begroting-${p.id.toLowerCase()}"`,btn:'Open'}); if(p.offerte&&p.offerte.status!=='geaccepteerd'&&Math.abs(k.totalExcl-p.offerte.basis)>.5) out.push({k:'or',i:'file',t:'Begroting gewijzigd na offerte',s:'Offerte moet worden bijgewerkt.',act:`data-act="pdtab" data-t="offerte" data-pid="${p.id}"`,btn:'Bekijk'}); if(k.openOpt.length) out.push({k:'vio',i:'tag',t:`${k.openOpt.length} open opties bij klant`,s:'Nog niet in contractwaarde opgenomen.'}); }
  const od=S.invoices.filter(i=>i.pid===p.id&&i.status==='verzonden'&&i.verval<TODAY); if(od.length) out.push({k:'bad',i:'euro',t:`Termijnfactuur ${od[0].nr} vervallen`,s:'Controleer betaling voor verdere start.',act:`data-act="pdtab" data-t="financien" data-pid="${p.id}"`,btn:'Controleer'});
  if(p.phase===6&&p.planned-p.progress>=5) out.push({k:'bad',i:'alert',t:`Loopt ${p.planned-p.progress}% achter op planning`,s:'Overweeg extra capaciteit.'});
  const cf=conflicts().filter(x=>x.a.pid===p.id||x.b.pid===p.id); if(cf.length) out.push({k:'bad',i:'cal',t:`${cf.length} planningsconflict`,act:`data-go="planning"`,btn:'Planning'});
  if(!S.blocks.some(b=>b.pid===p.id&&b.end>=TODAY)&&p.phase>=4&&p.phase<=6) out.push({k:'or',i:'cal',t:'Geen werk ingepland',act:`data-act="novaask" data-q="Maak een conceptplanning"`,btn:'Laat Nova plannen'});
  if(!out.length) out.push({k:'ok',i:'check',t:'Geen open punten',s:'Dossier is compleet en op schema.'});
  return out;
}
function intakeSummary(p){ const it=p.intake||{}; const c=client(p.clientId);
  if(!Object.values(it).some(Boolean)) return `Er is nog geen intake vastgelegd voor ${c.naam}. Plan een intake of vul de gegevens hiernaast in.`;
  return `${c.naam} wil: ${it.wensen||'(wensen nog niet vastgelegd)'}\n\nHuidige situatie: ${it.situatie||'onbekend'}. Afmetingen: ${it.afmetingen||'nog meten'}.\nAandachtspunten: ${it.aandacht||'geen genoteerd'}. Bereikbaarheid: ${it.bereikbaarheid||'onbekend'}.\nBudget ${it.budget||'onbekend'}, gewenste start ${it.startWens||'onbekend'}. Vergunning: ${it.vergunning||'onbekend'}.`; }

/* ---------- Offerte ---------- */
function offerteTab(p){
  const o=p.offerte; const k=p.begroting?calcB(p.begroting):null;
  if(!o){ return `<div class="card"><div class="empty">${ic('file')}<div>Er is nog geen offerte. Bedragen komen rechtstreeks uit de begroting${p.begroting?'':' (maak eerst een begroting)'}.</div>${p.begroting?`<button class="btn pri" data-act="mkofferte" data-pid="${p.id}">${ic('plus')}Offerte genereren uit begroting</button>`:`<button class="btn pri" data-act="mkbegroting" data-pid="${p.id}">Begroting starten</button>`}</div></div>`; }
  const changed = k && Math.abs(k.totalExcl-o.basis)>.5;
  const st={concept:['mut','Concept'],verzonden:['blue','Verzonden'],geaccepteerd:['ok','Ondertekend']}[o.status];
  const sum=p.termijnen.reduce((s,t)=>s+(+t.pct||0),0); const locked=o.status==='geaccepteerd';
  let cum=0;
  return `<div class="stack" style="gap:16px">
  ${changed&&o.status==='concept'?`<div class="alert warn">${ic('alert')}<div class="grow"><b>De begroting is gewijzigd.</b> Conceptofferte staat op ${eur(o.basis)}, begroting op ${eur(k.totalExcl)}.</div><button class="btn sm" data-act="offupdate" data-pid="${p.id}">Concept bijwerken</button></div>`:''}
  ${changed&&o.status==='verzonden'?`<div class="alert warn">${ic('alert')}<div class="grow"><b>Begroting gewijzigd na verzending.</b> Een verzonden offerte wordt nooit stilzwijgend aangepast.</div><button class="btn sm" data-act="offversion" data-pid="${p.id}">Nieuwe versie ${o.versie+1} maken</button></div>`:''}
  ${changed&&locked?`<div class="alert info">${ic('lock')}<div class="grow"><b>Contract is vastgezet op ${eur(o.basis)}.</b> Wijzigingen in de begroting lopen via meerwerk.</div></div>`:''}
  <div class="grid g-main">
    <div class="card"><div class="card-h"><h3>Offerte ${o.nr} · versie ${o.versie}</h3><span class="pill ${st[0]}">${st[1]}</span></div><div class="card-b">
      <div class="grid g3" style="gap:12px;margin-bottom:12px"><div><span class="lbl">Aanneemsom excl. btw</span><div style="font-size:20px;font-weight:800" class="num">${eur(o.basis)}</div></div><div><span class="lbl">Btw 21%</span><div class="num" style="font-size:15px;font-weight:600">${eur(o.basis*.21)}</div></div><div><span class="lbl">Incl. btw</span><div class="num" style="font-size:15px;font-weight:600">${eur(o.basis*1.21)}</div></div></div>
      <div class="sumrow"><span class="muted">Verzonden</span><span>${o.sent?fmtDY(o.sent):'—'}</span></div><div class="sumrow"><span class="muted">Ondertekend</span><span>${o.accepted?fmtDY(o.accepted)+' door '+esc(o.signedBy):'—'}</span></div>
      <div class="row wrap" style="margin-top:14px">
        <button class="btn" data-act="offpreview" data-pid="${p.id}">${ic('eye')}Klantpreview</button>
        ${o.status==='concept'?`<button class="btn pri" data-act="offsend" data-pid="${p.id}" ${sum!==100?'disabled title="Termijnen moeten samen 100% zijn"':''}>${ic('send')}Verzenden naar klant</button>`:''}
        ${o.status==='verzonden'?`<button class="btn pri" data-act="offsign" data-pid="${p.id}">${ic('pen')}Ondertekening openen</button><button class="btn" data-act="novaask" data-q="Maak een offerteopvolging">${ic('spark')}Opvolging</button>`:''}
        ${locked?`<button class="btn" data-act="pdtab" data-t="financien" data-pid="${p.id}">Naar termijnfacturen ${ic('chev')}</button>`:''}
      </div></div></div>
    <div class="card"><div class="card-h"><h3>Klantvragen</h3><span class="pill mut">Gedeeld</span></div><div class="card-b stack">${p.begroting&&p.begroting.notities.vragen.length?p.begroting.notities.vragen.map(v=>`<div class="msg n" style="max-width:100%"><b>${esc(v.van)}</b> · <span class="muted">${fmtD(v.datum)}</span><br>${esc(v.txt)}</div>`).join(''):'<span class="muted">Geen vragen van de klant.</span>'}</div></div>
  </div>
  <div class="card"><div class="card-h"><h3>Betalings<em>termijnen</em></h3><div class="acts">${locked?`<span class="pill ok">${ic('lock')}Vastgelegd in contract</span>`:`<button class="btn sm" data-act="preset" data-n="3" data-pid="${p.id}">3 termijnen</button><button class="btn sm" data-act="preset" data-n="9" data-pid="${p.id}">9 termijnen</button><button class="btn sm" data-act="addterm" data-pid="${p.id}">${ic('plus')}Termijn</button>`}</div></div>
    <div class="tw"><table class="t"><thead><tr><th>#</th><th>Omschrijving</th><th class="r">%</th><th class="r">Excl. btw</th><th class="r">Btw</th><th class="r">Incl. btw</th><th class="r">Cumulatief</th>${locked?'':'<th></th>'}</tr></thead><tbody>
    ${p.termijnen.map((t,i)=>{ cum+=(+t.pct||0); const a=o.basis*(+t.pct||0)/100; return `<tr><td>${i+1}</td><td>${locked?esc(t.oms):`<input class="in" style="height:30px" value="${esc(t.oms)}" data-term="oms" data-pid="${p.id}" data-i="${i}" aria-label="Omschrijving termijn ${i+1}">`}</td><td class="r">${locked?pct(t.pct,0):`<input class="in num" style="height:30px;width:70px;text-align:right" type="number" min="0" max="100" step="1" value="${t.pct}" data-term="pct" data-pid="${p.id}" data-i="${i}" aria-label="Percentage termijn ${i+1}">`}</td><td class="r">${eur(a)}</td><td class="r">${eur(a*.21)}</td><td class="r">${eur(a*1.21)}</td><td class="r">${pct(cum,0)}</td>${locked?'':`<td class="r"><button class="btn xs ghost" data-act="delterm" data-pid="${p.id}" data-i="${i}" aria-label="Verwijder termijn">${ic('trash')}</button></td>`}</tr>`; }).join('')}
    </tbody><tfoot><tr><td></td><td><b>Totaal</b></td><td class="r"><b class="${sum===100?'up':'dn'}">${pct(sum,0)}</b></td><td class="r"><b>${eur(o.basis*sum/100)}</b></td><td></td><td class="r"><b>${eur(o.basis*sum/100*1.21)}</b></td><td></td>${locked?'':'<td></td>'}</tr></tfoot></table></div>
    ${sum!==100?`<div class="card-b"><div class="alert bad">${ic('alert')}<div class="grow">De termijnen tellen op tot ${pct(sum,0)}. Dit moet precies 100% zijn voordat de offerte verzonden kan worden.</div></div></div>`:''}
  </div></div>`;
}

/* ---------- Begroting ---------- */
function chapterBars(k){ const max=Math.max(...k.chapters.map(c=>c.totaal),1); return k.chapters.map(c=>`<div class="chb"><span class="code">${esc(c.nr)}</span><span class="nm">${esc(c.naam)}</span><div class="bar hide-m"><i style="width:${c.totaal/max*100}%"></i></div><b class="num" style="text-align:right;font-weight:600">${eur(c.totaal)}</b><span class="num muted hide-m" style="text-align:right;font-size:12px">${pct(k.direct?c.totaal/k.direct*100:0)}</span></div>`).join(''); }
const heur = v => eur(v).replace('€','<b>€</b>');
const heur0 = v => eur0(v).replace('€','<b>€</b>');
function mconvText(m,direct){ m=+m; if(!(m>=0&&m<100)) return 'Kies een marge tussen 0 en 100%.'; const o=opslagFromMarge(m); return `vraagt een opslag van ${pct(o,2)} → verkoopprijs ${eur(direct*(1+o/100))}. Een opslag van ${pct(m,0)} geeft maar ${pct(margeFromOpslag(m),2)} marge.`; }
function findLineById(m,id){ let r=null; eachLine(m,(l,nr)=>{ if(l.id===id) r={l,nr}; }); return r; }

/* ---------- Begrotingsmodule: de Renovion-begrotingstool, gekoppeld aan het projectdossier ----------
   De tool draait ongewijzigd in een eigen frame. Bij openen krijgt hij het begrotingsmodel van het dossier
   (window.__osBeg.get), elke opslag in de tool schrijft terug naar het dossier (window.__osBeg.put). */
let _toolHtml=null;
function toolHtml(){ if(_toolHtml==null){ try{ _toolHtml=OSB.urls.tool||''; }catch(e){ _toolHtml=''; } } return _toolHtml; }
function vBegroting(id){
  const p=proj(id); if(!p) return vProject(id); if(!p.begroting){ UI.pdTab[id]='begroting'; return vProject(id); }
  const k=calcB(p.begroting); const locked=p.offerte&&p.offerte.status==='geaccepteerd';
  return `<div class="bmod"><div class="bmod-bar">
    <div class="crumb"><a href="/project-${p.id.toLowerCase()}">${ic('chevl')}${esc(p.naam)}</a>${ic('chev')}<span>${esc(p.begroting.nr||'Begroting')}</span></div>
    <span class="sync" id="bsync"><i></i>Gekoppeld aan ${p.id}</span><span style="flex:1"></span>
    ${locked?`<span class="pill or" title="Contract ${esc(p.offerte.nr)} is ondertekend; wijzigingen lopen via meerwerk">${ic('lock')}Contract vastgezet</span>`:''}
    <span class="muted" style="font-size:12px">Excl. btw</span><b class="tot" id="btot">${eur(k.totalExcl)}</b>
    <button class="btn sm" data-act="nova">${ic('spark')}Nova</button>
    <button class="btn sm pri" data-act="gooff" data-pid="${p.id}">Naar offerte ${ic('chev')}</button></div>
    <iframe id="begframe" data-pid="${p.id}" title="Begrotingstool ${esc(p.naam)}"></iframe></div>`;
}
function updBegBar(id){ const p=proj(id); if(!p||!p.begroting) return; const t=$('#btot'); if(t) t.textContent=eur(calcB(p.begroting).totalExcl); const s=$('#bsync'); if(s) s.innerHTML=`<i></i>Opgeslagen in ${p.id} · ${new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})}`; }
function loadBegFrame(){ const fr=$('#begframe'); if(!fr) return; const h=toolHtml(); UI.begPid=fr.dataset.pid; UI.begReload=false;
  if(!h){ fr.replaceWith(Object.assign(document.createElement('div'),{className:'empty',innerHTML:'De begrotingstool kon niet worden geladen.'})); return; }
  UI.begGot=false; const sk=document.createElement('div'); sk.className='sk-frame'; sk.setAttribute('aria-hidden','true'); sk.innerHTML='<span class="sk" style="height:56px;border-radius:14px"></span><span class="sk" style="height:120px;border-radius:14px"></span><span class="sk" style="height:40px;width:60%"></span><span class="sk" style="height:40px"></span><span class="sk" style="height:40px"></span><span class="sk" style="height:40px;width:80%"></span>'; fr.parentNode.appendChild(sk); fr.addEventListener('load',()=>{ sk.classList.add('gone'); setTimeout(()=>sk.remove(),260); },{once:true}); fr.src=h;
  setTimeout(()=>{ const f=$('#begframe'); if(f&&!UI.begGot&&!document.getElementById('begwarn')) f.insertAdjacentHTML('beforebegin',`<div class="alert warn" id="begwarn" style="margin:12px 24px 0">${ic('alert')}<div class="grow">De begrotingstool start niet. Herlaad de pagina; lukt het dan nog niet, controleer je internetverbinding.</div></div>`); },5000); }
window.__osBeg={
  get(){ UI.begGot=true; const p=proj(UI.begPid); if(!p||!p.begroting) return null; const m=JSON.parse(JSON.stringify(p.begroting)); const c=client(p.clientId);
    m.meta=Object.assign({},m.meta||{},{project:p.naam,locatie:[p.adres,p.plaats].filter(Boolean).join(', '),nummer:p.id,opdrachtgever:c.naam});
    const inv=S.invoices.filter(i=>i.pid===p.id); const old=(m.pay&&m.pay.terms)||[];
    m.pay=Object.assign({clause:'',baseMode:'auto',base:0},m.pay||{});
    m.pay.terms=p.termijnen.map((t,i)=>{ const f=inv.find(x=>x.termijn===i); return {id:(old[i]&&old[i].id)||uid('t'),d:t.oms,pct:+t.pct||0,st:f?(f.status==='betaald'?'betaald':f.status==='verzonden'?'gefactureerd':'gepland'):'gepland',fixed:false,amt:0,date:(f&&f.betaald)||''}; });
    return m; },
  put(m){ const p=proj(UI.begPid); if(!p||!p.begroting||!m||!Array.isArray(m.chapters)) return;
    const keep={nr:p.begroting.nr,versie:p.begroting.versie,status:p.begroting.status,notities:p.begroting.notities};
    p.begroting=Object.assign(m,keep,{gewijzigd:TODAY});
    const nm=m.meta&&String(m.meta.project||'').trim(); if(nm&&nm!==p.naam) p.naam=nm;
    if(!(p.offerte&&p.offerte.status==='geaccepteerd')&&m.pay&&Array.isArray(m.pay.terms)&&m.pay.terms.length) p.termijnen=m.pay.terms.map(t=>({oms:t.d,pct:+t.pct||0}));
    save(); updBegBar(p.id); }
};

/* ---------- Planning ---------- */
const PLANNABLE = () => S.emps.filter(e=>e.type!=='kantoor');
function vPlanning(){
  const ws=UI.planWeek, days=UI.planView==='week'?5:10; const dates=[]; for(let i=0,s=ws; dates.length<days; s=addDays(s,1),i++) if(!isWeekend(s)) dates.push(s);
  const end=dates[dates.length-1]; const cf=conflicts(); const cids=confIds(); const wk=isoWeek(ws);
  if(UI.planView==='cap') return vCapaciteit();
  const rows=PLANNABLE().map(e=>{
    const bl=S.blocks.filter(b=>b.emp===e.id&&b.end>=dates[0]&&b.start<=end).sort((a,b)=>a.start<b.start?-1:1);
    const lanes=[]; const placed=bl.map(b=>{ const s=b.start<dates[0]?dates[0]:b.start, en=b.end>end?end:b.end; const c0=dates.indexOf(s)>=0?dates.indexOf(s):dates.findIndex(d=>d>=s); let c1=dates.indexOf(en); if(c1<0){ c1=-1; dates.forEach((d,i)=>{ if(d<=en) c1=i; }); } let lane=0; while(lanes[lane]&&lanes[lane]>=c0) lane++; lanes[lane]=c1; return {b,c0,c1,lane}; }).filter(x=>x.c0>=0&&x.c1>=x.c0);
    const hrs=bl.reduce((s,b)=>{ const a=b.start<dates[0]?dates[0]:b.start, z=b.end>end?end:b.end; return s+workdays(a,z)*8; },0); const capw=e.cap*(days/5);
    return `<div class="prow"><div class="who">${avatar(e.naam)}<div style="min-width:0"><b>${esc(e.naam.split(' ')[0])}</b><small>${esc(e.rol)}${e.type==='partner'?' · partner':''}</small><small class="num ${hrs>capw?'dn':''}">${hrs}u / ${capw}u</small></div></div>
    <div class="pcells" style="--days:${days}">${dates.map((d,i)=>`<div class="pcell ${d===TODAY?'today':''}" style="grid-column:${i+1};grid-row:1 / span ${Math.max(1,lanes.length)}" data-drop="${e.id}" data-day="${d}"></div>`).join('')}
    ${placed.map(x=>{ const p=proj(x.b.pid)||{naam:'Intern',plaats:'',kleur:0}; return `<div class="blk pc${p.kleur%6} ${cids.has(x.b.id)?'conf':''}" draggable="true" data-blk="${x.b.id}" data-act="editblock" data-id="${x.b.id}" style="grid-column:${x.c0+1} / ${x.c1+2};grid-row:${x.lane+1}" title="${esc(p.naam+' · '+x.b.titel)}"><b>${esc(p.naam)}</b><small>${esc(x.b.titel)} · ${esc(p.plaats)}</small></div>`; }).join('')}</div></div>`; }).join('');
  const wcf=cf.filter(c=>c.day>=dates[0]&&c.day<=end);
  return `<div class="page"><div class="ph"><div><h1>Planning &amp; <em>capaciteit</em></h1><p>Sleep blokken naar een andere dag of vakman. Dubbele bezetting wordt direct gemarkeerd.</p></div>
    <div class="acts"><div class="seg"><button class="${UI.planView==='week'?'on':''}" data-act="pview" data-v="week">Week</button><button class="${UI.planView==='2w'?'on':''}" data-act="pview" data-v="2w">2 weken</button><button class="${UI.planView==='cap'?'on':''}" data-act="pview" data-v="cap">Capaciteit</button></div><button class="btn" data-act="novaask" data-q="Welke vakmensen zijn vrijdag beschikbaar?">${ic('spark')}Beschikbaarheid</button><button class="btn pri" data-act="newblock">${ic('plus')}Inplannen</button></div></div>
  <div class="row wrap"><button class="btn sm" data-act="pweek" data-d="-7" aria-label="Vorige week">${ic('chevl')}</button><b>Week ${wk} · ${fmtD(dates[0])} t/m ${fmtD(end)} ${D(end).getFullYear()}</b><button class="btn sm" data-act="pweek" data-d="7" aria-label="Volgende week">${ic('chev')}</button><button class="btn sm" data-act="pweek" data-d="0">Vandaag</button></div>
  ${cf.length?`<div class="alert bad">${ic('alert')}<div class="grow"><b>${cf.length} ${cf.length===1?'conflict':'conflicten'} in de planning.</b> ${cf.map(c=>`${firstName(c.emp)} op ${cap(dayName(c.day))} ${fmtD(c.day)} (${esc(proj(c.a.pid)?.naam)} + ${esc(proj(c.b.pid)?.naam)})`).join(' · ')}${wcf.length?'':' · niet in deze week'}</div>${!wcf.length?`<button class="btn sm" data-act="pjump" data-w="${monday(cf[0].day)}">Toon</button>`:''}</div>`:`<div class="alert info">${ic('check')}<div class="grow">Geen dubbele bezetting in de planning.</div></div>`}
  <div class="card tw"><div class="plan" style="${days>5?'min-width:1400px':''}"><div class="plan-h" style="--days:${days}"><div>Uitvoerders (${PLANNABLE().length})</div>${dates.map(d=>`<div class="${d===TODAY?'today':''}">${cap(dayName(d))} ${fmtD(d)}</div>`).join('')}</div>${rows}</div></div></div>`;
}
function vCapaciteit(){
  const weeks=[0,1,2,3].map(i=>addDays(UI.planWeek,i*7));
  return `<div class="page"><div class="ph"><div><h1>Planning &amp; <em>capaciteit</em></h1><p>Geplande uren tegenover afgesproken capaciteit per week.</p></div><div class="acts"><div class="seg"><button data-act="pview" data-v="week">Week</button><button data-act="pview" data-v="2w">2 weken</button><button class="on" data-act="pview" data-v="cap">Capaciteit</button></div></div></div>
  <div class="card tw"><table class="t"><thead><tr><th>Vakman</th><th>Specialisme</th>${weeks.map(w=>`<th>Week ${fmtD(w)}</th>`).join('')}</tr></thead><tbody>
  ${PLANNABLE().map(e=>`<tr><td><div class="row">${avatar(e.naam,'sm')}<b>${esc(e.naam)}</b></div></td><td>${esc(e.rol)}${e.type==='partner'?' <span class="pill mut">Partner</span>':''}</td>${weeks.map(w=>{ const we=addDays(w,4); const h=S.blocks.filter(b=>b.emp===e.id&&b.end>=w&&b.start<=we).reduce((s,b)=>s+workdays(b.start<w?w:b.start,b.end>we?we:b.end)*8,0); const r=h/e.cap; return `<td style="min-width:140px"><div class="row between" style="font-size:12px"><span class="num ${r>1?'dn':''}">${h}u / ${e.cap}u</span><span class="muted">${r>1?'Overboekt':h===0?'Vrij':Math.round(r*100)+'%'}</span></div><div class="bar ${r>1?'':'blue'}" style="margin-top:4px"><i style="width:${Math.min(100,r*100)}%;${r>1?'background:var(--bad)':''}"></i></div></td>`; }).join('')}</tr>`).join('')}
  </tbody></table></div></div>`;
}

/* ---------- Taken ---------- */
const prioPill = p => p==='hoog'?'<span class="pill bad">Hoog</span>':p==='laag'?'<span class="pill ok">Laag</span>':'<span class="pill mut">Normaal</span>';
const stPill = s => ({open:'<span class="pill mut">Open</span>',todo:'<span class="pill warn">Te doen</span>',bezig:'<span class="pill blue">Bezig</span>',wacht:'<span class="pill vio">Wacht op</span>',afgerond:'<span class="pill ok">Afgerond</span>'})[s];
function taskTable(list){
  if(!list.length) return `<div class="empty">${ic('checksq')}Geen taken in deze weergave.<button class="btn sm" data-act="newtask">Taak aanmaken</button></div>`;
  return `<div class="tw"><table class="t"><thead><tr><th style="width:34px"></th><th>Taak</th><th>Project / klant</th><th>Eigenaar</th><th>Deadline</th><th>Status</th><th>Prioriteit</th></tr></thead><tbody>
  ${list.map(t=>{ const p=proj(t.pid); return `<tr class="click" data-act="opentask" data-id="${t.id}"><td><button class="chk ${t.status==='afgerond'?'on':''}" data-act="donetask" data-id="${t.id}" aria-label="Taak afronden">${t.status==='afgerond'?ic('check'):''}</button></td><td><b style="${t.status==='afgerond'?'text-decoration:line-through;color:var(--muted)':''}">${esc(t.titel)}</b>${t.checklist.length?`<div class="sub">${t.checklist.filter(c=>c.d).length}/${t.checklist.length} checklist</div>`:''}</td><td>${p?`${esc(client(p.clientId).naam)}<div class="sub">${esc(p.naam)}</div>`:'<span class="muted">Intern</span>'}</td><td>${t.eig?`<div class="row" style="gap:6px">${avatar(empName(t.eig),'sm')}<span>${esc(firstName(t.eig))}</span></div>`:'<span class="pill bad">Geen eigenaar</span>'}</td><td>${t.status==='afgerond'?fmtD(t.dl):dueLabel(t.dl)}</td><td>${stPill(t.status)}</td><td>${prioPill(t.prio)}</td></tr>`; }).join('')}</tbody></table></div>`;
}
function vTaken(){
  const base=S.tasks.filter(t=>!UI.taskProj||t.pid===UI.taskProj);
  const cnt=k=>k==='open'?base.filter(t=>t.status!=='afgerond').length:base.filter(t=>t.status===k).length;
  const tab=UI.taskTab; const list=base.filter(t=>tab==='open'?t.status!=='afgerond':t.status===tab).sort((a,b)=>(a.dl||'9')<(b.dl||'9')?-1:1);
  const od=base.filter(t=>t.status!=='afgerond'&&t.dl<TODAY), noown=base.filter(t=>t.status!=='afgerond'&&!t.eig), blk=base.filter(t=>t.status==='wacht');
  return `<div class="page"><div class="ph"><div><h1>Taken &amp; <em>werkstroom</em></h1><p>Van actie tot oplevering. Elke taak hangt aan een projectdossier.</p></div><div class="acts"><div class="seg"><button class="${UI.taskView==='lijst'?'on':''}" data-act="tview" data-v="lijst">${'Lijst'}</button><button class="${UI.taskView==='kanban'?'on':''}" data-act="tview" data-v="kanban">Kanban</button></div><button class="btn pri" data-act="newtask">${ic('plus')}Taak</button></div></div>
  ${(od.length||noown.length||blk.length)?`<div class="alert warn">${ic('spark')}<div class="grow"><b>Nova:</b> ${[od.length?`${od.length} verlopen deadline${od.length>1?'s':''}`:'',noown.length?`${noown.length} zonder eigenaar`:'',blk.length?`${blk.length} wacht op een ander`:''].filter(Boolean).join(' · ')}.</div></div>`:''}
  <div class="row between wrap"><div class="tabs">${Object.entries(TASK_ST).map(([k,l])=>`<button class="tab ${tab===k?'on':''}" data-act="ttab" data-t="${k}">${l}<span class="c">${cnt(k)}</span></button>`).join('')}</div>
  <select class="in" style="width:auto;min-width:200px" id="tproj" aria-label="Filter op project"><option value="">Alle projecten</option>${S.projects.map(p=>`<option value="${p.id}" ${UI.taskProj===p.id?'selected':''}>${esc(p.naam)}</option>`).join('')}</select></div>
  <form class="card" style="padding:10px;display:flex;gap:8px;flex-wrap:wrap" data-form="quicktask"><input class="in" name="titel" id="qt-titel" placeholder="Wat moet er gebeuren?" style="flex:2;min-width:200px" aria-label="Nieuwe taak"><input class="in" type="date" name="dl" value="${TODAY}" style="width:150px" aria-label="Deadline"><select class="in" name="prio" style="width:120px" aria-label="Prioriteit"><option value="normaal">Normaal</option><option value="hoog">Hoog</option><option value="laag">Laag</option></select><select class="in" name="eig" style="width:150px" aria-label="Eigenaar">${S.emps.map(e=>`<option value="${e.id}" ${e.id===ME?'selected':''}>${esc(e.naam)}</option>`).join('')}</select><button class="btn pri" type="submit" aria-label="Toevoegen">${ic('plus')}</button></form>
  ${UI.taskView==='lijst'?`<div class="card">${taskTable(list)}</div>`:`<div class="kb">${Object.entries(TASK_ST).map(([k,l])=>`<div class="kcol" data-kdrop="${k}"><h4>${l}<span class="pill mut">${base.filter(t=>t.status===k).length}</span></h4>${base.filter(t=>t.status===k).slice(0,k==='afgerond'?6:99).map(t=>{ const p=proj(t.pid); return `<div class="kcard" draggable="true" data-ktask="${t.id}" data-act="opentask" data-id="${t.id}"><b>${esc(t.titel)}</b><span class="muted">${p?esc(p.naam):'Intern'}</span><div class="row between">${t.eig?avatar(empName(t.eig),'sm'):'<span class="pill bad">Geen eigenaar</span>'}<span style="font-size:12px">${dueLabel(t.dl)}</span>${prioPill(t.prio)}</div></div>`; }).join('')}</div>`).join('')}</div>`}
  </div>`;
}

/* ---------- Commercieel ---------- */
function vSales(){
  const cols=[0,1,2,3]; const leads=S.projects.filter(p=>p.phase<=3);
  const pipe=leads.reduce((s,p)=>s+projectValue(p),0); const kans=[.1,.25,.4,.6]; const weighted=leads.reduce((s,p)=>s+projectValue(p)*kans[p.phase],0);
  return `<div class="page"><div class="ph"><div><h1>Aanvragen &amp; <em>sales</em></h1><p>Sleep een kaart naar de volgende fase. Akkoord kan alleen via ondertekening van de offerte.</p></div><button class="btn pri" data-act="newlead">${ic('plus')}Nieuwe aanvraag</button></div>
  <div class="grid g4"><div class="card kpi"><span class="lbl">Open leads</span><span class="v num">${leads.length}</span></div><div class="card kpi"><span class="lbl">Potentiële omzet</span><span class="v num">${eur0(pipe)}</span></div><div class="card kpi dark"><span class="lbl">Gewogen pipeline</span><span class="v num">${heur0(weighted)}</span><span class="s">kans × waarde (10/25/40/60%)</span></div><div class="card kpi"><span class="lbl">Gewonnen dit jaar</span><span class="v num">${eur0(S.projects.filter(p=>p.offerte&&p.offerte.status==='geaccepteerd').reduce((s,p)=>s+projectValue(p),0))}</span></div></div>
  <div class="kb">${cols.map(ph=>`<div class="kcol" data-ldrop="${ph}"><h4>${PHASES[ph]}<span class="pill mut">${leads.filter(p=>p.phase===ph).length}</span></h4>${leads.filter(p=>p.phase===ph).map(p=>{ const c=client(p.clientId); const miss=!c.tel; return `<div class="kcard" draggable="true" data-lead="${p.id}" data-go="project-${p.id.toLowerCase()}"><div class="row between"><b>${esc(c.naam)}</b><span class="pill or num">${Math.round(kans[ph]*100)}%</span></div><span class="muted">${esc(p.type)} · ${esc(p.plaats)}</span><div class="row between"><b class="num">${eur0(projectValue(p))}</b><span class="row" style="gap:6px">${avatar(empName(p.leider),'sm')}</span></div>${miss?'<span class="pill bad">Telefoonnummer ontbreekt</span>':''}</div>`; }).join('')}</div>`).join('')}</div></div>`;
}
function vKlanten(){
  return `<div class="page"><div class="ph"><div><h1>Klanten &amp; <em>CRM</em></h1><p>${S.clients.length} relaties. Klik voor het meest recente projectdossier.</p></div><button class="btn pri" data-act="newlead">${ic('plus')}Klant toevoegen</button></div>
  <div class="card tw"><table class="t"><thead><tr><th>Klant</th><th>Soort</th><th>Contact</th><th>Plaats</th><th>Dossiers</th><th class="r">Totale waarde</th></tr></thead><tbody>
  ${S.clients.map(c=>{ const ps=S.projects.filter(p=>p.clientId===c.id); return `<tr class="click" ${ps[0]?`data-go="project-${ps[0].id.toLowerCase()}"`:''}><td><div class="row">${avatar(c.naam,'sm')}<b>${esc(c.naam)}</b></div></td><td>${esc(c.soort)}</td><td>${esc(c.contact)}<div class="sub">${c.tel?esc(c.tel):'<span class="dn">Geen telefoon</span>'}</div></td><td>${esc(c.plaats)}</td><td>${ps.map(p=>phasePill(p)).join(' ')||'—'}</td><td class="r">${eur0(ps.reduce((s,p)=>s+projectValue(p),0))}</td></tr>`; }).join('')}</tbody></table></div></div>`;
}
function vCalculaties(){
  const ps=S.projects.filter(p=>p.begroting);
  return `<div class="page"><div class="ph"><div><h1>Calcu<em>laties</em></h1><p>Elke begroting opent in de Renovion-begrotingstool en voedt direct de offerte.</p></div></div>
  <div class="card tw"><table class="t"><thead><tr><th>Begroting</th><th>Project</th><th>Status</th><th class="r">Directe kosten</th><th class="r">Excl. btw</th><th class="r">Marge</th></tr></thead><tbody>
  ${ps.map(p=>{ const k=calcB(p.begroting); return `<tr class="click" data-go="begroting-${p.id.toLowerCase()}"><td><b>${p.begroting.nr}</b><div class="sub">versie ${p.begroting.versie}</div></td><td>${esc(p.naam)}<div class="sub">${esc(client(p.clientId).naam)}</div></td><td><span class="pill ok">${esc(p.begroting.status)}</span>${k.missing?' <span class="pill warn">Prijs ontbreekt</span>':''}</td><td class="r">${eur(k.direct)}</td><td class="r"><b>${eur(k.totalExcl)}</b></td><td class="r">${pct(k.marge)}</td></tr>`; }).join('')}
  ${S.projects.filter(p=>!p.begroting&&p.phase>=1&&p.phase<=3).map(p=>`<tr><td><span class="muted">Nog geen begroting</span></td><td>${esc(p.naam)}<div class="sub">${esc(client(p.clientId).naam)}</div></td><td><span class="pill mut">${PHASES[p.phase]}</span></td><td></td><td class="r muted">indicatie ${eur0(p.waarde)}</td><td class="r"><button class="btn xs" data-act="mkbegroting" data-pid="${p.id}">Starten</button></td></tr>`).join('')}
  </tbody></table></div></div>`;
}
function vOffertes(){
  const ps=S.projects.filter(p=>p.offerte);
  return `<div class="page"><div class="ph"><div><h1><em>Offertes</em></h1><p>Elke offerte is een vastgezette versie van een begroting.</p></div></div>
  <div class="card tw"><table class="t"><thead><tr><th>Offerte</th><th>Project</th><th>Verzonden</th><th>Status</th><th class="r">Aanneemsom excl. btw</th></tr></thead><tbody>
  ${ps.map(p=>{ const o=p.offerte; const st={concept:'<span class="pill mut">Concept</span>',verzonden:'<span class="pill blue">Verzonden</span>',geaccepteerd:'<span class="pill ok">Ondertekend</span>'}[o.status]; return `<tr class="click" data-act="pdtab" data-t="offerte" data-pid="${p.id}"><td><b>${o.nr}</b><div class="sub">versie ${o.versie}</div></td><td>${esc(p.naam)}<div class="sub">${esc(client(p.clientId).naam)}</div></td><td>${fmtDY(o.sent)}${o.status==='verzonden'?`<div class="sub ${diffDays(o.sent,TODAY)>=3?'dn':''}">${diffDays(o.sent,TODAY)} dagen geleden</div>`:''}</td><td>${st}</td><td class="r"><b>${eur(o.basis)}</b></td></tr>`; }).join('')}</tbody></table></div></div>`;
}
function vFacturatie(){
  const inv=S.invoices.slice().sort((a,b)=>a.datum<b.datum?1:-1); const open=inv.filter(i=>i.status==='verzonden');
  return `<div class="page"><div class="ph"><div><h1>Factu<em>ratie</em></h1><p>Termijnfacturen uit de ondertekende betalingsschema's. Betaalstatus werkt direct door in het projectdossier.</p></div></div>
  <div class="grid kpis"><div class="card kpi dark"><span class="lbl">Openstaand incl. btw</span><span class="v num">${heur(open.reduce((s,i)=>s+i.bedrag*1.21,0))}</span><span class="s">${open.length} facturen</span></div><div class="card kpi"><span class="lbl">Vervallen</span><span class="v num dn">${open.filter(i=>i.verval<TODAY).length}</span></div><div class="card kpi"><span class="lbl">Betaald dit jaar</span><span class="v num">${eur0(inv.filter(i=>i.status==='betaald').reduce((s,i)=>s+i.bedrag*1.21,0))}</span><span class="s">incl. btw</span></div><div class="card kpi"><span class="lbl">Concepten</span><span class="v num">${inv.filter(i=>i.status==='concept').length}</span></div></div>
  <div class="card tw"><table class="t"><thead><tr><th>Factuur</th><th>Klant / project</th><th>Termijn</th><th>Vervaldatum</th><th class="r">Incl. btw</th><th>Status</th><th></th></tr></thead><tbody>
  ${inv.map(i=>{ const p=proj(i.pid); return `<tr><td><b>${i.nr}</b><div class="sub">${fmtD(i.datum)}</div></td><td>${esc(client(p.clientId).naam)}<div class="sub">${esc(p.naam)}</div></td><td>${i.termijn+1}. ${esc(i.oms)}</td><td>${fmtD(i.verval)}</td><td class="r">${eur(i.bedrag*1.21)}</td><td>${invPill(i)}</td><td class="r">${i.status==='verzonden'?`<button class="btn xs" data-act="payinv" data-nr="${i.nr}">Markeer betaald</button>`:i.status==='concept'?`<button class="btn xs" data-act="sendinv" data-nr="${i.nr}">Verzenden</button>`:''}</td></tr>`; }).join('')}</tbody></table></div></div>`;
}
function vInstellingen(){
  return `<div class="page"><div class="ph"><div><h1>Instel<em>lingen</em></h1><p>Je account, de werkwijze van Nova en de outbox.</p></div></div>
  <div class="grid g2"><div class="card"><div class="card-h"><h3>Mijn <em>account</em></h3></div><div class="card-b stack"><div class="row" style="gap:12px">${avatar(myName())}<div><b>${esc(myName())}</b><div class="muted" style="font-size:12.5px">${esc(OSB.me.mail||'')}, ${esc(ME_ROL)}</div></div></div><p class="muted" style="margin:0;font-size:12.5px">Alles wat je doet, wordt direct op de server opgeslagen en is meteen zichtbaar voor je collega's. Een nieuw wachtwoord maakt de directie in Teambeheer.</p><div class="row" style="gap:8px"><button class="btn" data-act="theme">${ic('moon')}Donker / licht</button><button class="btn" data-act="logout">${ic('logout')}Uitloggen</button></div></div></div>
  <div class="card"><div class="card-h"><h3>Nova</h3></div><div class="card-b stack"><div class="f"><label for="novamode">Werkwijze</label><select class="in" id="novamode"><option value="advies" ${S.prefs.novaMode==='advies'?'selected':''}>Alleen adviseren</option><option value="bevestigen" ${S.prefs.novaMode==='bevestigen'?'selected':''}>Actie voorbereiden, ik bevestig</option><option value="auto" ${S.prefs.novaMode==='auto'?'selected':''}>Veilige interne acties direct uitvoeren</option></select></div><p class="muted" style="margin:0;font-size:12px">Financiële, contractuele en externe acties vragen altijd bevestiging, ongeacht deze instelling.</p></div></div>
  <div class="card"><div class="card-h"><h3>Outbox</h3><span class="pill mut">${S.outbox.length}</span></div><div class="card-b">${S.outbox.length?S.outbox.map(m=>`<div class="li"><span class="ic blue">${ic('mail')}</span><div class="tx"><b>${esc(m.onderwerp)}</b><small>Aan ${esc(m.aan)} · ${fmtD(m.d)} · niet extern verzonden</small></div></div>`).join(''):'<span class="muted">Nog geen e-mails. Zonder mailprovider worden berichten alleen hier geplaatst.</span>'}</div></div></div></div>`;
}
const MODS={
  'm-intake':['Intakes en opnames','Stapsgewijze intakewizard met spraakinvoer, foto\'s, afmetingen en een Nova-samenvatting.',['Intake per dossier werkt al in het tabblad Aanvraag & intake van elk project.']],
  'm-prijslijst':['Prijslijst','Kostendatabase met 40+ artikelen, tariefhistorie en "toevoegen aan begroting".',[]],
  'm-werkbonnen':['Werkbonnen','Mobiele werkbonnen met checklist, uren, foto\'s en handtekening. Status: Concept → Afgesloten.',[]],
  'm-kwaliteit':['Kwaliteit en oplevering','Controlelijsten, restpunten, Wkb-bewijsstukken en de opleverflow.',[]],
  'm-workforce':['Workforce','Vakmensen, certificaten, beschikbaarheid en teams samenstellen.',['Capaciteit per vakman zie je al in Planning → Capaciteit.']],
  'm-onderaannemers':['Onderaannemers','Profielen, Renovion-keurmerk en documentstatus.',[]],
  'm-partner':['Partner Portal','Onboardingwizard en opdrachtenoverzicht voor partners.',[]],
  'm-werkhub':['Werkhub en prijsaanvragen','Prijsaanvragen per werkpakket, vergelijking en gunning als verplichting in de prognose.',[]],
  'm-financieel':['Financieel','Organisatie-KPI\'s, cashflow, werkvoorraad en marges per project.',['Projectfinanciën werken al per dossier, en facturen in Facturatie.']],
  'm-inkoop':['Inkoop','Inkooporders en inkoopfacturen gekoppeld aan begrotingsposten.',[]],
  'm-documenten':['Documenten','Documentbibliotheek, templategenerator met variabelen en Renovion Sign.',['Documenten per dossier staan al in het tabblad Documenten.']],
  'm-marketing':['Marketing','Leadbronnen, kosten per lead, SEO en CRO.',[]],
  'm-rapportages':['Rapportages','Weekafsluiting en managementrapportages.',[]],
  'm-teamchat':['Teamchat','Kanalen per project en team, threads en taak-vanuit-bericht.',[]],
  'm-automations':['Automations','Triggers, voorwaarden en acties met signaleren / bevestigen / automatisch.',['Signalen zoals "offerte 3 dagen zonder reactie" werken al op Vandaag en Aandacht.']],
  'm-teambeheer':['Teambeheer','Gebruikers, rollen, rechten en de rolweergave.',[]],
};
function vModule(r){ const m=MODS[r]||['Module','',[]];
  return `<div class="page"><div class="ph"><div><h1>${m[0]}</h1><p>Deze module wordt in de volgende bouwronde uitgewerkt.</p></div></div>
  <div class="card"><div class="empty" style="padding:48px 24px">${ic('rocket')}<b style="color:var(--text);font-size:15px">${m[0]} volgt in ronde 2</b><div style="max-width:520px">${esc(m[1])}</div>${m[2].map(x=>`<div class="alert info" style="text-align:left">${ic('check')}<div class="grow">${esc(x)}</div></div>`).join('')}<a class="btn" href="/vandaag">Terug naar Vandaag</a></div></div></div>`;
}

/* ---------- Modals ---------- */
function modal(title,body,foot,wide){ $('#layer').innerHTML=`<div class="modal-bg" data-act="mclose-bg"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="mh"><h3>${title}</h3><button class="iconbtn" data-act="mclose" aria-label="Sluiten">${ic('x')}</button></div><div class="mb">${body}</div>${foot?`<div class="mf">${foot}</div>`:''}</div></div>`; setTimeout(()=>{ const f=$('#layer input:not([type=hidden]),#layer textarea,#layer select'); f&&f.focus(); },30); }
function closeModal(){ $('#layer').innerHTML=''; }
const empOpts=(sel,filter)=>S.emps.filter(filter||(()=>true)).map(e=>`<option value="${e.id}" ${e.id===sel?'selected':''}>${esc(e.naam)} · ${esc(e.rol)}</option>`).join('');
const projOpts=(sel,blank=true)=>(blank?'<option value="">Geen (intern)</option>':'')+S.projects.map(p=>`<option value="${p.id}" ${p.id===sel?'selected':''}>${esc(p.naam)}</option>`).join('');
function mTask(t,pid){
  const n=!t; t=t||{titel:'',pid:pid||'',eig:ME,dl:addDays(TODAY,1),status:'todo',prio:'normaal',oms:'',checklist:[]};
  modal(n?'Nieuwe taak':'Taak bewerken',`<form class="fg" data-form="task" data-id="${n?'':t.id}">
    <div class="f full"><label for="t-titel">Titel</label><input class="in" id="t-titel" name="titel" value="${esc(t.titel)}" required></div>
    <div class="f"><label for="t-pid">Projectdossier</label><select class="in" id="t-pid" name="pid">${projOpts(t.pid)}</select></div>
    <div class="f"><label for="t-eig">Eigenaar</label><select class="in" id="t-eig" name="eig"><option value="">Nog niet toegewezen</option>${empOpts(t.eig)}</select></div>
    <div class="f"><label for="t-dl">Deadline</label><input class="in" type="date" id="t-dl" name="dl" value="${t.dl}"></div>
    <div class="f"><label for="t-prio">Prioriteit</label><select class="in" id="t-prio" name="prio">${['hoog','normaal','laag'].map(x=>`<option ${t.prio===x?'selected':''} value="${x}">${cap(x)}</option>`).join('')}</select></div>
    <div class="f"><label for="t-status">Status</label><select class="in" id="t-status" name="status">${Object.entries(TASK_ST).map(([k,l])=>`<option value="${k}" ${t.status===k?'selected':''}>${l}</option>`).join('')}</select></div>
    <div class="f full"><label for="t-oms">Omschrijving</label><textarea class="in" id="t-oms" name="oms">${esc(t.oms)}</textarea></div>
    ${!n&&t.checklist.length?`<div class="full"><span class="lbl">Checklist</span>${t.checklist.map((c,i)=>`<label class="row" style="padding:5px 0;cursor:pointer"><input type="checkbox" name="cl${i}" ${c.d?'checked':''}> ${esc(c.t)}</label>`).join('')}</div>`:''}
  </form>`,`${!n?`<button class="btn danger" data-act="deltask" data-id="${t.id}" style="margin-right:auto">${ic('trash')}Verwijderen</button>`:''}<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">${n?'Taak aanmaken':'Opslaan'}</button>`);
}
function mBlock(b,pid){
  const n=!b; b=b||{emp:osField(),pid:pid||'',titel:'',start:addDays(monday(TODAY),7),end:addDays(monday(TODAY),8)};
  modal(n?'Werk inplannen':'Planning bewerken',`<form class="fg" data-form="block" data-id="${n?'':b.id}">
    <div class="f full"><label for="b-titel">Werkzaamheden</label><input class="in" id="b-titel" name="titel" value="${esc(b.titel)}" placeholder="Bijv. tegelwerk" required></div>
    <div class="f"><label for="b-pid">Project</label><select class="in" id="b-pid" name="pid">${projOpts(b.pid,false)}</select></div>
    <div class="f"><label for="b-emp">Vakman</label><select class="in" id="b-emp" name="emp">${empOpts(b.emp,e=>e.type!=='kantoor')}</select></div>
    <div class="f"><label for="b-start">Van</label><input class="in" type="date" id="b-start" name="start" value="${b.start}"></div>
    <div class="f"><label for="b-end">Tot en met</label><input class="in" type="date" id="b-end" name="end" value="${b.end}"></div>
    <div class="full" id="b-check"></div></form>`,`${!n?`<button class="btn danger" data-act="delblock" data-id="${b.id}" style="margin-right:auto">${ic('trash')}Verwijderen</button><button class="btn" data-act="wb-fromblock" data-id="${b.id}">${ic('wrench')}Werkbon maken</button>`:''}<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">${n?'Inplannen':'Opslaan'}</button>`);
  blockCheck();
}
function blockCheck(){ const f=document.querySelector('[data-form="block"]'); if(!f) return; const e=f.emp.value,s=f.start.value,en=f.end.value,id=f.dataset.id; const box=$('#b-check'); if(!s||!en) return; if(en<s){ box.innerHTML=`<div class="alert bad">${ic('alert')}<div class="grow">De einddatum ligt vóór de startdatum.</div></div>`; return; }
  const ov=S.blocks.filter(b=>b.id!==id&&b.emp===e&&b.start<=en&&s<=b.end); box.innerHTML= ov.length?`<div class="alert bad">${ic('alert')}<div class="grow"><b>${esc(firstName(e))} is al ingepland:</b> ${ov.map(b=>`${esc(proj(b.pid)?.naam)} (${fmtD(b.start)}–${fmtD(b.end)})`).join(', ')}. Je kunt toch opslaan; het wordt als conflict gemarkeerd.</div></div>`:`<div class="alert info">${ic('check')}<div class="grow">${esc(firstName(e))} is beschikbaar · ${workdays(s,en)} werkdagen (${workdays(s,en)*8} uur).</div></div>`; }
