function mAppt(){
  modal('Afspraak plannen',`<form class="fg" data-form="appt"><div class="f full"><label for="a-titel">Onderwerp</label><input class="in" id="a-titel" name="titel" required></div><div class="f"><label for="a-d">Datum</label><input class="in" type="date" id="a-d" name="d" value="${TODAY}"></div><div class="f"><label for="a-t">Tijd</label><input class="in" type="time" id="a-t" name="tijd" value="15:00"></div><div class="f full"><label for="a-pid">Projectdossier</label><select class="in" id="a-pid" name="pid">${projOpts('')}</select></div></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Afspraak opslaan</button>`);
}
function mConfirm(title,txt,okLabel,fn,danger){ UI._confirm=fn; modal(title,`<p style="margin:0">${txt}</p>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn ${danger?'danger':'pri'}" data-act="confirm-ok">${okLabel}</button>`); }
function mSign(p){
  const o=p.offerte, c=client(p.clientId);
  modal(`Ondertekenen · ${o.nr} v${o.versie}`,`<div class="alert info">${ic('lock')}<div class="grow">Digitale ondertekening: naam, handtekening, datum en tijd worden vastgelegd. Dit is een gewone elektronische handtekening, geen gekwalificeerde.</div></div>
  <div class="calcbox"><div class="row between"><span>Aanneemsom excl. btw</span><b class="num">${eur(o.basis)}</b></div><div class="row between"><span>Incl. 21% btw</span><b class="num">${eur(o.basis*1.21)}</b></div><div class="row between"><span>Betalingsschema</span><span>${p.termijnen.map(t=>t.pct+'%').join(' / ')}</span></div></div>
  <form class="fg" data-form="sign" data-pid="${p.id}"><div class="f"><label for="s-naam">Naam ondertekenaar</label><input class="in" id="s-naam" name="naam" value="${esc(c.contact)}" required></div><div class="f"><label for="s-mail">E-mail ter verificatie</label><input class="in" id="s-mail" name="mail" value="${esc(c.mail)}"></div>
  <label class="full row" style="cursor:pointer;align-items:flex-start"><input type="checkbox" name="akkoord" id="s-ak" style="margin-top:3px"> <span>Ik heb de offerte, de algemene voorwaarden en het betalingsschema gelezen en ga akkoord.</span></label>
  <div class="full f"><label>Handtekening</label><canvas class="sig" id="sigpad" aria-label="Handtekeningveld"></canvas><div class="row between"><small class="muted">Teken met muis of vinger · ${fmtDL(TODAY)}</small><button type="button" class="btn xs ghost" data-act="sigclear">Wissen</button></div></div><div class="full ferr" id="s-err"></div></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">${ic('pen')}Ondertekenen en project activeren</button>`,true);
  const cv=$('#sigpad'); const r=cv.getBoundingClientRect(); cv.width=r.width*2; cv.height=r.height*2; const ctx=cv.getContext('2d'); ctx.scale(2,2); ctx.lineWidth=2.2; ctx.lineCap='round'; ctx.strokeStyle=getComputedStyle(document.body).color; let dn=false; UI.signed=false;
  const pos=e=>{ const b=cv.getBoundingClientRect(); return [e.clientX-b.left,e.clientY-b.top]; };
  cv.onpointerdown=e=>{ dn=true; cv.setPointerCapture(e.pointerId); ctx.beginPath(); ctx.moveTo(...pos(e)); };
  cv.onpointermove=e=>{ if(!dn) return; ctx.lineTo(...pos(e)); ctx.stroke(); UI.signed=true; };
  cv.onpointerup=()=>dn=false;
}
function mPreview(p,kind){
  const o=p.offerte; const c=client(p.clientId); const k=p.begroting?calcB(p.begroting):null; const amt=kind==='beg'?k.totalExcl:o.basis;
  modal(kind==='beg'?'PDF-voorbeeld begroting':'Klantpreview offerte',`<div class="docprev">
  <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap"><div><div style="color:#FF580A;font-weight:800;font-size:16px">Renovion</div><small style="color:#76839A">Van aanvraag tot nazorg</small></div><div style="text-align:right;font-size:11px;color:#76839A">${kind==='beg'?p.begroting.nr+' v'+p.begroting.versie:o.nr+' · versie '+o.versie}<br>${fmtDY(TODAY)}</div></div>
  <div style="margin:22px 0 14px;padding:20px;border-radius:8px;background:#0D1B2E;color:#fff"><small style="color:#9FB0CC;letter-spacing:.08em;text-transform:uppercase">${kind==='beg'?'Begroting':'Offerte'} voor ${esc(c.naam)}</small><h2 style="color:#fff">${esc(p.naam)}</h2><span style="color:#FF580A">${esc(p.adres)}, ${esc(p.plaats)}</span></div>
  ${k?`<table><thead><tr><th>Hoofdstuk</th><th class="r">Bedrag</th></tr></thead><tbody>${k.chapters.map(ch=>`<tr><td>${ch.nr} ${esc(ch.naam)}</td><td class="r">${eur(ch.totaal)}</td></tr>`).join('')}<tr><td>Staartkosten en opslagen</td><td class="r">${eur(k.staartTot)}</td></tr></tbody></table>`:''}
  <table style="margin-top:12px"><tr><td><b>Aanneemsom excl. btw</b></td><td class="r"><b>${eur(amt)}</b></td></tr><tr><td>Btw 21%</td><td class="r">${eur(amt*.21)}</td></tr><tr><td><b>Totaal incl. btw</b></td><td class="r"><b>${eur(amt*1.21)}</b></td></tr></table>
  <h4 style="margin:18px 0 6px">Betalingstermijnen</h4><table>${p.termijnen.map((t,i)=>`<tr><td>${i+1}. ${esc(t.oms)}</td><td class="r">${t.pct}%</td><td class="r">${eur(amt*t.pct/100*1.21)}</td></tr>`).join('')}</table>
  ${k&&k.openOpt.length?`<h4 style="margin:18px 0 6px">Optioneel (niet inbegrepen)</h4><table>${k.openOpt.map(x=>`<tr><td>${esc(x.d)}</td><td class="r">${+x.p?eur(optPrice(x,p.begroting)*1.21):'Prijs op aanvraag'}</td></tr>`).join('')}</table>`:''}
  <p style="margin-top:18px;color:#76839A;font-size:11px">Interne kostprijzen, opslagen en privénotities worden niet getoond aan de klant.</p></div>
  <p class="muted" style="margin:0;font-size:12px">Afdrukken naar PDF werkt in de lokaal geopende HTML-versie via Ctrl/Cmd + P.</p>`,`<button class="btn" data-act="mclose">Sluiten</button>`,true);
}

/* ---------- Mutations ---------- */
function newPD(){ S.seq.pd++; return 'PD-'+YEAR+'-'+String(S.seq.pd).padStart(4,'0'); }
function createLead(f){
  const cid=uid('c'); S.clients.push({id:cid,naam:f.naam,soort:f.soort,contact:f.contact||f.naam,tel:f.tel||'',mail:f.mail||'',plaats:f.plaats||''});
  const id=newPD(); const nm=`${f.type.replace('renovatie','')} ${f.naam.replace(/^Familie\s+/i,'')}`.replace(/\s+/g,' ').trim();
  const p={id,naam:nm,clientId:cid,adres:f.adres||'',plaats:f.plaats||'',type:f.type,phase:0,leider:osSales(),progress:0,planned:0,kleur:S.projects.length%6,waarde:+f.budget||0,termijnen:[{oms:'Bij opdracht',pct:40},{oms:'Bij start uitvoering',pct:40},{oms:'Bij oplevering',pct:20}],begroting:null,offerte:null,docs:[],activity:[],intake:{wensen:f.oms||'',budget:f.budget?eur0(+f.budget):''},kosten:0};
  addActivity(p,`Nieuwe aanvraag via ${f.bron}`,'mut'); S.projects.unshift(p);
  S.tasks.push({id:uid('t'),titel:'Eerste contact opnemen',pid:id,eig:osSales(),dl:addDays(TODAY,1),status:'open',prio:'hoog',oms:'Automatisch aangemaakt bij nieuwe aanvraag.',checklist:[]});
  if(!f.tel) S.tasks.push({id:uid('t'),titel:'Telefoonnummer opvragen',pid:id,eig:osSales(),dl:addDays(TODAY,1),status:'todo',prio:'normaal',oms:'Automation: telefoonnummer ontbreekt.',checklist:[]});
  S.outbox.push({d:TODAY,aan:f.mail||f.naam,onderwerp:`Ontvangst aanvraag ${id}`});
  return p;
}
const TEMPLATES={
  default:[['10','Bouwplaatsvoorzieningen',[['Bouwplaatsvoorzieningen en bescherming',1,'post',4,0,0,0,250]]],['21','Sloopwerk',[['Slopen en afvoeren',1,'post',12,0,450]]],['40','Installaties',[['Installatiewerk',1,'post',0,0,0,0]]],['45','Afbouw',[['Afbouw en afwerking',20,'m²',1,35]]],['90','Oplevering',[['Opleverschoonmaak',1,'post',4,25]]]],
};
function mkBegroting(p){
  S.seq.beg++; const c=client(p.clientId); const T=TEMPLATES.default;
  p.begroting={v:2,nr:'BEG-'+YEAR+'-'+String(S.seq.beg).padStart(4,'0'),versie:1,status:'Concept',gewijzigd:TODAY,rate:55,btw:21,attachments:[],
    meta:{project:p.naam,locatie:[p.adres,p.plaats].filter(Boolean).join(', '),nummer:p.id,begroting:'Begroting 01 · '+p.type,opdrachtgever:c.naam,datum:D(TODAY).toLocaleDateString('nl-NL',{day:'2-digit',month:'2-digit',year:'numeric'}),auteur:myName(),bvo:''},
    scope:{docs:[],incl:p.intake&&p.intake.wensen?[p.intake.wensen]:[],excl:[]},
    chapters:T.map(([code,name,ls])=>({id:uid('c'),code,name,open:true,pars:[{id:uid('p'),code:'.01',name:'Algemeen',lines:ls.map(x=>({id:uid('l'),t:'line',d:x[0],q:x[1],u:x[2],n:x[3]||0,m:x[4]||0,e:x[5]||0,o:x[6]||0,v:x[7]||0,r:null}))}]})),
    staart:[{id:uid('s'),name:'Algemene kosten',pct:8},{id:uid('s'),name:'Winst en risico',pct:7}],options:[],pay:{terms:[],clause:'',baseMode:'auto',base:0},notities:{prive:'',vragen:[]}};
  if(p.phase<2) p.phase=2; addActivity(p,`Begroting ${p.begroting.nr} gestart vanuit sjabloon, met de intakegegevens als uitgangspunt`,'vio');
}
function mkOfferte(p){ S.seq.ren++; p.offerte={nr:'REN-'+YEAR+'-'+String(S.seq.ren).padStart(4,'0'),versie:1,status:'concept',basis:calcB(p.begroting).totalExcl}; addActivity(p,`Conceptofferte ${p.offerte.nr} gegenereerd uit ${p.begroting.nr}`,'blue'); }
function signOfferte(p,naam){
  const o=p.offerte; o.status='geaccepteerd'; o.accepted=TODAY; o.signedBy=naam; o.basis=p.begroting?calcB(p.begroting).totalExcl:o.basis;
  if(p.phase<5) p.phase=5; if(!p.start){ p.start=addDays(monday(TODAY),14); p.eind=addDays(p.start,35); }
  if(p.begroting) p.begroting.status='Definitief';
  S.seq.fact++; S.invoices.push({nr:'F-'+YEAR+'-'+String(S.seq.fact).padStart(4,'0'),pid:p.id,termijn:0,oms:p.termijnen[0].oms,bedrag:r2(o.basis*p.termijnen[0].pct/100),datum:TODAY,verval:addDays(TODAY,14),status:'concept'});
  ['Werkvoorbereiding starten','Materialen bestellen','Teambriefing voorbereiden','Klant uitnodigen voor Service Hub'].forEach((t,i)=>S.tasks.push({id:uid('t'),titel:t,pid:p.id,eig:i===3?osSales():(emp(p.leider)&&emp(p.leider).sysrol!=='Sales'?p.leider:osPL()),dl:addDays(TODAY,i+2),status:'todo',prio:i<2?'hoog':'normaal',oms:'Aangemaakt bij projectactivatie.',checklist:[]}));
  S.outbox.push({d:TODAY,aan:client(p.clientId).mail,onderwerp:`Bevestiging opdracht ${o.nr}`});
  addActivity(p,`Offerte ${o.nr} v${o.versie} ondertekend door ${naam}. Contract vastgezet, dossier geactiveerd.`,'ok');
}

/* ---------- Nova ---------- */
function novaCtx(){ const r=route(); let id=null; if(r.startsWith('project-')) id=r.slice(8).toUpperCase(); if(r.startsWith('begroting-')) id=r.slice(10).toUpperCase(); const p=id&&proj(id); return p?{p,where:r.startsWith('begroting-')?'begroting':'dossier'}:null; }
function renderNova(){
  const ctx=novaCtx(); const sp=!!(window.SpeechRecognition||window.webkitSpeechRecognition);
  const sug=ctx?[['Vat de projectvoortgang samen','Status in één alinea'],['Vat de intake samen','Wensen en situatie'],[ctx.p.begroting?'Verhoog de materiaalprijs van deze post met 10%':'Maak een conceptbegroting','Begroting aanpassen'],['Maak een conceptplanning','Volgende week inplannen']]
    :[['Welke projecten lopen achter?','Voortgang vs planning'],['Welke facturen staan open?','Debiteurenoverzicht'],['Plan morgen om 10.00 een terugbelafspraak met familie Bakker','Afspraak + taak'],['Welke vakmensen zijn vrijdag beschikbaar?','Capaciteit']];
  const modeL={advies:'Alleen adviseren',bevestigen:'Stelt voor · jij bevestigt',auto:'Veilige acties direct'}[S.prefs.novaMode];
  const first=!document.querySelector('.drawer');
  $('#layer').innerHTML=`<div class="drawer-bg" data-act="nclose-bg"><aside class="drawer ${first?'anim':''}" role="dialog" aria-label="Nova assistent"><div class="nv-h"><span class="novaav sm">${ic('spark')}</span><div style="flex:1"><b>Nova</b><small>${modeL}</small></div><button class="iconbtn" data-act="nclose" aria-label="Sluiten">${ic('x')}</button></div>
  <div class="nv-ctx">${ctx?`Nova werkt nu binnen: <b>${ctx.p.id} — ${esc(ctx.p.naam)}</b>${ctx.where==='begroting'?' · begroting '+esc(ctx.p.begroting.nr||''):''}`:'Nova werkt nu binnen: <b>hele organisatie</b>. Open een dossier voor projectcontext.'}</div>
  <div class="nv-body" id="nvbody">${UI.novaMsgs.length?UI.novaMsgs.map(novaMsgHtml).join(''):`<div class="msg n">Hoi ${esc(myFirst())}. Wat kan ik voor je klaarzetten? Bijvoorbeeld: "Plan morgen om 10.00 een terugbelafspraak met familie Jansen" of "Verdeel de betaling over 50%, 30% en 20%".</div><div class="lbl">Suggesties</div><div class="sugg">${sug.map(([q,s])=>`<button data-act="novaask" data-q="${esc(q)}">${esc(q)}<small>${esc(s)}</small></button>`).join('')}</div>`}</div>
  <form class="nv-in" data-form="nova"><button type="button" class="mic" data-act="mic" aria-label="Spraakinvoer" ${sp?'':'disabled title="Spraakherkenning wordt niet ondersteund in deze browser"'}>${ic('mic')}</button><input id="nvin" placeholder="Typ ${sp?'of spreek ':''}je opdracht…" autocomplete="off" aria-label="Opdracht voor Nova"><button class="send" type="submit" aria-label="Versturen">${ic('send')}</button></form>
  <div class="nv-note">${OSB.ai?'Nova werkt met Claude op jullie eigen gegevens en voert pas iets uit als jij bevestigt.':'Nova heeft nog geen AI-sleutel en herkent nu alleen vaste opdrachten.'}${sp?'':' Spraak is in deze browser niet beschikbaar; typen werkt altijd.'}</div></aside></div>`;
  const b=$('#nvbody'); b.scrollTop=b.scrollHeight; setTimeout(()=>$('#nvin')?.focus(),30);
}
function novaMsgHtml(m){
  if(m.r==='u') return `<div class="msg u">${esc(m.t)}</div>`;
  if(m.r==='n') return `<div class="msg n">${m.html||esc(m.t)}</div>`;
  if(m.r==='p'){ const x=m.p; return `<div class="prop ${m.state?'done':''}"><div class="ph2">${ic('spark')}Voorstel${m.state==='ok'?' · uitgevoerd':m.state==='x'?' · geannuleerd':''}</div><div class="pb"><div><span class="k">Begrepen</span><div>${esc(x.begrepen)}</div></div><div><span class="k">Gebruikte gegevens</span><div>${esc(x.data)}</div></div><div><span class="k">Voorgestelde wijzigingen</span><ul>${x.changes.map(c=>`<li>${c}</li>`).join('')}</ul></div>${x.gevolg?`<div><span class="k">Gevolgen</span><div>${x.gevolg}</div></div>`:''}</div>${m.state?'':`<div class="pf"><button class="btn sm pri" data-act="pok" data-id="${m.id}">${ic('check')}Bevestigen</button><button class="btn sm" data-act="pedit" data-id="${m.id}">Aanpassen</button><button class="btn sm ghost" data-act="px" data-id="${m.id}">Annuleren</button></div>`}</div>`; }
  return '';
}
function novaSay(html){ UI.novaMsgs.push({r:'n',html}); }
function novaPropose(p,apply,safe){
  const id=uid('p');
  if(S.prefs.novaMode==='advies'){ novaSay(`Ik adviseer: ${p.changes.join('; ')}. Je werkwijze staat op "Alleen adviseren", dus ik voer niets uit.`); return; }
  if(S.prefs.novaMode==='auto'&&safe){ const r=apply(); save(); render(); novaSay(`Direct uitgevoerd (veilige interne actie): ${p.changes.join('; ')}.${r?' '+r:''}`); return; }
  UI.pending[id]=apply; UI.novaMsgs.push({r:'p',id,p});
}
const DAYS=['zondag','maandag','dinsdag','woensdag','donderdag','vrijdag','zaterdag'];
function parseDay(t){ if(/overmorgen/.test(t)) return addDays(TODAY,2); if(/morgen/.test(t)) return addDays(TODAY,1); if(/vandaag/.test(t)) return TODAY; if(/volgende week/.test(t)) return addDays(monday(TODAY),7); for(let i=0;i<7;i++){ if(t.includes(DAYS[i])){ let d=TODAY; for(let n=0;n<7;n++){ if(D(d).getDay()===i) return d; d=addDays(d,1);} } } return null; }
function parseTime(t){ const m=t.match(/(\d{1,2})[:.](\d{2})/)||t.match(/om (\d{1,2})\s*(?:uur)?/); if(!m) return null; return String(m[1]).padStart(2,'0')+':'+(m[2]&&m[2].length===2?m[2]:'00'); }
function findClientIn(t){ return S.clients.find(c=>{ const last=c.naam.replace(/^Familie\s+/i,'').toLowerCase(); return t.includes(last.toLowerCase())||t.includes(c.naam.toLowerCase()); }); }
function ctxProject(t){ const c=findClientIn(t); if(c){ const p=S.projects.find(p=>p.clientId===c.id); if(p) return p; } const byName=S.projects.find(p=>t.includes(p.naam.toLowerCase())); if(byName) return byName; return novaCtx()?.p||null; }
function novaHandle(raw){
  const t=raw.toLowerCase().trim(); UI.novaMsgs.push({r:'u',t:raw});
  const ctxp=ctxProject(t);
  try{
  // 1. Terugbelafspraak / afspraak
  if(/terugbel|bel.*afspraak|afspraak.*(met|bij)|plan .*afspraak/.test(t)){
    const c=findClientIn(t); const p=c?S.projects.find(x=>x.clientId===c.id):ctxp; const d=parseDay(t)||addDays(TODAY,1); const tm=parseTime(t)||'10:00'; const who=c?c.naam:p?client(p.clientId).naam:'klant';
    novaPropose({begrepen:`Terugbelafspraak met ${who} op ${dayName(d)} ${fmtD(d)} om ${tm}.`,data:p?`${p.id} · ${p.naam} · tel. ${client(p.clientId).tel||'ontbreekt'}`:'Geen dossier gevonden',changes:[`Afspraak in agenda: ${dayName(d)} ${fmtD(d)} ${tm}`,`Taak "Terugbellen ${who}" voor ${esc(myFirst())}`],gevolg:p&&!client(p.clientId).tel?'Let op: telefoonnummer ontbreekt in het dossier.':''},()=>{ S.agenda.push({id:uid('a'),d,tijd:tm,titel:`Terugbelafspraak ${who.toLowerCase().startsWith('familie')?who.toLowerCase().replace('familie','familie'):who}`,sub:p?p.naam:'',pid:p?p.id:''}); S.tasks.push({id:uid('t'),titel:`Terugbellen ${who}`,pid:p?p.id:'',eig:ME,dl:d,status:'todo',prio:'normaal',oms:`Afspraak om ${tm}`,checklist:[]}); if(p) addActivity(p,`Terugbelafspraak gepland op ${fmtD(d)} ${tm}`,'blue'); },true); return;
  }
  // 2. Taak
  if(/\btaak\b/.test(t)&&/(maak|nieuwe|zet|aan)/.test(t)){
    const d=parseDay(t)||addDays(TODAY,1); let titel=raw.replace(/^(nova,?\s*)?/i,'').replace(/(maak|zet)\s+(een\s+)?(nieuwe\s+)?taak\s*(aan)?\s*/i,'').replace(/\b(voor\s+)?(morgen|vandaag|overmorgen|maandag|dinsdag|woensdag|donderdag|vrijdag)\b/ig,'').replace(/^(om|:|voor|om te)\s+/i,'').replace(/\s+/g,' ').trim().replace(/\.$/,'');
    if(!titel) titel=ctxp?`Opvolgen ${ctxp.naam}`:'Nieuwe taak'; titel=cap(titel);
    novaPropose({begrepen:`Een taak voor ${dayName(d)} ${fmtD(d)}.`,data:ctxp?`${ctxp.id} · ${ctxp.naam}`:'Geen projectcontext',changes:[`Taak "${esc(titel)}"`,`Eigenaar ${esc(myFirst())}, deadline ${fmtD(d)}, prioriteit normaal`]},()=>{ S.tasks.push({id:uid('t'),titel,pid:ctxp?ctxp.id:'',eig:ME,dl:d,status:'todo',prio:'normaal',oms:'Aangemaakt via Nova.',checklist:[]}); },true); return;
  }
  // 3. Intake samenvatten
  if(/intake/.test(t)&&/(vat|samen)/.test(t)){ if(!ctxp){ novaSay('Van welk project? Open een dossier of noem de klantnaam.'); return; } novaSay(`<b>Intake ${esc(ctxp.naam)}</b><br>${esc(intakeSummary(ctxp)).replace(/\n/g,'<br>')}`); return; }
  // 4. Marge-scenario
  if(/marge/.test(t)&&/(onderaann|duurder|stijg)/.test(t)){ const p=ctxp&&ctxp.begroting?ctxp:S.projects.find(x=>x.begroting); const m=t.match(/(\d+(?:[.,]\d+)?)\s*%/); const x=m?parseFloat(m[1].replace(',','.')):8; const b=JSON.parse(JSON.stringify(p.begroting)); const k0=calcB(p.begroting); eachLine(b,l=>{ l.o=(+l.o||0)*(1+x/100); }); const k1=calcB(b); const fixed=(p.offerte&&p.offerte.status==='geaccepteerd')?p.offerte.basis:k0.totalExcl; const m1=(fixed-k1.direct)/fixed*100;
    novaSay(`<b>Scenario ${esc(p.naam)}: onderaanneming +${NUM.format(x)}%</b><br>Onderaanneming stijgt van ${eur(k0.cat.oa)} naar ${eur(k1.cat.oa)} (+${eur(k1.cat.oa-k0.cat.oa)}).<br>Bij een vaste aanneemsom van ${eur(fixed)} daalt de brutomarge van ${pct(k0.marge)} naar <b>${pct(m1)}</b>.<br>Wil je de prijs doorberekenen, dan wordt de aanneemsom ${eur(k1.totalExcl)} (opslagen blijven gelijk).`); return; }
  // 5. Prijs verhogen
  if(/(verhoog|verlaag)/.test(t)&&/(prijs|materiaal|post)/.test(t)){
    const p=ctxp&&ctxp.begroting?ctxp:null; if(!p){ novaSay('Open eerst een begroting, dan weet ik welke post je bedoelt.'); return; }
    const b=p.begroting; let found=null;
    const pm2=t.match(/(\d{2}\.\d{2}\.\d{2})|post\s*(\d{2})\.?(\d{2})/);
    if(pm2){ const want=pm2[1]||null; eachLine(b,(l,nr)=>{ if(found) return; if(want?nr===want:nr.startsWith(pm2[2]+'.'+pm2[3])) found={l,nr}; }); }
    if(!found){ let best=null; eachLine(b,(l,nr)=>{ const v=(+l.q||0)*(+l.m||0); if(!best||v>best.v) best={l,nr,v}; }); found=best; }
    const down=/verlaag/.test(t); const pc=t.match(/(\d+(?:[.,]\d+)?)\s*%/); const ab=t.match(/€\s*([\d.]+(?:,\d+)?)|(\d[\d.]*)\s*euro/);
    const l=found.l, lnr=found.nr; const oldMat=+l.m||0; let newMat;
    if(pc){ const x=parseFloat(pc[1].replace(',','.'))*(down?-1:1); newMat=r2(oldMat*(1+x/100)); }
    else if(ab){ const a=parseFloat((ab[1]||ab[2]).replace(/\./g,'').replace(',','.'))*(down?-1:1); newMat=r2(oldMat + a/(+l.q||1)); }
    else { novaSay('Met hoeveel? Noem een percentage (bijv. 10%) of een bedrag (bijv. € 2.000).'); return; }
    const k0=calcB(b); const tmp=JSON.parse(JSON.stringify(b)); findLineById(tmp,l.id).l.m=newMat; const k1=calcB(tmp);
    novaPropose({begrepen:`Materiaalprijs van post ${lnr} ${down?'verlagen':'verhogen'}.`,data:`${b.nr} · ${lnr} ${esc(l.d)} · ${NUM.format(+l.q||0)} ${esc(l.u||'')}`,changes:[`Materiaal per eenheid: ${eur(oldMat)} → <b>${eur(newMat)}</b>`,`Materiaal regel: ${eur(oldMat*(+l.q||0))} → ${eur(newMat*(+l.q||0))}`],gevolg:`Aanneemsom excl. btw ${eur(k0.totalExcl)} → <b>${eur(k1.totalExcl)}</b>.${p.offerte&&p.offerte.status!=='concept'?' De offerte wordt niet automatisch gewijzigd.':''}`},()=>{ const cur=findLineById(p.begroting,l.id); if(cur) cur.l.m=newMat; p.begroting.gewijzigd=TODAY; UI.begReload=true; addActivity(p,`Nova: materiaalprijs ${lnr} aangepast naar ${eur(newMat)}`,'or'); },false); return;
  }
  // 6. Betaling verdelen
  if(/(verdeel|betaling|termijn)/.test(t)&&/\d+\s*%/.test(t)){
    const p=ctxp; if(!p){ novaSay('Voor welk project? Open het dossier of noem de klant.'); return; }
    const nums=[...t.matchAll(/(\d+(?:[.,]\d+)?)\s*%/g)].map(m=>parseFloat(m[1].replace(',','.'))); const sum=nums.reduce((a,b)=>a+b,0);
    if(p.offerte&&p.offerte.status==='geaccepteerd'){ novaSay(`Het betalingsschema van ${esc(p.naam)} is vastgelegd in het ondertekende contract en kan niet meer worden gewijzigd.`); return; }
    if(Math.abs(sum-100)>.001){ novaSay(`Deze percentages tellen op tot ${NUM.format(sum)}%. Een betalingsschema moet precies 100% zijn.`); return; }
    const labels=nums.length===3?['Bij opdracht','Bij start uitvoering','Bij oplevering']:nums.map((_,i)=>i===0?'Bij opdracht':i===nums.length-1?'Bij oplevering':`Termijn ${i+1}`);
    const base=p.offerte?p.offerte.basis:projectValue(p);
    novaPropose({begrepen:`Betalingsschema in ${nums.length} termijnen.`,data:`${p.id} · ${p.offerte?p.offerte.nr:'nog geen offerte'} · basis ${eur(base)}`,changes:nums.map((n,i)=>`${i+1}. ${labels[i]}: ${NUM.format(n)}% = ${eur(base*n/100*1.21)} incl. btw`),gevolg:'Totaal 100%. Bestaande termijnen worden vervangen.'},()=>{ p.termijnen=nums.map((n,i)=>({oms:labels[i],pct:n})); addActivity(p,`Betalingsschema aangepast naar ${nums.join('/')}%`,'or'); },false); return;
  }
  // 7. Offerte-opvolging
  if(/opvolg/.test(t)){
    let p=ctxp&&ctxp.offerte&&ctxp.offerte.status==='verzonden'?ctxp:S.projects.filter(x=>x.offerte&&x.offerte.status==='verzonden').sort((a,b)=>a.offerte.sent<b.offerte.sent?-1:1)[0];
    if(!p){ novaSay('Er staan geen verzonden offertes open die opvolging nodig hebben.'); return; } const c=client(p.clientId);
    novaPropose({begrepen:`Opvolging van offerte ${p.offerte.nr}.`,data:`${c.naam} · verzonden ${fmtD(p.offerte.sent)} (${diffDays(p.offerte.sent,TODAY)} dagen) · ${eur(p.offerte.basis)}`,changes:[`Taak "Offerte ${p.offerte.nr} nabellen" voor ${esc(firstName(osOwner(p)))}, morgen`,`Conceptmail "Heeft u nog vragen over uw offerte?" in de outbox`],gevolg:'De e-mail wordt niet echt verzonden; er is geen mailprovider gekoppeld.'},()=>{ S.tasks.push({id:uid('t'),titel:`Offerte ${p.offerte.nr} nabellen`,pid:p.id,eig:osOwner(p),dl:addDays(TODAY,1),status:'todo',prio:'hoog',oms:'Via Nova.',checklist:[]}); S.outbox.push({d:TODAY,aan:c.mail,onderwerp:`Heeft u nog vragen over uw offerte ${p.offerte.nr}?`}); addActivity(p,'Offerte-opvolging klaargezet (mail in de outbox)','blue'); },false); return;
  }
  // 8. Achter
  if(/achter/.test(t)){ const bh=behind(); novaSay(bh.length?`<b>${bh.length} ${bh.length===1?'project loopt':'projecten lopen'} achter:</b><br>${bh.map(p=>`• <a href="/project-${p.id.toLowerCase()}" data-act="nclose">${esc(p.naam)}</a>: ${p.progress}% gereed, planning verwacht ${p.planned}% (${p.planned-p.progress}% achter)`).join('<br>')}<br><br>Tip: bekijk de capaciteit voor extra inzet.`:'Alle projecten in uitvoering liggen op schema.'); return; }
  // 9. Beschikbaarheid
  if(/beschikbaar|vrij\b|wie kan/.test(t)){ const d=parseDay(t)||TODAY; const role=['timmerman','loodgieter','elektricien','schilder','tegelzetter','stratenmaker','uitvoerder'].find(r=>t.includes(r)||t.includes(r+'s')||t.includes(r.replace(/man$/,'mannen'))); const all=PLANNABLE().filter(e=>!role||e.rol.toLowerCase()===role); const free=all.filter(e=>!S.blocks.some(b=>b.emp===e.id&&b.start<=d&&d<=b.end)); const busy=all.filter(e=>!free.includes(e));
    novaSay(`<b>${cap(dayName(d))} ${fmtD(d)}${role?' · '+role+'s':''}</b><br>Beschikbaar: ${free.length?free.map(e=>`${esc(e.naam)} (${esc(e.rol)})`).join(', '):'niemand'}<br><span class="muted">Ingepland: ${busy.map(e=>{ const b=S.blocks.find(b=>b.emp===e.id&&b.start<=d&&d<=b.end); return `${esc(firstName(e.id))} → ${esc(proj(b.pid)?.naam||'')}`; }).join(', ')||'—'}</span>`); return; }
  // 10. Conceptplanning
  if(/planning/.test(t)&&/(maak|concept|plan)/.test(t)){
    const p=ctxp&&ctxp.phase>=3&&ctxp.phase<=7?ctxp:S.projects.find(x=>x.phase===5);
    if(!p){ novaSay('Ik vind geen project dat klaar is voor planning. Open een dossier in voorbereiding of uitvoering.'); return; }
    const ROLES={Badkamerrenovatie:['Timmerman','Loodgieter','Tegelzetter','Elektricien'],Keukenrenovatie:['Timmerman','Loodgieter','Elektricien'],Verbouwing:['Uitvoerder','Timmerman','Elektricien'],default:['Timmerman','Loodgieter','Elektricien']};
    const roles=ROLES[p.type]||ROLES.default; let d=addDays(monday(TODAY),7); const plan=[];
    for(const r of roles){ const cands=PLANNABLE().filter(e=>e.rol===r); let pick=null, s=d; for(let tries=0;tries<10&&!pick;tries++){ pick=cands.find(e=>!S.blocks.some(b=>b.emp===e.id&&b.start<=addDays(s,1)&&s<=b.end)&&!plan.some(x=>x.emp===e.id&&x.start<=addDays(s,1)&&s<=x.end)); if(!pick){ s=addDays(s,1); if(isWeekend(s)) s=addDays(s,2);} }
      if(pick){ let e=addDays(s,1); if(isWeekend(e)) e=addDays(e,2); plan.push({emp:pick.id,start:s,end:e,titel:{Timmerman:'Timmerwerk',Loodgieter:'Leidingwerk',Tegelzetter:'Tegelwerk',Elektricien:'Elektra',Uitvoerder:'Uitvoering en toezicht'}[r]||r}); d=addDays(s,1); if(isWeekend(d)) d=addDays(d,2); } }
    novaPropose({begrepen:`Conceptplanning voor ${p.naam} vanaf week van ${fmtD(addDays(monday(TODAY),7))}.`,data:`${p.id} · ${p.type} · benodigde specialismen: ${roles.join(', ')} · beschikbaarheid uit planning`,changes:plan.map(x=>`${esc(x.titel)}: ${esc(empName(x.emp))}, ${dayName(x.start)} ${fmtD(x.start)} t/m ${dayName(x.end)} ${fmtD(x.end)}`),gevolg:'Volgorde houdt rekening met afhankelijkheden: eerst ruw werk, dan installaties, dan afwerking. Er ontstaan geen dubbele boekingen.'},()=>{ plan.forEach(x=>S.blocks.push({id:uid('b'),pid:p.id,...x})); addActivity(p,`Conceptplanning van ${plan.length} blokken ingepland via Nova`,'blue'); UI.planWeek=addDays(monday(TODAY),7); },true); return;
  }
  // 11. Conceptbegroting
  if(/begroting/.test(t)&&/(maak|concept|start)/.test(t)){ const p=ctxp; if(!p){ novaSay('Voor welk dossier? Open het projectdossier en vraag het opnieuw.'); return; } if(p.begroting){ const k=calcB(p.begroting); novaSay(`${esc(p.naam)} heeft al begroting ${p.begroting.nr} (${eur(k.totalExcl)} excl. btw). <a href="/begroting-${p.id.toLowerCase()}" data-act="nclose">Open de begroting</a>.`); return; }
    novaPropose({begrepen:`Conceptbegroting voor ${p.naam}.`,data:`Intake: ${p.intake.wensen||'geen wensen vastgelegd'} · type ${p.type}`,changes:['Begroting met 5 standaardhoofdstukken','Uurtarief € 55, AK 8%, W&R 7%','Fase naar Begroting']},()=>{ mkBegroting(p); },true); return; }
  // 12. Facturen open
  if(/factu|openstaa|debiteur/.test(t)){ const open=S.invoices.filter(i=>i.status==='verzonden'); const tot=open.reduce((s,i)=>s+i.bedrag*1.21,0); novaSay(`<b>${open.length} openstaande facturen · ${eur(tot)} incl. btw</b><br>${open.map(i=>`• ${i.nr} ${esc(proj(i.pid).naam)}: ${eur(i.bedrag*1.21)}, vervalt ${fmtD(i.verval)}${i.verval<TODAY?' <b class="dn">vervallen</b>':''}`).join('<br>')}<br><a href="/facturatie" data-act="nclose">Naar facturatie</a>`); return; }
  // 13. Missende prijzen / grootste posten
  if(/(missen|zonder).*(prijs)|prijs ontbreekt/.test(t)){ const p=ctxp&&ctxp.begroting?ctxp:S.projects.find(x=>x.begroting); const ls=[]; eachLine(p.begroting,(l,nr)=>{ if(lineMissing(l)) ls.push({l,nr}); }); novaSay(ls.length?`In ${p.begroting.nr} ${ls.length===1?'mist 1 regel':'missen '+ls.length+' regels'} een prijs:<br>${ls.map(x=>`• ${x.nr} ${esc(x.l.d)}`).join('<br>')}`:'Alle regels hebben een prijs.'); return; }
  if(/grootste|duurste/.test(t)){ const p=ctxp&&ctxp.begroting?ctxp:S.projects.find(x=>x.begroting); const ls=[]; eachLine(p.begroting,(l,nr)=>ls.push({l,nr,v:calcLine(l,+p.begroting.rate||55).totaal})); ls.sort((a,b)=>b.v-a.v); const k=calcB(p.begroting); novaSay(`<b>Grootste kostenposten ${esc(p.naam)}</b><br>${ls.slice(0,5).map(x=>`• ${x.nr} ${esc(x.l.d)}: ${eur(x.v)} (${pct(x.v/k.direct*100)})`).join('<br>')}`); return; }
  // 14. Aanbetaling
  if(/aanbetaling/.test(t)){ const p=ctxp||S.projects.find(x=>S.invoices.some(i=>i.pid===x.id&&i.termijn===0)); const i=S.invoices.find(x=>x.pid===p.id&&x.termijn===0); novaSay(i?`Aanbetaling ${esc(p.naam)}: factuur ${i.nr}, ${eur(i.bedrag*1.21)} incl. btw, status <b>${i.status==='betaald'?'betaald op '+fmtD(i.betaald):i.verval<TODAY?'vervallen sinds '+fmtD(i.verval):i.status}</b>.${i.status!=='betaald'?' Ik registreer geen betaling zonder bevestiging; markeer hem als betaald in Financiën zodra het geld binnen is.':''}`:`Er is nog geen aanbetalingsfactuur voor ${esc(p.naam)}.`); return; }
  // 15. Voortgang
  if(/voortgang|status|samenvat/.test(t)){ if(ctxp){ const p=ctxp, f=projectFin(p); const op=S.tasks.filter(x=>x.pid===p.id&&x.status!=='afgerond'); novaSay(`<b>${esc(p.naam)} · ${PHASES[p.phase]}</b><br>Voortgang ${p.progress}%${p.phase===6?` (planning ${p.planned}%)`:''}. Oplevering gepland ${fmtDY(p.eind)}.<br>Contract ${eur(f.val)}, gefactureerd ${eur(f.gefact)}, betaald ${eur(f.betaald)}.<br>${op.length} open taken${op.filter(x=>x.dl<TODAY).length?', waarvan '+op.filter(x=>x.dl<TODAY).length+' verlopen':''}.<br>Aandachtspunten: ${novaInsights(p).map(x=>x.t).join('; ')}.`); }
    else { const u=S.projects.filter(p=>p.phase===6); novaSay(`<b>${u.length} projecten in uitvoering</b><br>${u.map(p=>`• ${esc(p.naam)}: ${p.progress}%${p.planned-p.progress>=5?' (achter)':''}`).join('<br>')}`); } return; }
  if(novaR2(t)) return;
  novaSay(`Dat herken ik nog niet. Ik kan onder meer:<br>• werkbonnen, certificaten en prijsaanvragen tonen<br>• taken en terugbelafspraken maken<br>• intake of projectvoortgang samenvatten<br>• begrotingsposten aanpassen en marge-scenario's doorrekenen<br>• betalingsschema's verdelen<br>• conceptplanning en beschikbaarheid<br>• openstaande facturen en achterlopende projecten tonen`);
  } finally { renderNova(); }
}
let recog=null;
function toggleMic(){ const SR=window.SpeechRecognition||window.webkitSpeechRecognition; if(!SR) return; const btn=document.querySelector('.mic');
  if(recog){ recog.stop(); return; }
  recog=new SR(); recog.lang='nl-NL'; recog.interimResults=true; btn.classList.add('on');
  recog.onresult=e=>{ $('#nvin').value=[...e.results].map(r=>r[0].transcript).join(''); };
  recog.onerror=e=>{ toast(e.error==='not-allowed'||e.error==='service-not-allowed'?'Microfoon geweigerd of niet beschikbaar hier. Typ je opdracht.':'Spraakherkenning gestopt: '+e.error,'warn'); };
  recog.onend=()=>{ btn?.classList.remove('on'); recog=null; const v=$('#nvin')?.value.trim(); if(v){ $('#nvin').value=''; novaAsk(v); } };
  try{ recog.start(); }catch(e){ recog=null; btn.classList.remove('on'); toast('Spraak kon niet starten. Typ je opdracht.','warn'); }
}

/* ---------- Search ---------- */
function doSearch(q){
  const box=$('#sres'); q=q.trim().toLowerCase(); if(q.length<2){ box.hidden=true; return; }
  const m=s=>String(s||'').toLowerCase().includes(q);
  const groups=[
    ['Projectdossiers',S.projects.filter(p=>m(p.naam)||m(p.id)||m(p.plaats)||m(client(p.clientId).naam)).slice(0,5).map(p=>({go:'project-'+p.id.toLowerCase(),t:p.naam,s:`${p.id} · ${client(p.clientId).naam} · ${PHASES[p.phase]}`,i:'folder'}))],
    ['Klanten',S.clients.filter(c=>m(c.naam)||m(c.contact)||m(c.mail)).slice(0,4).map(c=>{ const p=S.projects.find(p=>p.clientId===c.id); return {go:p?'project-'+p.id.toLowerCase():'klanten',t:c.naam,s:`${c.contact} · ${c.plaats}`,i:'users'}; })],
    ['Offertes',S.projects.filter(p=>p.offerte&&(m(p.offerte.nr))).map(p=>({go:'project-'+p.id.toLowerCase(),tab:'offerte',pid:p.id,t:p.offerte.nr,s:p.naam,i:'file'}))],
    ['Taken',S.tasks.filter(t=>m(t.titel)).slice(0,5).map(t=>({task:t.id,t:t.titel,s:(proj(t.pid)||{naam:'Intern'}).naam,i:'checksq'}))],
    ['Medewerkers',S.emps.filter(e=>m(e.naam)||m(e.rol)).slice(0,4).map(e=>({go:'workforce',t:e.naam,s:e.rol,i:'team'}))],
    ['Werkbonnen',S.werkbonnen.filter(w=>m(w.nr)||m(w.titel)).slice(0,4).map(w=>({go:'werkbon-'+w.nr.toLowerCase(),t:w.nr+' · '+w.titel,s:(proj(w.pid)||{naam:''}).naam,i:'wrench'}))],
    ['Onderaannemers',S.subs.filter(x=>m(x.naam)||m(x.vak)||m(x.contact)).slice(0,4).map(x=>({go:'onderaannemers',t:x.naam,s:x.vak+' · '+KEUR[subStatus(x)][0],i:'handshake'}))],
    ['Prijsaanvragen',S.rfqs.filter(r=>m(r.id)||m(r.titel)).slice(0,4).map(r=>({go:'prijsaanvraag-'+r.id.toLowerCase(),t:r.id+' · '+r.titel,s:PA_ST[r.status][0],i:'store'}))],
    ['Documenten',S.projects.flatMap(p=>p.docs.filter(d=>m(d.naam)).map(d=>({go:'project-'+p.id.toLowerCase(),tab:'documenten',pid:p.id,t:d.naam,s:p.naam,i:'file'})) ).slice(0,4)],
  ].filter(g=>g[1].length);
  UI.sres=groups.flatMap(g=>g[1]);
  let idx=0; box.innerHTML=groups.length?groups.map(([g,items])=>`<h6>${g}</h6>${items.map(x=>`<button data-act="sres" data-i="${idx++}">${ic(x.i)}<span><b>${esc(x.t)}</b><small>${esc(x.s)}</small></span></button>`).join('')}`).join(''):`<div class="empty" style="padding:16px">Niets gevonden voor "${esc(q)}".</div>`;
  box.hidden=false;
}

/* ---------- Events ---------- */
function menuAt(btn,html){ closeMenus(); const r=btn.getBoundingClientRect(); const m=document.createElement('div'); m.className='menu'; m.id='popmenu'; m.innerHTML=html; document.body.appendChild(m); const w=m.offsetWidth; m.style.top=(r.bottom+6+window.scrollY)+'px'; m.style.left=Math.max(12,Math.min(window.innerWidth-w-12,r.right-w))+'px'; }
function closeMenus(){ $('#popmenu')?.remove(); }
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-act],[data-go]'); if(!$('#popmenu')?.contains(e.target)&&!e.target.closest('#plusbtn,[data-act="usermenu"],#notifbtn')) closeMenus();
  if(!e.target.closest('.search')) $('#sres').hidden=true;
  if(!el) return;
  const a=el.dataset.act, d=el.dataset;
  if(!a&&d.go){ e.preventDefault(); go(d.go); return; }
  switch(a){
    case 'burger': { const s=$('#side'); s.classList.toggle('open'); if(s.classList.contains('open')){ const sc=document.createElement('div'); sc.className='scrim'; sc.dataset.act='scrim'; document.body.appendChild(sc);} else document.querySelector('.scrim')?.remove(); break; }
    case 'scrim': $('#side').classList.remove('open'); el.remove(); break;
    case 'ngroup': UI.collapsed[d.g]=!UI.collapsed[d.g]; saveUI(); renderSide(); break;
    case 'nova': e.preventDefault(); UI.novaOpen=true; renderNova(); break;
    case 'nclose': if(el.tagName==='A'&&!matchMedia('(max-width: 900px)').matches) break; closeNova(); break;
    case 'novaask': novaAsk(d.q); break;
    case 'mic': toggleMic(); break;
    case 'pok': { const f=UI.pending[d.id]; if(!f) break; const r=f(); delete UI.pending[d.id]; UI.novaMsgs.find(m=>m.id===d.id).state='ok'; save(); render(); novaSay('Uitgevoerd. '+(r||'De wijziging is verwerkt in alle gekoppelde onderdelen.')); renderNova(); toast('Nova-actie uitgevoerd'); break; }
    case 'px': delete UI.pending[d.id]; UI.novaMsgs.find(m=>m.id===d.id).state='x'; renderNova(); break;
    case 'pedit': { const m=UI.novaMsgs.find(m=>m.id===d.id); const idx=UI.novaMsgs.indexOf(m); const u=UI.novaMsgs.slice(0,idx).reverse().find(x=>x.r==='u'); m.state='x'; delete UI.pending[d.id]; renderNova(); $('#nvin').value=u?u.t:''; $('#nvin').focus(); break; }
    case 'plus': menuAt(el,`<button data-act="newlead">${ic('funnel')}Nieuwe aanvraag / lead</button><button data-act="newtask">${ic('checksq')}Taak</button><button data-act="newappt">${ic('cal')}Afspraak</button><button data-act="newblock">${ic('team')}Werk inplannen</button><hr><button data-go="calculaties">${ic('calc')}Calculatie</button>`); break;
    case 'usermenu': menuAt(el,`<button data-act="theme">${ic('moon')}Donker / licht wisselen</button><button data-act="os-motion">${ic('bolt')}Animaties ${moPref()?'uit':'aan'}zetten</button><button data-go="instellingen">${ic('gear')}Instellingen</button><hr><button data-act="logout">${ic('logout')}Uitloggen</button>`); break;
    case 'notif': menuAt(el,`<div style="padding:8px 10px" class="lbl">Meldingen</div>${S.notifs.map(n=>`<button>${ic('bell')}<span>${esc(n.t)}<br><small class="muted">${fmtD(n.d)}</small></span></button>`).join('')||'<div class="muted" style="padding:10px">Geen nieuwe meldingen.</div>'}${S.notifs.length?`<hr><button data-act="notifclear">${ic('check')}Alles gelezen</button>`:''}`); break;
    case 'notifclear': S.notifs=[]; closeMenus(); commit(); break;
    case 'theme': { const r=document.documentElement; const dark=r.dataset.theme?r.dataset.theme==='dark':matchMedia('(prefers-color-scheme: dark)').matches; r.dataset.theme=dark?'light':'dark'; try{ localStorage.setItem('rn-theme',r.dataset.theme); }catch(e){} closeMenus(); break; }
    case 'logout': closeMenus(); OSB.flush(); setTimeout(()=>document.getElementById('logoutform').submit(),250); break;
    case 'confirm-ok': { const f=UI._confirm; closeModal(); if(f){ f(); commit('Uitgevoerd'); } break; }
    case 'mclose': closeModal(); break;
    case 'mclose-bg': if(e.target===el) closeModal(); break;
    case 'submit': submitForm(document.querySelector('#layer form')); break;
    case 'newtask': closeMenus(); mTask(null,d.pid); break;
    case 'opentask': if(e.target.closest('.chk')) break; mTask(S.tasks.find(t=>t.id===d.id)); break;
    case 'donetask': { e.stopPropagation(); const t=S.tasks.find(t=>t.id===d.id); t.status=t.status==='afgerond'?'todo':'afgerond'; if(t.pid&&t.status==='afgerond') addActivity(proj(t.pid),`Taak afgerond: ${t.titel}`,'ok'); commit(t.status==='afgerond'?'Taak afgerond':'Taak heropend'); break; }
    case 'deltask': S.tasks=S.tasks.filter(t=>t.id!==d.id); closeModal(); commit('Taak verwijderd'); break;
    case 'newlead': closeMenus(); mLead(); break;
    case 'newappt': closeMenus(); mAppt(); break;
    case 'newblock': closeMenus(); mBlock(null,d.pid); break;
    case 'editblock': mBlock(S.blocks.find(b=>b.id===d.id)); break;
    case 'delblock': S.blocks=S.blocks.filter(b=>b.id!==d.id); closeModal(); commit('Planning verwijderd'); break;
    case 'att': { const it=attention()[+d.i]; if(!it) break; if(it.tab) UI.pdTab[it.go.slice(8).toUpperCase()]=it.tab; if(it.week){ UI.planWeek=it.week; UI.planView='week'; } if(it.wbTab) UI.wbTab=it.wbTab; if(it.wfTab) UI.wfTab=it.wfTab; go(it.go); break; }
    case 'projf': UI.projFilter=d.f; render(); break;
    case 'pdtab': UI.pdTab[d.pid]=d.t; if(route()!=='project-'+d.pid.toLowerCase()) go('project-'+d.pid.toLowerCase()); else render(); break;
    case 'phaseclick': { const map=['intake','intake','begroting','offerte','offerte','planning','planning','overzicht','activiteiten']; UI.pdTab[d.pid]=map[+d.i]; render(); break; }
    case 'progress': { const p=proj(d.pid); p.progress=Math.max(0,Math.min(100,p.progress+(+d.d))); if(p.progress===100&&p.phase===6){ p.phase=7; addActivity(p,'Uitvoering gereed, fase Oplevering','ok'); } commit(`Voortgang ${p.progress}%`); break; }
    case 'copy': { const v=d.v; if(!v){ toast('Geen telefoonnummer bekend','warn'); break; } try{ navigator.clipboard.writeText(v).then(()=>toast('Nummer gekopieerd: '+v),()=>toast('Kopiëren niet toegestaan. Nummer: '+v,'warn')); }catch(err){ toast('Nummer: '+v,'warn'); } break; }
    case 'mailklant': { const p=proj(d.pid); const c=client(p.clientId); S.outbox.push({d:TODAY,aan:c.mail,onderwerp:`Projectupdate ${p.naam}`}); addActivity(p,'Projectupdate klaargezet in outbox (niet extern verzonden)','blue'); commit('Update in outbox geplaatst. Er is niets extern verzonden.'); break; }
    case 'mkbegroting': { const p=proj(d.pid); mkBegroting(p); save(); go('begroting-'+p.id.toLowerCase()); toast('Begroting aangemaakt vanuit sjabloon'); break; }
    case 'mkofferte': { const p=proj(d.pid); mkOfferte(p); if(p.phase<3) p.phase=3; commit('Conceptofferte gegenereerd'); break; }
    case 'gooff': { const p=proj(d.pid); UI.pdTab[p.id]='offerte'; go('project-'+p.id.toLowerCase()); break; }
    case 'offupdate': { const p=proj(d.pid); p.offerte.basis=calcB(p.begroting).totalExcl; addActivity(p,`Conceptofferte bijgewerkt naar ${eur(p.offerte.basis)}`,'blue'); commit('Conceptofferte bijgewerkt'); break; }
    case 'offversion': { const p=proj(d.pid); mConfirm('Nieuwe offerteversie',`Versie ${p.offerte.versie} blijft bewaard zoals verzonden. Versie ${p.offerte.versie+1} wordt een nieuw concept ${p.begroting?`op basis van de huidige begroting (${eur(calcB(p.begroting).totalExcl)})`:`met het huidige bedrag (${eur(p.offerte.basis)})`}.`,'Versie maken',()=>{ p.offerte.versie++; p.offerte.status='concept'; if(p.begroting) p.offerte.basis=calcB(p.begroting).totalExcl; p.offerte.sent=null; addActivity(p,`Offerte ${p.offerte.nr} versie ${p.offerte.versie} aangemaakt`,'blue'); }); break; }
    case 'offsend': { const p=proj(d.pid); mConfirm('Offerte verzenden',`Offerte ${p.offerte.nr} v${p.offerte.versie} (${eur(p.offerte.basis*1.21)} incl. btw) wordt vastgezet en in de outbox geplaatst voor ${esc(client(p.clientId).mail)}. Er wordt niets extern verzonden.`,'Verzenden',()=>{ p.offerte.status='verzonden'; p.offerte.sent=TODAY; if(p.phase<3) p.phase=3; S.outbox.push({d:TODAY,aan:client(p.clientId).mail,onderwerp:`Uw offerte ${p.offerte.nr}`}); addActivity(p,`Offerte ${p.offerte.nr} v${p.offerte.versie} verzonden (in de outbox)`,'blue'); }); break; }
    case 'offsign': mSign(proj(d.pid)); break;
    case 'sigclear': { const cv=$('#sigpad'); cv.getContext('2d').clearRect(0,0,cv.width,cv.height); UI.signed=false; break; }
    case 'offpreview': mPreview(proj(d.pid),'off'); break;
    case 'preset': { const p=proj(d.pid); p.termijnen=d.n==='3'?[{oms:'Bij opdracht',pct:40},{oms:'Bij start uitvoering',pct:40},{oms:'Bij oplevering',pct:20}]:[{oms:'Bij opdracht',pct:10},{oms:'Fundering gereed',pct:15},{oms:'Begane grondvloer',pct:10},{oms:'Ruwbouw gereed',pct:15},{oms:'Wind- en waterdicht',pct:15},{oms:'Installaties',pct:10},{oms:'Afbouw',pct:10},{oms:'Oplevering',pct:10},{oms:'Na onderhoudstermijn',pct:5}]; commit(`Schema met ${d.n} termijnen ingesteld`); break; }
    case 'addterm': proj(d.pid).termijnen.push({oms:'Nieuwe termijn',pct:0}); commit(); break;
    case 'delterm': proj(d.pid).termijnen.splice(+d.i,1); commit(); break;
    case 'mkinvoice': { const p=proj(d.pid); const t=p.termijnen[+d.i]; S.seq.fact++; S.invoices.push({nr:'F-'+YEAR+'-'+String(S.seq.fact).padStart(4,'0'),pid:p.id,termijn:+d.i,oms:t.oms,bedrag:r2(p.offerte.basis*t.pct/100),datum:TODAY,verval:addDays(TODAY,14),status:'concept'}); addActivity(p,`Conceptfactuur termijn ${+d.i+1} aangemaakt`,'blue'); commit('Conceptfactuur aangemaakt'); break; }
    case 'sendinv': { const i=S.invoices.find(x=>x.nr===d.nr); i.status='verzonden'; i.datum=TODAY; i.verval=addDays(TODAY,14); addActivity(proj(i.pid),`Factuur ${i.nr} verzonden (in de outbox)`,'blue'); S.outbox.push({d:TODAY,aan:client(proj(i.pid).clientId).mail,onderwerp:`Factuur ${i.nr}`}); commit('Factuur verzonden: de klant ziet hem in het portaal, de mail staat in de outbox'); break; }
    case 'payinv': { const i=S.invoices.find(x=>x.nr===d.nr); mConfirm('Betaling registreren',`Bevestig dat ${eur(i.bedrag*1.21)} voor ${i.nr} is ontvangen. In de demo is dit een handmatige registratie; er is geen bankkoppeling.`,'Markeer betaald',()=>{ i.status='betaald'; i.betaald=TODAY; addActivity(proj(i.pid),`Betaling ${i.nr} geregistreerd: ${eur(i.bedrag*1.21)}`,'ok'); }); break; }
    case 'scrollto': e.preventDefault(); document.getElementById(d.t)?.scrollIntoView({behavior:'smooth'}); break;
    case 'pweek': UI.planWeek=d.d==='0'?monday(TODAY):addDays(UI.planWeek,+d.d); render(); break;
    case 'pjump': UI.planWeek=d.w; render(); break;
    case 'pview': UI.planView=d.v; render(); break;
    case 'ttab': UI.taskTab=d.t; render(); break;
    case 'tview': UI.taskView=d.v; render(); break;
    case 'sres': { const x=UI.sres[+d.i]; $('#sres').hidden=true; $('#gsearch').value=''; if(x.task){ mTask(S.tasks.find(t=>t.id===x.task)); break; } if(x.tab) UI.pdTab[x.pid]=x.tab; go(x.go); break; }
  }
});
function formData(f){ const o={}; new FormData(f).forEach((v,k)=>o[k]=typeof v==='string'?v.trim():v); return o; }
function fieldErr(f,name,msg){ const el=f&&f.querySelector(`[name="${name}"]`); if(!el){ toast(msg,'warn'); return; } el.classList.add('err'); el.focus(); let er=el.parentElement.querySelector('.ferr'); if(!er){ er=document.createElement('div'); er.className='ferr'; el.parentElement.appendChild(er);} er.textContent=msg; }
function submitForm(f){
  if(!f) return; const k=f.dataset.form, v=formData(f);
  if(R2_FORMS[k]) return R2_FORMS[k](f,v);
  if(k==='task'){ if(!v.titel) return fieldErr(f,'titel','Geef de taak een titel.'); const id=f.dataset.id; if(id){ const t=S.tasks.find(t=>t.id===id); Object.assign(t,{titel:v.titel,pid:v.pid,eig:v.eig,dl:v.dl,prio:v.prio,status:v.status,oms:v.oms}); t.checklist.forEach((c,i)=>c.d=!!f.querySelector(`[name="cl${i}"]`)?.checked); } else { S.tasks.push({id:uid('t'),titel:v.titel,pid:v.pid,eig:v.eig,dl:v.dl,prio:v.prio,status:v.status,oms:v.oms,checklist:[]}); if(v.pid) addActivity(proj(v.pid),`Taak aangemaakt: ${v.titel}`,'mut'); } closeModal(); commit(id?'Taak opgeslagen':'Taak aangemaakt'); }
  if(k==='block'){ if(!v.titel) return fieldErr(f,'titel','Omschrijf de werkzaamheden.'); if(!v.start||!v.end) return fieldErr(f,'start','Kies een periode.'); if(v.end<v.start) return fieldErr(f,'end','Einddatum ligt vóór de start.'); const id=f.dataset.id; if(id) Object.assign(S.blocks.find(b=>b.id===id),{titel:v.titel,pid:v.pid,emp:v.emp,start:v.start,end:v.end}); else { S.blocks.push({id:uid('b'),...v}); addActivity(proj(v.pid),`${v.titel} ingepland: ${empName(v.emp)}, ${fmtD(v.start)}–${fmtD(v.end)}`,'blue'); } closeModal(); const cf=conflicts().some(c=>(c.a.emp===v.emp)&&c.day>=v.start&&c.day<=v.end); commit(cf?'Opgeslagen, maar dubbel ingepland':'Ingepland',cf?'warn':'ok'); }
  if(k==='lead'){ if(!v.naam) return fieldErr(f,'naam','Naam is verplicht.'); if(v.mail&&!/^\S+@\S+\.\S+$/.test(v.mail)) return fieldErr(f,'mail','Dit e-mailadres klopt niet.'); const p=createLead(v); closeModal(); save(); go('project-'+p.id.toLowerCase()); toast(`Projectdossier ${p.id} aangemaakt. Taak voor Joris klaargezet.`); }
  if(k==='appt'){ if(!v.titel) return fieldErr(f,'titel','Geef een onderwerp.'); S.agenda.push({id:uid('a'),d:v.d,tijd:v.tijd,titel:v.titel,sub:v.pid?proj(v.pid).naam:'Intern',pid:v.pid}); closeModal(); commit('Afspraak opgeslagen'); }
  if(k==='sign'){ const err=$('#s-err'); if(!v.naam){ err.textContent='Vul de naam van de ondertekenaar in.'; return; } if(!f.akkoord.checked){ err.textContent='Vink de akkoordverklaring aan.'; return; } if(!UI.signed){ err.textContent='Plaats een handtekening in het vak.'; return; } const p=proj(f.dataset.pid); signOfferte(p,v.naam); UI.pdTab[p.id]='overzicht'; closeModal(); commit(`Ondertekend. ${p.id} is geactiveerd: termijnfactuur 1 en 4 taken klaargezet.`); }
}
document.addEventListener('submit',e=>{ e.preventDefault(); const f=e.target; const k=f.dataset.form;
  if(k==='nova'){ const i=$('#nvin'); const v=i.value.trim(); if(v){ i.value=''; novaAsk(v); } return; }
  if(k==='quicktask'){ const v=formData(f); if(!v.titel){ fieldErr(f,'titel','Typ eerst wat er moet gebeuren.'); return; } S.tasks.push({id:uid('t'),titel:v.titel,pid:UI.taskProj||'',eig:v.eig,dl:v.dl,prio:v.prio,status:'todo',oms:'',checklist:[]}); commit('Taak toegevoegd'); setTimeout(()=>$('#qt-titel')?.focus(),20); return; }
  if(k==='intake'){ const p=proj(f.dataset.pid); p.intake=Object.assign(p.intake||{},formData(f)); if(p.phase===0) p.phase=1; addActivity(p,'Intake bijgewerkt','vio'); commit('Intake opgeslagen'); return; }
  submitForm(f);
});
document.addEventListener('input',e=>{
  const t=e.target;
  if(t.id==='gsearch'){ doSearch(t.value); return; }
  if(t.id==='mconv'){ UI.mconv=t.value; const p=proj(t.dataset.pid); $('#mconvout').textContent=mconvText(t.value,calcB(p.begroting).direct); return; }
  if(t.closest('[data-form="block"]')) blockCheck();
  if(t.classList.contains('err')){ t.classList.remove('err'); t.parentElement.querySelector('.ferr')?.remove(); }
});
document.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset.optst){ const p=proj(t.dataset.pid); const o=p.begroting.options[+t.dataset.optst]; o.s=t.value; if(t.value==='akkoord') addActivity(p,`Meerwerk akkoord: ${o.d} (${eur(optPrice(o,p.begroting))})`,'or'); commit(t.value==='akkoord'?`Meerwerk akkoord. Contractwaarde nu ${eur(projectValue(p))}`:'Optie bijgewerkt'); return; }
  if(t.dataset.term){ const p=proj(t.dataset.pid); const tm=p.termijnen[+t.dataset.i]; if(t.dataset.term==='pct') tm.pct=parseFloat(t.value)||0; else tm.oms=t.value; commit(); return; }
  if(t.id==='tproj'){ UI.taskProj=t.value; render(); return; }
  if(t.id==='novamode'){ S.prefs.novaMode=t.value; commit('Werkwijze Nova opgeslagen'); return; }
  if(t.dataset.upload){ const p=proj(t.dataset.upload); for(const fl of t.files){ p.docs.unshift({naam:fl.name,cat:'Upload',datum:TODAY}); addActivity(p,`Document geüpload: ${fl.name}`,'blue'); } commit(`${t.files.length} document(en) toegevoegd`); return; }
  if(t.closest('[data-form="block"]')) blockCheck();
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){ if($('#layer').innerHTML){ $('#layer').innerHTML=''; } else if(UI.novaOpen){ closeNova(); } closeMenus(); $('#sres').hidden=true; }
  if(e.target.id==='gsearch'&&e.key==='Enter'){ const b=$('#sres button'); b&&b.click(); }
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){ e.preventDefault(); $('#gsearch').focus(); }
});

/* ---------- Drag & drop ---------- */
let dragId=null, dragKind=null;
document.addEventListener('dragstart',e=>{ const b=e.target.closest('[data-blk],[data-ktask],[data-lead]'); if(!b) return; dragKind=b.dataset.blk?'blk':b.dataset.ktask?'task':'lead'; dragId=b.dataset.blk||b.dataset.ktask||b.dataset.lead; e.dataTransfer.effectAllowed='move'; try{ e.dataTransfer.setData('text/plain',dragId); }catch(_){} });
document.addEventListener('dragover',e=>{ const c=e.target.closest(dragKind==='blk'?'[data-drop]':dragKind==='task'?'[data-kdrop]':'[data-ldrop]'); if(!c) return; e.preventDefault(); document.querySelectorAll('.over').forEach(x=>x!==c&&x.classList.remove('over')); c.classList.add('over'); });
document.addEventListener('dragleave',e=>{ const c=e.target.closest('.over'); if(c&&!c.contains(e.relatedTarget)) c.classList.remove('over'); });
document.addEventListener('drop',e=>{
  document.querySelectorAll('.over').forEach(x=>x.classList.remove('over'));
  if(dragKind==='blk'){ const c=e.target.closest('[data-drop]'); if(!c) return; e.preventDefault(); const b=S.blocks.find(x=>x.id===dragId); const len=diffDays(b.start,b.end); let ns=c.dataset.day; let ne=addDays(ns,len); if(isWeekend(ne)) ne=addDays(ne,2); const moved=b.emp!==c.dataset.drop||b.start!==ns; b.emp=c.dataset.drop; b.start=ns; b.end=ne; if(!moved) return; const p=proj(b.pid); if(p) addActivity(p,`Planning verplaatst: ${b.titel} → ${empName(b.emp)}, ${fmtD(ns)}`,'blue'); const cf=confIds().has(b.id); commit(cf?`Verplaatst, maar ${firstName(b.emp)} is nu dubbel ingepland`:`Verplaatst naar ${firstName(b.emp)}, ${dayName(ns)} ${fmtD(ns)}`,cf?'warn':'ok'); }
  if(dragKind==='task'){ const c=e.target.closest('[data-kdrop]'); if(!c) return; e.preventDefault(); const t=S.tasks.find(x=>x.id===dragId); t.status=c.dataset.kdrop; commit(`Status: ${TASK_ST[t.status]}`); }
  if(dragKind==='lead'){ const c=e.target.closest('[data-ldrop]'); if(!c) return; e.preventDefault(); const p=proj(dragId); const ph=+c.dataset.ldrop; if(ph===3&&!p.offerte){ toast('Maak eerst een begroting en offerte voordat de lead naar Offerte kan.','warn'); return; } if(ph===2&&!p.begroting){ mkBegroting(p); } p.phase=ph; addActivity(p,`Salesfase gewijzigd naar ${PHASES[ph]}`,'vio'); commit(`${client(p.clientId).naam} → ${PHASES[ph]}`); }
  dragId=null; dragKind=null;
});
function afterRender(r){ if(r.startsWith('begroting-')) loadBegFrame(); r2AfterRender(r); }

