Object.assign(P,{
  bell:'<path d="M6 8a6 6 0 1 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.9 1.9 0 0 0 3.4 0"/>',
  camera:'<path d="M4 7h3l2-3h6l2 3h3a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V8a1 1 0 0 1 1-1z"/><circle cx="12" cy="13" r="4"/>',
  play:'<path d="M7 4v16l13-8z"/>',
  shield:'<path d="M12 3 4 6v6c0 4.5 3.4 8 8 9 4.6-1 8-4.5 8-9V6z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',
  scan:'<path d="M4 8V5a1 1 0 0 1 1-1h3M16 4h3a1 1 0 0 1 1 1v3M20 16v3a1 1 0 0 1-1 1h-3M8 20H5a1 1 0 0 1-1-1v-3"/><path d="M8 9h8M8 12h8M8 15h5"/>',
  back:'<path d="M9 14 4 9l5-5"/><path d="M4 9h10a6 6 0 0 1 0 12h-1"/>',
  star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1L3.2 9.5l6.1-.9z"/>',
});

const WB_ST=[['concept','Concept','mut'],['gepland','Gepland','blue'],['uitgegeven','Uitgegeven','vio'],['uitvoering','In uitvoering','or'],['controle','Ter controle','warn'],['goedgekeurd','Goedgekeurd','ok'],['afgesloten','Afgesloten','mut']];
const wbIdx = s => WB_ST.findIndex(x=>x[0]===s);
const wbPill = s => { const x=WB_ST.find(y=>y[0]===s)||WB_ST[0]; return `<span class="pill ${x[2]}"><span class="d"></span>${x[1]}</span>`; };
const KEUR={nieuw:['Nieuw','mut'],beoordeling:['In beoordeling','blue'],goedgekeurd:['Goedgekeurd','ok'],ontbreekt:['Document ontbreekt','warn'],verlopen:['Document verlopen','bad'],geblokkeerd:['Tijdelijk geblokkeerd','bad']};
