/* demomigratie overgeslagen: de structuur staat in de fabrieksstaat */

/* ---------- Afgeleide functies ---------- */
const sub = id => (S.subs||[]).find(s=>s.id===id);
const docState = d => { if(d.ok===false) return 'ontbreekt'; if(d.g&&d.g<TODAY) return 'verlopen'; if(d.g&&diffDays(TODAY,d.g)<=30) return 'binnenkort'; return 'ok'; };
const docPill = d => { const s=docState(d); return s==='ok'?`<span class="pill ok">${d.g?'Geldig t/m '+fmtD(d.g)+' '+D(d.g).getFullYear():'In orde'}</span>`:s==='binnenkort'?`<span class="pill warn">Verloopt ${fmtD(d.g)}</span>`:s==='verlopen'?`<span class="pill bad">Verlopen ${fmtD(d.g)}</span>`:'<span class="pill bad">Ontbreekt</span>'; };
function subStatus(s){ if(s.blocked) return 'geblokkeerd'; const st=s.docs.map(docState); if(st.includes('verlopen')) return 'verlopen'; if(st.includes('ontbreekt')) return 'ontbreekt'; return s.keurmerk; }
const keurPill = s => { const k=KEUR[subStatus(s)]; return `<span class="pill ${k[1]}">${ic('shield')}${k[0]}</span>`; };
const certState = c => docState({g:c.g,ok:true});
function allCerts(){ const out=[]; for(const e of S.emps) for(const c of e.certs||[]) out.push({wie:e.naam,rol:e.rol,type:e.type,c,emp:e.id}); for(const s of S.subs) for(const d of s.docs) if(d.g) out.push({wie:s.naam,rol:s.vak,type:'bedrijf',c:{t:d.t,g:d.g},sub:s.id}); return out.sort((a,b)=>(a.c.g||'9')<(b.c.g||'9')?-1:1); }
function weekRange(off){ const s=addDays(monday(TODAY),7*off); return [s,addDays(s,4)]; }
function plannedHours(empId,a,b){ return S.blocks.filter(x=>x.emp===empId&&x.end>=a&&x.start<=b).reduce((s,x)=>s+workdays(x.start<a?a:x.start,x.end>b?b:x.end)*8,0); }
function absentDays(e,a,b){ let n=0; for(const ab of e.afwezig||[]){ const s=ab.van>a?ab.van:a, z=ab.tot<b?ab.tot:b; if(s<=z) n+=workdays(s,z); } return n; }
function isFree(empId,a,b){ const e=emp(empId); return !S.blocks.some(x=>x.emp===empId&&x.start<=b&&a<=x.end) && !(e.afwezig||[]).some(ab=>ab.van<=b&&a<=ab.tot); }
const wb = nr => S.werkbonnen.find(w=>w.nr===nr);
const pa = id => S.rfqs.find(r=>r.id===id);
const awardBid = r => r.bids.find(b=>b.sub===r.awardedTo);
const awardPrice = r => (awardBid(r)||{prijs:0}).prijs;
function paCommitments(pid){ const rs=S.rfqs.filter(r=>r.pid===pid&&(r.status==='gegund'||r.status==='afgerond')); return {verpl:rs.filter(r=>r.status==='gegund').reduce((s,r)=>s+awardPrice(r),0),delta:rs.reduce((s,r)=>s+awardPrice(r)-r.budget,0),n:rs.length}; }
function projHours(pid){ return S.werkbonnen.filter(w=>w.pid===pid&&wbIdx(w.status)>=wbIdx('goedgekeurd')).reduce((s,w)=>s+(+w.uren||0),0); }
function wbShare(w){ const p=proj(w.pid); const tot=p&&p.begroting?calcB(p.begroting).uren:0; const base=tot>0?tot:Math.max(80,S.werkbonnen.filter(x=>x.pid===w.pid).reduce((s,x)=>s+x.begrUren,0)); return Math.min(25,Math.round(w.begrUren/base*100)); }

/* ---------- Werkbonnen ---------- */
function vWerkbonnen(){
  const f=UI.wbTab||'open'; const [a,b]=weekRange(0);
  const list=S.werkbonnen.filter(w=>f==='alle'||(f==='open'&&wbIdx(w.status)<wbIdx('goedgekeurd'))||w.status===f).sort((x,y)=>x.datum<y.datum?-1:1);
  const cnt=k=>S.werkbonnen.filter(w=>w.status===k).length;
  const urenWk=S.werkbonnen.filter(w=>w.datum>=a&&w.datum<=b).reduce((s,w)=>s+(+w.uren||0),0), begrWk=S.werkbonnen.filter(w=>w.datum>=a&&w.datum<=b).reduce((s,w)=>s+w.begrUren,0);
  const tabs=[['open','Open'],['uitvoering','In uitvoering'],['controle','Ter controle'],['goedgekeurd','Goedgekeurd'],['afgesloten','Afgesloten'],['alle','Alle']];
  return `<div class="page"><div class="ph"><div><h1>Werk<em>bonnen</em></h1><p>Digitale werkbonnen per planningsblok. Afronden en goedkeuren werkt door in de uren, de projectvoortgang en de taken.</p></div>
    <div class="acts"><button class="btn" data-act="wb-paper">${ic('scan')}Papieren werkbon uitlezen</button><button class="btn pri" data-act="wb-new">${ic('plus')}Werkbon</button></div></div>
  <div class="grid kpis"><div class="card kpi dark"><span class="lbl">Uren deze week</span><span class="v num">${NUM.format(urenWk)}<b style="font-size:18px;color:var(--on-navy-2)"> / ${begrWk} u</b></span><span class="s">geregistreerd tegenover begroot</span></div>
    <div class="card kpi"><span class="lbl">In uitvoering</span><span class="v num">${cnt('uitvoering')}</span><span class="s">${cnt('uitgegeven')} uitgegeven aan vakmensen</span></div>
    <div class="card kpi"><span class="lbl">Ter controle</span><span class="v num ${cnt('controle')?'dn':''}">${cnt('controle')}</span><span class="s">wachten op goedkeuring</span></div>
    <div class="card kpi"><span class="lbl">Afgerond</span><span class="v num">${cnt('goedgekeurd')+cnt('afgesloten')}</span><span class="s">goedgekeurd of afgesloten</span></div></div>
  <div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${f===k?'on':''}" data-act="wb-tab" data-t="${k}">${l}${k!=='alle'&&k!=='open'?`<span class="c">${cnt(k)}</span>`:''}</button>`).join('')}</div>
  <div class="card">${list.length?`<div class="tw"><table class="t"><thead><tr><th>Werkbon</th><th>Project / adres</th><th>Vakman</th><th>Datum</th><th class="r">Uren</th><th>Checklist</th><th>Status</th></tr></thead><tbody>
  ${list.map(w=>{ const p=proj(w.pid)||{naam:'—',adres:'',plaats:''}; const dn=w.checklist.filter(c=>c.d).length; const over=w.uren>w.begrUren*1.1&&w.uren>0; return `<tr class="click" data-go="werkbon-${w.nr.toLowerCase()}"><td><b>${w.nr}</b><div class="sub">${esc(w.titel)}</div></td><td>${esc(p.naam)}<div class="sub">${esc([p.adres,p.plaats].filter(Boolean).join(', '))}</div></td><td><div class="row" style="gap:8px">${avatar(empName(w.emp),'sm')}${esc(firstName(w.emp))}</div></td><td>${fmtD(w.datum)}${w.eind&&w.eind!==w.datum?' – '+fmtD(w.eind):''}</td><td class="r"><span class="${over?'dn':''}">${NUM.format(+w.uren||0)}</span> <span class="muted">/ ${w.begrUren}</span></td><td style="min-width:120px"><div class="bar ${dn===w.checklist.length?'ok':''}"><i style="width:${w.checklist.length?dn/w.checklist.length*100:0}%"></i></div><div class="sub">${dn}/${w.checklist.length}</div></td><td>${wbPill(w.status)}${w.obstakels&&wbIdx(w.status)<wbIdx('afgesloten')?' <span class="pill warn" title="Obstakel gemeld">'+ic('alert')+'</span>':''}</td></tr>`; }).join('')}
  </tbody></table></div>`:`<div class="empty">${ic('wrench')}Geen werkbonnen in deze weergave.</div>`}</div></div>`;
}
function vWerkbon(nr){
  const w=wb(nr); if(!w) return `<div class="page"><div class="empty">Werkbon ${esc(nr)} niet gevonden. <a class="btn" href="/werkbonnen">Naar werkbonnen</a></div></div>`;
  const p=proj(w.pid)||{naam:'—',adres:'',plaats:'',clientId:''}; const c=client(p.clientId); const si=wbIdx(w.status); const e=emp(w.emp)||{naam:'—',rol:''};
  const editable=w.status==='uitvoering'; const dn=w.checklist.filter(x=>x.d).length;
  // Mobiele werkhub (vakman)
  let phone=`<div class="phone"><div class="phone-top"><span>Renovion Werkhub</span><span>${esc(firstName(w.emp))} · ${esc(e.rol)}</span></div>
    <div class="phone-h"><span class="eyebrow">${w.nr} · ${cap(dayName(w.datum))} ${fmtD(w.datum)}</span><h3>${esc(w.titel)}</h3><small>${esc(p.naam)}</small><small>${ic('pin').replace('<svg','<svg style="width:12px;height:12px;vertical-align:-1px"')} ${esc([p.adres,p.plaats].filter(Boolean).join(', '))}</small></div>`;
  if(w.status==='concept'||w.status==='gepland') phone+=`<div class="alert info">${ic('clock')}<div class="grow">Deze werkbon is nog niet uitgegeven. De vakman ziet hem zodra kantoor hem uitgeeft.</div></div>`;
  if(w.status==='uitgegeven') phone+=`<div class="ph-sec"><span class="lbl">Wat ga je doen</span>${w.checklist.map(x=>`<div class="cl-item" style="cursor:default">${ic('chev')}<span style="text-decoration:none;color:inherit">${esc(x.t)}</span></div>`).join('')}</div>
    <div class="ph-sec"><span class="lbl">Materialen klaarleggen</span><div class="card card-b" style="padding:10px 14px">${w.materialen.map(m=>`<div class="sumrow"><span>${esc(m.t)}</span><span>${NUM.format(m.q)} ${esc(m.u)}</span></div>`).join('')||'<span class="muted">Geen materialen opgegeven.</span>'}</div></div>
    <div class="kv"><span>Contact op locatie</span><b>${esc(c.contact||c.naam)} · ${esc(c.tel||'geen nummer')}</b><span>Begroot</span><b>${w.begrUren} uur</b></div>
    <button class="btn pri bigbtn" data-act="wb-start" data-nr="${w.nr}">${ic('play')}Start werkbon</button>`;
  if(si>=wbIdx('uitvoering')){
    phone+=`<div class="ph-sec"><div class="row between"><span class="lbl">Checklist</span><span class="muted" style="font-size:12px">${dn}/${w.checklist.length}</span></div>${w.checklist.map((x,i)=>`<button class="cl-item ${x.d?'on':''}" ${editable?`data-act="wb-chk" data-nr="${w.nr}" data-i="${i}"`:'disabled'}><span class="chk ${x.d?'on':''}">${x.d?ic('check'):''}</span><span>${esc(x.t)}</span></button>`).join('')}</div>
    <div class="ph-sec"><span class="lbl">Gewerkte uren</span><div class="uren-ctl">${editable?`<button class="round" data-act="wb-uren" data-nr="${w.nr}" data-d="-0.5" aria-label="Halfuur minder">−</button>`:'<span></span>'}<div style="text-align:center"><b>${NUM.format(+w.uren||0)}</b><div class="muted" style="font-size:11.5px">van ${w.begrUren} begroot</div></div>${editable?`<button class="round" data-act="wb-uren" data-nr="${w.nr}" data-d="0.5" aria-label="Halfuur meer">+</button>`:'<span></span>'}</div></div>
    <div class="ph-sec"><span class="lbl">Foto’s</span><div class="thumbs">${w.fotos.map(f=>`<img src="${f.src}" alt="${esc(f.naam)}">`).join('')}${editable?`<label class="ph-add" title="Foto toevoegen">${ic('camera')}<input type="file" accept="image/*" hidden multiple data-wbfoto="${w.nr}"></label>`:''}</div>${!w.fotos.length&&!editable?'<span class="muted" style="font-size:12px">Geen foto’s.</span>':''}</div>
    <div class="ph-sec"><label class="lbl" for="wb-opm">Opmerkingen</label><textarea class="in" id="wb-opm" data-wbf="opm" data-nr="${w.nr}" ${editable?'':'readonly'} placeholder="Wat is er gedaan?">${esc(w.opm)}</textarea></div>
    <div class="ph-sec"><label class="lbl" for="wb-obs">Obstakels of afwijkingen</label><textarea class="in" id="wb-obs" data-wbf="obstakels" data-nr="${w.nr}" ${editable?'':'readonly'} placeholder="Bijv. leiding ligt anders dan op tekening">${esc(w.obstakels)}</textarea></div>`;
    if(editable) phone+=`<div class="ph-sec"><span class="lbl">Aftekenen door klant of uitvoerder</span><canvas class="sig" id="wbsig" aria-label="Handtekeningveld"></canvas><div class="row between"><input class="in" id="wb-signame" placeholder="Naam" value="${esc(c.contact||'')}" style="max-width:220px"><button type="button" class="btn xs ghost" data-act="wb-sigclear">Wissen</button></div></div>
      <div class="ferr" id="wb-err"></div><button class="btn pri bigbtn" data-act="wb-finish" data-nr="${w.nr}">${ic('check')}Afronden en indienen</button>`;
    else phone+=`<div class="alert ${si>=wbIdx('goedgekeurd')?'info':'warn'}">${ic(si>=wbIdx('goedgekeurd')?'check':'clock')}<div class="grow">${w.getekend?`Afgetekend door <b>${esc(w.getekend)}</b>. `:''}${w.status==='controle'?'Wacht op goedkeuring door kantoor.':'Goedgekeurd en verwerkt.'}</div></div>`;
  }
  phone+=`</div>`;
  // Backoffice
  const acts={concept:`<button class="btn pri" data-act="wb-set" data-nr="${w.nr}" data-s="gepland">Inplannen</button>`,gepland:`<button class="btn pri" data-act="wb-set" data-nr="${w.nr}" data-s="uitgegeven">${ic('send')}Uitgeven aan ${esc(firstName(w.emp))}</button>`,uitgegeven:`<span class="muted" style="font-size:12.5px">Wacht tot de vakman de werkbon start.</span>`,uitvoering:`<span class="muted" style="font-size:12.5px">De vakman werkt aan deze werkbon.</span>`,
    controle:`<button class="btn pri" data-act="wb-approve" data-nr="${w.nr}">${ic('check')}Goedkeuren en verwerken</button><button class="btn" data-act="wb-set" data-nr="${w.nr}" data-s="uitvoering">${ic('back')}Terugsturen</button>`,goedgekeurd:`<button class="btn" data-act="wb-set" data-nr="${w.nr}" data-s="afgesloten">${ic('lock')}Afsluiten</button>`,afgesloten:''}[w.status];
  const task=S.tasks.find(t=>t.id===w.taskId); const tarief=+e.tarief||50; const share=wbShare(w);
  const back=`<div class="stack" style="gap:14px">
    <div class="card card-b"><div class="stepper">${WB_ST.map((s,i)=>`<div class="step ${i<si?'done':i===si?'cur':''}"><span class="o">${i<si?ic('check'):i+1}</span><span>${s[1]}</span></div>`).join('')}</div></div>
    <div class="card"><div class="card-h"><h3>Kantoor<em>weergave</em></h3>${wbPill(w.status)}</div><div class="card-b stack">
      <div class="kv"><span>Projectdossier</span><a href="/project-${w.pid.toLowerCase()}" style="font-weight:600">${w.pid} · ${esc(p.naam)}</a><span>Vakman</span><b>${esc(e.naam)} · ${esc(e.rol)}</b><span>Periode</span><b>${fmtDY(w.datum)}${w.eind&&w.eind!==w.datum?' t/m '+fmtDY(w.eind):''}</b><span>Begroot</span><b>${w.begrUren} uur · ${eur(w.begrUren*tarief)}</b><span>Geregistreerd</span><b class="${w.uren>w.begrUren*1.1?'dn':''}">${NUM.format(+w.uren||0)} uur · ${eur((+w.uren||0)*tarief)}</b>${task?`<span>Gekoppelde taak</span><b>${esc(task.titel)} ${stPill(task.status)}</b>`:''}</div>
      ${w.obstakels?`<div class="alert warn">${ic('alert')}<div class="grow"><b>Obstakel gemeld:</b> ${esc(w.obstakels)}</div></div>`:''}
      ${w.status==='controle'?`<div class="calcbox"><b>Bij goedkeuren gebeurt dit</b><div>• ${NUM.format(+w.uren||0)} uur wordt geboekt op ${w.pid} (${eur((+w.uren||0)*tarief)} arbeidskosten)</div><div>• Projectvoortgang +${share}% (aandeel van deze werkbon in de begrote uren)</div>${task?`<div>• Taak "${esc(task.titel)}" wordt afgerond</div>`:''}<div>• Activiteit in het projectdossier</div></div>`:''}
      <div class="acts">${acts}${w.status!=='afgesloten'?`<button class="btn ghost" data-act="wb-edit" data-nr="${w.nr}">${ic('edit')}Bewerken</button>`:''}</div></div></div>
    <div class="card"><div class="card-h"><h3>Logboek</h3></div><div class="card-b">${timeline(w.log.slice().reverse().map(x=>({d:x.d,t:x.t,k:'blue'})))}</div></div></div>`;
  return `<div class="page"><div class="ph"><div><div class="crumb" style="color:var(--muted);margin-bottom:6px"><a href="/werkbonnen">Werkbonnen</a>${ic('chev')}<span>${w.nr}</span></div><h1>${esc(w.titel)}</h1><p>${esc(p.naam)} · ${esc(e.naam)}</p></div></div>
  <div class="wb-cols">${phone}${back}</div></div>`;
}
function mWerkbon(w,pid,blockId){
  const n=!w; const bl=blockId&&S.blocks.find(b=>b.id===blockId);
  w=w||{pid:pid||(bl&&bl.pid)||'',emp:(bl&&bl.emp)||osField(),titel:(bl&&bl.titel)||'',datum:(bl&&bl.start)||addDays(TODAY,1),eind:(bl&&bl.end)||addDays(TODAY,1),begrUren:bl?workdays(bl.start,bl.end)*8:8,checklist:[],materialen:[],opm:''};
  modal(n?'Nieuwe werkbon':'Werkbon '+w.nr+' bewerken',`<form class="fg" data-form="werkbon" data-nr="${n?'':w.nr}" data-block="${blockId||''}">
    <div class="f full"><label for="w-titel">Werkzaamheden</label><input class="in" id="w-titel" name="titel" value="${esc(w.titel)}" required></div>
    <div class="f"><label for="w-pid">Projectdossier</label><select class="in" id="w-pid" name="pid">${projOpts(w.pid,false)}</select></div>
    <div class="f"><label for="w-emp">Vakman</label><select class="in" id="w-emp" name="emp">${empOpts(w.emp,e=>e.type!=='kantoor')}</select></div>
    <div class="f"><label for="w-datum">Van</label><input class="in" type="date" id="w-datum" name="datum" value="${w.datum}"></div>
    <div class="f"><label for="w-eind">Tot en met</label><input class="in" type="date" id="w-eind" name="eind" value="${w.eind||w.datum}"></div>
    <div class="f"><label for="w-begr">Begrote uren</label><input class="in" type="number" min="0" step="0.5" id="w-begr" name="begrUren" value="${w.begrUren}"></div>
    <div class="f"><label for="w-task">Koppel aan taak</label><select class="in" id="w-task" name="taskId"><option value="">Geen</option>${S.tasks.filter(t=>t.status!=='afgerond').map(t=>`<option value="${t.id}" ${w.taskId===t.id?'selected':''}>${esc(t.titel)} · ${esc((proj(t.pid)||{naam:'Intern'}).naam)}</option>`).join('')}</select></div>
    <div class="f full"><label for="w-cl">Checklist (één punt per regel)</label><textarea class="in" id="w-cl" name="checklist" placeholder="Werkplek voorbereiden&#10;…">${esc(w.checklist.map(c=>c.t).join('\n'))}</textarea></div>
    <div class="f full"><label for="w-mat">Materialen (aantal eenheid omschrijving, één per regel)</label><textarea class="in" id="w-mat" name="materialen" placeholder="6 zak Tegellijm C2TE">${esc(w.materialen.map(m=>`${NUM.format(m.q)} ${m.u} ${m.t}`).join('\n'))}</textarea></div>
  </form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">${n?'Werkbon aanmaken':'Opslaan'}</button>`);
}
function parseMat(txt){ return String(txt||'').split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{ const m=l.match(/^([\d.,]+)\s+(\S+)\s+(.+)$/); return m?{q:parseNL(m[1]),u:m[2],t:m[3]}:{q:1,u:'st',t:l}; }); }
function mPaper(){
  UI.paper=null;
  modal('Papieren werkbon uitlezen',`<div class="alert info">${ic('scan')}<div class="grow">Upload een foto of scan van de papieren werkbon. De foto wordt bij de werkbon bewaard; controleer en vul de velden zelf aan.</div></div>
    <label class="btn" style="align-self:flex-start;cursor:pointer">${ic('upload')}Foto of PDF kiezen<input type="file" accept="image/*,application/pdf" hidden id="paperfile"></label><div id="paperprev"></div>`,`<button class="btn" data-act="mclose">Annuleren</button>`);
}
function paperForm(name,src){
  const p=S.projects.find(x=>x.phase===6)||S.projects[0];
  $('#paperprev').innerHTML=`<div class="extract"><b>Gesimuleerde uitlezing van ${esc(name)}</b> · controleer alle velden</div>${src?`<img src="${src}" alt="" style="max-height:160px;border-radius:10px;border:1px solid var(--border)">`:''}
  <form class="fg" data-form="paper"><div class="f full"><label for="pp-titel">Werkzaamheden</label><input class="in" id="pp-titel" name="titel" value="Herstel lekkage afvoer keuken"></div>
  <div class="f"><label for="pp-pid">Projectdossier</label><select class="in" id="pp-pid" name="pid">${projOpts(p.id,false)}</select></div><div class="f"><label for="pp-emp">Vakman</label><select class="in" id="pp-emp" name="emp">${empOpts(osField(),e=>e.type!=='kantoor')}</select></div>
  <div class="f"><label for="pp-d">Datum</label><input class="in" type="date" id="pp-d" name="datum" value="${addDays(TODAY,-1)}"></div><div class="f"><label for="pp-u">Gewerkte uren</label><input class="in" type="number" step="0.5" id="pp-u" name="uren" value="3.5"></div>
  <div class="f full"><label for="pp-opm">Opmerkingen</label><textarea class="in" id="pp-opm" name="opm">Sifon vervangen, afvoer doorgespoten. Klant tekende af.</textarea></div>
  <div class="f full"><label for="pp-sig">Afgetekend door</label><input class="in" id="pp-sig" name="getekend" value="${esc(client(p.clientId).contact||'')}"></div></form>`;
  document.querySelector('#layer .mf').innerHTML=`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Werkbon aanmaken (ter controle)</button>`;
}
function downscale(file,max){ return new Promise(res=>{ const fr=new FileReader(); fr.onload=()=>{ const img=new Image(); img.onload=()=>{ const r=Math.min(1,max/Math.max(img.width,img.height)); const c=document.createElement('canvas'); c.width=Math.round(img.width*r); c.height=Math.round(img.height*r); c.getContext('2d').drawImage(img,0,0,c.width,c.height); res(c.toDataURL('image/jpeg',.6)); }; img.onerror=()=>res(null); img.src=fr.result; }; fr.onerror=()=>res(null); fr.readAsDataURL(file); }); }
function bindSig(id){ const cv=$('#'+id); if(!cv) return; const r=cv.getBoundingClientRect(); cv.width=r.width*2; cv.height=r.height*2; const ctx=cv.getContext('2d'); ctx.scale(2,2); ctx.lineWidth=2.2; ctx.lineCap='round'; ctx.strokeStyle=getComputedStyle(document.body).color; let dn=false; UI.wbSigned=false; const pos=e=>{ const b=cv.getBoundingClientRect(); return [e.clientX-b.left,e.clientY-b.top]; };
  cv.onpointerdown=e=>{ dn=true; cv.setPointerCapture(e.pointerId); ctx.beginPath(); ctx.moveTo(...pos(e)); }; cv.onpointermove=e=>{ if(!dn) return; ctx.lineTo(...pos(e)); ctx.stroke(); UI.wbSigned=true; }; cv.onpointerup=()=>dn=false; }
function wbLog(w,t){ w.log.push({d:TODAY,t}); }
function approveWb(w){
  const p=proj(w.pid); const e=emp(w.emp)||{}; const tarief=+e.tarief||50; const share=wbShare(w); const kost=(+w.uren||0)*tarief;
  w.status='goedgekeurd'; wbLog(w,`Goedgekeurd door ${myName()}: ${NUM.format(+w.uren||0)} uur geboekt`);
  if(p){ p.kosten=(p.kosten||0)+kost; const old=p.progress||0; p.progress=Math.min(100,old+share); if(p.phase>=5&&p.phase<6&&p.progress>0) p.phase=6; if(p.progress===100&&p.phase===6){ p.phase=7; addActivity(p,'Uitvoering gereed, fase Oplevering','ok'); }
    addActivity(p,`Werkbon ${w.nr} goedgekeurd: ${NUM.format(+w.uren||0)} uur ${firstName(w.emp)}, voortgang ${old}% → ${p.progress}%`,'ok'); }
  const t=S.tasks.find(x=>x.id===w.taskId); if(t&&t.status!=='afgerond'){ t.status='afgerond'; if(p) addActivity(p,`Taak afgerond via werkbon: ${t.titel}`,'ok'); }
  return `${NUM.format(+w.uren||0)} uur geboekt (${eur(kost)}), voortgang +${share}%${t?', taak afgerond':''}.`;
}

/* ---------- Workforce ---------- */
function vWorkforce(){
  const tab=UI.wfTab||'mensen'; const [a,b]=weekRange(0), [na,nb]=weekRange(1);
  const vak=S.emps.filter(e=>e.type!=='kantoor'); const busyNow=vak.filter(e=>S.blocks.some(x=>x.emp===e.id&&x.start<=TODAY&&TODAY<=x.end));
  const freeNext=vak.filter(e=>isFree(e.id,na,nb)); const certs=allCerts(); const expired=certs.filter(c=>certState(c.c)==='verlopen'), soon=certs.filter(c=>certState(c.c)==='binnenkort');
  const onb=S.subs.filter(s=>['nieuw','beoordeling','ontbreekt'].includes(subStatus(s))); const openPa=S.rfqs.filter(r=>r.status==='uitgezet');
  const f=UI.wfFilter||'alle';
  const ORD={intern:0,partner:1,kantoor:2}; const people=S.emps.filter(e=>f==='alle'?true:f==='intern'?e.type==='intern':f==='partner'?e.type==='partner':e.type==='kantoor').sort((x,y)=>ORD[x.type]-ORD[y.type]);
  let body='';
  if(tab==='mensen') body=`<div class="row between wrap"><div class="seg">${[['alle','Iedereen'],['intern','Eigen vakmensen'],['partner','Partners'],['kantoor','Kantoor']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="wf-filter" data-f="${k}">${l}</button>`).join('')}</div><span class="muted" style="font-size:12.5px">${people.length} personen · beschikbaarheid week van ${fmtD(na)}</span></div>
    <div class="grid g3">${people.map(e=>{ const h=plannedHours(e.id,na,nb), ab=absentDays(e,na,nb), cap=e.cap-ab*8; const ex=(e.certs||[]).filter(c=>certState(c)!=='ok'); return `<div class="card person" data-act="wf-open" data-id="${e.id}">
      <div class="ptop">${avatar(e.naam,'lg')}<div style="min-width:0;flex:1"><h4>${esc(e.naam)}</h4><span class="muted">${esc(e.rol)} · ${esc(e.regio||'—')}</span></div>${e.type==='partner'?'<span class="pill vio">Partner</span>':e.type==='kantoor'?'<span class="pill mut">Kantoor</span>':'<span class="pill blue">Eigen</span>'}</div>
      <div class="chips">${(e.specs||[]).slice(0,3).map(s=>`<span class="chip" style="padding-left:10px">${esc(s)}</span>`).join('')}</div>
      ${e.type!=='kantoor'?`<div><div class="row between" style="font-size:12px"><span class="muted">Volgende week</span><span class="num ${h>cap?'dn':''}">${h}u / ${cap}u${ab?` · ${ab}d afwezig`:''}</span></div><div class="bar ${h>cap?'':'blue'}" style="margin-top:4px"><i style="width:${cap?Math.min(100,h/cap*100):100}%;${h>cap?'background:var(--bad)':''}"></i></div></div>`:''}
      <div class="meta"><span>${stars(e.rating||0)}</span>${ex.length?`<span class="pill ${ex.some(c=>certState(c)==='verlopen')?'bad':'warn'}">${ex.length} certificaat ${ex.some(c=>certState(c)==='verlopen')?'verlopen':'verloopt'}</span>`:'<span class="pill ok">Certificaten in orde</span>'}</div></div>`; }).join('')}</div>`;
  if(tab==='teams') body=`<div class="row between wrap"><p class="muted" style="margin:0">Stel teams samen uit eigen vakmensen en partners en plan ze in één keer in.</p><button class="btn pri" data-act="wf-newteam">${ic('plus')}Nieuw team</button></div>
    <div class="grid g2">${S.teams.map(t=>{ const leden=t.leden.map(emp).filter(Boolean); const h=leden.reduce((s,e)=>s+plannedHours(e.id,na,nb),0); const kost=leden.reduce((s,e)=>s+plannedHours(e.id,na,nb)*(+e.tarief||0),0); const disc=[...new Set(leden.map(e=>e.rol))]; const free=leden.filter(e=>isFree(e.id,na,nb)).length; const p=proj(t.pid);
      return `<div class="card"><div class="card-h"><h3>${esc(t.naam)}</h3><select class="in" style="width:auto;max-width:220px;height:30px" data-teampid="${t.id}" aria-label="Project voor ${esc(t.naam)}"><option value="">Niet toegewezen</option>${S.projects.filter(x=>x.phase>=3&&x.phase<=7).map(x=>`<option value="${x.id}" ${x.id===t.pid?'selected':''}>${esc(x.naam)}</option>`).join('')}</select></div><div class="card-b stack">
        <div class="chips">${leden.map(e=>`<span class="chip">${avatar(e.naam,'sm')}${esc(firstName(e.id))} <span class="muted">${esc(e.rol)}</span><button data-act="wf-rmlid" data-t="${t.id}" data-e="${e.id}" aria-label="${esc(e.naam)} verwijderen">×</button></span>`).join('')}<select class="in" style="width:auto;height:30px" data-addlid="${t.id}" aria-label="Lid toevoegen"><option value="">+ Lid toevoegen</option>${S.emps.filter(e=>e.type!=='kantoor'&&!t.leden.includes(e.id)).map(e=>`<option value="${e.id}">${esc(e.naam)} · ${esc(e.rol)}</option>`).join('')}</select></div>
        <div class="grid g3" style="gap:10px"><div><span class="lbl">Vakdisciplines</span><div style="font-size:12.5px">${esc(disc.join(', ')||'—')}</div></div><div><span class="lbl">Volgende week</span><div class="num">${h} uur · ${free}/${leden.length} vrij</div></div><div><span class="lbl">Gesch. arbeidskosten</span><div class="num"><b>${eur(kost)}</b></div></div></div>
        <div class="row wrap"><button class="btn sm pri" data-act="wf-planteam" data-t="${t.id}" ${leden.length?'':'disabled'}>${ic('cal')}Team inplannen</button>${p?`<a class="btn sm" href="/project-${p.id.toLowerCase()}">${esc(p.naam)} ${ic('chev')}</a>`:''}<button class="btn sm ghost danger" data-act="wf-delteam" data-t="${t.id}" style="margin-left:auto">${ic('trash')}</button></div></div></div>`; }).join('')}</div>`;
  if(tab==='certs') body=`<div class="card"><div class="tw"><table class="t"><thead><tr><th>Certificaat / document</th><th>Wie</th><th>Soort</th><th>Geldig tot</th><th>Status</th><th></th></tr></thead><tbody>
    ${certs.map((x,i)=>`<tr><td><b>${esc(x.c.t)}</b></td><td>${esc(x.wie)}<div class="sub">${esc(x.rol)}</div></td><td>${x.type==='bedrijf'?'Onderaannemer':x.type==='partner'?'Partner':x.type==='kantoor'?'Kantoor':'Eigen personeel'}</td><td>${fmtDY(x.c.g)}</td><td>${docPill(x.c)}</td><td class="r">${certState(x.c)!=='ok'?`<button class="btn xs" data-act="wf-renew" data-emp="${x.emp||''}" data-sub="${x.sub||''}" data-t="${esc(x.c.t)}">Vernieuwd registreren</button>`:''}</td></tr>`).join('')}
    </tbody></table></div><div class="card-b muted" style="font-size:12px;border-top:1px solid var(--border2)">Een geregistreerd certificaat is een interne controle en geen sluitend bewijs van wettelijke compliance.</div></div>`;
  return `<div class="page"><div class="ph"><div><h1>Work<em>force</em></h1><p>Eigen vakmensen, partners en kantoor op één plek, met beschikbaarheid, certificaten en teams.</p></div><div class="acts"><a class="btn" href="/onderaannemers">${ic('handshake')}Onderaannemers</a><a class="btn pri" href="/werkhub">${ic('store')}Werkhub</a></div></div>
  <div class="grid g4"><div class="card kpi dark"><span class="lbl">Vakmensen</span><span class="v num">${vak.length}</span><span class="s">${vak.filter(e=>e.type==='intern').length} eigen · ${vak.filter(e=>e.type==='partner').length} partners</span></div>
    <div class="card kpi"><span class="lbl">Nu ingezet</span><span class="v num">${busyNow.length}</span><span class="s">op ${new Set(S.blocks.filter(x=>x.start<=TODAY&&TODAY<=x.end).map(x=>x.pid)).size} projecten vandaag</span></div>
    <div class="card kpi"><span class="lbl">Vrij volgende week</span><span class="v num">${freeNext.length}</span><span class="s">${esc(freeNext.slice(0,3).map(e=>firstName(e.id)).join(', ')||'niemand')}</span></div>
    <div class="card kpi"><span class="lbl">Certificaten</span><span class="v num ${expired.length?'dn':''}">${expired.length} verlopen</span><span class="s">${soon.length} verlopen binnen 30 dagen</span></div></div>
  <div class="row wrap" style="gap:8px"><span class="pill ${onb.length?'warn':'ok'}">${onb.length} onboarding niet compleet</span><span class="pill ${openPa.length?'blue':'mut'}">${openPa.length} open prijsaanvragen</span><span class="pill mut">${S.teams.length} teams</span></div>
  <div class="tabs">${[['mensen','Vakmensen'],['teams','Teams'],['certs','Certificaten']].map(([k,l])=>`<button class="tab ${tab===k?'on':''}" data-act="wf-tab" data-t="${k}">${l}</button>`).join('')}</div>
  ${body}</div>`;
}
function mPerson(id){
  const e=emp(id); const hist=[...new Set(S.blocks.filter(b=>b.emp===id).map(b=>b.pid))].map(proj).filter(Boolean); const s=S.subs.find(x=>x.empId===id); const wbs=S.werkbonnen.filter(w=>w.emp===id);
  modal(esc(e.naam),`<div class="row" style="gap:14px">${avatar(e.naam,'lg')}<div><b style="font-size:16px">${esc(e.rol)}</b><div class="muted">${e.type==='partner'?'Partner'+(s?' · '+esc(s.naam):''):e.type==='kantoor'?'Kantoor':'Eigen personeel'} · sinds ${fmtDY(e.sinds)}</div></div><span style="margin-left:auto">${stars(e.rating||0)}</span></div>
  <form class="fg" data-form="person" data-id="${e.id}">
    <div class="f"><label for="p-tel">Telefoon</label><input class="in" id="p-tel" name="tel" value="${esc(e.tel)}"></div><div class="f"><label for="p-mail">E-mail</label><input class="in" id="p-mail" name="mail" value="${esc(e.mail)}"></div>
    <div class="f"><label for="p-regio">Werkgebied</label><input class="in" id="p-regio" name="regio" value="${esc(e.regio||'')}"></div><div class="f"><label for="p-tarief">Uurtarief (€)</label><input class="in" type="number" step="0.5" id="p-tarief" name="tarief" value="${+e.tarief||0}"></div>
    <div class="f"><label for="p-cap">Capaciteit per week (uur)</label><input class="in" type="number" id="p-cap" name="cap" value="${e.cap}"></div><div class="f"><label for="p-rating">Interne beoordeling</label><select class="in" id="p-rating" name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${e.rating===n?'selected':''}>${n} van 5</option>`).join('')}</select></div>
    <div class="f full"><label for="p-specs">Specialismen (komma-gescheiden)</label><input class="in" id="p-specs" name="specs" value="${esc((e.specs||[]).join(', '))}"></div>
    <div class="f"><label for="p-talen">Gesproken talen</label><input class="in" id="p-talen" name="talen" value="${esc((e.talen||[]).join(', '))}"></div>
    <div class="f"><label for="p-afw">Afwezig (van t/m)</label><div class="row"><input class="in" type="date" id="p-afw" name="afwVan"><input class="in" type="date" name="afwTot" aria-label="Afwezig tot"></div></div>
  </form>
  ${(e.afwezig||[]).length?`<div><span class="lbl">Geplande afwezigheid</span>${e.afwezig.map(a=>`<div class="sumrow"><span>${esc(a.reden||'Afwezig')}</span><span>${fmtD(a.van)} t/m ${fmtD(a.tot)}</span></div>`).join('')}</div>`:''}
  <div><span class="lbl">Certificaten</span>${(e.certs||[]).map(c=>`<div class="sumrow"><span>${esc(c.t)}</span>${docPill(c)}</div>`).join('')||'<div class="muted">Geen certificaten geregistreerd.</div>'}</div>
  <div><span class="lbl">Opdrachtgeschiedenis</span>${hist.map(p=>`<div class="sumrow"><a href="/project-${p.id.toLowerCase()}" data-act="mclose">${esc(p.naam)}</a><span class="muted">${S.blocks.filter(b=>b.emp===id&&b.pid===p.id).length} blokken · ${wbs.filter(w=>w.pid===p.id).reduce((s,w)=>s+(+w.uren||0),0)} uur</span></div>`).join('')||'<div class="muted">Nog geen opdrachten.</div>'}</div>
  <p class="muted" style="margin:0;font-size:12px">De interne beoordeling is niet zichtbaar voor klanten of partners.</p>`,`<button class="btn" data-act="mclose">Sluiten</button><button class="btn pri" data-act="submit">Opslaan</button>`,true);
}
function mPlanTeam(t){
  const [na]=weekRange(1);
  modal('Team inplannen · '+esc(t.naam),`<form class="fg" data-form="planteam" data-t="${t.id}"><div class="f full"><label for="pt-pid">Project</label><select class="in" id="pt-pid" name="pid">${projOpts(t.pid,false)}</select></div>
  <div class="f full"><label for="pt-titel">Werkzaamheden</label><input class="in" id="pt-titel" name="titel" value="${esc(t.naam.replace(/^Team\s+/,''))}" required></div>
  <div class="f"><label for="pt-s">Van</label><input class="in" type="date" id="pt-s" name="start" value="${na}"></div><div class="f"><label for="pt-e">Tot en met</label><input class="in" type="date" id="pt-e" name="end" value="${addDays(na,1)}"></div>
  <div class="full" id="pt-check"></div></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Inplannen</button>`);
  teamCheck();
}
function teamCheck(){ const f=document.querySelector('[data-form="planteam"]'); if(!f) return; const t=S.teams.find(x=>x.id===f.dataset.t); const s=f.start.value, e=f.end.value; if(!s||!e) return; const rows=t.leden.map(id=>{ const free=isFree(id,s,e); return `<div class="sumrow"><span class="row" style="gap:8px">${avatar(empName(id),'sm')}${esc(empName(id))}</span>${free?'<span class="pill ok">Beschikbaar</span>':'<span class="pill bad">Al ingepland of afwezig</span>'}</div>`; }).join('');
  const kost=t.leden.reduce((a,id)=>a+workdays(s,e)*8*(+emp(id).tarief||0),0);
  $('#pt-check').innerHTML=`${rows}<div class="calcbox" style="margin-top:8px"><div class="row between"><span>${workdays(s,e)} werkdagen × ${t.leden.length} personen</span><b>${workdays(s,e)*8*t.leden.length} uur</b></div><div class="row between"><span>Geschatte arbeidskosten</span><b>${eur(kost)}</b></div></div>`; }

/* ---------- Onderaannemers ---------- */
function vOnderaannemers(){
  const f=UI.subFilter||'alle'; const list=S.subs.filter(s=>f==='alle'||subStatus(s)===f);
  const cnt=k=>S.subs.filter(s=>subStatus(s)===k).length;
  return `<div class="page"><div class="ph"><div><h1>Onder<em>aannemers</em></h1><p>Partnerbedrijven met het Renovion-keurmerk. Je kunt alleen gunnen aan goedgekeurde partners.</p></div><div class="acts"><a class="btn" href="/partner">${ic('team')}Partner Portal</a><button class="btn pri" data-act="pp-onboard">${ic('plus')}Partner aanmelden</button></div></div>
  <div class="grid g4"><div class="card kpi dark"><span class="lbl">Partnerbedrijven</span><span class="v num">${S.subs.length}</span><span class="s">${cnt('goedgekeurd')} goedgekeurd</span></div><div class="card kpi"><span class="lbl">In beoordeling</span><span class="v num">${cnt('nieuw')+cnt('beoordeling')}</span><span class="s">onboarding loopt</span></div><div class="card kpi"><span class="lbl">Document actie nodig</span><span class="v num ${cnt('verlopen')+cnt('ontbreekt')?'dn':''}">${cnt('verlopen')+cnt('ontbreekt')}</span><span class="s">verlopen of ontbrekend</span></div><div class="card kpi"><span class="lbl">Lopende opdrachten</span><span class="v num">${S.rfqs.filter(r=>r.status==='gegund').length}</span><span class="s">${eur0(S.rfqs.filter(r=>r.status==='gegund').reduce((s,r)=>s+awardPrice(r),0))} verplichting</span></div></div>
  <div class="tabs">${[['alle','Alle'],['goedgekeurd','Goedgekeurd'],['beoordeling','In beoordeling'],['nieuw','Nieuw'],['ontbreekt','Document ontbreekt'],['verlopen','Document verlopen'],['geblokkeerd','Geblokkeerd']].map(([k,l])=>`<button class="tab ${f===k?'on':''}" data-act="sub-filter" data-f="${k}">${l}${k!=='alle'?`<span class="c">${cnt(k)}</span>`:''}</button>`).join('')}</div>
  <div class="card tw"><table class="t"><thead><tr><th>Bedrijf</th><th>Vakgebied</th><th>Regio</th><th class="r">Tarief</th><th>Beoordeling</th><th>Keurmerk</th><th class="r">Opdrachten</th></tr></thead><tbody>
  ${list.map(s=>`<tr class="click" data-act="sub-open" data-id="${s.id}"><td><div class="row">${avatar(s.naam,'sm')}<div><b>${esc(s.naam)}</b><div class="sub">${esc(s.contact)} · KvK ${s.kvk}</div></div></div></td><td>${esc(s.vak)}</td><td>${esc(s.regio)}</td><td class="r">${eur(s.tarief)}/${esc(s.eenheid)}</td><td>${s.rating?stars(s.rating):'<span class="muted">Nog geen</span>'}</td><td>${keurPill(s)}</td><td class="r">${s.opdrachten}</td></tr>`).join('')}
  </tbody></table></div></div>`;
}
function mSub(id){
  const s=sub(id); const st=subStatus(s); const pas=S.rfqs.filter(r=>r.invited.includes(id));
  modal(esc(s.naam),`<div class="row wrap" style="gap:10px">${keurPill(s)}<span class="muted">${esc(s.vak)} · ${esc(s.regio)} · KvK ${s.kvk}</span></div>
  ${s.blocked?`<div class="alert bad">${ic('lock')}<div class="grow"><b>Tijdelijk geblokkeerd.</b> ${esc(s.blockReden||'')}</div></div>`:''}
  <div class="kv"><span>Contactpersoon</span><b>${esc(s.contact)}</b><span>E-mail</span><b>${esc(s.mail)}</b><span>Tarief</span><b>${eur(s.tarief)} per ${esc(s.eenheid)}</b>${s.empId?`<span>Vakman in planning</span><b>${esc(empName(s.empId))}</b>`:''}</div>
  <div><span class="lbl">Documenten</span>${s.docs.map((d,i)=>`<div class="check-row">${ic(docState(d)==='ok'?'check':'alert')}<div class="grow"><b>${esc(d.t)}</b>${d.t==='Identiteit gecontroleerd'?'<small>Alleen de controle is vastgelegd, er wordt geen kopie van het identiteitsbewijs bewaard.</small>':''}</div>${docPill(d)}${docState(d)!=='ok'?`<button class="btn xs" data-act="sub-doc" data-id="${s.id}" data-i="${i}">${d.ok===false?'Ontvangen':'Vernieuwd'}</button>`:''}</div>`).join('')}</div>
  <div><span class="lbl">Uitgevoerde controles</span>${s.checks.length?s.checks.map(c=>`<div class="check-row">${ic(c.ok?'check':'clock')}<div class="grow"><b>${esc(c.t)}</b><small>${c.ok?`door ${esc(c.door)} op ${fmtDY(c.d)}`:'nog uit te voeren'}</small></div></div>`).join(''):'<div class="muted">Nog geen controles uitgevoerd.</div>'}</div>
  ${pas.length?`<div><span class="lbl">Prijsaanvragen</span>${pas.map(r=>`<div class="sumrow"><a href="/prijsaanvraag-${r.id.toLowerCase()}" data-act="mclose">${r.id} · ${esc(r.titel)}</a><span>${r.awardedTo===id?'<span class="pill or">Gegund</span>':r.bids.some(b=>b.sub===id)?'<span class="pill blue">Prijs ingediend</span>':'<span class="pill mut">Uitgenodigd</span>'}</span></div>`).join('')}</div>`:''}
  <p class="muted" style="margin:0;font-size:12px">Een contract of certificaat is geen sluitend bewijs van wettelijke compliance. De controles hierboven zijn interne verificaties.</p>`,
  `${s.blocked?`<button class="btn" data-act="sub-unblock" data-id="${s.id}">Blokkade opheffen</button>`:`<button class="btn danger" data-act="sub-block" data-id="${s.id}">Tijdelijk blokkeren</button>`}${(st==='nieuw'||st==='beoordeling')?`<button class="btn pri" data-act="sub-approve" data-id="${s.id}">${ic('shield')}Keurmerk toekennen</button>`:''}<button class="btn" data-act="mclose">Sluiten</button>`,true);
}

/* ---------- Werkhub / prijsaanvragen ---------- */
function vWerkhub(){
  const f=UI.paFilter||'open'; const list=S.rfqs.filter(r=>f==='alle'||(f==='open'&&(r.status==='concept'||r.status==='uitgezet'))||r.status===f);
  const verpl=S.rfqs.filter(r=>r.status==='gegund').reduce((s,r)=>s+awardPrice(r),0); const gun=S.rfqs.filter(r=>r.status!=='concept'&&r.status!=='uitgezet'); const delta=gun.reduce((s,r)=>s+awardPrice(r)-r.budget,0);
  return `<div class="page"><div class="ph"><div><h1>Werk<em>hub</em></h1><p>Prijsaanvragen per werkpakket uit de begroting. Een gegunde prijs telt direct mee als verplichting in de projectprognose.</p></div><button class="btn pri" data-act="pa-new">${ic('plus')}Nieuwe prijsaanvraag</button></div>
  <div class="grid g4"><div class="card kpi dark"><span class="lbl">Openstaande verplichtingen</span><span class="v num">${heur(verpl)}</span><span class="s">${S.rfqs.filter(r=>r.status==='gegund').length} lopende opdrachten</span></div>
    <div class="card kpi"><span class="lbl">Open prijsaanvragen</span><span class="v num">${S.rfqs.filter(r=>r.status==='uitgezet').length}</span><span class="s">${S.rfqs.filter(r=>r.status==='concept').length} concept</span></div>
    <div class="card kpi"><span class="lbl">Reacties binnen</span><span class="v num">${S.rfqs.filter(r=>r.status==='uitgezet').reduce((s,r)=>s+r.bids.length,0)}</span><span class="s">van ${S.rfqs.filter(r=>r.status==='uitgezet').reduce((s,r)=>s+r.invited.length,0)} uitnodigingen</span></div>
    <div class="card kpi"><span class="lbl">Gegund t.o.v. begroting</span><span class="v num ${delta>0?'dn':'up'}">${delta>0?'+':''}${eur(delta)}</span><span class="s">${gun.length} gegunde werkpakketten</span></div></div>
  <div class="tabs">${[['open','Open'],['gegund','Gegund'],['afgerond','Opgeleverd'],['alle','Alle']].map(([k,l])=>`<button class="tab ${f===k?'on':''}" data-act="pa-filter" data-f="${k}">${l}</button>`).join('')}</div>
  <div class="grid g2">${list.map(r=>{ const p=proj(r.pid)||{naam:'—'}; const st=PA_ST[r.status]; const best=r.bids.length?Math.min(...r.bids.map(b=>b.prijs)):0; return `<div class="card pcard" data-go="prijsaanvraag-${r.id.toLowerCase()}">
    <div class="row between"><span class="id">${r.id}${r.ch?' · hoofdstuk '+esc(r.ch):''}</span><span class="pill ${st[1]}">${st[0]}</span></div>
    <div><h4>${esc(r.titel)}</h4><span class="muted">${esc(p.naam)}</span></div>
    <div class="grid g3" style="gap:8px;font-size:12.5px"><div><span class="lbl">Budget</span><div class="num"><b>${eur0(r.budget)}</b></div></div><div><span class="lbl">${r.status==='gegund'||r.status==='afgerond'?'Gegund':'Laagste prijs'}</span><div class="num"><b>${r.awardedTo?eur0(awardPrice(r)):best?eur0(best):'—'}</b></div></div><div><span class="lbl">${r.awardedTo?'Partner':'Reacties'}</span><div>${r.awardedTo?esc(sub(r.awardedTo).naam):`${r.bids.length}/${r.invited.length}`}</div></div></div>
    ${r.status==='gegund'?`<div><div class="row between" style="font-size:12px"><span class="muted">Voortgang</span><span class="num">${r.voortgang||0}%</span></div><div class="bar" style="margin-top:4px"><i style="width:${r.voortgang||0}%"></i></div></div>`:r.status==='uitgezet'?`<span class="muted" style="font-size:12px">Reageren kan tot ${fmtD(r.deadline)}${r.deadline<TODAY?' <span class="dn">(verlopen)</span>':''}</span>`:''}
  </div>`; }).join('')||`<div class="card"><div class="empty">${ic('store')}Geen prijsaanvragen in deze weergave.</div></div>`}</div></div>`;
}
function vPa(id){
  const r=pa(id); if(!r) return `<div class="page"><div class="empty">Prijsaanvraag niet gevonden. <a class="btn" href="/werkhub">Naar Werkhub</a></div></div>`;
  const p=proj(r.pid)||{naam:'—',docs:[]}; const st=PA_ST[r.status];
  const eligible=b=>subStatus(sub(b.sub))==='goedgekeurd'; const cand=r.bids.filter(b=>eligible(b)&&b.compleet>=95); const best=cand.length?cand.reduce((a,b)=>a.prijs<=b.prijs?a:b):null;
  const pend=r.invited.filter(s=>!r.bids.some(b=>b.sub===s));
  return `<div class="page"><div class="band"><img class="bimg" src="${HERO}" alt="" aria-hidden="true">
    <div class="btop"><div class="crumb"><a href="/werkhub">Werkhub</a>${ic('chev')}<span>${r.id}</span></div><div class="acts">
      ${r.status==='concept'?`<button class="btn pri" data-act="pa-send" data-id="${r.id}" ${r.invited.length?'':'disabled'}>${ic('send')}Uitnodigingen verzenden</button>`:''}
      
      ${r.status==='gegund'?`<button class="btn pri" data-act="pa-done" data-id="${r.id}">${ic('check')}Oplevering registreren</button>`:''}</div></div>
    <div style="display:grid;gap:6px"><span class="eyebrow">Prijsaanvraag · ${esc(p.naam)}</span><h1>${esc(r.titel)}</h1><span class="sub">${st[0]}${r.orderNr?' · opdracht '+r.orderNr:''}</span><div class="rule"></div></div>
    <div class="bmeta"><div><span>Projectdossier</span><b>${r.pid}</b></div><div><span>Werkpakket</span><b>${r.ch?'Hoofdstuk '+esc(r.ch):'Handmatig'}</b></div><div><span>Budget uit begroting</span><b class="num">${eur(r.budget)}</b></div><div><span>Reactietermijn</span><b>${fmtDY(r.deadline)}</b></div><div><span>Uitgenodigd</span><b>${r.invited.length} partners</b></div></div></div>
  <div class="card"><div class="card-h"><h3>Prijs<em>vergelijking</em></h3><span class="cmp-note">Aanbevolen = laagste prijs met complete scope bij een goedgekeurde partner</span></div>
    ${r.bids.length?`<div class="tw"><table class="t"><thead><tr><th>Partner</th><th class="r">Prijs excl. btw</th><th class="r">t.o.v. budget</th><th>Start · duur</th><th>Scope</th><th>Voorwaarden</th><th></th></tr></thead><tbody>
      ${r.bids.slice().sort((a,b)=>a.prijs-b.prijs).map(b=>{ const s=sub(b.sub); const d=b.prijs-r.budget; const isBest=best&&best.sub===b.sub&&r.status==='uitgezet'; const won=r.awardedTo===b.sub; return `<tr class="${isBest||won?'best':''}"><td><b>${esc(s.naam)}</b><div class="sub">${keurPill(s)}</div></td><td class="r"><b>${eur(b.prijs)}</b></td><td class="r ${d>0?'dn':'up'}">${d>0?'+':''}${eur(d)}<div class="sub">${pct(d/r.budget*100)}</div></td><td>${fmtD(b.start)} · ${b.dagen} dagen</td><td><span class="pill ${b.compleet>=95?'ok':'warn'}">${b.compleet}%</span>${b.opm?`<div class="sub">${esc(b.opm)}</div>`:''}</td><td style="max-width:220px;font-size:12px">${esc(b.voorw)}</td><td class="r">${won?'<span class="pill or">Gegund</span>':r.status==='uitgezet'?`<button class="btn xs ${isBest?'pri':''}" data-act="pa-award" data-id="${r.id}" data-sub="${b.sub}">Gunnen</button>`:''}${isBest?'<div class="sub" style="color:var(--ok);font-weight:600">Aanbevolen</div>':''}</td></tr>`; }).join('')}
    </tbody></table></div>`:`<div class="empty">${ic('clock')}${r.status==='concept'?'Nog niet verzonden.':'Nog geen prijzen ontvangen.'}</div>`}
    ${pend.length&&r.status==='uitgezet'?`<div class="card-b" style="border-top:1px solid var(--border2);font-size:12.5px"><span class="muted">Wacht nog op:</span> ${pend.map(s=>esc(sub(s).naam)).join(', ')}</div>`:''}</div>
  <div class="grid g2">
      <div class="card"><div class="card-h"><h3>Scope</h3></div><div class="card-b stack"><p style="margin:0;white-space:pre-wrap">${esc(r.scope)}</p>${r.docs.length?`<div><span class="lbl">Bijgevoegd</span>${r.docs.map(d=>`<div class="docrow">${ic('file')}${esc(d)}</div>`).join('')}</div>`:''}</div></div>
      ${r.status==='concept'?`<div class="card"><div class="card-h"><h3>Partners uitnodigen</h3></div><div class="card-b stack">${S.subs.map(s=>`<label class="row" style="cursor:pointer;font-size:13px"><input type="checkbox" data-painv="${r.id}" value="${s.id}" ${r.invited.includes(s.id)?'checked':''}> <span style="flex:1">${esc(s.naam)} <span class="muted">${esc(s.vak)}</span></span>${keurPill(s)}</label>`).join('')}</div></div>`:''}
      ${r.status==='gegund'?`<div class="card"><div class="card-h"><h3>Voortgang opdracht</h3><b class="num">${r.voortgang||0}%</b></div><div class="card-b stack"><input type="range" class="range" min="0" max="100" step="5" value="${r.voortgang||0}" data-pavg="${r.id}" aria-label="Voortgang"><div class="kv"><span>Opdracht</span><b>${r.orderNr}</b><span>Gegund op</span><b>${fmtDY(r.gegundOp)}</b><span>Verplichting</span><b class="num">${eur(awardPrice(r))}</b></div></div></div>`:''}
      ${r.status==='afgerond'?`<div class="alert info">${ic('check')}<div class="grow">Opgeleverd op ${fmtDY(r.opgeleverd)}. ${eur(awardPrice(r))} is als werkelijke kosten geboekt op ${r.pid}.</div></div>`:''}
  </div></div>`;
}
function mNewPa(){
  const ps=S.projects.filter(p=>p.phase>=2&&p.phase<=7);
  modal('Nieuwe prijsaanvraag',`<form class="fg" data-form="pa"><div class="f full"><label for="pa-pid">Projectdossier</label><select class="in" id="pa-pid" name="pid">${ps.map(p=>`<option value="${p.id}">${esc(p.naam)} · ${p.id}</option>`).join('')}</select></div>
  <div class="f full"><label for="pa-ch">Werkpakket uit de begroting</label><select class="in" id="pa-ch" name="ch"></select></div>
  <div class="f full"><label for="pa-titel">Titel</label><input class="in" id="pa-titel" name="titel" required></div>
  <div class="f"><label for="pa-budget">Budget (€ excl. btw)</label><input class="in" type="number" min="0" step="10" id="pa-budget" name="budget"></div><div class="f"><label for="pa-dl">Reageren vóór</label><input class="in" type="date" id="pa-dl" name="deadline" value="${addDays(TODAY,7)}"></div>
  <div class="f full"><label for="pa-scope">Scope en planning</label><textarea class="in" id="pa-scope" name="scope" style="min-height:96px"></textarea></div>
  <div class="full"><span class="lbl">Partners uitnodigen</span><div class="stack" style="gap:6px;margin-top:6px">${S.subs.map(s=>`<label class="row" style="cursor:pointer;font-size:13px"><input type="checkbox" name="inv" value="${s.id}"> <span style="flex:1">${esc(s.naam)} <span class="muted">${esc(s.vak)}</span></span>${keurPill(s)}</label>`).join('')}</div></div>
  </form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn" data-act="submit" data-mode="concept">Opslaan als concept</button><button class="btn pri" data-act="pa-submit-send">Opslaan en uitnodigen</button>`,true);
  paFillCh();
}
function paFillCh(){ const f=document.querySelector('[data-form="pa"]'); if(!f) return; const p=proj(f.pid.value); const sel=f.ch;
  const chs=p&&p.begroting?calcB(p.begroting).chapters:[]; sel.innerHTML=chs.map(c=>`<option value="${esc(c.nr)}">${esc(c.nr)} ${esc(c.naam)} · ${eur0(c.totaal)}</option>`).join('')+`<option value="">Handmatig werkpakket</option>`; paFillFromCh(); }
function paFillFromCh(){ const f=document.querySelector('[data-form="pa"]'); if(!f) return; const p=proj(f.pid.value); const code=f.ch.value;
  if(!code||!p.begroting){ f.titel.value=f.titel.value||''; f.budget.value=f.budget.value||''; return; }
  const k=calcB(p.begroting).chapters.find(c=>c.nr===code); const ch=p.begroting.chapters.find(c=>c.code===code);
  f.titel.value=`${k.naam} ${p.naam}`; f.budget.value=Math.round(k.totaal);
  const lines=[]; for(const pr of ch.pars) for(const l of pr.lines) if(l.t!=='text'&&+l.q) lines.push(`• ${l.d} (${NUM.format(+l.q)} ${l.u})`);
  f.scope.value=`Werkpakket hoofdstuk ${code} ${k.naam} volgens begroting ${p.begroting.nr}:\n${lines.slice(0,8).join('\n')}${lines.length>8?`\n• … en ${lines.length-8} regels meer`:''}\nLocatie: ${[p.adres,p.plaats].filter(Boolean).join(', ')}.`;
  const vakmap={Tegel:'Tegelzetter',Schilder:'Schilder',Dak:'Dakdekker',Elektr:'Elektricien',Water:'Installateur',Install:'Installateur',Grond:'Grondwerker',Riool:'Grondwerker',Sloop:'Sloper',Stuc:'Stukadoor',Timmer:'Timmerman',Metsel:'Timmerman'};
  const vak=Object.entries(vakmap).find(([k2])=>k.naam.includes(k2)); f.querySelectorAll('[name="inv"]').forEach(cb=>{ const s=sub(cb.value); cb.checked=!!vak&&s.vak===vak[1]&&subStatus(s)!=='geblokkeerd'; }); }
function simBids(r){ let n=0; for(const sid of r.invited){ if(r.bids.some(b=>b.sub===sid)) continue; const s=sub(sid); if(subStatus(s)==='geblokkeerd') continue; const h=hashN(sid+r.id); const f=0.86+(h%30)/100; const start=addDays(monday(TODAY),7*(1+h%3)); const voorw=['Betaling 14 dagen na oplevering','Betaling 30 dagen na factuur, 5 jaar garantie','30% bij start, rest bij oplevering','Exclusief steiger en afvoer'][h%4]; const comp=[100,100,95,85][h%4];
  r.bids.push({sub:sid,prijs:Math.round(r.budget*f/10)*10,f,start,dagen:Math.max(2,Math.round(r.budget/2600)),voorw,compleet:comp,datum:TODAY,opm:comp<95?'Niet alle posten geprijsd':''}); n++; } return n; }
function awardPa(r,sid){
  const p=proj(r.pid); const s=sub(sid); const b=r.bids.find(x=>x.sub===sid);
  S.seq.oa++; r.status='gegund'; r.awardedTo=sid; r.orderNr='OA-'+YEAR+'-'+String(S.seq.oa).padStart(4,'0'); r.gegundOp=TODAY; r.voortgang=0;
  S.outbox.push({d:TODAY,aan:s.mail,onderwerp:`Opdrachtbevestiging ${r.orderNr}: ${r.titel}`});
  r.bids.filter(x=>x.sub!==sid).forEach(x=>S.outbox.push({d:TODAY,aan:sub(x.sub).mail,onderwerp:`Uitslag prijsaanvraag ${r.id}`}));
  S.tasks.push({id:uid('t'),titel:`Opdrachtbevestiging ${r.orderNr} laten tekenen`,pid:r.pid,eig:osWvb(),dl:addDays(TODAY,2),status:'todo',prio:'hoog',oms:`${s.naam} · ${eur(b.prijs)}`,checklist:[]});
  let planned='';
  if(s.empId){ let e=b.start, left=b.dagen-1; while(left>0){ e=addDays(e,1); if(!isWeekend(e)) left--; } S.blocks.push({id:uid('b'),emp:s.empId,pid:r.pid,titel:r.titel,start:b.start,end:e}); planned=` ${firstName(s.empId)} staat ingepland vanaf ${fmtD(b.start)}.`; }
  if(p) addActivity(p,`${r.id} gegund aan ${s.naam} voor ${eur(b.prijs)} (budget ${eur(r.budget)}). Opdracht ${r.orderNr}.`,'or');
  s.opdrachten++;
  return `Gegund aan ${s.naam}. ${eur(b.prijs)} staat nu als verplichting in de prognose van ${r.pid}.${planned}`;
}

/* ---------- Partner Portal ---------- */
function vPartner(){
  const sid=(ME_ROL==='Onderaannemer'?osMySub():UI.ppSub)||(S.subs[0]||{}).id; const s=sub(sid)||(ME_ROL==='Onderaannemer'?null:S.subs[0]); const tab=UI.ppTab||'uitnodigingen'; if(!s) return `<div class="page"><div class="ph"><div><h1>Partner<em>portaal</em></h1><p>Prijsaanvragen, opdrachten en documenten van een partner.</p></div></div><div class="card"><div class="empty">${ic('team')}${ME_ROL==='Onderaannemer'?'Je bedrijfsdossier is nog niet aan je account gekoppeld. Neem contact op met Renovion; daarna zie je hier je prijsaanvragen en opdrachten.':'Nog geen partners. Voeg een partner toe bij Onderaannemers; daarna zie je hier hoe zijn portaal eruitziet.'}</div></div></div>`;
  const inv=S.rfqs.filter(r=>r.invited.includes(s.id)&&r.status==='uitgezet'); const orders=S.rfqs.filter(r=>r.awardedTo===s.id); const wbs=s.empId?S.werkbonnen.filter(w=>w.emp===s.empId&&wbIdx(w.status)<wbIdx('goedgekeurd')):[];
  let body='';
  if(tab==='uitnodigingen') body=inv.length?inv.map(r=>{ const p=proj(r.pid)||{plaats:''}; const mine=r.bids.find(b=>b.sub===s.id); return `<div class="card"><div class="card-h"><h3>${esc(r.titel)}</h3>${mine?'<span class="pill ok">Prijs ingediend</span>':`<span class="pill blue">Reageer vóór ${fmtD(r.deadline)}</span>`}</div><div class="card-b grid g2">
      <div class="stack"><p style="margin:0;white-space:pre-wrap;font-size:13px">${esc(r.scope)}</p><div class="kv"><span>Plaats</span><b>${esc(p.plaats||'')}</b><span>Referentie</span><b>${r.id}</b></div>${r.docs.length?`<div>${r.docs.map(d=>`<div class="docrow">${ic('file')}${esc(d)}</div>`).join('')}</div>`:''}</div>
      ${mine?`<div class="calcbox"><div class="row between"><span>Uw prijs</span><b>${eur(mine.prijs)}</b></div><div class="row between"><span>Start</span><b>${fmtDY(mine.start)}</b></div><div class="row between"><span>Duur</span><b>${mine.dagen} werkdagen</b></div><div>${esc(mine.voorw)}</div></div>`:
      `<form class="fg" data-form="ppbid" data-id="${r.id}" data-sub="${s.id}"><div class="f"><label for="bp-${r.id}">Prijs excl. btw (€)</label><input class="in" type="number" min="1" step="10" id="bp-${r.id}" name="prijs" required></div><div class="f"><label for="bs-${r.id}">Kan starten op</label><input class="in" type="date" id="bs-${r.id}" name="start" value="${addDays(monday(TODAY),7)}"></div><div class="f"><label for="bd-${r.id}">Duur (werkdagen)</label><input class="in" type="number" min="1" id="bd-${r.id}" name="dagen" value="3"></div><div class="f"><label for="bc-${r.id}">Scope geprijsd</label><select class="in" id="bc-${r.id}" name="compleet"><option value="100">Volledig</option><option value="85">Gedeeltelijk</option></select></div><div class="f full"><label for="bv-${r.id}">Voorwaarden / opmerkingen</label><input class="in" id="bv-${r.id}" name="voorw" placeholder="Bijv. betaling 14 dagen na oplevering"></div><div class="full"><button class="btn pri" type="submit">${ic('send')}Prijs indienen</button></div></form>`}
    </div></div>`; }).join(''):`<div class="card"><div class="empty">${ic('mail')}Geen openstaande uitnodigingen.</div></div>`;
  if(tab==='opdrachten') body=`<div class="card">${orders.length||wbs.length?`<div class="tw"><table class="t"><thead><tr><th>Opdracht</th><th>Project</th><th class="r">Bedrag</th><th>Voortgang</th><th>Status</th></tr></thead><tbody>${orders.map(r=>`<tr><td><b>${r.orderNr}</b><div class="sub">${esc(r.titel)}</div></td><td>${esc((proj(r.pid)||{plaats:''}).plaats)}</td><td class="r">${eur(awardPrice(r))}</td><td style="min-width:120px"><div class="bar"><i style="width:${r.status==='afgerond'?100:r.voortgang||0}%"></i></div></td><td>${r.status==='afgerond'?'<span class="pill ok">Opgeleverd</span>':'<span class="pill or">Lopend</span>'}</td></tr>`).join('')}${wbs.map(w=>`<tr class="click" data-go="werkbon-${w.nr.toLowerCase()}"><td><b>${w.nr}</b><div class="sub">${esc(w.titel)}</div></td><td>${esc((proj(w.pid)||{plaats:''}).plaats)}</td><td class="r muted">werkbon</td><td>${fmtD(w.datum)}</td><td>${wbPill(w.status)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nog geen opdrachten.</div>`}</div>`;
  if(tab==='documenten') body=`<div class="card"><div class="card-b">${s.docs.map((d,i)=>`<div class="check-row">${ic(docState(d)==='ok'?'check':'alert')}<div class="grow"><b>${esc(d.t)}</b>${d.t==='Identiteit gecontroleerd'?'<small>Wordt eenmalig door Renovion gecontroleerd. U hoeft geen kopie te uploaden.</small>':''}</div>${docPill(d)}${docState(d)!=='ok'&&d.t!=='Identiteit gecontroleerd'?`<label class="btn xs" style="cursor:pointer">${ic('upload')}Uploaden<input type="file" hidden data-ppdoc="${s.id}" data-i="${i}"></label>`:''}</div>`).join('')}</div></div>`;
  return `<div class="page"><div class="band portal-band"><div class="btop"><div style="display:grid;gap:6px"><span class="eyebrow">Renovion Partner Portal</span><h1>Welkom, <em>${esc(s.contact.split(' ')[0])}</em></h1><span class="sub" style="color:var(--on-navy-2)">${esc(s.naam)} · ${esc(s.vak)}</span><div class="rule"></div></div>
    <div class="stack" style="gap:6px;align-items:flex-end" ${IS_EXTERNAL?'data-os-hide':''}><label class="eyebrow" for="ppsel">Bekijk als partner</label><select class="in" id="ppsel" style="width:auto;min-width:230px">${S.subs.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.naam)}</option>`).join('')}</select></div></div>
    <div class="bmeta"><div><span>Keurmerk</span><b>${KEUR[subStatus(s)][0]}</b></div><div><span>Uitnodigingen</span><b>${inv.filter(r=>!r.bids.some(b=>b.sub===s.id)).length} open</b></div><div><span>Lopende opdrachten</span><b>${orders.filter(r=>r.status==='gegund').length}</b></div><div><span>Documenten</span><b>${s.docs.filter(d=>docState(d)!=='ok').length?s.docs.filter(d=>docState(d)!=='ok').length+' actie nodig':'In orde'}</b></div></div></div>
  <div class="alert info" ${IS_EXTERNAL?'data-os-hide':''}>${ic('team')}<div class="grow">Zo ziet een partner zijn portaal. Hij logt zelf in en ziet geen interne beoordelingen, budgetten of prijzen van andere partners.</div><button class="btn sm" data-act="pp-onboard">Nieuwe partner aanmelden</button></div>
  <div class="tabs">${[['uitnodigingen','Prijsaanvragen'],['opdrachten','Mijn opdrachten'],['documenten','Documenten']].map(([k,l])=>`<button class="tab ${tab===k?'on':''}" data-act="pp-tab" data-t="${k}">${l}</button>`).join('')}</div>
  ${body}</div>`;
}
const ONB_STEPS=['Gegevens','Specialismen','Tarieven & gebied','Documenten','Afspraken','Controle'];
function mOnboard(){
  const o=UI.onb=UI.onb||{step:0,d:{bedrijf:'',contact:'',kvk:'',mail:'',tel:'',vak:'Tegelzetter',ervaring:'5-10 jaar',specs:'',tarief:'',regio:'',vca:'',avb:'',grek:'ja',bewoond:false,dba:false,akkoord:false}}; const d=o.d; const s=o.step;
  const F=(n,l,t='text',x='')=>`<div class="f ${x}"><label for="ob-${n}">${l}</label><input class="in" id="ob-${n}" name="${n}" type="${t}" value="${esc(d[n])}"></div>`;
  const steps=[
    `${F('bedrijf','Bedrijfsnaam')}${F('contact','Contactpersoon')}${F('kvk','KvK-nummer')}${F('tel','Telefoon')}${F('mail','E-mail','email','full')}`,
    `<div class="f"><label for="ob-vak">Vakgebied</label><select class="in" id="ob-vak" name="vak">${['Tegelzetter','Schilder','Timmerman','Elektricien','Installateur','Stukadoor','Dakdekker','Grondwerker','Sloper','Stratenmaker'].map(v=>`<option ${d.vak===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="f"><label for="ob-erv">Ervaring</label><select class="in" id="ob-erv" name="ervaring">${['0-2 jaar','2-5 jaar','5-10 jaar','10+ jaar'].map(v=>`<option ${d.ervaring===v?'selected':''}>${v}</option>`).join('')}</select></div>${F('specs','Specialismen (komma-gescheiden)','text','full')}`,
    `${F('tarief','Uurtarief excl. btw (€)','number')}${F('regio','Werkgebied (plaats + straal)')}`,
    `<div class="full alert info">${ic('lock')}<div class="grow">Wij vragen alleen wat nodig is voor deze samenwerking. Een kopie van uw identiteitsbewijs of VOG slaan wij niet op; wij registreren alleen dat de controle is gedaan.</div></div>${F('vca','VCA geldig tot','date')}${F('avb','Aansprakelijkheidsverzekering geldig tot','date')}<div class="f"><label for="ob-g">G-rekening aanwezig</label><select class="in" id="ob-g" name="grek"><option value="ja" ${d.grek==='ja'?'selected':''}>Ja</option><option value="nee" ${d.grek==='nee'?'selected':''}>Nee</option></select></div><label class="row full" style="cursor:pointer"><input type="checkbox" name="bewoond" ${d.bewoond?'checked':''}> Ik werk in bewoonde woningen of zorginstellingen (dan vragen wij een VOG-controle aan)</label>`,
    `<div class="full calcbox"><b>Samenwerkingsafspraken</b><div>• Werken volgens de modelovereenkomst (DBA) van Renovion Groep</div><div>• Prijzen per prijsaanvraag, betaling volgens opdrachtbevestiging</div><div>• Veiligheid volgens GPI en V&amp;G-plan per project</div></div><label class="row full" style="cursor:pointer"><input type="checkbox" name="dba" ${d.dba?'checked':''}> Ik ga akkoord met de modelovereenkomst</label>`,
    `<div class="full kv"><span>Bedrijf</span><b>${esc(d.bedrijf||'—')}</b><span>Contact</span><b>${esc(d.contact||'—')} · ${esc(d.mail||'')}</b><span>Vakgebied</span><b>${esc(d.vak)} · ${esc(d.ervaring)}</b><span>Tarief</span><b>${d.tarief?eur(+d.tarief)+' per uur':'—'}</b><span>Werkgebied</span><b>${esc(d.regio||'—')}</b><span>VCA</span><b>${d.vca?'t/m '+fmtDY(d.vca):'Ontbreekt'}</b><span>Verzekering</span><b>${d.avb?'t/m '+fmtDY(d.avb):'Ontbreekt'}</b><span>Modelovereenkomst</span><b>${d.dba?'Akkoord':'Nog niet'}</b></div><label class="row full" style="cursor:pointer"><input type="checkbox" name="akkoord" ${d.akkoord?'checked':''}> Deze gegevens kloppen</label>`];
  modal('Partner aanmelden',`<div class="wsteps">${ONB_STEPS.map((_,i)=>`<span class="${i<=s?'on':''}"></span>`).join('')}</div><div class="row between"><b>Stap ${s+1} van 6 · ${ONB_STEPS[s]}</b></div><form class="fg" data-form="onb">${steps[s]}</form><div class="ferr" id="ob-err"></div>`,
    `${s>0?`<button class="btn" data-act="onb-prev">Vorige</button>`:''}<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="onb-next">${s===5?'Aanmelding indienen':'Volgende'}</button>`);
}
function onbCollect(){ const f=document.querySelector('[data-form="onb"]'); if(!f) return; const d=UI.onb.d; f.querySelectorAll('input,select').forEach(el=>{ d[el.name]=el.type==='checkbox'?el.checked:el.value.trim(); }); }

/* ---------- Projectdossier-tabs ---------- */
const PD_R2={
  werkbonnen(p){ const ws=S.werkbonnen.filter(w=>w.pid===p.id).sort((a,b)=>a.datum<b.datum?-1:1); const uren=ws.reduce((s,w)=>s+(+w.uren||0),0), begr=ws.reduce((s,w)=>s+w.begrUren,0);
    return `<div class="card"><div class="card-h"><h3>Werkbonnen <span class="muted" style="font-weight:500;font-size:13px">· ${NUM.format(uren)} van ${begr} uur geregistreerd</span></h3><button class="btn sm pri" data-act="wb-new" data-pid="${p.id}">${ic('plus')}Werkbon</button></div>
    ${ws.length?`<div class="tw"><table class="t"><thead><tr><th>Werkbon</th><th>Vakman</th><th>Datum</th><th class="r">Uren</th><th>Status</th></tr></thead><tbody>${ws.map(w=>`<tr class="click" data-go="werkbon-${w.nr.toLowerCase()}"><td><b>${w.nr}</b><div class="sub">${esc(w.titel)}</div></td><td>${esc(empName(w.emp))}</td><td>${fmtD(w.datum)}</td><td class="r">${NUM.format(+w.uren||0)} / ${w.begrUren}</td><td>${wbPill(w.status)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nog geen werkbonnen.</div>`}</div>`; },
  inkoop(p){ const rs=S.rfqs.filter(r=>r.pid===p.id); const c=paCommitments(p.id);
    return `<div class="grid g3"><div class="card kpi dark"><span class="lbl">Vastgelegde verplichtingen</span><span class="v num">${heur(c.verpl)}</span><span class="s">gegunde, nog niet opgeleverde opdrachten</span></div><div class="card kpi"><span class="lbl">Gegund t.o.v. budget</span><span class="v num ${c.delta>0?'dn':'up'}">${c.delta>0?'+':''}${eur(c.delta)}</span><span class="s">verwerkt in verwachte marge</span></div><div class="card kpi"><span class="lbl">Prijsaanvragen</span><span class="v num">${rs.length}</span><span class="s">${rs.filter(r=>r.status==='uitgezet').length} wachten op reactie</span></div></div>
    <div class="card"><div class="card-h"><h3>Prijsaanvragen en onderaanneming</h3><button class="btn sm pri" data-act="pa-new" data-pid="${p.id}">${ic('plus')}Prijsaanvraag</button></div>${rs.length?`<div class="tw"><table class="t"><thead><tr><th>Aanvraag</th><th class="r">Budget</th><th class="r">Gegund</th><th>Partner</th><th>Status</th></tr></thead><tbody>${rs.map(r=>`<tr class="click" data-go="prijsaanvraag-${r.id.toLowerCase()}"><td><b>${r.id}</b><div class="sub">${esc(r.titel)}</div></td><td class="r">${eur(r.budget)}</td><td class="r">${r.awardedTo?eur(awardPrice(r)):'—'}</td><td>${r.awardedTo?esc(sub(r.awardedTo).naam):`${r.bids.length}/${r.invited.length} reacties`}</td><td><span class="pill ${PA_ST[r.status][1]}">${PA_ST[r.status][0]}</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nog geen prijsaanvragen. Zet een werkpakket uit de begroting uit bij partners.</div>`}</div>`; },
};
function r2Attention(){
  const items=[]; const ctrl=S.werkbonnen.filter(w=>w.status==='controle'); if(ctrl.length) items.push({k:'or',icon:'wrench',t:`${ctrl.length} ${ctrl.length===1?'werkbon wacht':'werkbonnen wachten'} op goedkeuring`,s:ctrl.slice(0,3).map(w=>`${w.nr} ${firstName(w.emp)}`).join(', '),btn:'Bekijk',go:'werkbonnen',wbTab:'controle'});
  const exp=allCerts().filter(c=>certState(c.c)==='verlopen'); if(exp.length) items.push({k:'bad',icon:'shield',t:`${exp.length} ${exp.length===1?'certificaat is':'certificaten zijn'} verlopen`,s:exp.slice(0,3).map(c=>`${c.c.t} · ${c.wie}`).join(', '),btn:'Bekijk',go:'workforce',wfTab:'certs'});
  const bids=S.rfqs.filter(r=>r.status==='uitgezet'&&r.bids.length); if(bids.length) items.push({k:'blue',icon:'store',t:`Prijzen binnen voor ${bids.length} ${bids.length===1?'prijsaanvraag':'prijsaanvragen'}`,s:bids.map(r=>`${r.titel} (${r.bids.length})`).join(', '),btn:'Vergelijk',go:'prijsaanvraag-'+bids[0].id.toLowerCase()});
  return items;
}

/* ---------- Nova-uitbreiding ---------- */
function novaR2(t){
  if(/werkbon/.test(t)){ const c=S.werkbonnen.filter(w=>w.status==='controle'), u=S.werkbonnen.filter(w=>w.status==='uitvoering'); novaSay(`<b>Werkbonnen</b><br>${c.length} ter controle${c.length?': '+c.map(w=>`<a href="/werkbon-${w.nr.toLowerCase()}" data-act="nclose">${w.nr}</a> ${esc(firstName(w.emp))} (${NUM.format(+w.uren||0)}/${w.begrUren} u${w.obstakels?', obstakel gemeld':''})`).join(', '):''}<br>${u.length} in uitvoering: ${u.map(w=>`${esc(firstName(w.emp))} · ${esc(w.titel)}`).join(', ')||'—'}`); return true; }
  if(/certificaat|certificaten|vca|verloopt|verlopen/.test(t)){ const l=allCerts().filter(c=>certState(c.c)!=='ok'); novaSay(l.length?`<b>${l.length} certificaten vragen actie</b><br>${l.map(c=>`• ${esc(c.c.t)} · ${esc(c.wie)}: ${certState(c.c)==='verlopen'?'<b class="dn">verlopen</b> '+fmtD(c.c.g):'verloopt '+fmtD(c.c.g)}`).join('<br>')}<br>Ik informeer niemand automatisch; vraag me een taak aan te maken als je wilt opvolgen.`:'Alle certificaten zijn geldig.'); return true; }
  if(/prijsaanvra|onderaannem|partnerprijs|werkhub/.test(t)){ const o=S.rfqs.filter(r=>r.status==='uitgezet'); novaSay(`<b>Werkhub</b><br>${o.map(r=>{ const b=r.bids.length?r.bids.reduce((a,x)=>a.prijs<x.prijs?a:x):null; return `• <a href="/prijsaanvraag-${r.id.toLowerCase()}" data-act="nclose">${esc(r.titel)}</a>: ${r.bids.length}/${r.invited.length} prijzen${b?`, laagste ${eur(b.prijs)} van ${esc(sub(b.sub).naam)} (budget ${eur(r.budget)})`:''}`; }).join('<br>')||'Geen open prijsaanvragen.'}<br>Openstaande verplichtingen: ${eur(S.rfqs.filter(r=>r.status==='gegund').reduce((s,r)=>s+awardPrice(r),0))}.`); return true; }
  return false;
}

/* ---------- Router-uitbreiding ---------- */
const R2_ROUTES={werkbonnen:vWerkbonnen,workforce:vWorkforce,onderaannemers:vOnderaannemers,partner:vPartner,werkhub:vWerkhub};
function r2Route(r){ if(R2_ROUTES[r]) return R2_ROUTES[r](); if(r.startsWith('werkbon-')) return vWerkbon(r.slice(8).toUpperCase()); if(r.startsWith('prijsaanvraag-')) return vPa(r.slice(14).toUpperCase()); return null; }
function r2AfterRender(r){ if(r.startsWith('werkbon-')&&$('#wbsig')) bindSig('wbsig'); }

/* ---------- Formulieren ---------- */
const R2_FORMS={
  werkbon(f,v){ if(!v.titel) return fieldErr(f,'titel','Omschrijf de werkzaamheden.'); if(v.eind<v.datum) return fieldErr(f,'eind','Einddatum ligt vóór de start.');
    const cl=String(v.checklist||'').split('\n').map(x=>x.trim()).filter(Boolean); const nr=f.dataset.nr;
    if(nr){ const w=wb(nr); Object.assign(w,{titel:v.titel,pid:v.pid,emp:v.emp,datum:v.datum,eind:v.eind,begrUren:parseNL(v.begrUren),taskId:v.taskId}); w.checklist=cl.map(t=>({t,d:(w.checklist.find(c=>c.t===t)||{}).d||false})); w.materialen=parseMat(v.materialen); wbLog(w,'Werkbon bewerkt'); closeModal(); commit('Werkbon opgeslagen'); return; }
    S.seq.wb++; const w={nr:'WB-'+YEAR+'-'+String(S.seq.wb).padStart(4,'0'),pid:v.pid,emp:v.emp,blockId:f.dataset.block||'',datum:v.datum,eind:v.eind,titel:v.titel,status:'concept',begrUren:parseNL(v.begrUren),uren:0,checklist:cl.map(t=>({t,d:false})),materialen:parseMat(v.materialen),fotos:[],opm:'',obstakels:'',getekend:'',taskId:v.taskId,log:[{d:TODAY,t:'Werkbon aangemaakt'}]};
    if(!w.checklist.length) w.checklist=[{t:'Werkplek voorbereid',d:false},{t:'Werkzaamheden uitgevoerd',d:false},{t:'Werkplek opgeruimd',d:false}];
    S.werkbonnen.push(w); const p=proj(w.pid); if(p) addActivity(p,`Werkbon ${w.nr} aangemaakt: ${w.titel}`,'mut'); closeModal(); save(); go('werkbon-'+w.nr.toLowerCase()); toast(`Werkbon ${w.nr} aangemaakt`); },
  paper(f,v){ S.seq.wb++; const w={nr:'WB-'+YEAR+'-'+String(S.seq.wb).padStart(4,'0'),pid:v.pid,emp:v.emp,blockId:'',datum:v.datum,eind:v.datum,titel:v.titel,status:'controle',begrUren:parseNL(v.uren),uren:parseNL(v.uren),checklist:[{t:'Werkzaamheden volgens papieren werkbon',d:true}],materialen:[],fotos:UI.paper&&UI.paper.src?[{naam:UI.paper.naam,src:UI.paper.src}]:[],opm:v.opm,obstakels:'',getekend:v.getekend,log:[{d:TODAY,t:`Ingelezen van papieren werkbon (${UI.paper?UI.paper.naam:'upload'}), gesimuleerde uitlezing gecontroleerd`}]};
    S.werkbonnen.push(w); closeModal(); save(); go('werkbon-'+w.nr.toLowerCase()); toast(`Werkbon ${w.nr} aangemaakt en klaargezet voor controle`); },
  person(f,v){ const e=emp(f.dataset.id); Object.assign(e,{tel:v.tel,mail:v.mail,regio:v.regio,tarief:parseNL(v.tarief),cap:parseNL(v.cap)||e.cap,rating:+v.rating,specs:v.specs.split(',').map(x=>x.trim()).filter(Boolean),talen:v.talen.split(',').map(x=>x.trim()).filter(Boolean)});
    if(v.afwVan&&v.afwTot){ if(v.afwTot<v.afwVan) return fieldErr(f,'afwVan','"Tot" ligt vóór "van".'); e.afwezig.push({van:v.afwVan,tot:v.afwTot,reden:'Afwezig'}); const cf=S.blocks.filter(b=>b.emp===e.id&&b.start<=v.afwTot&&v.afwVan<=b.end); closeModal(); commit(cf.length?`Afwezigheid opgeslagen. Let op: ${cf.length} ingepland blok valt in deze periode`:'Profiel opgeslagen',cf.length?'warn':'ok'); return; }
    closeModal(); commit('Profiel opgeslagen'); },
  planteam(f,v){ if(!v.titel) return fieldErr(f,'titel','Omschrijf de werkzaamheden.'); if(!v.start||!v.end||v.end<v.start) return fieldErr(f,'end','Kies een geldige periode.'); const t=S.teams.find(x=>x.id===f.dataset.t); let n=0, conf=0;
    for(const id of t.leden){ if(!isFree(id,v.start,v.end)) conf++; S.blocks.push({id:uid('b'),emp:id,pid:v.pid,titel:v.titel,start:v.start,end:v.end}); n++; }
    t.pid=v.pid; const p=proj(v.pid); if(p) addActivity(p,`${t.naam} ingepland: ${v.titel}, ${fmtD(v.start)}–${fmtD(v.end)} (${n} personen)`,'blue'); closeModal(); commit(conf?`${n} blokken ingepland, ${conf} met dubbele bezetting`:`${n} blokken ingepland`,conf?'warn':'ok'); },
  pa(f,v,send){ if(!v.titel) return fieldErr(f,'titel','Geef de prijsaanvraag een titel.'); if(!(parseNL(v.budget)>0)) return fieldErr(f,'budget','Vul een budget in.'); const inv=[...f.querySelectorAll('[name="inv"]:checked')].map(x=>x.value); if(send&&!inv.length){ fieldErr(f,'deadline','Kies minstens één partner om uit te nodigen.'); return; }
    S.seq.pa++; const r={id:'PA-'+YEAR+'-'+String(S.seq.pa).padStart(4,'0'),pid:v.pid,ch:v.ch,titel:v.titel,budget:parseNL(v.budget),scope:v.scope,deadline:v.deadline,status:'concept',invited:inv,docs:(proj(v.pid).docs||[]).filter(d=>/tekening|plattegrond|bestek|keuze/i.test(d.naam)).map(d=>d.naam),bids:[]};
    S.rfqs.push(r); if(send) sendPa(r); else addActivity(proj(r.pid),`Prijsaanvraag ${r.id} als concept opgeslagen`,'mut'); closeModal(); save(); go('prijsaanvraag-'+r.id.toLowerCase()); toast(send?`${r.id} uitgezet bij ${inv.length} partners: zij zien de aanvraag in hun partnerportaal`:`${r.id} opgeslagen als concept`); },
  ppbid(f,v){ const r=pa(f.dataset.id); const p=parseNL(v.prijs); if(!(p>0)) return fieldErr(f,'prijs','Vul een prijs in.'); r.bids.push({sub:f.dataset.sub,prijs:p,start:v.start,dagen:parseNL(v.dagen)||1,voorw:v.voorw||'Geen bijzondere voorwaarden',compleet:+v.compleet,datum:TODAY,opm:+v.compleet<95?'Gedeeltelijk geprijsd':''}); addActivity(proj(r.pid),`Prijs ontvangen van ${sub(f.dataset.sub).naam} voor ${r.id}: ${eur(p)}`,'blue'); S.notifs.unshift({t:`Nieuwe prijs voor ${r.titel}`,d:TODAY}); commit('Prijs ingediend. Renovion ontvangt een melding.'); },
};
function sendPa(r){ r.status='uitgezet'; for(const sid of r.invited) S.outbox.push({d:TODAY,aan:sub(sid).mail,onderwerp:`Prijsaanvraag ${r.id}: ${r.titel}`}); addActivity(proj(r.pid),`Prijsaanvraag ${r.id} uitgezet bij ${r.invited.length} partners`,'blue'); }

/* ---------- Events ---------- */
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act, d=el.dataset;
  switch(a){
    case 'wb-tab': UI.wbTab=d.t; render(); break;
    case 'wb-new': mWerkbon(null,d.pid); break;
    case 'wb-edit': mWerkbon(wb(d.nr)); break;
    case 'wb-fromblock': mWerkbon(null,'',d.id); break;
    case 'wb-paper': mPaper(); break;
    case 'wb-set': { const w=wb(d.nr); const lbl=WB_ST.find(x=>x[0]===d.s)[1]; const back=w.status==='controle'&&d.s==='uitvoering'; w.status=d.s; wbLog(w,back?'Teruggestuurd naar vakman':`Status: ${lbl}`); if(d.s==='uitgegeven') S.outbox.push({d:TODAY,aan:(emp(w.emp)||{}).mail,onderwerp:`Werkbon ${w.nr}: ${w.titel}`}); commit(back?'Teruggestuurd naar de vakman':d.s==='uitgegeven'?`Uitgegeven aan ${firstName(w.emp)} (melding in outbox)`:`Status ${lbl}`); break; }
    case 'wb-start': { const w=wb(d.nr); w.status='uitvoering'; wbLog(w,`Gestart door ${firstName(w.emp)}`); const p=proj(w.pid); if(p&&p.phase===5){ p.phase=6; addActivity(p,'Uitvoering gestart (eerste werkbon)','ok'); } commit('Werkbon gestart'); break; }
    case 'wb-chk': { const w=wb(d.nr); const c=w.checklist[+d.i]; c.d=!c.d; save(); render(); break; }
    case 'wb-uren': { const w=wb(d.nr); w.uren=Math.max(0,(+w.uren||0)+(+d.d)); save(); render(); break; }
    case 'wb-sigclear': { const cv=$('#wbsig'); cv.getContext('2d').clearRect(0,0,cv.width,cv.height); UI.wbSigned=false; break; }
    case 'wb-finish': { const w=wb(d.nr); const err=$('#wb-err'); const open=w.checklist.filter(c=>!c.d).length; const nm=$('#wb-signame').value.trim();
      if(!(+w.uren>0)){ err.textContent='Registreer eerst je gewerkte uren.'; break; } if(open&&!w.obstakels.trim()){ err.textContent=`${open} checklistpunt${open>1?'en staan':' staat'} nog open. Vink af of beschrijf bij Obstakels waarom.`; break; } if(!UI.wbSigned||!nm){ err.textContent='Laat de werkbon aftekenen (naam en handtekening).'; break; }
      w.getekend=nm; w.status='controle'; wbLog(w,`Afgerond en ingediend, afgetekend door ${nm}`); S.notifs.unshift({t:`Werkbon ${w.nr} ingediend door ${firstName(w.emp)}`,d:TODAY}); commit('Ingediend. Kantoor krijgt een melding.'); break; }
    case 'wb-approve': { const w=wb(d.nr); const msg=approveWb(w); commit(msg); break; }
    case 'wf-tab': UI.wfTab=d.t; render(); break;
    case 'wf-filter': UI.wfFilter=d.f; render(); break;
    case 'wf-open': mPerson(d.id); break;
    case 'wf-newteam': { S.teams.push({id:uid('tm'),naam:'Nieuw team',leden:[],pid:''}); UI.wfTab='teams'; commit('Team aangemaakt. Voeg leden toe.'); break; }
    case 'wf-rmlid': { const t=S.teams.find(x=>x.id===d.t); t.leden=t.leden.filter(x=>x!==d.e); commit(); break; }
    case 'wf-delteam': { const t=S.teams.find(x=>x.id===d.t); mConfirm('Team verwijderen',`${esc(t.naam)} verwijderen? Ingeplande blokken blijven staan.`,'Verwijderen',()=>{ S.teams=S.teams.filter(x=>x.id!==d.t); },true); break; }
    case 'wf-planteam': mPlanTeam(S.teams.find(x=>x.id===d.t)); break;
    case 'wf-renew': { const nd=addDays(TODAY,365*(/VCA/.test(d.t)?10:3)); if(d.emp){ const c=emp(d.emp).certs.find(x=>x.t===d.t); c.g=nd; } else { const dd=sub(d.sub).docs.find(x=>x.t===d.t); dd.g=nd; dd.ok=true; } commit(`${d.t} geregistreerd t/m ${fmtDY(nd)}`); break; }
    case 'sub-filter': UI.subFilter=d.f; render(); break;
    case 'sub-open': mSub(d.id); break;
    case 'sub-doc': { const s=sub(d.id); const dd=s.docs[+d.i]; dd.ok=true; if(dd.g!==null||dd.t!=='G-rekening'&&dd.t!=='Identiteit gecontroleerd') dd.g=addDays(TODAY,365); s.checks.push({t:`${dd.t} ontvangen en gecontroleerd`,door:myName(),d:TODAY,ok:true}); save(); mSub(d.id); render(); toast(`${dd.t} geregistreerd`); break; }
    case 'sub-approve': { const s=sub(d.id); s.keurmerk='goedgekeurd'; s.checks.push({t:'Renovion-keurmerk toegekend',door:myName(),d:TODAY,ok:true}); closeModal(); commit(subStatus(s)==='goedgekeurd'?`${s.naam} is goedgekeurd`:`Keurmerk toegekend, maar status blijft "${KEUR[subStatus(s)][0]}" tot de documenten in orde zijn`,subStatus(s)==='goedgekeurd'?'ok':'warn'); break; }
    case 'sub-block': { const s=sub(d.id); s.blocked=true; s.blockReden=`Geblokkeerd door ${myName()} op ${fmtDY(TODAY)}.`; s.checks.push({t:'Tijdelijk geblokkeerd',door:myName(),d:TODAY,ok:true}); closeModal(); commit(`${s.naam} tijdelijk geblokkeerd`,'warn'); break; }
    case 'sub-unblock': { const s=sub(d.id); s.blocked=false; s.checks.push({t:'Blokkade opgeheven',door:myName(),d:TODAY,ok:true}); closeModal(); commit('Blokkade opgeheven'); break; }
    case 'pa-filter': UI.paFilter=d.f; render(); break;
    case 'pa-new': mNewPa(); if(d.pid){ const f=document.querySelector('[data-form="pa"]'); f.pid.value=d.pid; paFillCh(); } break;
    case 'pa-submit-send': { const f=document.querySelector('[data-form="pa"]'); R2_FORMS.pa(f,formData(f),true); break; }
    case 'pa-send': { const r=pa(d.id); mConfirm('Uitnodigingen verzenden',`${r.invited.length} partners ontvangen prijsaanvraag ${r.id}. Er wordt niets extern verzonden; de berichten komen in de outbox.`,'Verzenden',()=>sendPa(r)); break; }
    case 'pa-sim': { const r=pa(d.id); const n=simBids(r); if(n){ addActivity(proj(r.pid),`${n} partnerprijzen ontvangen voor ${r.id} (gesimuleerd)`,'blue'); } commit(n?`${n} gesimuleerde reacties toegevoegd`:'Geen partners meer om te simuleren'); break; }
    case 'pa-award': { const r=pa(d.id); const s=sub(d.sub); const b=r.bids.find(x=>x.sub===d.sub); if(subStatus(s)!=='goedgekeurd'){ toast(`Gunnen aan ${s.naam} kan niet: keurmerk is "${KEUR[subStatus(s)][0]}". Los dit eerst op bij Onderaannemers.`,'warn'); break; }
      mConfirm('Opdracht gunnen',`${esc(s.naam)} voor <b>${eur(b.prijs)}</b> excl. btw (budget ${eur(r.budget)}, verschil ${eur(b.prijs-r.budget)}).${b.compleet<95?`<br><br><b style="color:var(--warn)">Let op: deze partner heeft de scope niet volledig geprijsd${b.opm?' ('+esc(b.opm)+')':''}. Ontbrekende posten komen voor rekening van het project.</b>`:''}<br><br>Dit maakt opdracht en opdrachtbevestiging aan, zet het bedrag als verplichting in de prognose van ${r.pid}${s.empId?', plant '+esc(firstName(s.empId))+' in vanaf '+fmtD(b.start):''} en informeert de andere partners (in de outbox).`,'Gunnen',()=>{ UI._awardMsg=awardPa(r,d.sub); }); break; }
    case 'pa-done': { const r=pa(d.id); mConfirm('Oplevering registreren',`Bevestig dat ${esc(sub(r.awardedTo).naam)} ${esc(r.titel)} heeft opgeleverd. ${eur(awardPrice(r))} gaat van verplichting naar werkelijke kosten.`,'Registreren',()=>{ r.status='afgerond'; r.voortgang=100; r.opgeleverd=TODAY; const p=proj(r.pid); if(p){ p.kosten=(p.kosten||0)+awardPrice(r); addActivity(p,`Oplevering ${r.orderNr} geregistreerd: ${eur(awardPrice(r))} geboekt`,'ok'); } }); break; }
    case 'pp-tab': UI.ppTab=d.t; render(); break;
    case 'pp-onboard': UI.onb=null; mOnboard(); break;
    case 'onb-prev': onbCollect(); UI.onb.step--; mOnboard(); break;
    case 'onb-next': { onbCollect(); const o=UI.onb, dd=o.d; const err=m=>{ $('#ob-err').textContent=m; };
      if(o.step===0&&(!dd.bedrijf||!dd.contact||!/^\d{8}$/.test(dd.kvk)||!/^\S+@\S+\.\S+$/.test(dd.mail))){ err('Vul bedrijfsnaam, contactpersoon, een KvK-nummer van 8 cijfers en een geldig e-mailadres in.'); break; }
      if(o.step===2&&!(parseNL(dd.tarief)>0)){ err('Vul een uurtarief in.'); break; }
      if(o.step===4&&!dd.dba){ err('Akkoord met de modelovereenkomst is nodig om samen te werken.'); break; }
      if(o.step<5){ o.step++; mOnboard(); break; }
      if(!dd.akkoord){ err('Bevestig dat de gegevens kloppen.'); break; }
      const id='s'+(S.subs.length+1)+uid(''); const sb={id,naam:dd.bedrijf,contact:dd.contact,empId:'',vak:dd.vak,regio:dd.regio||'—',kvk:dd.kvk,tarief:parseNL(dd.tarief),eenheid:'uur',rating:0,keurmerk:'beoordeling',blocked:false,opdrachten:0,mail:dd.mail,
        docs:[{t:'KvK-uittreksel',g:addDays(TODAY,365),ok:true},{t:'Aansprakelijkheidsverzekering',g:dd.avb||null,ok:!!dd.avb},{t:'VCA-certificaat',g:dd.vca||null,ok:!!dd.vca},{t:'G-rekening',g:null,ok:dd.grek==='ja'},{t:'Identiteit gecontroleerd',g:null,ok:false},{t:'Modelovereenkomst (DBA)',g:addDays(TODAY,365*2),ok:true},...(dd.bewoond?[{t:'VOG-controle (alleen status)',g:null,ok:false}]:[])],
        checks:[{t:'Aanmelding ontvangen via Partner Portal',door:'Systeem',d:TODAY,ok:true},{t:'KvK-inschrijving controleren',door:'—',d:'',ok:false},{t:'Identiteit controleren bij kennismaking (geen kopie)',door:'—',d:'',ok:false}]};
      S.subs.push(sb); S.tasks.push({id:uid('t'),titel:`Onboarding ${dd.bedrijf} beoordelen`,pid:'',eig:osInkoop(),dl:addDays(TODAY,3),status:'todo',prio:'normaal',oms:'Aangemaakt via Partner Portal.',checklist:[{t:'KvK controleren',d:false},{t:'Kennismaking en ID-controle',d:false},{t:'Proefopdracht plannen',d:false}]});
      UI.onb=null; closeModal(); UI.subFilter='alle'; commit(`${dd.bedrijf} aangemeld. Status: in beoordeling, taak voor Fatima klaargezet.`); break; }
  }
});
document.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset.wbf){ const w=wb(t.dataset.nr); w[t.dataset.wbf]=t.value; save(); return; }
  if(t.dataset.wbfoto){ const w=wb(t.dataset.wbfoto); const fs=[...t.files].slice(0,6); Promise.all(fs.map(f=>downscale(f,360).then(src=>src&&({naam:f.name,src})))).then(arr=>{ arr.filter(Boolean).forEach(x=>w.fotos.push(x)); wbLog(w,`${arr.filter(Boolean).length} foto('s) toegevoegd`); commit(`${arr.filter(Boolean).length} foto('s) toegevoegd`); }); return; }
  if(t.id==='paperfile'&&t.files[0]){ const f=t.files[0]; const isImg=/^image\//.test(f.type); (isImg?downscale(f,480):Promise.resolve(null)).then(src=>{ UI.paper={naam:f.name,src}; paperForm(f.name,src); }); return; }
  if(t.dataset.addlid&&t.value){ const tm=S.teams.find(x=>x.id===t.dataset.addlid); tm.leden.push(t.value); commit(`${empName(t.value)} toegevoegd aan ${tm.naam}`); return; }
  if(t.dataset.teampid!==undefined){ const tm=S.teams.find(x=>x.id===t.dataset.teampid); tm.pid=t.value; commit('Projecttoewijzing opgeslagen'); return; }
  if(t.closest('[data-form="planteam"]')){ teamCheck(); return; }
  if(t.closest('[data-form="pa"]')){ if(t.name==='pid') paFillCh(); else if(t.name==='ch') paFillFromCh(); return; }
  if(t.dataset.painv){ const r=pa(t.dataset.painv); if(t.checked) r.invited.push(t.value); else r.invited=r.invited.filter(x=>x!==t.value); commit(); return; }
  if(t.dataset.pavg){ const r=pa(t.dataset.pavg); r.voortgang=+t.value; commit(`Voortgang ${r.voortgang}%`); return; }
  if(t.id==='ppsel'){ UI.ppSub=t.value; render(); return; }
  if(t.dataset.ppdoc){ const s=sub(t.dataset.ppdoc); const dd=s.docs[+t.dataset.i]; dd.ok=true; dd.g=addDays(TODAY,365); s.checks.push({t:`${dd.t} geüpload via portal (${t.files[0]?t.files[0].name:'bestand'}), nog te beoordelen`,door:s.contact,d:TODAY,ok:true}); commit(`${dd.t} ontvangen`); return; }
});
document.addEventListener('input',e=>{ if(e.target.closest('[data-form="planteam"]')) teamCheck(); });

