/* ---------- Grafiekhulpjes ---------- */
function niceMax(v){ if(v<=0) return 1; const e=Math.pow(10,Math.floor(Math.log10(v))); const n=v/e; return (n<=1?1:n<=2?2:n<=2.5?2.5:n<=5?5:10)*e; }
function kfmt(v){ const a=Math.abs(v), s=v<0?'−':''; if(a>=1e6) return s+'€ '+(a/1e6).toLocaleString('nl-NL',{maximumFractionDigits:1})+' mln'; if(a>=1e3) return s+'€ '+Math.round(a/1e3)+'k'; return s+'€ '+Math.round(a); }
function barChart(o){
  const mob=window.matchMedia&&matchMedia('(max-width: 640px)').matches; const W=mob?360:(o.w||560),H=mob?230:(o.h||(o.w&&o.w<500?220:240)),pl=mob?46:54,pr=10,pt=10,pb=26; const every=mob&&o.labels.length>6?2:1; const n=o.labels.length; const ser=o.series;
  const vals=ser.flatMap(s=>s.values).concat(o.line?o.line.values:[]); let mx=niceMax(Math.max(0,...vals)); let mn=Math.min(0,...vals); if(mn<0) mn=-niceMax(-mn);
  const y=v=>pt+(mx-v)/(mx-mn)*(H-pt-pb); const bw=(W-pl-pr)/n; const gw=Math.min(bw*0.72,ser.length*34); const each=(gw-(ser.length-1)*2)/ser.length;
  let g=''; const ticks=4; for(let i=0;i<=ticks;i++){ const v=mn+(mx-mn)*i/ticks; g+=`<line class="grid-l" x1="${pl}" x2="${W-pr}" y1="${y(v)}" y2="${y(v)}"/><text x="${pl-8}" y="${y(v)+4}" text-anchor="end">${kfmt(v)}</text>`; }
  g+=`<line class="base-l" x1="${pl}" x2="${W-pr}" y1="${y(0)}" y2="${y(0)}"/>`;
  o.labels.forEach((l,i)=>{ const cx=pl+bw*i+bw/2; if(i%every===0) g+=`<text x="${cx}" y="${H-8}" text-anchor="middle">${esc(l)}</text>`;
    ser.forEach((s,j)=>{ const v=s.values[i]||0; if(!v) return; const x=cx-gw/2+j*(each+2), y0=y(0), y1=y(v), r=Math.min(4,each/2,Math.abs(y0-y1)); const top=Math.min(y0,y1), bot=Math.max(y0,y1);
      g+= v>=0?`<path d="M${x},${bot}V${top+r}Q${x},${top} ${x+r},${top}H${x+each-r}Q${x+each},${top} ${x+each},${top+r}V${bot}Z" fill="var(${s.c})"/>`:`<path d="M${x},${top}V${bot-r}Q${x},${bot} ${x+r},${bot}H${x+each-r}Q${x+each},${bot} ${x+each},${bot-r}V${top}Z" fill="var(${s.c})"/>`; }); });
  if(o.line){ const pts=o.line.values.map((v,i)=>[pl+bw*i+bw/2,y(v)]); g+=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="var(${o.line.c})" stroke-width="2" stroke-linejoin="round"/>`+pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="var(${o.line.c})" stroke="var(--card)" stroke-width="2"/>`).join(''); }
  o.labels.forEach((l,i)=>{ const tip=`<b>${esc(o.tipLabels?o.tipLabels[i]:l)}</b>`+ser.map(s=>`<div class="tr"><span><i style="background:var(${s.c})"></i>${esc(s.name)}</span><span>${eur0(s.values[i]||0)}</span></div>`).join('')+(o.line?`<div class="tr"><span><i style="background:var(${o.line.c})"></i>${esc(o.line.name)}</span><span>${eur0(o.line.values[i])}</span></div>`:''); g+=`<rect class="hit" x="${pl+bw*i}" y="${pt}" width="${bw}" height="${H-pt-pb}" data-tip="${esc(tip)}"/>`; });
  const leg=(ser.length>1||o.line)?`<div class="chart-legend">${ser.map(s=>`<span><i style="background:var(${s.c})"></i>${esc(s.name)}</span>`).join('')}${o.line?`<span><i class="ln" style="background:var(${o.line.c})"></i>${esc(o.line.name)}</span>`:''}</div>`:'';
  return `${leg}<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(o.aria||'')}">${g}</svg></div>`;
}
document.addEventListener('mouseover',e=>{ const t=e.target.closest('[data-tip]'); let tip=$('#ctip'); if(!t){ if(tip) tip.hidden=true; return; } if(!tip){ tip=document.createElement('div'); tip.id='ctip'; document.body.appendChild(tip); } tip.innerHTML=t.dataset.tip; tip.hidden=false; });
document.addEventListener('mousemove',e=>{ const tip=$('#ctip'); if(!tip||tip.hidden) return; const w=tip.offsetWidth, h=tip.offsetHeight; tip.style.left=Math.min(window.innerWidth-w-12,e.clientX+14)+'px'; tip.style.top=Math.max(8,e.clientY-h-12)+'px'; });

/* ---------- Financiële berekeningen ---------- */
const MONTHS=['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec'];
const ym = d => d.slice(0,7);
const contracted = () => S.projects.filter(p=>p.offerte&&p.offerte.status==='geaccepteerd');
// Termijn 1 bij opdracht, termijn 2 bij start, laatste bij oplevering; tussenliggende termijnen gelijk verdeeld over de uitvoering
function termDates(p){ const n=p.termijnen.length; const s=p.start||TODAY, e=p.eind||addDays(s,60); const span=Math.max(1,diffDays(s,e)); return p.termijnen.map((t,i)=>i===0?(p.offerte.accepted||s):n<=2?e:addDays(s,Math.round(span*(i-1)/(n-2)))); }
function finCalc(){
  const inv=S.invoices.filter(i=>i.status!=='concept');
  const omzetMaand=m=>inv.filter(i=>ym(i.datum)===m).reduce((s,i)=>s+i.bedrag,0);
  const months2026=Array.from({length:+TODAY.slice(5,7)},(_,i)=>`${YEAR}-${String(i+1).padStart(2,'0')}`);
  const omzetReeks=months2026.map(m=>omzetMaand(m));
  const nu=ym(TODAY); const omzetM=omzetMaand(nu); const omzetQ=[0,1,2].map(k=>`${YEAR}-${String(Math.floor((+TODAY.slice(5,7)-1)/3)*3+1+k).padStart(2,'0')}`).reduce((s,m)=>s+omzetMaand(m),0); const omzetJ=omzetReeks.reduce((a,b)=>a+b,0);
  const proj=contracted(); let voorraad=0, nogTeFact=0; const fut=[];
  for(const p of proj){ const f=projectFin(p); voorraad+=Math.max(0,f.val-f.gefact); const ds=termDates(p); p.termijnen.forEach((t,i)=>{ if(!S.invoices.some(x=>x.pid===p.id&&x.termijn===i)){ const a=p.offerte.basis*(+t.pct||0)/100; nogTeFact+=a; fut.push({pid:p.id,d:ds[i]<TODAY?TODAY:ds[i],a}); } }); }
  const openOff=S.projects.filter(p=>p.offerte&&p.offerte.status==='verzonden').reduce((s,p)=>s+projectValue(p),0);
  const kans=[.1,.25,.4,.6]; const pipe=S.projects.filter(p=>p.phase<=3).reduce((s,p)=>s+projectValue(p)*kans[p.phase],0);
  let sv=0,sb=0,sw=0; for(const p of proj.filter(p=>p.phase<8)){ const f=projectFin(p); sv+=f.val; sb+=f.begroot; sw+=f.verwacht; }
  const deb=S.invoices.filter(i=>i.status==='verzonden'); const debTot=deb.reduce((s,i)=>s+i.bedrag*1.21,0), debVerv=deb.filter(i=>i.verval<TODAY).reduce((s,i)=>s+i.bedrag*1.21,0);
  const cred=S.inkoop.filter(x=>x.status!=='betaald'); const credTot=cred.reduce((s,x)=>s+x.bedrag,0);
  const verpl=S.rfqs.filter(r=>r.status==='gegund').reduce((s,r)=>s+awardPrice(r),0);
  const nIntern=S.emps.filter(e=>e.type==='intern').length, nKantoor=S.emps.filter(e=>e.type==='kantoor').length; const pers=nIntern*S.fin.loonIntern+nKantoor*S.fin.loonKantoor;
  // cashflow komende 6 maanden (excl. btw)
  const cm=[]; for(let i=0;i<6;i++){ const d=new Date(2026,10+i,1); cm.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); }
  const inM=cm.map(()=>0), outM=cm.map(()=>0); const idx=d=>{ const k=ym(d<TODAY?TODAY:d); const i=cm.indexOf(k); return i<0?(k<cm[0]?0:-1):i; };
  for(const i of deb){ const k=idx(i.verval); if(k>=0) inM[k]+=i.bedrag; }
  for(const f of fut){ const k=idx(addDays(f.d,14)); if(k>=0) inM[k]+=f.a; }
  for(const r of S.rfqs.filter(r=>r.status==='gegund')){ const b=awardBid(r); const k=idx(addDays(b.start,30)); if(k>=0) outM[k]+=b.prijs; }
  for(const x of cred){ const k=idx(x.verval); if(k>=0) outM[k]+=x.bedrag; }
  for(const p of proj.filter(p=>p.phase<8)){ const f=projectFin(p); const rest=Math.max(0,f.verwacht-f.werkelijk-paCommitments(p.id).verpl); const months=cm.filter(m=>m<=ym(p.eind||cm[5])); const share=months.length?rest*0.55/months.length:0; months.forEach(m=>{ outM[cm.indexOf(m)]+=share; }); }
  for(let i=0;i<6;i++) outM[i]+=pers+S.fin.bedrijfskosten;
  const saldo=[]; let b=S.fin.bank; for(let i=0;i<6;i++){ b+=inM[i]-outM[i]; saldo.push(Math.round(b)); }
  // werkvoorraad per maand (resterende contractwaarde, lineair verdeeld tot oplevering)
  const wv=cm.map(()=>0); for(const p of proj.filter(p=>p.phase<8)){ const f=projectFin(p); const rest=Math.max(0,f.val*(1-(p.progress||0)/100)); const ms=cm.filter(m=>m<=ym(p.eind||cm[0])); if(!ms.length) continue; ms.forEach(m=>wv[cm.indexOf(m)]+=rest/ms.length); }
  return {omzetReeks,months2026,omzetM,omzetQ,omzetJ,voorraad,nogTeFact,openOff,pipe,bm:sv?(sv-sb)/sv*100:0,em:sv?(sv-sw)/sv*100:0,debTot,debVerv,deb,credTot,cred,verpl,pers,cm,inM,outM,saldo,wv,proj};
}
const cmLabel = m => MONTHS[+m.slice(5)-1]+(m.slice(5)==='01'?' ’'+m.slice(2,4):'');

/* ---------- Financieel ---------- */
function vFinancieel(){
  const tab=UI.finTab||'overzicht'; const F=finCalc();
  const mStat=m=>m>=12?['ok','Gezond']:m>=6?['warn','Krap']:['bad','Risico'];
  let body='';
  if(tab==='overzicht'){
    const cats={arbeid:0,mat:0,mt:0,oa:0,ov:0}; for(const p of S.projects.filter(p=>p.begroting)){ const k=calcB(p.begroting); for(const c in cats) cats[c]+=k.cat[c]; } const ct=Object.values(cats).reduce((a,b)=>a+b,0)||1;
    const catL=[['Arbeid','arbeid','--c-arb'],['Materiaal','mat','--c-mat'],['Onderaanneming','oa','--c-oa'],['Materieel','mt','--c-mt'],['Overig','ov','--c-ov']];
    const paid=S.invoices.filter(i=>i.status==='betaald').reduce((s,i)=>s+i.bedrag*1.21,0); const totInv=paid+F.debTot-F.debVerv+F.debVerv;
    const projRows=F.proj.filter(p=>p.phase<8).map(p=>({p,f:projectFin(p)}));
    
    body=`<div class="grid g2">
      <div class="card"><div class="card-h"><h3>Omzet<em>ontwikkeling</em> ${YEAR}</h3><span class="muted" style="font-size:12px">gefactureerd excl. btw</span></div><div class="card-b">${barChart({labels:F.months2026.map(cmLabel),series:[{name:'Omzet',values:F.omzetReeks,c:'--ch1'}],aria:'Omzet per maand 2026'})}</div></div>
      <div class="card"><div class="card-h"><h3>Cashflow<em>prognose</em></h3><span class="muted" style="font-size:12px">komende 6 maanden · excl. btw</span></div><div class="card-b">${barChart({labels:F.cm.map(cmLabel),series:[{name:'Ontvangsten',values:F.inM.map(Math.round),c:'--ch1'},{name:'Uitgaven',values:F.outM.map(Math.round),c:'--ch2'}],line:{name:'Banksaldo',values:F.saldo,c:'--ch3'},aria:'Cashflowprognose'})}</div></div>
    </div>
    <div class="grid g2">
      <div class="card"><div class="card-h"><h3>Begroot <em>versus</em> werkelijk</h3></div><div class="card-b">
        <div class="chart-legend"><span><i style="background:var(--ch2)"></i>Besteed van begroting (werkelijk + verplichtingen)</span><span><i class="ln" style="background:var(--ch1);width:3px;height:12px"></i>Voortgang</span></div>
        ${projRows.map(({p,f})=>{ const sp=f.begroot?(f.werkelijk+f.verpl)/f.begroot*100:0; const over=sp>(p.progress||0)+10; return `<div class="hrow" data-tip="${esc(`<b>${esc(p.naam)}</b><div class="tr"><span>Begroot</span><span>${eur0(f.begroot)}</span></div><div class="tr"><span>Werkelijk</span><span>${eur0(f.werkelijk)}</span></div><div class="tr"><span>Verplichtingen</span><span>${eur0(f.verpl)}</span></div><div class="tr"><span>Voortgang</span><span>${p.progress}%</span></div>`)}"><a class="nm" href="/project-${p.id.toLowerCase()}">${esc(p.naam)}</a><div class="pbar"><i style="width:${Math.min(100,sp)}%"></i><b style="left:${Math.min(100,p.progress||0)}%"></b></div><span class="v"><b>${pct(sp,0)}</b> <span class="muted" style="font-size:11px">· ${p.progress||0}% klaar</span>${over?`<div><span class="pill warn" style="height:18px;font-size:10.5px">Kosten lopen voor</span></div>`:''}</span></div>`; }).join('')}
      </div></div>
      <div class="card"><div class="card-h"><h3>Verwachte marge <em>per project</em></h3></div><div class="card-b">
        ${projRows.slice().sort((a,b)=>a.f.marge-b.f.marge).map(({p,f})=>{ const st=mStat(f.marge); return `<div class="hrow"><a class="nm" href="/project-${p.id.toLowerCase()}">${esc(p.naam)}</a><div class="hbars"><i style="width:${Math.max(1,Math.min(100,f.marge/30*100))}%;background:var(--${st[0]==='ok'?'ok':st[0]==='warn'?'warn-c':'bad'})"></i></div><span class="v"><b>${pct(f.marge)}</b> <span class="pill ${st[0]}" style="height:18px;font-size:10.5px">${st[1]}</span></span></div>`; }).join('')}
        <p class="muted" style="margin:10px 0 0;font-size:12px">Gezond ≥ 12% · krap 6–12% · risico &lt; 6%. Gegunde partnerprijzen en geboekte uren zijn meegerekend.</p></div></div>
    </div>
    <div class="grid g3">
      <div class="card"><div class="card-h"><h3>Werkvoorraad</h3></div><div class="card-b">${barChart({labels:F.cm.map(cmLabel),series:[{name:'Resterende contractwaarde',values:F.wv.map(Math.round),c:'--ch1'}],w:380,aria:'Werkvoorraad per maand'})}</div></div>
      <div class="card"><div class="card-h"><h3>Facturen</h3></div><div class="card-b"><div class="stack-bar"><i style="width:${paid/totInv*100}%;background:var(--ch3)"></i><i style="width:${(F.debTot-F.debVerv)/totInv*100}%;background:var(--ch1)"></i><i style="width:${F.debVerv/totInv*100}%;background:var(--ch2)"></i></div>
        <div class="leg"><span class="sw" style="background:var(--ch3)"></span><span>Betaald</span><b class="num">${eur0(paid)}</b><span class="p num">${pct(paid/totInv*100,0)}</span><span class="sw" style="background:var(--ch1)"></span><span>Open, nog niet vervallen</span><b class="num">${eur0(F.debTot-F.debVerv)}</b><span class="p num">${pct((F.debTot-F.debVerv)/totInv*100,0)}</span><span class="sw" style="background:var(--ch2)"></span><span>Vervallen</span><b class="num">${eur0(F.debVerv)}</b><span class="p num">${pct(F.debVerv/totInv*100,0)}</span></div><p class="muted" style="margin:10px 0 0;font-size:12px">incl. btw</p></div></div>
      <div class="card"><div class="card-h"><h3>Kostenverdeling</h3><span class="muted" style="font-size:12px">alle begrotingen</span></div><div class="card-b"><div class="stack-bar">${catL.map(([_,k,c])=>`<i style="width:${cats[k]/ct*100}%;background:var(${c})"></i>`).join('')}</div><div class="leg">${catL.map(([l,k,c])=>`<span class="sw" style="background:var(${c})"></span><span>${l}</span><b class="num">${eur0(cats[k])}</b><span class="p num">${pct(cats[k]/ct*100)}</span>`).join('')}</div></div></div>
    </div>
    <div class="card"><div class="card-h"><h3>Aannames prognose</h3><span class="muted" style="font-size:12px">pas aan om de cashflow door te rekenen</span></div><div class="card-b fg" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))">
      ${[['bank','Banksaldo nu'],['bedrijfskosten','Bedrijfskosten per maand'],['loonIntern','Loonkosten eigen vakman / mnd'],['loonKantoor','Loonkosten kantoor / mnd']].map(([k,l])=>`<div class="f"><label for="fa-${k}">${l} (€)</label><input class="in num" type="number" step="100" id="fa-${k}" data-finas="${k}" value="${S.fin[k]}"></div>`).join('')}
    </div></div>`;
  }
  if(tab==='projecten'){
    const rows=S.projects.filter(p=>p.offerte&&p.offerte.status==='geaccepteerd').map(p=>{ const f=projectFin(p); const orig=p.offerte.basis; const mw=f.val-orig; const bu=p.begroting?calcB(p.begroting).uren:S.werkbonnen.filter(w=>w.pid===p.id).reduce((s,w)=>s+w.begrUren,0); return {p,f,orig,mw,bu}; });
    const T=k=>rows.reduce((s,r)=>s+(typeof k==='function'?k(r):r.f[k]),0);
    body=`<div class="card tw"><table class="t"><thead><tr><th>Projectdossier</th><th class="r">Aanneemsom</th><th class="r">Meerwerk</th><th class="r">Contract</th><th class="r">Begroot</th><th class="r">Werkelijk</th><th class="r">Verplicht</th><th class="r">Uren</th><th class="r">Verwacht eind</th><th class="r">Marge</th></tr></thead><tbody>
      ${rows.map(({p,f,orig,mw,bu})=>`<tr class="click" data-act="pdtab" data-t="financien" data-pid="${p.id}"><td><b>${esc(p.naam)}</b><div class="sub">${p.id} · ${PHASES[p.phase]} · ${p.progress}%</div></td><td class="r">${eur0(orig)}</td><td class="r">${mw?eur0(mw):'—'}</td><td class="r"><b>${eur0(f.val)}</b></td><td class="r">${eur0(f.begroot)}</td><td class="r">${eur0(f.werkelijk)}</td><td class="r">${f.verpl?eur0(f.verpl):'—'}</td><td class="r">${NUM.format(f.uren)}<span class="muted"> / ${NUM.format(Math.round(bu))}</span></td><td class="r">${eur0(f.verwacht)}</td><td class="r ${f.marge<6?'dn':f.marge>=12?'up':''}">${pct(f.marge)}</td></tr>`).join('')}
    </tbody><tfoot><tr><td><b>Totaal</b></td><td class="r"><b>${eur0(T(r=>r.orig))}</b></td><td class="r">${eur0(T(r=>r.mw))}</td><td class="r"><b>${eur0(T('val'))}</b></td><td class="r">${eur0(T('begroot'))}</td><td class="r">${eur0(T('werkelijk'))}</td><td class="r">${eur0(T('verpl'))}</td><td class="r">${NUM.format(T('uren'))}</td><td class="r">${eur0(T('verwacht'))}</td><td class="r"><b>${pct(T('val')?(T('val')-T('verwacht'))/T('val')*100:0)}</b></td></tr></tfoot></table></div>`;
  }
  if(tab==='inkoop'){
    body=`<div class="card tw"><table class="t ink-t"><thead><tr><th>Factuur</th><th>Leverancier</th><th>Project</th><th>Inkooporder</th><th>Vervaldatum</th><th class="r">Bedrag excl.</th><th>Status</th><th></th></tr></thead><tbody>
      ${S.inkoop.slice().sort((a,b)=>a.datum<b.datum?1:-1).map(x=>{ const p=proj(x.pid)||{naam:'—'}; const st={ontvangen:['warn','Te beoordelen'],goedgekeurd:['blue','Goedgekeurd'],betaald:['ok','Betaald'],afgewezen:['bad','Afgewezen']}[x.status]; return `<tr><td><b>${x.nr}</b><div class="sub">${fmtD(x.datum)}</div></td><td>${esc(x.lev)}${x.opm?`<div class="sub">${esc(x.opm)}</div>`:''}</td><td>${esc(p.naam)}</td><td>${x.po}</td><td class="${x.status!=='betaald'&&x.verval<TODAY?'dn':''}">${fmtD(x.verval)}</td><td class="r">${eur(x.bedrag)}</td><td><span class="pill ${st[0]}">${st[1]}</span></td><td class="r t-acts"><div class="t-btns">${x.status==='ontvangen'?`<button class="btn xs" data-act="ink-no" data-nr="${x.nr}">Afwijzen</button><button class="btn xs pri" data-act="ink-ok" data-nr="${x.nr}">Goedkeuren</button>`:x.status==='goedgekeurd'?`<button class="btn xs" data-act="ink-pay" data-nr="${x.nr}">Markeer betaald</button>`:''}</div></td></tr>`; }).join('')}
    </tbody></table></div><p class="muted" style="margin:0;font-size:12px">Goedkeuren boekt het bedrag als werkelijke kosten op het projectdossier. Betalen gebeurt in de bank; hier registreer je alleen.</p>`;
  }
  if(tab==='declaraties'){
    body=`<div class="row between wrap"><span class="muted">Declaraties van medewerkers, per project.</span><button class="btn pri" data-act="dec-new">${ic('plus')}Declaratie indienen</button></div><div class="card tw"><table class="t"><thead><tr><th>Medewerker</th><th>Kostensoort</th><th>Project</th><th>Datum</th><th>Bon</th><th class="r">Bedrag</th><th>Status</th><th></th></tr></thead><tbody>
      ${S.declaraties.slice().sort((a,b)=>a.datum<b.datum?1:-1).map(x=>`<tr><td><div class="row" style="gap:8px">${avatar(empName(x.emp),'sm')}${esc(empName(x.emp))}</div></td><td>${esc(x.soort)}${x.opm?`<div class="sub">${esc(x.opm)}</div>`:''}</td><td>${esc((proj(x.pid)||{naam:'—'}).naam)}</td><td>${fmtD(x.datum)}</td><td>${x.bon?`<span class="docrow">${ic('file')}${esc(x.bon)}</span>`:'<span class="pill warn">Geen bon</span>'}</td><td class="r">${eur(x.bedrag)}</td><td>${{ingediend:'<span class="pill warn">Ingediend</span>',goedgekeurd:'<span class="pill ok">Goedgekeurd</span>',afgewezen:'<span class="pill bad">Afgewezen</span>'}[x.status]}</td><td class="r">${x.status==='ingediend'?`<button class="btn xs pri" data-act="dec-ok" data-id="${x.id}">Goedkeuren</button> <button class="btn xs" data-act="dec-no" data-id="${x.id}">Afwijzen</button>`:''}</td></tr>`).join('')}
    </tbody></table></div>`;
  }
  return `<div class="page"><div class="ph"><div><h1>Finan<em>cieel</em></h1><p>Alle bedragen komen uit dezelfde dossiers, facturen, werkbonnen en gunningen. Bedragen excl. btw tenzij anders vermeld.</p></div><a class="btn" href="/facturatie">${ic('receipt')}Verkoopfacturen</a></div>
  <div class="grid kpis"><div class="card kpi dark"><span class="lbl">Omzet dit jaar</span><span class="v num">${heur0(F.omzetJ)}</span><span class="s">deze maand ${eur0(F.omzetM)} · dit kwartaal ${eur0(F.omzetQ)}</span></div>
    <div class="card kpi"><span class="lbl">Bevestigde werkvoorraad</span><span class="v num">${eur0(F.voorraad)}</span><span class="s">nog te factureren ${eur0(F.nogTeFact)}</span></div>
    <div class="card kpi"><span class="lbl">Verwachte eindmarge</span><span class="v num ${F.em<F.bm-1?'dn':''}">${pct(F.em)}</span><span class="s">begroot ${pct(F.bm)}</span></div>
    <div class="card kpi"><span class="lbl">Banksaldo over 6 mnd</span><span class="v num ${F.saldo[5]<0?'dn':''}">${eur0(F.saldo[5])}</span><span class="s">laagste punt ${eur0(Math.min(...F.saldo))}</span></div></div>
  <div class="grid g4">
    <div class="card kpi"><span class="lbl">Debiteuren</span><span class="v num" style="font-size:20px">${eur0(F.debTot)}</span><span class="s"><span class="${F.debVerv?'dn':''}">${eur0(F.debVerv)} vervallen</span> · incl. btw</span></div>
    <div class="card kpi"><span class="lbl">Crediteuren</span><span class="v num" style="font-size:20px">${eur0(F.credTot)}</span><span class="s">${F.cred.length} inkoopfacturen open</span></div>
    <div class="card kpi"><span class="lbl">Inkoopverplichtingen</span><span class="v num" style="font-size:20px">${eur0(F.verpl)}</span><span class="s">gegunde partnerprijzen</span></div>
    <div class="card kpi"><span class="lbl">Pipeline</span><span class="v num" style="font-size:20px">${eur0(F.pipe)}</span><span class="s">gewogen · open offertes ${eur0(F.openOff)}</span></div></div>
  <div class="row wrap" style="gap:8px;font-size:12.5px"><span class="pill mut">Personeelskosten ${eur0(F.pers)} / mnd</span><span class="pill mut">Bedrijfskosten ${eur0(S.fin.bedrijfskosten)} / mnd</span></div>
  <div class="tabs">${[['overzicht','Overzicht'],['projecten','Projectfinanciën'],['inkoop','Inkoopfacturen'],['declaraties','Declaraties']].map(([k,l])=>`<button class="tab ${tab===k?'on':''}" data-act="fin-tab" data-t="${k}">${l}${k==='inkoop'?`<span class="c">${S.inkoop.filter(x=>x.status==='ontvangen').length}</span>`:k==='declaraties'?`<span class="c">${S.declaraties.filter(x=>x.status==='ingediend').length}</span>`:''}</button>`).join('')}</div>
  ${body}</div>`;
}

/* ---------- Klant Service Hub ---------- */
const PHASE_UITLEG=['Wij hebben uw aanvraag ontvangen en nemen contact met u op.','We bespreken uw wensen en bekijken de situatie ter plaatse.','We rekenen alle werkzaamheden en materialen zorgvuldig door.','U ontvangt een duidelijke offerte met alle keuzes op een rij.','U heeft getekend. Wij zetten uw project klaar.','Materialen worden besteld en het team wordt ingepland.','Ons team is aan het werk bij u.','Samen lopen we alles na en lossen we eventuele restpunten op.','Garantie en service, ook na de oplevering.'];
const KLANT_DOC=['Offerte','Overeenkomst','Tekening','Keuze','Vergunning','Planning','Garantie','Klant'];
function vServiceHub(){
  const opts=S.projects.filter(p=>p.phase>=4); const p=proj(hubPid())||opts[0]; if(!p) return `<div class="page"><div class="empty">Nog geen projecten in opdracht.</div></div>`;
  const c=client(p.clientId); const leider=emp(p.leider)||{naam:'—',tel:''}; const inv=S.invoices.filter(i=>i.pid===p.id&&i.status!=='concept');
  const val=projectValue(p)*1.21, betaald=inv.filter(i=>i.status==='betaald').reduce((s,i)=>s+i.bedrag*1.21,0), open=inv.filter(i=>i.status==='verzonden').reduce((s,i)=>s+i.bedrag*1.21,0);
  const nextT=p.termijnen.findIndex((t,i)=>!S.invoices.some(x=>x.pid===p.id&&x.termijn===i&&x.status!=='concept'));
  const nextMs=nextT>=0?p.termijnen[nextT].oms:PHASES[Math.min(8,p.phase+1)];
  const opties=p.begroting?(p.begroting.options||[]).map((o,i)=>({o,i})).filter(x=>x.o.s==='optie'):[];
  const afspr=S.agenda.filter(a=>a.pid===p.id&&a.d>=TODAY); const verz=S.klantVerzoeken.filter(v=>v.pid===p.id&&v.status==='open');
  const docs=(p.docs||[]).filter(d=>KLANT_DOC.includes(d.cat));
  const berichten=S.klantBerichten.filter(m=>m.pid===p.id); const notes=S.klantNotities.filter(n=>n.pid===p.id);
  const fotos=S.werkbonnen.filter(w=>w.pid===p.id).flatMap(w=>w.fotos.map(f=>({...f,d:w.datum,t:w.titel})));
  const updates=p.activity.filter(a=>/gestart|opgeleverd|klaar|gereed|ingepland|ondertekend|goedgekeurd|akkoord/i.test(a.t)&&!/€|marge|kosten|factuur|gegund|budget/i.test(a.t)).slice(0,6);
  const circ=2*Math.PI*36;
  const mode=UI.hubMode||'deel';
  return `<div class="page"><div class="hub">
  <div class="alert info" ${IS_EXTERNAL?'data-os-hide':''}>${ic('home')}<div class="grow"><b>Klantweergave.</b> Zo ziet ${esc(c.contact||c.naam)} het project. Interne kosten, marges, beoordelingen en partnerprijzen worden nooit getoond.</div><select class="in" id="hubsel" style="width:auto;min-width:220px" aria-label="Bekijk als klant van project">${opts.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(client(x.clientId).naam)} · ${esc(x.naam)}</option>`).join('')}</select></div>
  <div class="band"><img class="bimg" src="${HERO}" alt="" aria-hidden="true">
    <div class="hub-prog"><div class="ring"><svg viewBox="0 0 86 86"><circle cx="43" cy="43" r="36" fill="none" stroke="#ffffff22" stroke-width="7"/><circle cx="43" cy="43" r="36" fill="none" stroke="var(--orange)" stroke-width="7" stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-(p.progress||0)/100)}"/></svg><b>${p.progress||0}%</b></div>
    <div style="display:grid;gap:6px"><span class="eyebrow">Welkom bij uw project, ${esc((c.contact||c.naam).split(' ')[0])}</span><h1>${esc(p.naam)}</h1><span class="sub">${esc([p.adres,p.plaats].filter(Boolean).join(', '))}</span><div class="rule"></div></div></div>
    <div class="bmeta"><div><span>Huidige fase</span><b>${PHASES[p.phase]}</b></div><div><span>Volgende mijlpaal</span><b>${esc(nextMs)}</b></div><div><span>Verwachte oplevering</span><b>${fmtDY(p.eind)}</b></div><div><span>Uw projectleider</span><b>${esc(leider.naam)}</b></div><div><span>Telefoon</span><b>${esc(leider.tel||'—')}</b></div></div></div>
  <div class="grid g-main">
    <div class="stack" style="gap:16px">
      <div class="card"><div class="card-h"><h3>Mijn <em>acties</em></h3><span class="pill ${opties.length+afspr.filter(a=>!a.bevestigd).length+verz.length?'or':'ok'}">${opties.length+afspr.filter(a=>!a.bevestigd).length+verz.length} open</span></div><div class="card-b" style="padding-block:4px">
        ${opties.map(({o,i})=>`<div class="li"><span class="ic or">${ic('tag')}</span><div class="tx"><b>Keuze: ${esc(o.d)}</b><small>${+o.p?`Meerprijs ${eur(optPrice(o,p.begroting)*1.21)} incl. btw`:'Prijs volgt'}${o.t?' · '+esc(o.t):''}</small></div>${+o.p?`<button class="btn sm pri" data-act="hub-opt" data-pid="${p.id}" data-i="${i}">Akkoord</button>`:''}</div>`).join('')}
        ${afspr.map(a=>`<div class="li"><span class="ic blue">${ic('cal')}</span><div class="tx"><b>${esc(a.titel)}</b><small>${cap(dayName(a.d))} ${fmtD(a.d)} om ${a.tijd}</small></div>${a.bevestigd?'<span class="pill ok">Bevestigd</span>':`<button class="btn sm" data-act="hub-appt" data-id="${a.id}">Bevestigen</button>`}</div>`).join('')}
        ${verz.map(v=>`<div class="li"><span class="ic vio">${ic('upload')}</span><div class="tx"><b>${esc(v.titel)}</b><small>${esc(v.oms)}</small></div><label class="btn sm" style="cursor:pointer">Aanleveren<input type="file" hidden data-hubup="${v.id}"></label></div>`).join('')}
        ${!(opties.length+afspr.length+verz.length)?`<div class="empty">${ic('check')}Er staat niets voor u klaar.</div>`:''}
      </div></div>
      <div class="card"><div class="card-h"><h3>Recente <em>updates</em></h3></div><div class="card-b"><div class="updates">
        ${fotos.slice(-3).reverse().map(f=>`<div class="upd"><div class="pic"><img src="${f.src}" alt="${esc(f.t)}"></div><div class="t"><b>${esc(f.t)}</b><small>${fmtD(f.d)}</small></div></div>`).join('')}
        ${updates.map(u=>`<div class="upd"><div class="pic">${ic('camera')}</div><div class="t"><b>${esc(u.t.replace(/ door [A-Z][a-z]+.*$/,'').replace(/^Werkbon WB-\d+-\d+ goedgekeurd: [^,]+, /,'Werk afgerond: '))}</b><small>${fmtD(u.d)}</small></div></div>`).join('')||(fotos.length?'':'<span class="muted">Zodra het team foto’s maakt, ziet u ze hier.</span>')}
      </div></div></div>
      <div class="card"><div class="card-h"><h3>Berichten</h3><div class="seg"><button class="${mode==='deel'?'on':''}" data-act="hub-mode" data-m="deel">Met Renovion</button><button class="${mode==='prive'?'on':''}" data-act="hub-mode" data-m="prive">${ic('lock').replace('<svg','<svg style="width:12px;height:12px;vertical-align:-1px"')} Privé</button></div></div><div class="card-b stack">
        ${mode==='deel'?`<div class="msgs" id="hubmsgs">${berichten.map(m=>`<div class="msg ${m.van==='klant'?'mine':'n'}">${esc(m.txt)}<small>${esc(m.van==='klant'?'U':m.naam+' · Renovion')} · ${fmtD(m.d)} ${m.tijd}</small></div>`).join('')||'<span class="muted">Nog geen berichten.</span>'}</div>`:`<div class="msgs">${notes.map(n=>`<div class="msg priv">${esc(n.txt)}<small>Alleen voor u · ${fmtD(n.d)}</small></div>`).join('')||'<span class="muted">Privénotities ziet alleen u. Handig voor vragen die u later wilt stellen.</span>'}</div>`}
        <form class="row" data-form="hubmsg" data-pid="${p.id}" style="gap:8px"><input class="in" name="txt" id="hub-txt" placeholder="${mode==='deel'?'Stel een vraag aan Renovion':'Schrijf een privénotitie'}" autocomplete="off" aria-label="Bericht"><button class="btn pri" type="submit">${mode==='deel'?'Versturen':'Bewaren'}</button></form>
        <small class="muted">${mode==='deel'?`Uw bericht gaat naar ${esc(leider.naam)}. Wij reageren meestal binnen één werkdag.`:'Privénotities worden niet met Renovion gedeeld.'}</small></div></div>
    </div>
    <div class="stack" style="gap:16px">
      <div class="card"><div class="card-h"><h3>Mijn <em>betalingen</em></h3></div><div class="card-b">
        <div class="sumrow"><span class="muted">Totaal contract incl. btw</span><b class="num">${eur(val)}</b></div><div class="sumrow"><span class="muted">Betaald</span><span class="num up">${eur(betaald)}</span></div><div class="sumrow"><span class="muted">Openstaand</span><span class="num ${open?'dn':''}">${eur(open)}</span></div>
        <div class="bar ok" style="margin:10px 0"><i style="width:${val?betaald/val*100:0}%"></i></div>
        ${nextT>=0?`<div class="calcbox"><div class="row between"><span>Volgende termijn</span><b>${nextT+1}. ${esc(p.termijnen[nextT].oms)}</b></div><div class="row between"><span>Bedrag incl. btw</span><b class="num">${eur(p.offerte.basis*p.termijnen[nextT].pct/100*1.21)}</b></div></div>`:''}
        ${inv.length?`<div style="margin-top:10px"><span class="lbl">Betaalhistorie</span>${inv.map(i=>`<div class="sumrow"><span>${i.nr} · ${esc(i.oms)}</span><span>${i.status==='betaald'?`<span class="pill ok">Betaald ${fmtD(i.betaald)}</span>`:i.verval<TODAY?'<span class="pill bad">Vervallen</span>':`<span class="pill blue">Vóór ${fmtD(i.verval)}</span>`}</span></div>`).join('')}</div>`:''}
      </div></div>
      <div class="card"><div class="card-h"><h3>Mijn <em>documenten</em></h3></div><div class="card-b">${docs.map(d=>`<div class="sumrow"><span class="docrow">${ic('file')}${esc(d.naam)}</span><span class="muted">${fmtD(d.datum)}</span></div>`).join('')}${inv.map(i=>`<div class="sumrow"><span class="docrow">${ic('receipt')}Factuur ${i.nr}.pdf</span><span class="muted">${fmtD(i.datum)}</span></div>`).join('')}${!docs.length&&!inv.length?'<span class="muted">Nog geen documenten.</span>':''}</div></div>
      <div class="card"><div class="card-h"><h3>Project<em>tijdlijn</em></h3></div><div class="card-b"><div class="phase-tl">${PHASES.map((ph,i)=>`<div class="pst ${i<p.phase?'done':i===p.phase?'cur':''}"><span class="o">${i<p.phase?ic('check'):i+1}</span><div><b>${ph}</b>${i>=p.phase-1&&i<=p.phase+1?`<small>${PHASE_UITLEG[i]}</small>`:''}</div></div>`).join('')}</div></div></div>
    </div>
  </div></div></div>`;
}

/* ---------- Automations engine ---------- */
const AUTO_TYPES={
  lead:{lbl:'Nieuwe aanvraag',eval(){ return S.projects.filter(p=>p.phase===0&&!S.tasks.some(t=>t.pid===p.id&&/contact/i.test(t.titel))).map(p=>({k:'lead-'+p.id,pid:p.id,t:`Contacttaak voor nieuwe aanvraag ${p.naam}`,apply(){ S.tasks.push({id:uid('t'),titel:'Eerste contact opnemen',pid:p.id,eig:p.leider||osSales(),dl:addDays(TODAY,1),status:'open',prio:'hoog',oms:'Aangemaakt door automation.',checklist:[]}); return 'taak aangemaakt'; }})); }},
  tel:{lbl:'Klant zonder telefoonnummer',eval(){ return S.clients.filter(c=>!c.tel&&S.projects.some(p=>p.clientId===c.id&&p.phase<8)).map(c=>({k:'tel-'+c.id,pid:(S.projects.find(p=>p.clientId===c.id)||{}).id,t:`Aanvulverzoek telefoonnummer naar ${c.naam}`,apply(){ S.outbox.push({d:TODAY,aan:c.mail||c.naam,onderwerp:'Wilt u uw telefoonnummer aan ons doorgeven?'}); return 'mail in de outbox'; }})); }},
  intake:{lbl:'Intake in agenda',eval(){ return S.agenda.filter(a=>/intake/i.test(a.titel)&&a.d>=TODAY&&a.d<=addDays(TODAY,4)&&a.pid).map(a=>{ const c=client(proj(a.pid).clientId); return {k:'intake-'+a.id,pid:a.pid,t:`Herinnering intake ${fmtD(a.d)} ${a.tijd} aan ${c.naam}`,apply(){ S.outbox.push({d:TODAY,aan:c.mail,onderwerp:`Herinnering: intake op ${fmtD(a.d)} om ${a.tijd}`}); return 'herinnering in de outbox'; }}; }); }},
  offerte3:{lbl:'Offerte zonder reactie',eval(){ return S.projects.filter(p=>p.offerte&&p.offerte.status==='verzonden'&&diffDays(p.offerte.sent,TODAY)>=3&&!S.tasks.some(t=>t.status!=='afgerond'&&t.titel.includes(p.offerte.nr))).map(p=>({k:`off-${p.offerte.nr}-${p.offerte.versie}`,pid:p.id,t:`Opvolgtaak offerte ${p.offerte.nr} (${diffDays(p.offerte.sent,TODAY)} dagen stil)`,apply(){ S.tasks.push({id:uid('t'),titel:`Offerte ${p.offerte.nr} opvolgen`,pid:p.id,eig:osOwner(p),dl:addDays(TODAY,1),status:'todo',prio:'hoog',oms:'Aangemaakt door automation.',checklist:[]}); return 'opvolgtaak aangemaakt'; }})); }},
  getekend:{lbl:'Offerte ondertekend',eval(){ return S.projects.filter(p=>p.offerte&&p.offerte.status==='geaccepteerd'&&p.offerte.accepted&&diffDays(p.offerte.accepted,TODAY)<=14&&!S.tasks.some(t=>t.pid===p.id&&/werkvoorbereiding/i.test(t.titel))).map(p=>({k:'sign-'+p.offerte.nr,pid:p.id,t:`${p.naam} is ondertekend: werkvoorbereiding nog niet gestart`,apply(){ S.tasks.push({id:uid('t'),titel:'Werkvoorbereiding starten',pid:p.id,eig:osWvb(),dl:addDays(TODAY,2),status:'todo',prio:'hoog',oms:'Aangemaakt door automation.',checklist:[{t:'Materiaallijst uit begroting',d:false},{t:'Team samenstellen',d:false},{t:'Teambriefing',d:false}]}); return 'taak werkvoorbereiding'; }})); }},
  aanbetaling:{lbl:'Aanbetaling ontbreekt',eval(){ return S.invoices.filter(i=>i.termijn===0&&i.status==='verzonden'&&i.verval<TODAY).map(i=>({k:'aanb-'+i.nr,pid:i.pid,t:`Aanbetaling ${proj(i.pid).naam} (${i.nr}) niet ontvangen`,apply(){ S.notifs.unshift({t:`Aanbetaling ${proj(i.pid).naam} ontbreekt`,d:TODAY}); return 'melding directie'; }})); }},
  deadline:{lbl:'Deadline overschreden',eval(){ return S.tasks.filter(t=>t.status!=='afgerond'&&t.dl&&t.dl<TODAY).map(t=>({k:'dl-'+t.id,pid:t.pid,t:`Deadline verlopen: ${t.titel}`,apply(){ t.prio='hoog'; S.notifs.unshift({t:`Escalatie: ${t.titel} is over de deadline`,d:TODAY}); return 'prioriteit hoog + melding'; }})); }},
  materiaal:{lbl:'Inkooptaak loopt uit',eval(){ return S.tasks.filter(t=>t.status!=='afgerond'&&/bestel|inkoop/i.test(t.titel)&&t.dl&&t.dl<=addDays(TODAY,4)&&proj(t.pid)&&proj(t.pid).phase>=4).map(t=>{ const p=proj(t.pid); return {k:'mat-'+t.id,pid:p.id,t:`${t.titel} (${p.naam}) is nog niet afgerond, deadline ${fmtD(t.dl)}`,apply(){ const ch=S.chat.channels.find(c=>c.pid===p.id); const nm=firstName(p.leider); S.chat.msgs.push({id:uid('m'),ch:ch?ch.id:'inkoop',van:'nova',txt:`@${nm} ${t.titel} staat nog open (deadline ${fmtD(t.dl)}). Wil je checken of alles besteld is?`,d:TODAY,tijd:nowT(),pinned:false,replies:[],att:null}); return 'bericht in projectkanaal'; }}; }); }},
  certificaat:{lbl:'Certificaat verloopt',eval(){ return allCerts().filter(x=>x.type!=='kantoor'&&x.type!=='intern'&&certState(x.c)!=='ok').map(x=>({k:`cert-${x.wie}-${x.c.t}-${x.c.g}`,pid:'',t:`${x.c.t} van ${x.wie} ${certState(x.c)==='verlopen'?'is verlopen':'verloopt '+fmtD(x.c.g)}`,apply(){ const s=x.sub?sub(x.sub):S.subs.find(s=>s.empId===x.emp); S.outbox.push({d:TODAY,aan:s?s.mail:(emp(x.emp)||{}).mail,onderwerp:`Verzoek: ${x.c.t} vernieuwen`}); return 'mail in de outbox'; }})); }},
  fase:{lbl:'Projectmijlpaal bereikt',eval(){ const out=[]; for(const p of S.projects.filter(p=>p.phase>=5)) for(const m of [25,50,75,100]) if((p.progress||0)>=m) out.push({k:`fase-${p.id}-${m}`,pid:p.id,t:`${p.naam} heeft ${m}% bereikt: klantupdate voorbereiden`,apply(){ S.klantBerichten.push({id:uid('kb'),pid:p.id,van:'renovion',naam:empName(p.leider),txt:m===100?'Alle werkzaamheden zijn afgerond. We plannen graag de oplevering met u in.':`Goed nieuws: uw project is voor ${m}% klaar. ${PHASE_UITLEG[p.phase]}`,d:TODAY,tijd:nowT()}); addActivity(p,`Klantupdate ${m}% verstuurd via Service Hub`,'blue'); return 'bericht in Service Hub'; }}); return out; }},
  week:{lbl:'Vrijdag (weekafsluiting)',eval(){ if(D(TODAY).getDay()!==5) return []; const wk=monday(TODAY); return [{k:'week-'+wk,pid:'',t:`Weekrapport week van ${fmtD(wk)}`,apply(){ const F=finCalc(); const [a,b]=[wk,addDays(wk,4)]; S.rapporten.unshift({id:uid('r'),titel:`Weekrapport ${fmtD(a)} – ${fmtD(b)}`,d:TODAY,regels:[`Gefactureerd deze maand: ${eur0(F.omzetM)}`,`Uren op werkbonnen deze week: ${NUM.format(S.werkbonnen.filter(w=>w.datum>=a&&w.datum<=b).reduce((s,w)=>s+(+w.uren||0),0))}`,`Werkbonnen ter controle: ${S.werkbonnen.filter(w=>w.status==='controle').length}`,`Projecten achter op planning: ${behind().map(p=>p.naam).join(', ')||'geen'}`,`Planningsconflicten: ${conflicts().length}`,`Vervallen debiteuren: ${eur0(F.debVerv)}`]}); S.notifs.unshift({t:'Weekrapport staat klaar',d:TODAY}); return 'rapport aangemaakt'; }}]; }},
};
// Tijdstempel op de vaste demodag: echte kloktijd, maar nooit vóór het laatste bericht van vandaag
function nowT(){ const d=new Date(); let t=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
  const last=[...(S.chat?S.chat.msgs:[]),...(S.klantBerichten||[])].filter(m=>m.d===TODAY).map(m=>m.tijd).sort().pop();
  if(last&&t<=last){ let [h,mi]=last.split(':').map(Number); mi++; if(mi>=60){ mi=0; h=Math.min(23,h+1); } t=String(h).padStart(2,'0')+':'+String(mi).padStart(2,'0'); } return t; }
let _autoBusy=false, _autoMsgs=[];
function runAutomations(quiet){
  if(_autoBusy||!S.automations) return 0; _autoBusy=true; let n=0;
  try{
    for(const r of S.automations){ if(!r.aan) continue; const ty=AUTO_TYPES[r.type]; if(!ty) continue;
      for(const c of ty.eval()){ const key=r.id+':'+c.k; if(S.autoFired[key]) continue; S.autoFired[key]=TODAY;
        if(!S.autoInit&&r.type==='fase') continue; // bestaande mijlpalen niet opnieuw melden
        n++; r.teller++; r.laatste=TODAY;
        if(r.modus==='automatisch'){ const res=c.apply(); S.autoLog.unshift({d:TODAY,tijd:nowT(),rid:r.id,t:c.t,res:'Uitgevoerd: '+res}); _autoMsgs.push(`${r.naam}: ${c.t}`); }
        else if(r.modus==='bevestigen'){ S.autoQueue.push({key,rid:r.id,k:c.k,t:c.t,pid:c.pid||'',d:TODAY}); S.autoLog.unshift({d:TODAY,tijd:nowT(),rid:r.id,t:c.t,res:'Wacht op bevestiging'}); }
        else { S.autoLog.unshift({d:TODAY,tijd:nowT(),rid:r.id,t:c.t,res:'Gesignaleerd'}); }
      } }
    S.autoInit=true; if(S.autoLog.length>80) S.autoLog.length=80;
  } finally { _autoBusy=false; }
  if(_autoMsgs.length){ const m=_autoMsgs.splice(0); if(!quiet) setTimeout(()=>m.slice(0,2).forEach(x=>toast('Automation · '+x)),60); }
  return n;
}
const _saveR3=save; save=function(){ if(OSB.leader()) runAutomations(); _saveR3(); }; /* automations draaien in één scherm tegelijk (de server wijst het aan), anders zouden ze dubbel vuren */
function vAutomations(){
  const q=S.autoQueue; const tab=UI.autoTab||'regels';
  const MOD={signaleren:['mut','Alleen signaleren'],bevestigen:['blue','Eerst bevestigen'],automatisch:['ok','Automatisch']};
  return `<div class="page"><div class="ph"><div><h1>Auto<em>mations</em></h1><p>Regels die op wijzigingen in het systeem reageren. Elke gebeurtenis wordt één keer verwerkt, zodat er geen dubbele acties ontstaan.</p></div><button class="btn pri" data-act="auto-new">${ic('plus')}Nieuwe regel</button></div>
  <div class="grid g4"><div class="card kpi dark"><span class="lbl">Actieve regels</span><span class="v num">${S.automations.filter(r=>r.aan).length}<b style="font-size:18px;color:var(--on-navy-2)"> / ${S.automations.length}</b></span><span class="s">${S.automations.filter(r=>r.modus==='automatisch'&&r.aan).length} voeren zelf uit</span></div>
    <div class="card kpi"><span class="lbl">Wacht op bevestiging</span><span class="v num ${q.length?'dn':''}">${q.length}</span><span class="s">voorgestelde acties</span></div>
    <div class="card kpi"><span class="lbl">Uitvoeringen totaal</span><span class="v num">${S.automations.reduce((s,r)=>s+r.teller,0)}</span><span class="s">sinds ingebruikname</span></div>
    <div class="card kpi"><span class="lbl">Vandaag</span><span class="v num">${S.autoLog.filter(l=>l.d===TODAY).length}</span><span class="s">gebeurtenissen verwerkt</span></div></div>
  ${q.length?`<div class="card"><div class="card-h"><h3>Wacht op <em>bevestiging</em></h3><button class="btn sm" data-act="auto-okall">${ic('check')}Alles bevestigen</button></div><div class="card-b" style="padding-block:4px">${q.map((x,i)=>{ const r=S.automations.find(a=>a.id===x.rid)||{naam:''}; return `<div class="li"><span class="ic blue">${ic('bolt')}</span><div class="tx"><b>${esc(x.t)}</b><small>${esc(r.naam)} · actie: ${esc(r.actie||'')}</small></div><button class="btn sm pri" data-act="auto-ok" data-i="${i}">Bevestigen</button><button class="btn sm ghost" data-act="auto-skip" data-i="${i}">Overslaan</button></div>`; }).join('')}</div></div>`:''}
  <div class="card"><div class="card-h"><h3>Probeer het</h3><span class="muted" style="font-size:12px">een wijziging die een automation laat reageren</span></div><div class="card-b row wrap"><button class="btn" data-act="auto-demo-lead">${ic('funnel')}Maak testaanvraag zonder telefoonnummer</button><button class="btn" data-act="auto-rerun">${ic('reset')}Alle regels opnieuw uitvoeren</button><span class="muted" style="font-size:12.5px">De tweede keer gebeurt er niets: elke gebeurtenis wordt één keer verwerkt.</span></div></div>
  <div class="tabs">${[['regels','Regels'],['log','Activiteitenlog'],['rapporten','Rapporten']].map(([k,l])=>`<button class="tab ${tab===k?'on':''}" data-act="auto-tab" data-t="${k}">${l}</button>`).join('')}</div>
  ${tab==='regels'?`<div class="card">${S.automations.map(r=>`<div class="arule ${r.aan?'':'off'}"><button class="switch ${r.aan?'on':''}" data-act="auto-toggle" data-id="${r.id}" aria-label="${r.aan?'Uitzetten':'Aanzetten'}: ${esc(r.naam)}" aria-pressed="${r.aan}"></button>
    <div style="min-width:0"><b>${esc(r.naam)}</b><div class="flow"><span class="tr">${esc(r.trigger)}</span>${ic('chev')}<span>${esc(r.voorwaarde)}</span>${ic('chev')}<span class="ac">${esc(r.actie)}</span></div><div class="meta">${r.teller}× uitgevoerd · laatst ${fmtDY(r.laatste)}</div></div>
    <div class="acts"><select class="in" style="width:auto;height:30px" data-automod="${r.id}" aria-label="Uitvoermodus">${Object.entries(MOD).map(([k,v])=>`<option value="${k}" ${r.modus===k?'selected':''}>${v[1]}</option>`).join('')}</select><button class="btn xs ghost" data-act="auto-edit" data-id="${r.id}" aria-label="Bewerken">${ic('edit')}</button></div></div>`).join('')}</div>
    <p class="muted" style="margin:0;font-size:12px">Financiële, contractuele en externe acties (mails) vragen in productie altijd bevestiging. In deze demo komen mails alleen in de outbox.</p>`:''}
  ${tab==='log'?`<div class="card tw"><table class="t"><thead><tr><th>Moment</th><th>Regel</th><th>Gebeurtenis</th><th>Resultaat</th></tr></thead><tbody>${S.autoLog.map(l=>`<tr><td>${fmtD(l.d)} ${l.tijd}</td><td>${esc((S.automations.find(a=>a.id===l.rid)||{naam:'—'}).naam)}</td><td>${esc(l.t)}</td><td><span class="pill ${/Uitgevoerd|Bevestigd/.test(l.res)?'ok':/Wacht/.test(l.res)?'blue':/Overgeslagen/.test(l.res)?'mut':'warn'}">${esc(l.res)}</span></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">Nog geen gebeurtenissen.</div></td></tr>'}</tbody></table></div>`:''}
  ${tab==='rapporten'?`<div class="grid g2">${S.rapporten.map(r=>`<div class="card"><div class="card-h"><h3>${esc(r.titel)}</h3><span class="muted" style="font-size:12px">${fmtDY(r.d)}</span></div><div class="card-b">${r.regels.map(x=>`<div class="sumrow"><span>${esc(x)}</span></div>`).join('')}</div></div>`).join('')||`<div class="card"><div class="empty">${ic('report')}Nog geen rapporten. De weekafsluiting draait op vrijdag.</div></div>`}</div>`:''}
  </div>`;
}
function mAuto(r){
  const n=!r; r=r||{naam:'',type:'offerte3',trigger:'',voorwaarde:'',actie:'',modus:'bevestigen'};
  modal(n?'Nieuwe automation':'Automation bewerken',`<form class="fg" data-form="auto" data-id="${n?'':r.id}"><div class="f full"><label for="au-naam">Naam</label><input class="in" id="au-naam" name="naam" value="${esc(r.naam)}" required></div>
  <div class="f full"><label for="au-type">Trigger</label><select class="in" id="au-type" name="type">${Object.entries(AUTO_TYPES).map(([k,v])=>`<option value="${k}" ${r.type===k?'selected':''}>${esc(v.lbl)}</option>`).join('')}</select></div>
  <div class="f full"><label for="au-vw">Voorwaarde</label><input class="in" id="au-vw" name="voorwaarde" value="${esc(r.voorwaarde)}"></div>
  <div class="f full"><label for="au-ac">Actie</label><input class="in" id="au-ac" name="actie" value="${esc(r.actie)}"></div>
  <div class="f full"><label for="au-mod">Uitvoermodus</label><select class="in" id="au-mod" name="modus"><option value="signaleren" ${r.modus==='signaleren'?'selected':''}>Alleen signaleren</option><option value="bevestigen" ${r.modus==='bevestigen'?'selected':''}>Eerst bevestigen</option><option value="automatisch" ${r.modus==='automatisch'?'selected':''}>Automatisch uitvoeren</option></select></div>
  <p class="full muted" style="margin:0;font-size:12px">In dit prototype gebruiken nieuwe regels de logica van de gekozen trigger. In productie kies je voorwaarden en acties uit bouwstenen.</p></form>`,`${!n?`<button class="btn danger" data-act="auto-del" data-id="${r.id}" style="margin-right:auto">${ic('trash')}Verwijderen</button>`:''}<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Opslaan</button>`);
}
function autoConfirm(i){ const x=S.autoQueue[i]; if(!x) return ''; const r=S.automations.find(a=>a.id===x.rid); const c=r&&AUTO_TYPES[r.type].eval().find(c=>c.k===x.k); S.autoQueue.splice(i,1); if(!c){ S.autoLog.unshift({d:TODAY,tijd:nowT(),rid:x.rid,t:x.t,res:'Overgeslagen: niet meer van toepassing'}); return 'niet meer van toepassing'; } const res=c.apply(); S.autoLog.unshift({d:TODAY,tijd:nowT(),rid:x.rid,t:x.t,res:'Bevestigd: '+res}); return res; }

/* ---------- Teamchat ---------- */
function chChannels(){ const base=S.chat.channels; const klant=[...new Set(S.klantBerichten.map(m=>m.pid))].map(pid=>({id:'klant-'+pid,naam:(proj(pid)||{naam:pid}).naam,type:'klant',pid})); return {base,klant}; }
function chMsgs(id){ if(id.startsWith('klant-')){ const pid=id.slice(6); return S.klantBerichten.filter(m=>m.pid===pid).map(m=>({id:m.id,ch:id,van:m.van==='klant'?'klant':S.emps.find(e=>e.naam===m.naam)?.id||ME,klantNaam:m.naam,txt:m.txt,d:m.d,tijd:m.tijd,replies:[],pinned:false,att:null,klant:m.van==='klant'})); } return S.chat.msgs.filter(m=>m.ch===id); }
function unread(id){ return id.startsWith('klant-')?0:Math.max(0,chMsgs(id).length-(S.chat.read[id]||0)); }
function fmtChat(t){ let h=esc(t); h=h.replace(/@([A-Za-zÀ-ÿ]+)/g,'<span class="mention">@$1</span>'); h=h.replace(/PD-2026-(\d{4})/g,(m)=>proj(m)?`<a class="pdlink" href="/project-${m.toLowerCase()}">${m}</a>`:m); return h; }
function chMsgHtml(m,inThread){ const nm=m.van==='nova'?'Nova':m.van==='klant'?m.klantNaam+' (klant)':empName(m.van); const av=m.van==='nova'?`<span class="novaav sm">${ic('spark')}</span>`:avatar(m.van==='klant'?m.klantNaam:empName(m.van));
  return `<div class="cm ${m.pinned?'pinned':''}">${av}<div style="min-width:0"><div class="h"><b>${esc(nm)}</b><small>${m.d===TODAY?'vandaag':fmtD(m.d)} ${m.tijd}</small>${m.pinned?`<span class="pill warn" style="height:18px">${ic('pinned')}Vastgezet</span>`:''}${m.pdLinked?`<span class="pill blue" style="height:18px">${m.pdLinked}</span>`:''}</div><div class="tx">${fmtChat(m.txt)}</div>${m.att?`<span class="att">${ic('clip2')}${esc(m.att)}</span>`:''}${!inThread&&m.replies&&m.replies.length?`<button class="rep" data-act="ch-thread" data-id="${m.id}">${m.replies.length} ${m.replies.length===1?'reactie':'reacties'}</button>`:''}</div>
  ${!inThread&&!m.ch.startsWith('klant-')?`<div class="tools"><button data-act="ch-thread" data-id="${m.id}" title="Reageren in thread" aria-label="Reageren">${ic('reply')}</button><button data-act="ch-pin" data-id="${m.id}" title="${m.pinned?'Losmaken':'Vastzetten'}" aria-label="Vastzetten">${ic('pinned')}</button><button data-act="ch-task" data-id="${m.id}" title="Taak maken" aria-label="Taak maken">${ic('checksq')}</button><button data-act="ch-link" data-id="${m.id}" title="Koppel aan projectdossier" aria-label="Koppelen aan dossier">${ic('link')}</button></div>`:''}</div>`; }
function vTeamchat(){
  const {base,klant}=chChannels(); const cur=UI.chCur||'uitv'; const isK=cur.startsWith('klant-'); const ch=isK?klant.find(c=>c.id===cur):base.find(c=>c.id===cur); if(!ch){ UI.chCur='algemeen'; return vTeamchat(); }
  S.chat.read[cur]=chMsgs(cur).length; const msgs=chMsgs(cur); const thr=UI.chThread&&S.chat.msgs.find(m=>m.id===UI.chThread);
  const groups=[['Kanalen',base.filter(c=>c.type==='algemeen'||c.type==='afdeling')],['Projecten',base.filter(c=>c.type==='project')],['Teams',base.filter(c=>c.type==='team')]];
  let days=''; const body=msgs.map(m=>{ let sep=''; if(m.d!==days){ days=m.d; sep=`<div class="ch-day">${m.d===TODAY?'Vandaag':cap(dayName(m.d))+' '+fmtD(m.d)}</div>`; } return sep+chMsgHtml(m); }).join('');
  const pins=msgs.filter(m=>m.pinned).length;
  return `<div class="chat ${thr?'thr':''}"><aside class="ch-list">
    ${groups.map(([g,cs])=>`<h6>${g}</h6>${cs.map(c=>{ const u=unread(c.id); return `<button class="ch-btn ${c.id===cur?'on':''} ${u?'unread':''}" data-act="ch-open" data-id="${c.id}">${ic('hash').replace('<svg','<svg style="width:14px;height:14px;flex:none"')}<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.naam)}</span>${u?`<span class="cnt">${u}</span>`:''}</button>`; }).join('')}`).join('')}
    <h6>Klantcommunicatie</h6>${klant.map(c=>`<button class="ch-btn klant ${c.id===cur?'on':''}" data-act="ch-open" data-id="${c.id}">${ic('home').replace('<svg','<svg style="width:14px;height:14px;flex:none"')}<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.naam)}</span></button>`).join('')}
  </aside>
  <section class="ch-main"><div class="ch-mobile"><select class="in" id="chsel" aria-label="Kanaal">${[...base,...klant].map(c=>`<option value="${c.id}" ${c.id===cur?'selected':''}>${c.type==='klant'?'Klant: ':'#'}${esc(c.naam)}</option>`).join('')}</select></div>
    ${isK?`<div class="klantbar">${ic('home').replace('<svg','<svg style="width:13px;height:13px;vertical-align:-2px"')} Klantcommunicatie: berichten hier ziet de klant in de Service Hub.</div>`:''}
    <div class="ch-head"><h3>${isK?esc(ch.naam):'#'+esc(ch.naam)}</h3><span class="muted" style="font-size:12.5px">${esc(isK?'Gesprek met '+client(proj(ch.pid).clientId).naam:ch.oms||'')}</span><span style="flex:1"></span>${pins?`<span class="pill warn">${pins} vastgezet</span>`:''}${ch.pid?`<a class="btn sm" href="/project-${ch.pid.toLowerCase()}">${ic('folder')}${ch.pid}</a>`:''}<button class="btn sm" data-act="ch-sum">${ic('spark')}Samenvatten</button></div>
    ${UI.chSum&&UI.chSum.ch===cur?UI.chSum.html:''}
    <div class="ch-msgs" id="chmsgs">${body||'<div class="empty">Nog geen berichten in dit kanaal.</div>'}</div>
    <form class="ch-comp" data-form="chat" data-ch="${cur}"><label class="round" style="cursor:pointer;width:42px;height:42px" title="Bijlage toevoegen">${ic('clip2')}<input type="file" hidden id="chfile"></label><textarea class="in" name="txt" id="chtxt" rows="1" placeholder="${isK?'Bericht aan de klant (zichtbaar in Service Hub)':'Bericht aan #'+esc(ch.naam)+' · gebruik @naam en PD-nummers'}" aria-label="Bericht"></textarea><button class="send" type="submit" aria-label="Versturen">${ic('send')}</button></form>
    <div id="chatt" class="muted" style="font-size:12px;padding:0 18px 8px">${UI.chAtt?`Bijlage: ${esc(UI.chAtt)} <button class="btn xs ghost" data-act="ch-attx">Verwijderen</button>`:''}</div>
  </section>
  ${thr?`<aside class="ch-thread"><div class="ch-head"><h3>Thread</h3><span style="flex:1"></span><button class="iconbtn" data-act="ch-thread-x" aria-label="Thread sluiten">${ic('x')}</button></div><div class="ch-msgs">${chMsgHtml(thr,true)}<div class="ch-day">${thr.replies.length} reacties</div>${thr.replies.map(r=>chMsgHtml({...r,ch:thr.ch},true)).join('')}</div><form class="ch-comp" data-form="chreply" data-id="${thr.id}"><textarea class="in" name="txt" rows="1" placeholder="Reageer…" aria-label="Reactie"></textarea><button class="send" type="submit" aria-label="Versturen">${ic('send')}</button></form></aside>`:''}
  </div>`;
}
function chSummary(id){
  const ms=chMsgs(id).slice(-15); const who=[...new Set(ms.map(m=>m.van==='klant'?m.klantNaam:m.van==='nova'?'Nova':firstName(m.van)))]; const pds=[...new Set(ms.flatMap(m=>m.txt.match(/PD-2026-\d{4}/g)||[]))];
  const acts=ms.filter(m=>/\?|moet|graag|kan iemand|kijk jij|uiterlijk|vóór|nog niet|wie lost/i.test(m.txt));
  return `<div class="sumcard"><div class="h2"><span>${ic('spark').replace('<svg','<svg style="width:13px;height:13px;vertical-align:-2px"')} Nova · samenvatting van de laatste ${ms.length} berichten</span><button class="btn xs ghost" data-act="ch-sumx" aria-label="Sluiten">${ic('x')}</button></div><div class="b"><div>Deelnemers: ${esc(who.join(', '))}${pds.length?` · dossiers: ${pds.join(', ')}`:''}</div>${acts.length?`<b>Voorgestelde actiepunten</b>${acts.map(m=>`<div class="row between" style="gap:8px"><span>• ${esc(m.txt.length>110?m.txt.slice(0,110)+'…':m.txt)}</span><button class="btn xs" data-act="ch-task" data-id="${m.id}">Taak</button></div>`).join('')}`:'<div>Geen open vragen of actiepunten gevonden.</div>'}<div class="muted" style="font-size:11px">Lokale samenvatting op basis van trefwoorden, geen externe AI.</div></div></div>`;
}
function r3AfterRender(r){ if(r==='teamchat'){ const b=$('#chmsgs'); if(b) b.scrollTop=b.scrollHeight; } if(r==='servicehub'){ const b=$('#hubmsgs'); if(b) b.scrollTop=b.scrollHeight; } }
const _r2After=r2AfterRender; r2AfterRender=function(r){ _r2After(r); r3AfterRender(r); };

/* ---------- Koppelingen met bestaande onderdelen ---------- */
Object.assign(R2_ROUTES,{financieel:vFinancieel,servicehub:vServiceHub,automations:vAutomations,teamchat:vTeamchat});
for(const g of NAV) for(const it of g.items){ if(it[0]==='m-financieel') it[0]='financieel'; if(it[0]==='m-automations') it[0]='automations'; if(it[0]==='m-teamchat') it[0]='teamchat'; }
NAV.find(g=>g.g==='Projectmanagement').items.push(['servicehub','Klant Service Hub','home']);
const _r2Att=r2Attention; r2Attention=function(){ const items=_r2Att(); if(S.autoQueue&&S.autoQueue.length) items.push({k:'blue',icon:'bolt',t:`${S.autoQueue.length} automation-${S.autoQueue.length===1?'actie wacht':'acties wachten'} op bevestiging`,s:S.autoQueue.slice(0,2).map(x=>x.t).join(', '),btn:'Bekijk',go:'automations'});
  const kv=S.klantBerichten.filter(m=>m.van==='klant'&&!S.klantBerichten.some(x=>x.pid===m.pid&&x.van==='renovion'&&(x.d>m.d||(x.d===m.d&&x.tijd>m.tijd)))); if(kv.length) items.push({k:'or',icon:'chat',t:`${kv.length} ${kv.length===1?'klantvraag wacht':'klantvragen wachten'} op antwoord`,s:kv.map(m=>`${m.naam}: ${m.txt.slice(0,50)}`).join(' · '),btn:'Beantwoorden',go:'teamchat',chCur:'klant-'+kv[0].pid});
  const ink=S.inkoop.filter(x=>x.status==='ontvangen').length+S.declaraties.filter(x=>x.status==='ingediend').length; if(ink) items.push({k:'mut',icon:'receipt',t:`${ink} inkoopfacturen en declaraties te beoordelen`,s:'Financieel',btn:'Beoordelen',go:'financieel',finTab:S.inkoop.some(x=>x.status==='ontvangen')?'inkoop':'declaraties'});
  return items; };
const _novaR2=novaR2; novaR2=function(t){ if(_novaR2(t)) return true;
  if(/omzet|cashflow|liquiditeit|banksaldo|werkvoorraad|marges? per project/.test(t)){ const F=finCalc(); const low=F.proj.filter(p=>p.phase<8).map(p=>({p,m:projectFin(p).marge})).sort((a,b)=>a.m-b.m); novaSay(`<b>Financieel</b><br>Omzet dit jaar ${eur0(F.omzetJ)}, deze maand ${eur0(F.omzetM)}.<br>Bevestigde werkvoorraad ${eur0(F.voorraad)}; nog te factureren ${eur0(F.nogTeFact)}.<br>Banksaldo over 6 maanden ${eur0(F.saldo[5])} (laagste ${eur0(Math.min(...F.saldo))} in ${cmLabel(F.cm[F.saldo.indexOf(Math.min(...F.saldo))])}).<br>Verwachte eindmarge ${pct(F.em)} (begroot ${pct(F.bm)}). Laagste marge: ${low.slice(0,2).map(x=>`${esc(x.p.naam)} ${pct(x.m)}`).join(', ')}.<br><a href="/financieel" data-act="nclose">Open financieel dashboard</a>`); return true; }
  if(/automation|wachtrij/.test(t)){ novaSay(S.autoQueue.length?`<b>${S.autoQueue.length} acties wachten op bevestiging</b><br>${S.autoQueue.map(x=>'• '+esc(x.t)).join('<br>')}<br><a href="/automations" data-act="nclose">Naar automations</a>`:'Er wachten geen automation-acties.'); return true; }
  if(/klantvra|klantbericht|service ?hub/.test(t)){ const kv=S.klantBerichten.filter(m=>m.van==='klant').slice(-4); novaSay(`<b>Recente klantberichten</b><br>${kv.map(m=>`• ${esc(m.naam)} (${esc(proj(m.pid).naam)}): ${esc(m.txt)}`).join('<br>')}`); return true; }
  return false; };

/* ---------- Formulieren ---------- */
Object.assign(R2_FORMS,{
  auto(f,v){ if(!v.naam) return fieldErr(f,'naam','Geef de regel een naam.'); const id=f.dataset.id; const ty=AUTO_TYPES[v.type];
    if(id){ Object.assign(S.automations.find(a=>a.id===id),{naam:v.naam,type:v.type,trigger:ty.lbl,voorwaarde:v.voorwaarde,actie:v.actie,modus:v.modus}); }
    else S.automations.push({id:uid('a'),type:v.type,naam:v.naam,trigger:ty.lbl,voorwaarde:v.voorwaarde||'—',actie:v.actie||'—',modus:v.modus,aan:true,teller:0,laatste:TODAY});
    closeModal(); commit(id?'Regel opgeslagen':'Regel aangemaakt en direct actief'); },
  dec(f,v){ if(!(parseNL(v.bedrag)>0)) return fieldErr(f,'bedrag','Vul een bedrag in.'); S.declaraties.push({id:uid('dc'),emp:v.emp,soort:v.soort,bedrag:parseNL(v.bedrag),pid:v.pid,bon:UI.decBon||null,datum:v.datum,status:'ingediend',opm:v.opm}); UI.decBon=null; closeModal(); commit('Declaratie ingediend'); },
  hubmsg(f,v){ if(!v.txt) return; const p=proj(f.dataset.pid); const c=client(p.clientId);
    if((UI.hubMode||'deel')==='prive'){ S.klantNotities.push({pid:p.id,txt:v.txt,d:TODAY}); commit('Privénotitie bewaard. Renovion ziet deze niet.'); return; }
    S.klantBerichten.push({id:uid('kb'),pid:p.id,van:'klant',naam:c.contact||c.naam,txt:v.txt,d:TODAY,tijd:nowT()}); addActivity(p,`Klantvraag via Service Hub: "${v.txt.slice(0,60)}"`,'or'); S.notifs.unshift({t:`Nieuwe vraag van ${c.contact||c.naam}`,d:TODAY});
    S.tasks.push({id:uid('t'),titel:`Klantvraag beantwoorden: ${c.naam}`,pid:p.id,eig:p.leider,dl:addDays(TODAY,1),status:'todo',prio:'normaal',oms:v.txt,checklist:[]}); commit('Verstuurd. Renovion heeft uw vraag ontvangen.'); },
  chat(f,v){ const txt=(v.txt||'').trim(); if(!txt&&!UI.chAtt) return; const ch=f.dataset.ch;
    if(ch.startsWith('klant-')){ const pid=ch.slice(6); S.klantBerichten.push({id:uid('kb'),pid,van:'renovion',naam:myName(),txt,d:TODAY,tijd:nowT()}); addActivity(proj(pid),'Bericht aan klant via Service Hub','blue'); const t=S.tasks.find(x=>x.pid===pid&&x.status!=='afgerond'&&/^Klantvraag beantwoorden/.test(x.titel)); if(t) t.status='afgerond'; commit('Bericht staat in de Service Hub van de klant'); return; }
    S.chat.msgs.push({id:uid('m'),ch,van:ME,txt,d:TODAY,tijd:nowT(),pinned:false,replies:[],att:UI.chAtt||null}); UI.chAtt=null;
    const men=[...txt.matchAll(/@([A-Za-zÀ-ÿ]+)/g)].map(m=>S.emps.find(e=>e.naam.split(' ')[0].toLowerCase()===m[1].toLowerCase())).filter(Boolean); commit(men.length?`Verstuurd · ${men.map(e=>firstName(e.id)).join(', ')} krijgt een melding`:''); setTimeout(()=>$('#chtxt')?.focus(),30); },
  chreply(f,v){ const m=S.chat.msgs.find(x=>x.id===f.dataset.id); if(!v.txt) return; m.replies.push({van:ME,txt:v.txt,d:TODAY,tijd:nowT()}); commit(); },
});

/* ---------- Events ---------- */
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act, d=el.dataset;
  switch(a){
    case 'att': { const it=attention()[+d.i]; if(it&&it.chCur) UI.chCur=it.chCur; if(it&&it.finTab) UI.finTab=it.finTab; break; }
    case 'fin-tab': UI.finTab=d.t; render(); break;
    case 'ink-ok': { const x=S.inkoop.find(i=>i.nr===d.nr); x.status='goedgekeurd'; const p=proj(x.pid); if(p){ p.kosten=(p.kosten||0)+x.bedrag; addActivity(p,`Inkoopfactuur ${x.nr} ${x.lev} goedgekeurd: ${eur(x.bedrag)} geboekt`,'blue'); } commit(`Goedgekeurd en geboekt op ${x.pid}`); break; }
    case 'ink-no': { const x=S.inkoop.find(i=>i.nr===d.nr); x.status='afgewezen'; commit('Inkoopfactuur afgewezen','warn'); break; }
    case 'ink-pay': { const x=S.inkoop.find(i=>i.nr===d.nr); mConfirm('Betaling registreren',`Registreer dat ${eur(x.bedrag)} aan ${esc(x.lev)} is betaald. Er is geen bankkoppeling; je registreert de betaling zelf.`,'Registreren',()=>{ x.status='betaald'; }); break; }
    case 'dec-ok': { const x=S.declaraties.find(i=>i.id===d.id); if(!x.bon){ mConfirm('Declaratie zonder bon',`Er is geen bon bijgevoegd. Toch ${eur(x.bedrag)} goedkeuren?`,'Toch goedkeuren',()=>{ x.status='goedgekeurd'; const p=proj(x.pid); if(p) p.kosten=(p.kosten||0)+x.bedrag; }); break; } x.status='goedgekeurd'; const p=proj(x.pid); if(p){ p.kosten=(p.kosten||0)+x.bedrag; addActivity(p,`Declaratie ${empName(x.emp)} (${x.soort}) goedgekeurd`,'blue'); } commit('Declaratie goedgekeurd'); break; }
    case 'dec-no': { S.declaraties.find(i=>i.id===d.id).status='afgewezen'; commit('Declaratie afgewezen','warn'); break; }
    case 'dec-new': UI.decBon=null; modal('Declaratie indienen',`<form class="fg" data-form="dec"><div class="f"><label for="dc-emp">Medewerker</label><select class="in" id="dc-emp" name="emp">${empOpts(ME)}</select></div><div class="f"><label for="dc-soort">Kostensoort</label><select class="in" id="dc-soort" name="soort">${['Parkeren','Brandstof','Kilometervergoeding','Klein materiaal','Overig'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="f"><label for="dc-b">Bedrag (€)</label><input class="in" type="number" step="0.01" id="dc-b" name="bedrag"></div><div class="f"><label for="dc-d">Datum</label><input class="in" type="date" id="dc-d" name="datum" value="${TODAY}"></div><div class="f full"><label for="dc-p">Project</label><select class="in" id="dc-p" name="pid">${projOpts('',true)}</select></div><div class="f full"><label for="dc-o">Toelichting</label><input class="in" id="dc-o" name="opm"></div><label class="btn full" style="cursor:pointer;justify-self:start">${ic('upload')}Bon toevoegen<input type="file" hidden id="dcbon"></label><div class="full muted" id="dcbonname" style="font-size:12px"></div></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Indienen</button>`); break;
    case 'hub-mode': UI.hubMode=d.m; render(); break;
    case 'hub-opt': { const p=proj(d.pid); const o=p.begroting.options[+d.i]; mConfirm('Akkoord met meerwerk',`U gaat akkoord met <b>${esc(o.d)}</b> voor ${eur(optPrice(o,p.begroting)*1.21)} incl. btw. Dit wordt toegevoegd aan uw contract.`,'Akkoord geven',()=>{ o.s='akkoord'; addActivity(p,`Klant akkoord via Service Hub: ${o.d} (${eur(optPrice(o,p.begroting))})`,'or'); S.notifs.unshift({t:`Meerwerk akkoord: ${o.d}`,d:TODAY}); }); break; }
    case 'hub-appt': { const ap=S.agenda.find(x=>x.id===d.id); ap.bevestigd=true; if(ap.pid) addActivity(proj(ap.pid),`Afspraak ${fmtD(ap.d)} bevestigd door klant`,'blue'); commit('Afspraak bevestigd'); break; }
    case 'auto-tab': UI.autoTab=d.t; render(); break;
    case 'auto-toggle': { const r=S.automations.find(x=>x.id===d.id); r.aan=!r.aan; commit(r.aan?`${r.naam} staat aan`:`${r.naam} staat uit`); break; }
    case 'auto-new': mAuto(null); break;
    case 'auto-edit': mAuto(S.automations.find(x=>x.id===d.id)); break;
    case 'auto-del': S.automations=S.automations.filter(x=>x.id!==d.id); S.autoQueue=S.autoQueue.filter(x=>x.rid!==d.id); closeModal(); commit('Regel verwijderd'); break;
    case 'auto-ok': { const r=autoConfirm(+d.i); commit('Bevestigd: '+r); break; }
    case 'auto-okall': { let n=0; while(S.autoQueue.length){ autoConfirm(0); n++; } commit(`${n} acties uitgevoerd`); break; }
    case 'auto-skip': { const x=S.autoQueue.splice(+d.i,1)[0]; S.autoLog.unshift({d:TODAY,tijd:nowT(),rid:x.rid,t:x.t,res:'Overgeslagen'}); commit(); break; }
    case 'auto-demo-lead': { const before=S.autoQueue.length; createLead({naam:'Familie Testman',soort:'Particulier',contact:'Tom Testman',tel:'',mail:'tom@testman-demo.nl',type:'Badkamerrenovatie',adres:'Demolaan 1',plaats:'Arnhem',budget:'15000',bron:'Website',oms:'Testaanvraag voor de automation-demo'}); save(); UI.autoTab='log'; render(); toast(S.autoQueue.length>before?'De regel "Ontbrekend telefoonnummer" heeft gereageerd: actie staat klaar ter bevestiging.':'Aanvraag aangemaakt.'); break; }
    case 'auto-rerun': { const n=runAutomations(); _saveR3(); render(); toast(n?`${n} nieuwe gebeurtenissen verwerkt`:'Geen nieuwe gebeurtenissen: alles was al verwerkt, er zijn geen dubbele acties uitgevoerd.'); break; }
    case 'ch-open': UI.chCur=d.id; UI.chThread=null; save(); render(); break;
    case 'ch-thread': UI.chThread=d.id; render(); break;
    case 'ch-thread-x': UI.chThread=null; render(); break;
    case 'ch-pin': { const m=S.chat.msgs.find(x=>x.id===d.id); m.pinned=!m.pinned; commit(m.pinned?'Bericht vastgezet':'Losgemaakt'); break; }
    case 'ch-task': { const m=S.chat.msgs.find(x=>x.id===d.id)||chMsgs(UI.chCur).find(x=>x.id===d.id); const ch=S.chat.channels.find(c=>c.id===m.ch); const pid=(m.txt.match(/PD-2026-\d{4}/)||[])[0]||(ch&&ch.pid)||(m.ch.startsWith('klant-')?m.ch.slice(6):''); mTask(null,pid); $('#t-titel').value=m.txt.replace(/@\w+\s*/g,'').slice(0,80); $('#t-oms').value=`Uit teamchat (#${ch?ch.naam:'klant'}), ${m.van==='klant'?m.klantNaam:empName(m.van)}: ${m.txt}`; break; }
    case 'ch-link': { const m=S.chat.msgs.find(x=>x.id===d.id); UI.chLinkMsg=m.id; modal('Koppel bericht aan projectdossier',`<form class="fg" data-form="chlink"><div class="f full"><label for="cl-p">Projectdossier</label><select class="in" id="cl-p" name="pid">${projOpts((m.txt.match(/PD-2026-\d{4}/)||[])[0]||'',false)}</select></div><p class="full muted" style="margin:0">Het bericht verschijnt als activiteit in het dossier.</p></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="ch-link-ok">Koppelen</button>`); break; }
    case 'ch-link-ok': { const m=S.chat.msgs.find(x=>x.id===UI.chLinkMsg); const pid=$('#cl-p').value; m.pdLinked=pid; addActivity(proj(pid),`Teambericht gekoppeld (${empName(m.van)}): "${m.txt.slice(0,70)}"`,'mut'); closeModal(); commit(`Gekoppeld aan ${pid}`); break; }
    case 'ch-sum': UI.chSum={ch:UI.chCur||'uitv',html:chSummary(UI.chCur||'uitv')}; render(); break;
    case 'ch-sumx': UI.chSum=null; render(); break;
    case 'ch-attx': UI.chAtt=null; render(); break;
  }
});
document.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset.finas){ S.fin[t.dataset.finas]=parseNL(t.value); commit('Aanname bijgewerkt, prognose herberekend'); return; }
  if(t.id==='hubsel'){ UI.hubPid=t.value; render(); return; }
  if(t.dataset.hubup){ const v=S.klantVerzoeken.find(x=>x.id===t.dataset.hubup); const f=t.files[0]; v.status='ontvangen'; const p=proj(v.pid); p.docs.unshift({naam:f?f.name:'aangeleverd-bestand',cat:'Klant',datum:TODAY}); addActivity(p,`Klant leverde aan: ${v.titel}`,'blue'); commit('Bedankt, het bestand is ontvangen.'); return; }
  if(t.dataset.automod){ const r=S.automations.find(x=>x.id===t.dataset.automod); r.modus=t.value; commit(`Modus: ${t.options[t.selectedIndex].text}`); return; }
  if(t.id==='chsel'){ UI.chCur=t.value; UI.chThread=null; render(); return; }
  if(t.id==='chfile'&&t.files[0]){ UI.chAtt=t.files[0].name; $('#chatt').innerHTML=`Bijlage: ${esc(UI.chAtt)} <button class="btn xs ghost" data-act="ch-attx">Verwijderen</button>`; return; }
  if(t.id==='dcbon'&&t.files[0]){ UI.decBon=t.files[0].name; $('#dcbonname').textContent='Bon: '+UI.decBon; return; }
});
document.addEventListener('keydown',e=>{ if(e.key==='Enter'&&!e.shiftKey&&e.target.closest&&e.target.closest('.ch-comp')&&e.target.tagName==='TEXTAREA'){ e.preventDefault(); e.target.form.requestSubmit(); } });

