try{ UI.sb=localStorage.getItem('renovion-os-sb')||'auto'; }catch(e){ UI.sb='auto'; }
function applySb(){ const a=$('#app'); if(!a) return; a.classList.toggle('sb-closed',UI.sb==='closed'); a.classList.toggle('sb-open',UI.sb==='open'); }
function sbIsRail(){ const w=window.innerWidth; if(w<=900) return false; if(UI.sb==='closed') return true; if(UI.sb==='open') return false; return w<=1180; }

/* Sidebar: toggle-knop, beeldmerk en tooltips bij ingeklapte rail */
