/* Bottom navigation, rol-afhankelijk */
const BNAV_ITEMS={vandaag:['Vandaag','sun'],servicehub:['Mijn project','home'],partner:['Portal','team'],projecten:['Projecten','folder'],werkbonnen:['Werkbonnen','wrench'],planning:['Planning','cal'],taken:['Taken','checksq'],teamchat:['Chat','chat'],sales:['Sales','funnel'],financieel:['Financieel','chart']};
const BNAV_ROLE={Klant:['servicehub'],Onderaannemer:['partner','werkbonnen'],Uitvoerder:['vandaag','werkbonnen','planning','taken'],Sales:['vandaag','sales','projecten','taken'],Administratie:['vandaag','financieel','projecten','teamchat']};
const BNAV_PREF_FOR = rol => (BNAV_ROLE[rol]||['vandaag','projecten','planning','taken','werkbonnen','teamchat']).map(k=>[k,...BNAV_ITEMS[k]]);
function renderBnav(){ let nav=$('#bnav'); if(!nav){ nav=document.createElement('nav'); nav.id='bnav'; nav.className='bnav'; nav.setAttribute('aria-label','Hoofdnavigatie'); document.body.appendChild(nav); }
  const rol=curRol(), key=routeKey(route()); const items=BNAV_PREF_FOR(rol).filter(([k])=>allowed(rol,k)).slice(0,4); const nova=false; /* Nova zweeft nu als assistent in de hoek (ronde 7) */
  const att=attention().length; const unreadChat=S.chat?S.chat.channels.reduce((s,c)=>s+unread(c.id),0):0;
  const it=([k,l,i])=>`<a href="/${k}" class="${key===k?'on':''}" ${key===k?'aria-current="page"':''}>${ic(i)}<span>${l}</span>${k==='inbox'&&att?`<span class="cnt">${att}</span>`:''}${k==='teamchat'&&unreadChat?`<span class="cnt">${unreadChat}</span>`:''}</a>`;
  const left=items.slice(0,2), right=items.slice(2,4);
  nav.innerHTML=left.map(it).join('')+(nova?`<button class="fab" data-act="nova" aria-label="Nova openen">${ic('spark')}</button>`:'')+right.slice(0,nova?1:2).map(it).join('')+`<button data-act="burger" aria-label="Volledig menu">${ic('listi')}<span>Menu</span></button>`; }

/* Tabellen labelen zodat ze op de telefoon als kaarten worden getoond */
function labelTables(root){ (root||document).querySelectorAll('table.t:not(.perm)').forEach(tbl=>{ const hs=[...tbl.querySelectorAll('thead th')].map(th=>th.textContent.trim()); if(!hs.length) return; tbl.classList.add('rt'); tbl.querySelectorAll('tbody tr, tfoot tr').forEach(tr=>{ let col=0; [...tr.children].forEach(td=>{ if(hs[col]!==undefined&&!td.hasAttribute('data-label')) td.dataset.label=hs[col]; col+=(+td.getAttribute('colspan')||1); }); }); }); }
const _modalR6=modal; modal=function(...args){ _modalR6(...args); labelTables($('#layer')); };

/* Mobiele planning: dagweergave per vakman */
function vPlanningMobile(){
  const ws=UI.planWeek; const days=[]; for(let s=ws; days.length<5; s=addDays(s,1)) if(!isWeekend(s)) days.push(s);
  const d=UI.mDay&&days.includes(UI.mDay)?UI.mDay:(days.includes(TODAY)?TODAY:days[0]); UI.mDay=d; const cids=confIds();
  const rows=PLANNABLE().map(e=>{ const bl=S.blocks.filter(b=>b.emp===e.id&&b.start<=d&&d<=b.end); const ab=(e.afwezig||[]).find(a=>a.van<=d&&d<=a.tot);
    return `<div class="mplan-row">${avatar(e.naam)}<div style="min-width:0"><div class="row between"><b>${esc(e.naam)}</b><small class="muted">${esc(e.rol)}</small></div>${ab?`<span class="pill mut" style="margin-top:4px">${esc(ab.reden||'Afwezig')}</span>`:''}${bl.map(b=>{ const p=proj(b.pid)||{naam:'Intern',plaats:'',kleur:0}; return `<div class="blk pc${p.kleur%6} ${cids.has(b.id)?'conf':''}" data-act="editblock" data-id="${b.id}"><b>${esc(p.naam)}</b><small>${esc(b.titel)} · ${esc(p.plaats)} · ${fmtD(b.start)}${b.end!==b.start?'–'+fmtD(b.end):''}</small></div>`; }).join('')}${!bl.length&&!ab?'<div class="free">Beschikbaar</div>':''}</div></div>`; }).join('');
  const cf=conflicts().filter(c=>c.day>=days[0]&&c.day<=days[4]);
  return `<div class="page"><div class="ph"><div><h1>Plan<em>ning</em></h1><p>Dagoverzicht per vakman. Tik op een blok om het te wijzigen.</p></div><div class="acts"><button class="btn" data-act="pview" data-v="cap">Capaciteit</button><button class="btn pri" data-act="newblock">${ic('plus')}Inplannen</button></div></div>
  <div class="row between"><button class="btn sm" data-act="pweek" data-d="-7" aria-label="Vorige week">${ic('chevl')}</button><b>Week van ${fmtD(days[0])}</b><button class="btn sm" data-act="pweek" data-d="7" aria-label="Volgende week">${ic('chev')}</button></div>
  <div class="mplan-days">${days.map(x=>`<button class="${x===d?'on':''} ${x===TODAY?'today':''}" data-act="m-day" data-d="${x}"><small>${dayName(x)}</small><b>${D(x).getDate()}</b></button>`).join('')}</div>
  ${cf.length?`<div class="alert bad">${ic('alert')}<div class="grow"><b>${cf.length} ${cf.length===1?'conflict':'conflicten'} deze week:</b> ${cf.map(c=>`${firstName(c.emp)} ${dayName(c.day)} ${fmtD(c.day)}`).join(', ')}</div></div>`:''}
  <div class="card">${rows}</div></div>`;
}
