/* ---------- Ronde 8 · Mobile ready: aanraken, gebaren, terugknop, installeren ---------- */
const MOB=()=>matchMedia('(max-width: 900px)').matches;
const COARSE=()=>matchMedia('(pointer: coarse)').matches;
const APP_ICONS={"i180":"/os/img/icon-i180.png","i192":"/os/img/icon-i192.png","i512":"/os/img/icon-i512.png","m512":"/os/img/icon-m512.png"};
const IS_APP=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
if(IS_APP) document.documentElement.classList.add('is-app');
if(COARSE()) document.documentElement.classList.add('touch');

/* 1 · Slepen met je vinger: lang indrukken (0,35 s) en dan schuiven.
   Stuurt dezelfde drag-events als de muis, dus planning, kanbans, mail- en offertebuilder werken ongewijzigd. */
(function(){
  let lp=null, drag=null, ghost=null, loop=null;
  const hasDT=(()=>{ try{ new DataTransfer(); return true; }catch(e){ return false; } })();
  function fire(type,target,x,y){ let ev; try{ ev=new DragEvent(type,{bubbles:true,cancelable:true,clientX:x,clientY:y,dataTransfer:drag.dt}); }catch(e){ ev=new Event(type,{bubbles:true,cancelable:true}); Object.defineProperty(ev,'dataTransfer',{value:drag.dt}); Object.assign(ev,{clientX:x,clientY:y}); }
    if(!ev.dataTransfer) Object.defineProperty(ev,'dataTransfer',{value:drag.dt}); target.dispatchEvent(ev); return ev; }
  function scroller(el,axis){ while(el&&el!==document.body){ const cs=getComputedStyle(el); if(axis==='x'&&/(auto|scroll)/.test(cs.overflowX)&&el.scrollWidth>el.clientWidth+2) return el; if(axis==='y'&&/(auto|scroll)/.test(cs.overflowY)&&el.scrollHeight>el.clientHeight+2) return el; el=el.parentElement; } return null; }
  function start(src,x,y){ lp=null;
    const dt=hasDT?new DataTransfer():{setData(){},getData(){return ''},effectAllowed:'move',dropEffect:'move'};
    drag={src,dt,over:null,ok:false,x,y,x0:x,y0:y}; const r=src.getBoundingClientRect();
    ghost=src.cloneNode(true); ghost.className+=' tdrag-ghost'; ghost.removeAttribute('id'); Object.assign(ghost.style,{width:r.width+'px',height:r.height+'px',left:r.left+'px',top:r.top+'px'}); drag.dx=x-r.left; drag.dy=y-r.top;
    document.body.appendChild(ghost); src.classList.add('tdrag-src'); document.body.classList.add('tdragging');
    try{ navigator.vibrate&&navigator.vibrate(12); }catch(e){}
    fire('dragstart',src,x,y); move(x,y);
    loop=setInterval(autoscroll,16);
  }
  function move(x,y){ drag.x=x; drag.y=y; ghost.style.left=(x-drag.dx)+'px'; ghost.style.top=(y-drag.dy)+'px';
    const el=document.elementFromPoint(x,y); if(!el) return;
    if(drag.over&&drag.over!==el&&!drag.over.contains(el)) fire('dragleave',drag.over,x,y);
    const ev=fire('dragover',el,x,y); drag.ok=ev.defaultPrevented; drag.over=el; }
  function autoscroll(){ if(!drag) return; const {x,y}=drag, E=48, V=14; let moved=false; if(!drag.moved){ if(Math.hypot(x-drag.x0,y-drag.y0)<16) return; drag.moved=true; }
    const hx=scroller(drag.over||drag.src,'x'); if(hx){ const r=hx.getBoundingClientRect(); if(x<r.left+E){ hx.scrollLeft-=V; moved=true; } else if(x>r.right-E){ hx.scrollLeft+=V; moved=true; } }
    const vy=scroller(drag.over||drag.src,'y'); const top=vy?vy.getBoundingClientRect().top:0, bot=vy?vy.getBoundingClientRect().bottom:innerHeight;
    if(y<top+E+(vy?0:60)){ vy?vy.scrollTop-=V:scrollBy(0,-V); moved=true; } else if(y>bot-E-(vy?0:80)){ vy?vy.scrollTop+=V:scrollBy(0,V); moved=true; }
    if(moved) move(x,y); }
  function cleanup(){ clearInterval(loop); ghost&&ghost.remove(); ghost=null; drag&&drag.src.classList.remove('tdrag-src'); document.body.classList.remove('tdragging'); drag=null; }
  function end(){ const d=drag; if(d.over&&d.ok) fire('drop',d.over,d.x,d.y); else document.querySelectorAll('.over,.dropb').forEach(x=>x.classList.remove('over','dropb')); fire('dragend',d.src,d.x,d.y); cleanup(); }
  document.addEventListener('touchstart',e=>{ if(e.touches.length!==1||drag) return; const src=e.target.closest&&e.target.closest('[draggable="true"]'); if(!src) return; const t=e.touches[0];
    lp={src,x:t.clientX,y:t.clientY,timer:setTimeout(()=>{ if(lp) start(src,lp.x,lp.y); },350)}; },{passive:true});
  document.addEventListener('touchmove',e=>{ const t=e.touches[0]; if(drag){ e.preventDefault(); move(t.clientX,t.clientY); return; }
    if(lp){ if(Math.hypot(t.clientX-lp.x,t.clientY-lp.y)>10){ clearTimeout(lp.timer); lp=null; } else { lp.x=t.clientX; lp.y=t.clientY; } } },{passive:false});
  document.addEventListener('touchend',e=>{ if(lp){ clearTimeout(lp.timer); lp=null; } if(drag){ e.preventDefault(); end(); } },{passive:false});
  document.addEventListener('touchcancel',()=>{ if(lp){ clearTimeout(lp.timer); lp=null; } if(drag){ fire('dragend',drag.src,drag.x,drag.y); cleanup(); } });
  /* native drag van de browser niet laten meedoen tijdens een aanraaksleep */
  document.addEventListener('dragstart',e=>{ if(e.isTrusted&&(lp||drag)&&COARSE()){ e.preventDefault(); e.stopImmediatePropagation(); } },true);
  document.addEventListener('contextmenu',e=>{ if((lp||drag)&&e.target.closest&&e.target.closest('[draggable="true"]')) e.preventDefault(); });
  window.__touchDrag={active:()=>!!drag};
})();

/* 2 · Android-terugknop en swipe-terug sluiten eerst het open venster, menu of Nova */
(function(){
  let pushed=false, hashAt='', byPop=false, t=null;
  const open=()=>!!($('#layer')&&$('#layer').children.length)||!!UI.novaOpen||!!$('#side')?.classList.contains('open');
  function sync(){ clearTimeout(t); t=setTimeout(()=>{ const o=open();
    if(o&&!pushed&&MOB()){ history.pushState({ov:1},''); pushed=true; hashAt=location.pathname; }
    else if(!o&&pushed){ pushed=false; if(!byPop&&location.pathname===hashAt&&history.state&&history.state.ov) history.back(); } },40); }
  window.addEventListener('popstate',()=>{ if(!pushed) return; pushed=false; byPop=true;
    if($('#layer').children.length) $('#layer').innerHTML='';
    else if(UI.novaOpen) closeNova();
    else { $('#side').classList.remove('open'); document.querySelector('.scrim')?.remove(); }
    setTimeout(()=>{ byPop=false; sync(); },60); });
  window.addEventListener('hashchange',()=>{ if(pushed&&location.pathname!==hashAt){ pushed=false; } });
  const mo=new MutationObserver(sync);
  const watch=()=>{ mo.observe($('#layer'),{childList:true}); mo.observe($('#side'),{attributes:true,attributeFilter:['class']}); const d=document.getElementById('nvdock'); if(d) mo.observe(d,{childList:true}); };
  setTimeout(watch,0);
  const _rn=renderNova; renderNova=function(...a){ const r=_rn.apply(this,a); if(!mo._nv&&document.getElementById('nvdock')){ mo.observe(document.getElementById('nvdock'),{childList:true}); mo._nv=1; } return r; };
})();

/* 3 · Gebaren: veeg vanaf de linkerrand voor het menu, veeg menu dicht, veeg vensters omlaag om te sluiten */
(function(){
  let g=null;
  document.addEventListener('touchstart',e=>{ if(!MOB()||e.touches.length!==1) return; const t=e.touches[0], el=e.target;
    if(el.closest&&el.closest('[draggable="true"]')) return;
    const side=$('#side'), sheet=el.closest&&el.closest('.modal .mh, .nv-top');
    if(sheet){ const box=sheet.closest('.modal,.nv-panel'); g={k:'sheet',box,y0:t.clientY,x0:t.clientX,dy:0}; return; }
    if(side.classList.contains('open')){ g={k:'close',x0:t.clientX,y0:t.clientY,dx:0}; return; }
    if(t.clientX<22&&!$('#layer').children.length&&!UI.novaOpen) g={k:'open',x0:t.clientX,y0:t.clientY,dx:0};
  },{passive:true});
  document.addEventListener('touchmove',e=>{ if(!g) return; const t=e.touches[0]; const dx=t.clientX-g.x0, dy=t.clientY-g.y0;
    if(g.k==='sheet'){ if(dy>0&&Math.abs(dy)>Math.abs(dx)){ g.dy=dy; g.box.style.transition='none'; g.box.style.transform=`translateY(${dy}px)`; } return; }
    if(Math.abs(dy)>Math.abs(dx)*1.2&&Math.abs(dy)>14){ g=null; return; }
    g.dx=dx; if(g.k==='close'&&dx<0) $('#side').style.transform=`translateX(${dx}px)`;
  },{passive:true});
  document.addEventListener('touchend',()=>{ if(!g) return; const k=g;
    if(k.k==='sheet'){ k.box.style.transition=''; if(k.dy>90){ k.box.style.transform=`translateY(100%)`; setTimeout(()=>{ if(k.box.classList.contains('nv-panel')) closeNova(); else $('#layer').innerHTML=''; },150); } else k.box.style.transform=''; }
    if(k.k==='close'){ $('#side').style.transform=''; if(k.dx<-70){ $('#side').classList.remove('open'); document.querySelector('.scrim')?.remove(); } }
    if(k.k==='open'&&k.dx>60) document.querySelector('[data-act="burger"]')?.click();
    g=null; });
})();

/* 4 · Toetsenbord: vensters passen zich aan de zichtbare hoogte aan */
(function(){ const vv=window.visualViewport; if(!vv) return;
  const set=()=>{ document.documentElement.style.setProperty('--vvh',vv.height+'px'); document.documentElement.classList.toggle('kb-open',MOB()&&vv.height<innerHeight*0.78); };
  vv.addEventListener('resize',set); set();
  document.addEventListener('focusin',e=>{ if(!MOB()) return; const f=e.target; if(!f.matches||!f.matches('input,textarea,select')) return; setTimeout(()=>{ if(f.closest('.modal,.nv-panel')) f.scrollIntoView({block:'center',behavior:'smooth'}); },300); });
})();

/* 5 · Invoervelden: juiste mobiele toetsenborden */
function mobileInputs(root){ (root||document).querySelectorAll('input[type=number]:not([inputmode])').forEach(i=>i.setAttribute('inputmode',(i.step&&!/^\d+$/.test(i.step))||!i.step?'decimal':'numeric'));
  (root||document).querySelectorAll('input[name=mail]:not([type=email]),input[name=email]:not([type=email])').forEach(i=>{ i.type='email'; i.autocomplete='email'; });
  (root||document).querySelectorAll('input[name=tel]:not([type=tel])').forEach(i=>{ i.type='tel'; i.autocomplete='tel'; });
  const nv=document.getElementById('nvin'); if(nv){ nv.setAttribute('enterkeyhint','send'); }
  const gs=document.getElementById('gsearch'); if(gs){ gs.setAttribute('enterkeyhint','search'); gs.setAttribute('inputmode','search'); } }
const _modalR8=modal; modal=function(...a){ _modalR8(...a); mobileInputs($('#layer')); };

/* Hint voor slepen op touchscreens */
function dragHint(){ if(!COARSE()) return; document.querySelectorAll('#view .kb').forEach(kb=>{ if(kb.previousElementSibling&&kb.previousElementSibling.classList.contains('t-hint')) return; kb.insertAdjacentHTML('beforebegin',`<p class="t-hint">${ic('kanban')}Houd een kaart even ingedrukt om hem naar een andere kolom te slepen.</p>`); }); }

/* 6 · Installeren als app */
let _bip=null; window.addEventListener('beforeinstallprompt',e=>{ e.preventDefault(); _bip=e; });
