/* Na elke render: sectietabs, laatste tab onthouden, klantportaal-melding */
const _renderR10=render; render=function(...a){ const res=_renderR10.apply(this,a); const r=route();
  const s=sectionOf(r); if(s&&s.r.some(([x])=>x===secKey(r))) UI.secLast[s.id]=secKey(r);
  const tabs=secTabs(r); if(tabs&&!document.querySelector('#view .sectabs')){ const pg=document.querySelector('#view .page'); (pg||$('#view')).insertAdjacentHTML('afterbegin',tabs); }
  if(r==='servicehub'&&!$('#hubsm')){ const pid=hubPid(); const ms=(S.service||[]).filter(m=>m.pid===pid); const pg=document.querySelector('#view .page'); const anchor=pg&&(pg.querySelector('.band')||pg.firstElementChild);
    if(anchor) anchor.insertAdjacentHTML('afterend',`<div class="card" id="hubsm" style="margin-top:16px"><div class="card-h"><h3>Service &amp; <em>garantie</em></h3><button class="btn sm pri" data-act="hub-melding">${ic('plus')}Melding doen</button></div><div class="card-b" style="padding-block:4px">${ms.length?ms.slice(0,4).map(m=>`<div class="li"><span class="ic ${m.status==='opgelost'?'ok':m.status==='ingepland'?'blue':'or'}">${ic('wrench')}</span><div class="tx"><b>${esc(m.titel)}</b><small>${m.nr} · ${fmtD(m.d)} · ${m.status==='nieuw'?'Ontvangen, we nemen contact op':m.status==='ingepland'?'Monteur ingepland':'Opgelost'}</small></div></div>`).join(''):`<div class="empty" style="padding:14px">Iets niet in orde na de oplevering? Doe hier een melding.</div>`}</div></div>`); }
  return res; };

/* Nova kent de nieuwe onderdelen */
const _novaR2R10=novaR2; novaR2=function(t){
  if(/nacalcul|begroot.*werkelijk/.test(t)){ const c=novaCtx(); const ps=c&&c.p.begroting?[c.p]:S.projects.filter(p=>p.begroting&&!p.lost&&p.phase>=4);
    novaSay(`<b>Nacalculatie</b><br>${ps.map(p=>{ const n=nacalc(p); return `• <a href="/project-${p.id.toLowerCase()}" data-act="nclose">${esc(p.naam)}</a>: verwacht ${eur0(n.tv)} tegenover ${eur0(n.tb)} begroot (${n.afw>0?'+':''}${NUM.format(Math.round(n.afw*10)/10)}%), marge ${pct(n.margeV)}`; }).join('<br>')}${leerpunten().length?`<br><br>Leerpunt: ${esc(leerpunten()[0].rol)} ${leerpunten()[0].afw>0?'boekt meer':'boekt minder'} uren dan de norm (${Math.round(leerpunten()[0].afw)}%).`:''}`); return true; }
  if(/service|melding|garantie|nazorg/.test(t)){ const o=(S.service||[]).filter(m=>m.status!=='opgelost'); novaSay(o.length?`<b>${o.length} open servicemeldingen</b><br>${o.map(m=>`• ${m.nr} ${esc(m.titel)} · ${esc((proj(m.pid)||{}).naam||'')} · ${m.status}`).join('<br>')}<br><a href="/nazorg" data-act="nclose">Naar nazorg</a>`:'Er staan geen open servicemeldingen.'); return true; }
  if(/verloren|waarom.*(mis|verlo)/.test(t)){ const ls=lostSummary(); novaSay(ls.n?`<b>${ls.n} verloren leads (${eur0(ls.waarde)})</b><br>${ls.by.map(([r,n])=>`• ${esc(r)}: ${n}`).join('<br>')}`:'Er zijn geen verloren leads geregistreerd.'); return true; }
  if(/eindafrekening|slottermijn/.test(t)){ const c=novaCtx(); const p=c&&c.p; if(!p||!p.offerte||p.offerte.status!=='geaccepteerd'){ novaSay('Open een dossier met een getekende offerte, dan reken ik de eindafrekening voor je door.'); return true; } const e=eindCalc(p); novaSay(`<b>Eindafrekening ${esc(p.naam)}</b><br>Aanneemsom ${eur(e.basis)} + meerwerk ${eur(e.meer)} − minderwerk ${eur(e.minder)} = ${eur(e.eind)} excl. btw.<br>Gefactureerd ${eur(e.gefact)}, slottermijn <b>${eur(e.slot)}</b>.${e.vijfBedrag?`<br>5%-regeling: ${eur(e.vijfBedrag)} incl. btw via ${e.v.regeling==='depot'?'notarisdepot':'bankgarantie'}.`:''}`); return true; }
  return _novaR2R10(t); };


/* ---------- Ronde 11 · Afwerking: sectiekleuren en leesbaarheid ---------- */
const _renderR11=render; render=function(...a){ const res=_renderR11.apply(this,a); const r=route(); const s=sectionOf(r);
  document.documentElement.dataset.sec=s?s.id:'';
  const ph=document.querySelector('#view .page > .ph, #view .page > .sectabs + .ph');
  if(s&&ph&&!ph.querySelector('.sec-eye')&&s.r.some(([x])=>x===secKey(r))&&s.id!=='vandaag'){ const h=ph.querySelector('h1'); if(h) h.insertAdjacentHTML('beforebegin',`<span class="sec-eye">${ic(s.i)}${s.l}</span>`); }
  return res; };


