const RUN_ST={queued:['mut','Gepland'],running:['blue','Bezig'],waiting_for_approval:['warn','Wacht op goedkeuring'],waiting_for_customer:['vio','Wacht op klant'],waiting_for_evidence:['or','Wacht op bewijs'],waiting_for_supplier:['vio','Wacht op leverancier'],waiting_for_technical_approval:['warn','Wacht op technische controle'],paused:['mut','Gepauzeerd'],human_takeover:['blue','Menselijk overgenomen'],completed:['ok','Afgerond'],failed:['bad','Mislukt'],cancelled:['mut','Geannuleerd']};
const ACTIVE_ST=['queued','running','waiting_for_approval','waiting_for_customer','waiting_for_evidence','waiting_for_supplier','waiting_for_technical_approval'];

/* ===== hulpfuncties ===== */
const nowTs=()=>`${TODAY}T${(typeof nowT==='function'?nowT():'09:00')}`;
function hashOf(o){ const s=JSON.stringify(o); let h=5381; for(let i=0;i<s.length;i++) h=((h<<5)+h+s.charCodeAt(i))|0; return 'h'+(h>>>0).toString(16); }
function agAv(id,sm){ const a=AG[id]||AG.nova; if(id==='nova') return `<span class="novaav ${sm?'sm':''} agav">${ic('spark')}</span>`; return `<span class="agav ${sm?'sm':''}" style="--ac:${a.kleur}" title="${a.naam} · ${a.spec}">${a.naam[0]}</span>`; }
function agName(id){ return (AG[id]||{naam:id}).naam; }
function runPill(st){ const x=RUN_ST[st]||['mut',st]; return `<span class="pill ${x[0]}">${x[1]}</span>`; }
function cfgSkill(id){ const c=(S.ai.cfg.skills[id]||{}); return {level:c.level||SK[id].level,paused:!!c.paused,limit:c.limit!=null?c.limit:SK[id].limit}; }

/* ===== event bus met idempotentie ===== */
function emit(type,payload,o={}){
  const ai=S.ai; if(o.idem){ if(ai.idem[o.idem]){ const dup={event_id:'evt_'+String(++ai.seq.ev).padStart(4,'0'),organization_id:ORG_ID,type:'duplicate.ignored',schema_version:1,occurred_at:nowTs(),actor:o.actor||'system',subject_id:o.subject||payload.project_id||'',correlation_id:o.corr||'',causation_id:ai.idem[o.idem],payload:{ignored_type:type,idempotency_key:o.idem}}; ai.audit.unshift(dup); return null; } }
  const ev={event_id:'evt_'+String(++ai.seq.ev).padStart(4,'0'),organization_id:ORG_ID,type,schema_version:1,occurred_at:nowTs(),actor:o.actor||'system',subject_id:o.subject||payload.project_id||'',correlation_id:o.corr||(payload.project_id?'corr_'+payload.project_id:''),causation_id:o.cause||null,payload};
  ai.audit.unshift(ev); if(o.idem) ai.idem[o.idem]=ev.event_id; return ev; }

/* ===== uitvoeringen ===== */
function startRun(o){ const ai=S.ai; const r={run_id:'run_'+String(++ai.seq.run).padStart(3,'0'),organization_id:ORG_ID,project_id:o.pid||null,agent:o.agent,skill:o.skill,sop_version:o.sop||null,status:o.status||'running',human_owner_role:o.owner||(AG[o.agent]||{}).rol,subject_version:o.version||1,evidence_refs:[],proposed_action:o.proposed||null,approval_required:!!o.approval,next_action:o.next||null,wacht:o.wacht||'',taak:o.taak||'',started:o.started||nowTs(),last:o.started||nowTs(),kosten:o.kosten!=null?o.kosten:0.02,resultaat:o.resultaat||'',steps:[{ts:o.started||nowTs(),t:o.note||'Uitvoering gestart'}]};
  ai.runs.unshift(r); emit('run.started',{project_id:r.project_id,run_id:r.run_id,agent:r.agent,skill:r.skill,status:r.status},{actor:'agent:'+r.agent}); return r; }
function setRun(r,patch,note){ if(!r) return; const old=r.status; Object.assign(r,patch); r.last=nowTs(); r.kosten=Math.round((r.kosten+0.01)*100)/100; if(note) r.steps.push({ts:nowTs(),t:note});
  emit('run.updated',{project_id:r.project_id,run_id:r.run_id,from:old,to:r.status,note:note||''},{actor:'agent:'+r.agent}); }
function runBy(pid,skill){ return S.ai.runs.find(r=>r.project_id===pid&&r.skill===skill&&r.status!=='cancelled'); }
/* Mag een agent nu handelen? (stopfuncties per organisatie, agent, skill en uitvoering) */
function guard(agent,skill,run){ const ai=S.ai; if(ai.cfg.stop) return 'Organisatiebrede stop is actief (Skills & SOP’s).'; if((ai.cfg.agents[agent]||{}).paused) return `${agName(agent)} is gepauzeerd.`; if(skill&&cfgSkill(skill).paused) return `Skill “${SK[skill].naam}” is gepauzeerd.`; if(run&&['human_takeover','paused','cancelled'].includes(run.status)) return `Uitvoering ${run.run_id} is ${RUN_ST[run.status][1].toLowerCase()}; de agent handelt niet meer zelf.`; return ''; }
function blocked(msg){ toast(msg,'warn'); return true; }

/* ===== goedkeuringen, gekoppeld aan exacte versie ===== */
function reqApproval(o){ const ai=S.ai; const a={id:'apr_'+String(++ai.seq.apr).padStart(3,'0'),run_id:o.run?o.run.run_id:null,pid:o.pid,action:o.action,label:o.label,role:o.role,version:o.version||1,hash:o.hash,amount:o.amount||0,created:nowTs(),expires:addDays(TODAY,o.days||7),status:'open',scope:o.scope||''};
  ai.approvals.unshift(a); if(o.run) setRun(o.run,{status:'waiting_for_approval',approval_required:true,next_action:'await_approval:'+a.id,wacht:`Goedkeuring ${o.role}`},`Goedkeuring gevraagd: ${o.label}`);
  emit('approval.requested',{project_id:o.pid,approval_id:a.id,action:a.action,version:a.version,hash:a.hash,role:a.role},{actor:o.run?'agent:'+o.run.agent:'system'}); return a; }
function decideApproval(a,ok,curHash,by){ if(a.status!=='open') return a.status;
  if(curHash&&curHash!==a.hash){ a.status='invalid'; emit('approval.invalidated',{project_id:a.pid,approval_id:a.id,reason:'Inhoud gewijzigd na verzoek',was:a.hash,now:curHash},{actor:'system'}); return 'invalid'; }
  if(a.expires<TODAY){ a.status='expired'; emit('approval.expired',{project_id:a.pid,approval_id:a.id}); return 'expired'; }
  a.status=ok?'approved':'rejected'; a.by=by||myName(); a.at=nowTs(); emit(ok?'approval.granted':'approval.rejected',{project_id:a.pid,approval_id:a.id,action:a.action,version:a.version,hash:a.hash},{actor:'user:'+(by||ME)}); return a.status; }
function invalidateApprovals(pid,action,reason){ for(const a of S.ai.approvals) if(a.pid===pid&&a.status==='open'&&(!action||a.action===action)){ a.status='invalid'; emit('approval.invalidated',{project_id:pid,approval_id:a.id,reason},{actor:'system'}); } }

/* ===== chat, taken, dossier: dezelfde status overal ===== */
function chFor(pid){ const ch=S.chat.channels.find(c=>c.pid===pid); return ch?ch.id:'algemeen'; }
function agentSay(pid,agent,txt,card){ S.chat.msgs.push({id:uid('m'),ch:chFor(pid),van:'nova',agent,txt,card:card||null,d:TODAY,tijd:nowT(),pinned:false,replies:[],att:null}); }
function humanSay(pid,emp,txt){ S.chat.msgs.push({id:uid('m'),ch:chFor(pid),van:emp,txt,d:TODAY,tijd:nowT(),pinned:false,replies:[],att:null}); }
function agentTask(pid,titel,eig,dl,run,prio){ const t={id:uid('t'),titel,pid,eig,dl:dl||addDays(TODAY,1),status:'todo',prio:prio||'normaal',oms:run?`Aangemaakt door ${agName(run.agent)} (${run.run_id})`:'',checklist:[],run:run?run.run_id:null}; S.tasks.push(t); emit('task.created',{project_id:pid,task_id:t.id,titel,eigenaar:eig},{actor:run?'agent:'+run.agent:'system'}); return t; }
function doneTasks(pid,match){ S.tasks.filter(t=>t.pid===pid&&t.status!=='afgerond'&&match(t)).forEach(t=>{ t.status='afgerond'; emit('task.completed',{project_id:pid,task_id:t.id,titel:t.titel}); }); }

/* agentberichten in de teamchat met naam en label */
const _chMsgHtmlR12=chMsgHtml; chMsgHtml=function(m,inThread){ let h=_chMsgHtmlR12(m,inThread); if(m.agent&&m.agent!=='nova'){ h=h.replace(/>Nova</,`>${agName(m.agent)} <span class="agtag">agent</span><`).replace(/<span class="novaav sm">[\s\S]*?<\/span>/,agAv(m.agent,true)); } else if(m.agent==='nova'){ h=h.replace(/>Nova</,'>Nova <span class="agtag">assistent</span><'); }
  if(m.card) h=h.replace(/(<div class="tx">[\s\S]*?<\/div>)/,`$1<div class="chcard">${m.card}</div>`); return h; };

/* ===== state ===== */
function ensureR12(st){
  if(!st) return st;
  if(!st.ai) st.ai={cfg:{skills:{},agents:{},stop:false},runs:[],approvals:[],audit:[],idem:{},incidents:[],tickets:[],cases:[],seq:{run:0,ev:0,apr:0,inc:0,var:0,ct:0,ho:0},flow:null};
  const ai=st.ai;
  if(!ai.seeded){ ai.seeded=1; const S0=S; S=st; try{
    const r1=startRun({agent:'lex',skill:'complete_intake',pid:'PD-2026-0046',sop:'lead_intake_v2',status:'waiting_for_customer',next:'await_customer_reply',wacht:'Klant: telefoonnummer en foto’s',taak:'Ontbrekende gegevens opvragen',started:'2026-10-29T10:12',kosten:0.04,note:'Ontbrekende intakegegevens opgevraagd via portaal (simulatie)'});
    const r2=startRun({agent:'prep',skill:'check_material_status',pid:'PD-2026-0041',sop:'material_v1',status:'waiting_for_approval',next:'await_order_approval',wacht:'Intern akkoord bestelling PO-2026-034',taak:'Sanitair bestellen',started:'2026-10-30T08:05',kosten:0.03,proposed:'place_order',approval:true,note:'Bestelling sanitair voorbereid; wacht op akkoord werkvoorbereider'});
    reqApproval({run:r2,pid:'PD-2026-0041',action:'place_order',label:'Bestelling PO-2026-034 sanitair (€ 1.845)',role:'Werkvoorbereider',hash:hashOf({po:'PO-2026-034',bedrag:1845}),amount:1845});
    startRun({agent:'finn',skill:'budget_forecast',pid:'PD-2026-0038',sop:null,status:'running',next:'daily_forecast',taak:'Budgetbewaking kavel 4-15',started:'2026-10-30T06:00',kosten:0.01,note:'Dagelijkse prognose bijgewerkt'});
    startRun({agent:'milo',skill:'propose_schedule_change',pid:'PD-2026-0039',sop:null,status:'queued',next:'resolve_conflict',wacht:'Gepland: maandag 07:00',taak:'Dubbele inzet Peter oplossen',started:'2026-10-30T07:40',kosten:0,note:'Conflict gesignaleerd, voorstel staat gepland'});
    const r5=startRun({agent:'liv',skill:'prepare_customer_update',pid:'PD-2026-0038',status:'failed',next:'manual_recovery',wacht:'Herstelwachtrij · eigenaar Hanneke Vos',taak:'Weekupdate Hendriks per mail',started:'2026-10-30T07:00',kosten:0.02,note:'Verzenden via mail mislukt: geen mailprovider gekoppeld. Niet als verzonden gemarkeerd.'});
    r5.resultaat='Mislukt — staat in herstelwachtrij';
    const r6=startRun({agent:'liv',skill:'triage_care_question',pid:'PD-2026-0034',sop:'care_v1',status:'completed',next:null,taak:'Vraag ventilatie badkamer',started:'2026-10-27T14:20',kosten:0.01,note:'Beantwoord met goedgekeurd FAQ-artikel “Ventileren na oplevering” (v3)'}); r6.resultaat='FAQ-antwoord gegeven, ticket gesloten na klantbevestiging';
  } finally { S=S0; } }
  /* flowproject */
  if(!st.projects.find(p=>p.id==='PD-2026-0051')) seedFlowProject(st);
  return st; }
function seedFlowProject(st){
  if(!st.clients.some(c=>c.id==='c40')) st.clients.push({id:'c40',naam:'Familie Visser-de Wit',soort:'Particulier',contact:'Anouk Visser',tel:'06 28 44 17 90',mail:'anouk.visser@voorbeeld.nl',plaats:'Utrecht'});
  const p={id:'PD-2026-0051',naam:'Badkamer Visser-de Wit',clientId:'c40',adres:'Oudegracht 210',plaats:'Utrecht',type:'Badkamerrenovatie',phase:1,leider:'hanneke',progress:0,planned:0,kleur:4,waarde:20000,
    termijnen:[{oms:'Aanbetaling bij opdracht',pct:30},{oms:'Na leidingwerk en tegelwerk',pct:60},{oms:'Bij oplevering',pct:10}],begroting:null,offerte:null,docs:[{naam:'Plattegrond 1e verdieping.pdf',cat:'Tekening',datum:'2026-10-27'}],activity:[{d:'2026-10-27',t:'Aanvraag via website: badkamer 1e verdieping, woning uit 1932',k:'mut'}],
    intake:{wensen:'Inloopdouche, dubbele wastafel, hangtoilet',budget:'€ 18.000 – 22.000'},kosten:0,minderwerk:[],wps:[],evidence:[],flow:true};
  st.projects.unshift(p);
  if(st.chat&&!st.chat.channels.some(c=>c.pid===p.id)) st.chat.channels.push({id:'p-0051',naam:'pd-0051-badkamer-visser',type:'project',pid:p.id,oms:'Projectkanaal Badkamer Visser-de Wit'});
  st.ai.flow={pid:p.id,step:0,done:{},
    fields:{type:{v:'Badkamerrenovatie',src:'klant',by:'Webformulier'},wensen:{v:'Inloopdouche, dubbele wastafel, hangtoilet',src:'klant',by:'E-mail 27 okt'},locatie:{v:'Oudegracht 210, Utrecht (1e verdieping, woning 1932)',src:'klant',by:'Webformulier'},budget:{v:'€ 18.000 – 22.000',src:'klant',by:'Webformulier'},tekening:{v:'Plattegrond 1e verdieping.pdf',src:'document',by:'Bijlage e-mail'},opname:{v:'Ja, leidingwerk onbekend',src:'medewerker',by:'Joris Kuipers'},afmetingen:{v:'',src:''},periode:{v:'',src:''},stopcontacten:{v:'',src:''}},
    conflict:null,calc:{},quote:{},pr:{},inc:{},wp:{offline:false,queue:[]},vr:{},ho:{},care:{},cs:{}};
}
