  S.pos=S.pos||[]; S.pos.push({nr:'PO-2026-040',lev:'Tegelhuis Amstel',pid,datum:TODAY,levering:'2026-11-13',status:'besteld',bevestigd:null,regels:[{oms:'Wandtegel 60×120 mat',q:24,u:'m2',p:64},{oms:'Vloertegel 60×60 antraciet',q:6,u:'m2',p:52}]},{nr:'PO-2026-041',lev:'Sanitairgroothandel Midden',pid,datum:TODAY,levering:'2026-11-17',status:'besteld',bevestigd:TODAY,regels:[{oms:'Wandcloset hangend randloos',q:1,u:'st',p:395},{oms:'Badmeubel 120 cm dubbel',q:1,u:'st',p:1450},{oms:'Thermostatische regendouche',q:1,u:'st',p:690}]});
