  agentTask(pid,'Voorbereidingschecklist doorlopen','fatima',addDays(TODAY,3),r); emit('gate.created',{project_id:pid,gate:'startgate_aanbetaling'},{actor:'agent:milo'}); agentSay(pid,'milo','Project aangemaakt uit getekende offerte v1: 6 werkpakketten, start 9 nov, oplevering 23 nov. Startgate: aanbetaling.');
