document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act="af"]'); if(!el||el.disabled) return; e.preventDefault(); afAction(el.dataset.a,el); });
document.addEventListener('change',e=>{ const t=e.target; if(t.dataset&&t.dataset.afup){ const fl=t.files&&t.files[0]; if(!fl) return; const rd=new FileReader(); rd.onload=()=>{ const im=new Image(); im.onload=()=>{ const c=document.createElement('canvas'); const sc=Math.min(1,640/im.width); c.width=im.width*sc; c.height=im.height*sc; c.getContext('2d').drawImage(im,0,0,c.width,c.height);
      const w=AFP().wps.find(x=>x.id==='WP3'); const k=w.have.includes('foto_leiding')?'foto_extra':'foto_leiding'; const r=addEvidence({k,naam:fl.name,img:c.toDataURL('image/jpeg',0.75),meta:`${fl.type} · ${Math.round(fl.size/1024)} kB · eigen upload`,voorstel:'WP3 · checklist “Leidingwerk vóór dichtzetten” · intern'}); if(r==='queued') toast('Op toestel bewaard: niet gesynchroniseerd','warn'); commit(); }; im.src=rd.result; }; rd.readAsDataURL(fl); }
  if(t.dataset&&t.dataset.afcase){ const f=AF(); if(t.dataset.afcase==='consent'){ f.cs.consent=t.checked; emit('publication.consent_recorded',{project_id:f.pid,consent:t.checked},{actor:'user:'+ME}); } else { const e=AFP().evidence.find(x=>x.id===t.dataset.id); e.pub=t.checked; } commit(); } });


