SECTIONS.splice(SECTIONS.findIndex(s=>s.id==='teamchat')+1,0,{g:'Werkdag',id:'agents',l:'Nova & agents',i:'spark',r:[['agents','Uitvoeringen'],['goedkeuringen','Goedkeuringen'],['audit','Audit'],['skills','Skills & SOP’s']]});
for(const rol in PERM){ const a=PERM[rol]; if(Array.isArray(a)&&a.includes('vandaag')){ for(const k of ['agents','goedkeuringen']) if(!a.includes(k)) a.push(k); } }
NAV.find(g=>g.g==='Werkdag')?.items.push(['agents','Nova & agents','spark']);
Object.assign(R2_ROUTES,{agentflow:()=>vAgents(), /* de demoflow met een fictief project draait niet in het echte systeem */agents:()=>vAgents(),goedkeuringen:()=>vApprovals(),audit:()=>vAudit(),skills:()=>vSkills()});

/* Signalen naar inbox: goedkeuringen, herstelwachtrij, incidenten */
const _attR12=attention; attention=function(){ const items=_attR12(); const ai=S.ai; if(!ai) return items;
  for(const a of ai.approvals.filter(a=>a.status==='open')){ const r=ai.runs.find(x=>x.run_id===a.run_id); items.push({k:'blue',icon:'lock',t:`Goedkeuring: ${a.label}`,s:`${a.role}${r?' · '+agName(r.agent):''} · verloopt ${fmtD(a.expires)}`,btn:'Beoordelen',go:'goedkeuringen'}); }
  for(const r of ai.runs.filter(r=>r.status==='failed')) items.push({k:'bad',icon:'alert',t:`Herstelwachtrij: ${r.taak}`,s:`${agName(r.agent)} · ${r.wacht}`,btn:'Bekijk',go:'agents'});
  for(const i of ai.incidents.filter(i=>i.status!=='opgelost')) items.push({k:'bad',icon:'alert',t:`${i.id}: ${i.titel}`,s:`Eigenaar ${i.eig} · deadline ${fmtD(i.dl)}`,btn:'Openen',go:'agentflow'});
  return items; };

/* ===== Uitvoeringen ===== */
function vAgents(){ const ai=S.ai; const f=UI.runF||'actief'; const all=ai.runs;
  const list=all.filter(r=>f==='alle'||(f==='actief'?ACTIVE_ST.includes(r.status):f==='mens'?['waiting_for_approval','waiting_for_technical_approval','human_takeover','paused'].includes(r.status):f==='fout'?r.status==='failed':['completed','cancelled'].includes(r.status)));
  const cnt=k=>all.filter(r=>k==='actief'?ACTIVE_ST.includes(r.status):k==='mens'?['waiting_for_approval','waiting_for_technical_approval','human_takeover','paused'].includes(r.status):k==='fout'?r.status==='failed':['completed','cancelled'].includes(r.status)).length;
  const kost=all.filter(r=>r.started.startsWith(TODAY)).reduce((s,r)=>s+r.kosten,0);
  return `<div class="page"><div class="ph"><div><h1>Agent<em>overzicht</em></h1><p>Wat elke agent doet, waar hij op wacht en wie beslist. “Wacht op klant” of “gepland” is niet hetzelfde als actief verwerken.</p></div>${ai.cfg.stop?`<span class="pill bad">${ic('lock')}Organisatiebrede stop actief</span>`:''}</div>
  <div class="grid kpis"><div class="card kpi dark"><span class="lbl">Actieve uitvoeringen</span><span class="v num">${cnt('actief')}</span><span class="s">${all.filter(r=>r.status==='running').length} bezig, de rest wacht</span></div>
  <div class="card kpi"><span class="lbl">Wacht op een mens</span><span class="v num">${cnt('mens')}</span><span class="s">${ai.approvals.filter(a=>a.status==='open').length} open goedkeuringen</span></div>
  <div class="card kpi"><span class="lbl">Herstelwachtrij</span><span class="v num">${cnt('fout')}</span><span class="s">mislukt, met menselijke eigenaar</span></div>
  <div class="card kpi"><span class="lbl">Modelkosten vandaag</span><span class="v num">${eur(kost)}</span><span class="s">werkelijke kosten van de uitvoeringen</span></div></div>
  <div class="agrid">${AGENTS.map(a=>{ const n=all.filter(r=>r.agent===a.id&&ACTIVE_ST.includes(r.status)).length; const pz=(ai.cfg.agents[a.id]||{}).paused; return `<div class="agcard ${pz?'pz':''}" style="--ac:${a.kleur}">${agAv(a.id)}<div><b>${a.naam}</b><small>${a.spec}</small><small class="muted">Eigenaar: ${esc(a.eigenaar)}</small></div><span class="pill ${n?'blue':'mut'}">${n} actief</span><button class="btn xs" data-act="agt-pause" data-id="${a.id}">${pz?'Hervatten':'Pauzeren'}</button></div>`; }).join('')}</div>
  <div class="chips ibx-f">${[['actief','Actief'],['mens','Wacht op mens'],['fout','Herstelwachtrij'],['klaar','Afgerond'],['alle','Alle']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="run-f" data-f="${k}">${l}<span>${k==='alle'?all.length:cnt(k)}</span></button>`).join('')}</div>
  <div class="card"><div class="tw"><table class="t runs"><thead><tr><th>Agent · skill</th><th>Project · taak</th><th>Status</th><th>Gestart · laatst</th><th>Volgende stap · wacht op</th><th class="r">Kosten</th><th>Resultaat</th><th></th></tr></thead><tbody>
  ${list.map(r=>{ const p=proj(r.project_id); return `<tr><td><div class="row" style="gap:8px">${agAv(r.agent,true)}<div><b>${agName(r.agent)}</b><div class="sub">${esc((SK[r.skill]||{naam:r.skill}).naam)}</div></div></div></td><td>${p?`<a href="/project-${p.id.toLowerCase()}">${esc(p.naam)}</a>`:'—'}<div class="sub">${esc(r.taak||'')}</div></td><td>${runPill(r.status)}</td><td class="num sub">${fmtD(r.started.slice(0,10))} ${r.started.slice(11)}<div>laatst ${r.last.slice(11)}</div></td><td><span class="mono sub">${esc(r.next_action||'—')}</span><div class="sub">${esc(r.wacht||'')}</div></td><td class="r num">${eur(r.kosten)}</td><td class="sub">${esc(r.resultaat||'')}</td>
  <td class="r"><button class="btn xs ${r.status==='failed'?'pri':''}" data-act="run-open" data-id="${r.run_id}">${r.status==='failed'?'Herstellen':'Beheren'}</button></td></tr>`; }).join('')||`<tr><td colspan="8"><div class="empty">Geen uitvoeringen in deze lijst.</div></td></tr>`}
  </tbody></table></div></div></div>`; }
function mRun(r){ const ev=S.ai.audit.filter(e=>e.payload.run_id===r.run_id||e.actor==='agent:'+r.agent&&e.subject_id===r.project_id).slice(0,8);
  modal(`Uitvoering ${r.run_id}`,`<div class="row" style="gap:10px;margin-bottom:10px">${agAv(r.agent)}<div><b>${agName(r.agent)} · ${esc(SK[r.skill]?SK[r.skill].naam:r.skill)}</b><div class="muted">${runPill(r.status)} ${r.sop_version?'· SOP '+r.sop_version:''}</div></div></div>
   <span class="lbl">Uitvoeringscontract</span><pre class="json">${esc(JSON.stringify({run_id:r.run_id,organization_id:r.organization_id,project_id:r.project_id,agent:agName(r.agent),skill:r.skill,sop_version:r.sop_version,status:r.status,human_owner_role:r.human_owner_role,subject_version:r.subject_version,evidence_refs:r.evidence_refs,proposed_action:r.proposed_action,approval_required:r.approval_required,next_action:r.next_action},null,2))}</pre>
   <span class="lbl">Stappen</span>${r.steps.map(s=>`<div class="li"><span class="ic mut">${ic('clock')}</span><div class="tx"><b>${esc(s.t)}</b><small>${s.ts.replace('T',' ')}</small></div></div>`).join('')}
   <span class="lbl">Audit</span>${ev.map(e=>`<div class="sm mono">${e.event_id} · ${e.type} · ${e.occurred_at.slice(11)}</div>`).join('')||'<div class="muted">—</div>'}
   <p class="muted" style="font-size:12px">Er wordt een korte beslissamenvatting bewaard, geen verborgen modelredenering of secrets.</p>`,`<button class="btn" data-act="mclose">Sluiten</button>${ACTIVE_ST.includes(r.status)||r.status==='paused'?`<button class="btn" data-act="run-pause" data-id="${r.run_id}">${r.status==='paused'?'Hervatten':'Pauzeren'}</button><button class="btn" data-act="run-take" data-id="${r.run_id}">Menselijk overnemen</button>`:''}${r.status==='failed'?`<button class="btn pri" data-act="run-recover" data-id="${r.run_id}">Handmatig afhandelen</button>`:''}`,true); }

/* ===== Goedkeuringen ===== */
function vApprovals(){ const ai=S.ai; const open=ai.approvals.filter(a=>a.status==='open'); const done=ai.approvals.filter(a=>a.status!=='open').slice(0,12);
  const st={approved:['ok','Goedgekeurd'],rejected:['bad','Afgewezen'],invalid:['bad','Vervallen (inhoud gewijzigd)'],expired:['mut','Verlopen'],open:['warn','Open']};
  const row=a=>{ const r=ai.runs.find(x=>x.run_id===a.run_id); const p=proj(a.pid); const flow=p&&p.flow; return `<div class="li"><span class="ic ${a.status==='open'?'blue':st[a.status][0]}">${ic('lock')}</span><div class="tx"><b>${esc(a.label)}</b><small>${p?esc(p.naam)+' · ':''}${esc(a.role)}${r?' · '+agName(r.agent)+' ('+r.run_id+')':''} · versie-hash <span class="mono">${a.hash}</span> · ${a.status==='open'?'verloopt '+fmtD(a.expires):st[a.status][1]+(a.by?' door '+esc(a.by):'')}</small></div><div class="acts">${a.status==='open'?(flow?`<a class="btn sm" href="/agentflow">Openen in flow</a>`:`<button class="btn sm ghost" data-act="apr-no" data-id="${a.id}">Afwijzen</button><button class="btn sm pri" data-act="apr-ok" data-id="${a.id}">Goedkeuren</button>`):`<span class="pill ${st[a.status][0]}">${st[a.status][1]}</span>`}</div></div>`; };
  return `<div class="page"><div class="ph"><div><h1>Goed<em>keuringen</em></h1><p>Elke goedkeuring hoort bij een exacte actieversie. Wijzigt de inhoud of het bedrag, dan vervalt de goedkeuring. Rechten en actuele toestand worden vlak vóór uitvoering opnieuw gecontroleerd.</p></div></div>
  <div class="card"><div class="card-h"><h3>Open</h3><span class="pill warn">${open.length}</span></div><div class="card-b" style="padding-block:4px">${open.map(row).join('')||`<div class="empty">${ic('check')}Niets te beoordelen.</div>`}</div></div>
  <div class="card"><div class="card-h"><h3>Recent besloten</h3></div><div class="card-b" style="padding-block:4px">${done.map(row).join('')||'<div class="empty">—</div>'}</div></div></div>`; }

