document.addEventListener('change',e=>{ const t=e.target; if(t.dataset&&t.dataset.odf){ if(t.dataset.odf==='vk') UI.odVk=t.value; else UI.odType=t.value; render(); } });
const _renderR13=render; render=function(...a){ const r=_renderR13.apply(this,a); if(route()==='servicehub'&&curRol()==='Klant'){ const p=proj(hubPid()); recordView(p); } return r; };
/* Nova kent het dashboard */
const _novaR2R13=novaR2; novaR2=function(t){ if(/offerte/.test(t)&&/(dashboard|hoeveel|geopend|scorings|conversie|hit ?rate|opdrachtwaarde)/.test(t)){ const s=odStats(odFilter(allOffers())); novaSay(`<b>Offertes dit jaar</b><br>${s.n} verzonden (${eur0(s.waarde)}), ${Math.round(s.openRate)}% geopend door de klant.<br>${s.won.length} getekend: <b>${eur0(s.wonW)}</b> opdrachtwaarde, scoringskans ${Math.round(s.hit)}% op aantal.<br>${s.open.length} open (${eur0(s.openW)}, gewogen ${eur0(s.gewogen)}).<br><a href="/offertedash" data-act="nclose">Naar offertedashboard</a>`); return true; } return _novaR2R13(t); };


/* ---------- Ronde 14 · Maandplanning (per vakman en per project) ---------- */
UI.planMonth=UI.planMonth||addDays(TODAY,7).slice(0,7); UI.planLens=UI.planLens||'emp';
const MND=['januari','februari','maart','april','mei','juni','juli','augustus','september','oktober','november','december'];
function monthDays(ym){ const [y,m]=ym.split('-').map(Number); const out=[]; let d=`${ym}-01`; while(d.slice(0,7)===ym){ if(!isWeekend(d)) out.push(d); d=addDays(d,1); } return out; }
function shiftMonth(ym,n){ let [y,m]=ym.split('-').map(Number); m+=n; while(m>12){ m-=12; y++; } while(m<1){ m+=12; y--; } return `${y}-${String(m).padStart(2,'0')}`; }
function wkNo(d){ return isoWeek(d); }
function placeBars(bl,dates){ const first=dates[0], last=dates[dates.length-1]; const lanes=[];
  return bl.slice().sort((a,b)=>a.start<b.start?-1:1).map(b=>{ const s=b.start<first?first:b.start, e=b.end>last?last:b.end; let c0=dates.findIndex(d=>d>=s); let c1=-1; dates.forEach((d,i)=>{ if(d<=e) c1=i; }); if(c0<0||c1<c0) return null; let lane=0; while(lanes[lane]!=null&&lanes[lane]>=c0) lane++; lanes[lane]=c1; return {b,c0,c1,lane,cutL:b.start<first,cutR:b.end>last}; }).filter(Boolean); }
function vPlanMaand(){ const ym=UI.planMonth, dates=monthDays(ym), n=dates.length; const [y,m]=ym.split('-').map(Number); const cids=confIds();
  const weeks=[]; dates.forEach((d,i)=>{ const w=monday(d); const last=weeks[weeks.length-1]; if(last&&last.w===w) last.n++; else weeks.push({w,i,n:1}); });
  const head=`<div class="mg-row mg-head"><div class="mg-lab"></div>${weeks.map(w=>`<button class="mg-wk ${w.w===UI.planWeek?'sel':''}" style="grid-column:${w.i+2} / span ${w.n}" data-act="mg-week" data-w="${w.w}" title="Open week ${wkNo(w.w)}">wk ${wkNo(w.w)}</button>`).join('')}</div>
    <div class="mg-row mg-days"><div class="mg-lab"></div>${dates.map((d,i)=>`<div class="mg-d ${d===TODAY?'today':''} ${monday(d)===UI.planWeek?'insel':''}" style="grid-column:${i+2}"><small>${['zo','ma','di','wo','do','vr','za'][new Date(d+'T12:00').getDay()]}</small><b>${+d.slice(8)}</b></div>`).join('')}</div>`;
  const cells=(extra)=>dates.map((d,i)=>`<div class="mg-c ${d===TODAY?'today':''} ${monday(d)===UI.planWeek?'insel':''}" style="grid-column:${i+2};grid-row:1 / span ${extra}"></div>`).join('');
  let rows='';
  if(UI.planLens==='emp'){
    for(const e of PLANNABLE()){ const bl=S.blocks.filter(b=>b.emp===e.id&&b.end>=dates[0]&&b.start<=dates[n-1]); const pl=placeBars(bl,dates); const lanes=Math.max(1,...pl.map(x=>x.lane+1)); const hrs=bl.reduce((s,b)=>{ const a=b.start<dates[0]?dates[0]:b.start, z=b.end>dates[n-1]?dates[n-1]:b.end; return s+workdays(a,z)*8; },0); const cap=Math.round(e.cap*n/5); const load=cap?hrs/cap:0;
      rows+=`<div class="mg-row" style="grid-template-rows:repeat(${lanes},26px)"><div class="mg-lab" style="grid-row:1 / span ${lanes}">${avatar(e.naam,'sm')}<div><b>${esc(e.naam.split(' ')[0])}</b><small>${esc(e.rol)}</small></div><span class="mg-load ${load>1?'over':load>0.85?'full':''}" title="${hrs} van ${cap} uur">${Math.round(load*100)}%</span></div>${cells(lanes)}
      ${pl.map(x=>{ const p=proj(x.b.pid)||{naam:'Intern',kleur:0}; return `<div class="mg-bar pc${p.kleur%6} ${cids.has(x.b.id)?'conf':''} ${x.cutL?'cl':''} ${x.cutR?'cr':''}" data-act="editblock" data-id="${x.b.id}" style="grid-column:${x.c0+2} / ${x.c1+3};grid-row:${x.lane+1}" title="${esc(p.naam+' · '+x.b.titel+' · '+fmtD(x.b.start)+' – '+fmtD(x.b.end))}">${esc(p.naam)}</div>`; }).join('')}</div>`; }
    /* bezetting per dag */
    const tot=PLANNABLE().length; rows+=`<div class="mg-row mg-cap"><div class="mg-lab"><b>Bezetting</b><small>vakmensen ingepland</small></div>${dates.map((d,i)=>{ const k=new Set(S.blocks.filter(b=>b.start<=d&&d<=b.end&&PLANNABLE().some(e=>e.id===b.emp)).map(b=>b.emp)).size; const r=tot?k/tot:0; return `<div class="mg-cc" style="grid-column:${i+2};--o:${(0.12+r*0.88).toFixed(2)}" title="${fmtD(d)}: ${k} van ${tot} ingepland"><span>${k}</span></div>`; }).join('')}</div>`;
  } else {
    const ps=S.projects.filter(p=>!p.lost&&(S.blocks.some(b=>b.pid===p.id&&b.end>=dates[0]&&b.start<=dates[n-1])||(p.start&&p.eind&&p.start<=dates[n-1]&&p.eind>=dates[0]))).sort((a,b)=>(a.start||'9')<(b.start||'9')?-1:1);
    for(const p of ps){ const bl=S.blocks.filter(b=>b.pid===p.id&&b.end>=dates[0]&&b.start<=dates[n-1]); const pl=placeBars(bl,dates); const lanes=Math.max(1,...pl.map(x=>x.lane+1));
      const ms=[[p.start,'Start','▶'],[p.eind,'Oplevering','◆']].filter(([d])=>d&&d>=dates[0]&&d<=dates[n-1]).map(([d,l,s])=>{ let i=dates.indexOf(d); if(i<0) i=dates.findIndex(x=>x>d)-1; return i>=0?`<span class="mg-ms ${l==='Oplevering'?'end':''}" style="grid-column:${i+2};grid-row:1" title="${l} ${fmtD(d)}">${s}</span>`:''; }).join('');
      const behind=p.phase===6&&p.planned-p.progress>=5;
      rows+=`<div class="mg-row" style="grid-template-rows:repeat(${lanes},26px)"><a class="mg-lab" href="/project-${p.id.toLowerCase()}" style="grid-row:1 / span ${lanes}"><span class="mg-dot pc${p.kleur%6}"></span><div><b>${esc(p.naam)}</b><small>${PHASES[p.phase]} · ${p.progress||0}%${behind?' · <span class="dn">achter</span>':''}</small></div></a>${cells(lanes)}
      ${pl.map(x=>`<div class="mg-bar pc${p.kleur%6} ${cids.has(x.b.id)?'conf':''} ${x.cutL?'cl':''} ${x.cutR?'cr':''}" data-act="editblock" data-id="${x.b.id}" style="grid-column:${x.c0+2} / ${x.c1+3};grid-row:${x.lane+1}" title="${esc(x.b.titel+' · '+empName(x.b.emp)+' · '+fmtD(x.b.start)+' – '+fmtD(x.b.end))}">${esc(firstName(x.b.emp))} · ${esc(x.b.titel)}</div>`).join('')}${ms}</div>`; }
    if(!ps.length) rows=`<div class="empty">Geen projecten met planning in deze maand.</div>`;
  }
  const cfM=conflicts().filter(c=>c.day>=dates[0]&&c.day<=dates[n-1]);
  return `<div class="page"><div class="ph"><div><h1>Planning &amp; <em>capaciteit</em></h1><p>Maandoverzicht. Klik op een week om die week te openen, of op een blok om het te bewerken.</p></div>
    <div class="acts">${planSeg()}<button class="btn pri" data-act="newblock">${ic('plus')}Inplannen</button></div></div>
  <div class="card"><div class="card-h mg-tools"><div class="row" style="gap:6px"><button class="iconbtn" data-act="mg-m" data-d="-1" aria-label="Vorige maand">${ic('chevl')}</button><h3 style="min-width:150px;text-align:center">${MND[m-1]} ${y}</h3><button class="iconbtn" data-act="mg-m" data-d="1" aria-label="Volgende maand">${ic('chev')}</button><button class="btn sm ghost" data-act="mg-m" data-d="0">Deze maand</button></div>
    <div class="row" style="gap:8px;flex-wrap:wrap">${cfM.length?`<span class="pill bad">${ic('alert')}${cfM.length} ${cfM.length===1?'conflict':'conflicten'}</span>`:'<span class="pill ok">Geen conflicten</span>'}<div class="seg"><button class="${UI.planLens==='emp'?'on':''}" data-act="mg-lens" data-v="emp">Per vakman</button><button class="${UI.planLens==='proj'?'on':''}" data-act="mg-lens" data-v="proj">Per project</button></div></div></div>
    <div class="mg-wrap"><div class="mg" style="--n:${n}">${head}${rows}</div></div>
    ${UI.planLens==='proj'?`<div class="card-b mg-leg"><span>▶ start</span><span>◆ oplevering</span><span><i class="conf-i"></i>dubbel ingepland</span></div>`:`<div class="card-b mg-leg"><span><b>%</b> = ingeplande uren t.o.v. capaciteit deze maand</span><span><i class="conf-i"></i>dubbel ingepland</span></div>`}</div></div>`; }
function planSeg(){ return `<div class="seg">${[['week','Week'],['2w','2 weken'],['maand','Maand'],['cap','Capaciteit']].map(([k,l])=>`<button class="${UI.planView===k?'on':''}" data-act="pview" data-v="${k}">${l}</button>`).join('')}</div>`; }
/* bestaande weekweergave: knop Maand toevoegen */
const _vPlanningR14=vPlanning; vPlanning=function(){ if(UI.planView==='maand') return vPlanMaand(); let h=_vPlanningR14(); return h.replace(/(<button[^>]*data-v="2w"[^>]*>2 weken<\/button>)/,'$1<button class="" data-act="pview" data-v="maand">Maand</button>'); };
const _r2RouteR14=r2Route; r2Route=function(r){ if(r==='planning'&&UI.planView==='maand'&&allowed(curRol(),'planning')) return vPlanMaand(); return _r2RouteR14(r); };
document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act, d=el.dataset;
  if(a==='mg-m'){ UI.planMonth=d.d==='0'?TODAY.slice(0,7):shiftMonth(UI.planMonth,+d.d); render(); }
  else if(a==='mg-lens'){ UI.planLens=d.v; render(); }
  else if(a==='mg-week'){ UI.planWeek=d.w; UI.planView='week'; render(); }
  else if(a==='pview'&&d.v==='maand'){ UI.planMonth=addDays(UI.planWeek||TODAY,14).slice(0,7); }
},true);
/* mobiel: dagweergave krijgt een knop naar het maandoverzicht */
const _renderR14=render; render=function(...a){ const r=_renderR14.apply(this,a); if(route()==='planning'&&UI.planView!=='maand'&&matchMedia('(max-width: 900px)').matches&&!$('#mgbtn')){ const ph=document.querySelector('#view .page > .ph'); if(ph) ph.insertAdjacentHTML('beforeend',`<button class="btn" id="mgbtn" data-act="pview" data-v="maand">${ic('cal')}Maandoverzicht</button>`); } return r; };


/* ---------- Ronde 15 · Certificaten met kleurcodes en aanvinklijsten ---------- */
const CERT_CAT=[
  ['VCA-basis','VCA','#E49B16',10,'Veiligheid basis'],['VCA-VOL','VOL','#C2500C',10,'Veiligheid leidinggevende'],['BHV','BHV','#D23A3F',1,'Bedrijfshulpverlening'],['EHBO','EHBO','#1E8A5A',1,'Eerste hulp'],
  ['NEN 3140 (VOP)','NEN','#3E6BA8',3,'Elektrisch werken'],['Erkend gasinstallateur','GAS','#2B8C8C',5,'Gasinstallaties'],['Valbeveiliging','VAL','#7C5CD6',2,'Werken op hoogte'],['Hoogwerker','HW','#0E8FC2',5,'Hoogwerker bedienen'],
  ['DAV asbest','ASB','#64748B',3,'Asbestverwijdering'],['Rijbewijs BE','BE','#8B5E3C',10,'Aanhanger'],['Wkb-kwaliteitsborger','WKB','#C2506D',3,'Kwaliteitsborging']];
const CERT_BY=Object.fromEntries(CERT_CAT.map(c=>[c[0],c]));
const LANGS=['NL','EN','DE','PL','TR','AR','FR','RO'];
function certMeta(t){ return CERT_BY[t]||CERT_CAT.find(c=>t&&t.toLowerCase().startsWith(c[0].toLowerCase().split(' ')[0])&&t.toLowerCase().includes(c[1].toLowerCase()))||[t,(t||'?').replace(/[^A-Z0-9]/g,'').slice(0,4)||t.slice(0,3).toUpperCase(),'#8A95A8',3,'']; }
function certChip(c,sm){ const m=certMeta(c.t); const st=c.g?certState(c):'ok'; return `<span class="cchip ${sm?'sm':''} st-${st}" style="--cc:${m[2]}" title="${esc(c.t)}${c.g?' · '+(st==='verlopen'?'verlopen ':'geldig t/m ')+fmtDY(c.g):''}"><i>${esc(m[1])}</i>${sm?'':esc(c.t)}${st==='binnenkort'?' ⏱':''}${st==='verlopen'?' ✕':''}</span>`; }
function ensureR15(st){ if(!st) return st; if(!st.r15c){ st.r15c=1; const add=(id,t,g)=>{ const e=st.emps.find(x=>x.id===id); if(!e) return; e.certs=e.certs||[]; if(!e.certs.some(c=>c.t===t)) e.certs.push({t,g}); };
  add('klaas','EHBO','2027-03-15'); add('rob','EHBO','2026-11-20'); add('mehmet','EHBO','2027-05-01'); add('bram','Valbeveiliging','2026-11-20'); add('thomas','Rijbewijs BE','2031-02-01'); add('klaas','Wkb-kwaliteitsborger','2028-06-01'); }
  return st; }
/* demomigratie overgeslagen: de structuur staat in de fabrieksstaat */ const _seedR13c=ensureR2; ensureR2=function(st){ return ensureR15(_seedR13c(st)); };

/* Profielvenster: aanvinklijsten voor certificaten, specialismen en talen */
function certPanel(e){ const has=t=>(e.certs||[]).find(c=>c.t===t); const extra=(e.certs||[]).filter(c=>!CERT_BY[c.t]);
  return `<div class="ctog" data-emp="${e.id}">${[...CERT_CAT.map(c=>c[0]),...extra.map(c=>c.t)].map(t=>{ const c=has(t); const m=certMeta(t); const st=c&&c.g?certState(c):'ok';
    return `<div class="ct ${c?'on':''} st-${c?st:'off'}" style="--cc:${m[2]}"><label class="ct-l"><input type="checkbox" data-cert="${esc(t)}" ${c?'checked':''}><span class="ct-b">${esc(m[1])}</span><span class="ct-t"><b>${esc(t)}</b><small>${esc(m[4]||'')}</small></span></label>
      ${c?`<span class="ct-d"><input type="date" class="in sm" data-certdate="${esc(t)}" value="${c.g||''}" aria-label="Geldig tot ${esc(t)}"><small class="${st==='verlopen'?'dn':st==='binnenkort'?'wn':'ok'}">${st==='verlopen'?'Verlopen':st==='binnenkort'?'Verloopt binnenkort':'Geldig'}</small></span>`:''}</div>`; }).join('')}</div>`; }
function tagPanel(name,all,sel){ return `<div class="tagtog" data-tagfor="${name}">${all.map(t=>`<button type="button" class="tt ${sel.includes(t)?'on':''}" data-tag="${esc(t)}" aria-pressed="${sel.includes(t)}">${sel.includes(t)?'✓ ':''}${esc(t)}</button>`).join('')}<input type="hidden" name="${name}" value="${esc(sel.join(', '))}"></div>`; }
const _modalR15=modal; modal=function(...a){ _modalR15(...a); const f=document.querySelector('#layer form[data-form="person"]'); if(!f) return; const e=emp(f.dataset.id); if(!e) return;
  const allSpecs=[...new Set([...S.emps.flatMap(x=>x.specs||[]),'Tegelwerk','Timmerwerk','Loodgieterswerk','Elektra','Stucwerk','Schilderwerk','Dakwerk','Badkamers','Keukens','Kozijnen'])].sort();
  const sp=f.querySelector('#p-specs'); if(sp) sp.closest('.f').innerHTML=`<label>Specialismen</label>${tagPanel('specs',allSpecs,e.specs||[])}`;
  const tl=f.querySelector('#p-talen'); if(tl) tl.closest('.f').innerHTML=`<label>Gesproken talen</label>${tagPanel('talen',[...new Set([...LANGS,...(e.talen||[])])],e.talen||[])}`;
  const lbl=[...document.querySelectorAll('#layer .lbl')].find(x=>x.textContent==='Certificaten'); if(lbl){ const box=lbl.parentElement; box.innerHTML=`<span class="lbl">Certificaten <small class="muted" style="text-transform:none;letter-spacing:0;font-weight:500">vink aan wat iemand heeft</small></span>${certPanel(e)}`; } };
document.addEventListener('click',ev=>{ const b=ev.target.closest&&ev.target.closest('.tagtog .tt'); if(!b) return; b.classList.toggle('on'); const on=b.classList.contains('on'); b.setAttribute('aria-pressed',on); b.textContent=(on?'✓ ':'')+b.dataset.tag; const box=b.closest('.tagtog'); box.querySelector('input[type=hidden]').value=[...box.querySelectorAll('.tt.on')].map(x=>x.dataset.tag).join(', '); });
document.addEventListener('change',ev=>{ const t=ev.target; if(!t.dataset) return; const box=t.closest&&t.closest('.ctog'); if(!box) return; const e=emp(box.dataset.emp); e.certs=e.certs||[];
  if(t.dataset.cert){ const name=t.dataset.cert; if(t.checked){ if(!e.certs.some(c=>c.t===name)) e.certs.push({t:name,g:addDays(TODAY,365*certMeta(name)[3])}); } else e.certs=e.certs.filter(c=>c.t!==name); }
  if(t.dataset.certdate){ const c=e.certs.find(c=>c.t===t.dataset.certdate); if(c) c.g=t.value; }
  save(); box.outerHTML=certPanel(e); toast(t.dataset.cert?(t.checked?`${t.dataset.cert} toegevoegd`:`${t.dataset.cert} verwijderd`):'Geldigheid bijgewerkt'); });

/* Kleurchips overal waar certificaten verschijnen */
const _renderR15c=render; render=function(...a){ const r=_renderR15c.apply(this,a); const rt=route();
  if(rt==='workforce'){ document.querySelectorAll('#view .card.person').forEach(cd=>{ const e=emp(cd.dataset.id); if(!e||cd.querySelector('.cchips')||!(e.certs||[]).length) return; const ch=cd.querySelector('.chips'); (ch||cd).insertAdjacentHTML('afterend',`<div class="cchips">${e.certs.map(c=>certChip(c,true)).join('')}</div>`); });
    document.querySelectorAll('#view table.t tbody tr td:first-child b').forEach(b=>{ if(b.closest('td').querySelector('.cchip')) return; const t=b.textContent; if(CERT_BY[t]||certMeta(t)[2]!=='#8A95A8') b.insertAdjacentHTML('beforebegin',certChip({t},true)+' '); });
    const ph=document.querySelector('#view .page > .ph'); if(ph&&!$('#cleg')) ph.insertAdjacentHTML('afterend',`<div class="cleg" id="cleg">${CERT_CAT.map(c=>`<span class="cchip sm" style="--cc:${c[2]}" title="${c[0]}"><i>${c[1]}</i></span><small>${c[0]}</small>`).join('')}</div>`); }
  if(rt==='planning'&&UI.planView==='maand'&&UI.planLens==='emp') document.querySelectorAll('#view .mg-row').forEach(row=>{ });
  return r; };
/* maandplanning: certificaatstipjes per vakman */
const _vPlanMaandR15=vPlanMaand; vPlanMaand=function(){ let h=_vPlanMaandR15().replace(/grid-template-rows:repeat\(1,26px\)/g,'grid-template-rows:repeat(1,40px)'); if(UI.planLens!=='emp') return h;
  for(const e of PLANNABLE()){ if(!(e.certs||[]).length) continue; const short=esc(e.naam.split(' ')[0]); const dots=e.certs.map(c=>{ const m=certMeta(c.t), st=c.g?certState(c):'ok'; return `<i class="cd st-${st}" style="--cc:${m[2]}" title="${esc(c.t)}${st==='verlopen'?' · verlopen':st==='binnenkort'?' · verloopt binnenkort':''}"></i>`; }).join('');
    h=h.replace(`<b>${short}</b><small>${esc(e.rol)}</small>`,`<b>${short}<span class="cdl">${dots}</span></b><small>${esc(e.rol)}</small>`); }
  return h; };


/* ---------- Ronde 15 · Teamchat in WhatsApp-stijl: bubbels, citeren, reacties, selecteren → taak ---------- */
/* ME staat bovenaan: de ingelogde gebruiker */
const WA_COL=['#C2500C','#3863A0','#1A7D51','#7C5CD6','#C2506D','#0E8FC2','#A86A06','#2B8C8C','#8B5E3C','#D23A3F'];
const waCol=id=>{ let h=0; for(const ch of String(id)) h=(h*31+ch.charCodeAt(0))>>>0; return WA_COL[h%WA_COL.length]; };
const waName=m=>m.agent?agName(m.agent):m.van==='nova'?'Nova':m.van==='klant'?(m.klantNaam||'Klant'):empName(m.van)||m.van;
function waMine(m,isK){ return isK?m.van!=='klant':m.van===ME; }
function waPreview(id){ const ms=chMsgs(id); const m=ms[ms.length-1]; if(!m) return {t:'Nog geen berichten',d:''}; const who=waMine(m,id.startsWith('klant-'))?'Jij':waName(m).split(' ')[0]; return {t:`${who}: ${String(m.txt).replace(/[*_]/g,'').slice(0,60)}`,d:m.d===TODAY?m.tijd:fmtD(m.d),m}; }
function waAvatar(c){ if(c.type==='klant') return `<span class="wa-av" style="--ac:#7C5CD6">${ic('home')}</span>`; if(c.type==='project'){ const p=proj(c.pid); return `<span class="wa-av pc${p?p.kleur%6:0}">${ic('folder')}</span>`; } if(c.type==='team') return `<span class="wa-av" style="--ac:#2B8C8C">${ic('team')}</span>`; return `<span class="wa-av" style="--ac:#3E6BA8">${ic('hash')}</span>`; }
function waMembers(c,msgs){ const ids=[...new Set(msgs.map(m=>m.agent?agName(m.agent):m.van==='nova'?'Nova':m.van==='klant'?(m.klantNaam||'Klant'):firstName(m.van)))]; return ids.slice(0,5).join(', ')+(ids.length>5?` +${ids.length-5}`:''); }
function waFindMsg(id){ return S.chat.msgs.find(x=>x.id===id)||(UI.chCur?chMsgs(UI.chCur).find(x=>x.id===id):null); }
function waBubble(m,isK,prev){ const mine=waMine(m,isK); const cont=prev&&prev.van===m.van&&prev.agent===m.agent&&prev.d===m.d; const sel=UI.waSel&&UI.waSel.includes(m.id); const q=m.reply&&waFindMsg(m.reply);
  const t=m.task&&S.tasks.find(x=>x.id===m.task); const rx=m.reacts?Object.entries(m.reacts).filter(([,v])=>v.length):[];
  if(m.sys) return `<div class="wa-sys">${m.txt}</div>`;
  return `<div class="wa-m ${mine?'me':'them'} ${cont?'cont':''} ${sel?'sel':''} ${UI.waSel?'selmode':''}" data-wamsg="${m.id}">
    ${UI.waSel?`<span class="wa-ck">${sel?ic('check'):''}</span>`:''}
    <div class="wa-b">${!mine&&!cont?`<b class="wa-n" style="color:${m.agent||m.van==='nova'?'#E8590C':waCol(m.van)}">${esc(waName(m))}${m.agent||m.van==='nova'?' <span class="agtag">'+(m.agent&&m.agent!=='nova'?'agent':'assistent')+'</span>':''}${m.van==='klant'?' <span class="agtag">klant</span>':''}</b>`:''}
      ${q?`<div class="wa-q" style="--qc:${waCol(q.van)}"><b>${esc(waName(q))}</b><span>${esc(String(q.txt).replace(/[*_]/g,'').slice(0,90))}</span></div>`:''}
      <div class="wa-t">${fmtChat(m.txt)}</div>
      ${m.card?`<div class="chcard">${m.card}</div>`:''}
      ${m.att?`<span class="wa-att">${ic('clip2')}${esc(m.att)}</span>`:''}
      ${t?`<button class="wa-task ${t.status==='afgerond'?'done':''}" data-act="wa-taskopen" data-id="${t.id}">${ic(t.status==='afgerond'?'check':'checksq')}Taak: ${esc(t.titel)} · ${esc(firstName(t.eig)||'—')} · ${t.status==='afgerond'?'afgerond':t.dl?fmtD(t.dl):'open'}</button>`:''}
      ${m.pdLinked?`<span class="wa-tag">${ic('folder')}${m.pdLinked}</span>`:''}${m.pinned?`<span class="wa-tag pin">${ic('pinned')}vastgezet</span>`:''}
      <span class="wa-time">${m.tijd||''}${mine&&!isK?`<i class="wa-tick ${chMsgs(m.ch).some(x=>x.d+x.tijd>m.d+m.tijd&&x.van!==ME)?'read':''}">✓✓</i>`:''}</span>
      ${rx.length?`<span class="wa-rx">${rx.map(([e,v])=>`<button data-act="wa-react" data-id="${m.id}" data-e="${e}" title="${v.map(x=>empName(x)||x).join(', ')}">${e}${v.length>1?' '+v.length:''}</button>`).join('')}</span>`:''}
      ${m.replies&&m.replies.length?`<button class="wa-thr" data-act="ch-thread" data-id="${m.id}">${m.replies.length} ${m.replies.length===1?'reactie':'reacties'} in thread</button>`:''}
    </div>
    ${UI.waSel?'':`<div class="wa-acts" role="toolbar" aria-label="Acties bij bericht">${['👍','✅','👀'].map(e=>`<button data-act="wa-react" data-id="${m.id}" data-e="${e}" aria-label="Reageer ${e}">${e}</button>`).join('')}<button data-act="wa-reply" data-id="${m.id}" title="Citeren en antwoorden" aria-label="Antwoorden">${ic('reply')}</button><button data-act="wa-task1" data-id="${m.id}" title="Taak maken" aria-label="Taak maken">${ic('checksq')}</button><button data-act="ch-pin" data-id="${m.id}" title="Vastzetten" aria-label="Vastzetten">${ic('pinned')}</button>${!isK?`<button data-act="ch-link" data-id="${m.id}" title="Koppel aan dossier" aria-label="Koppel aan dossier">${ic('link')}</button>`:''}</div>`}
  </div>`; }

vTeamchat=function(){ const {base,klant}=chChannels(); const all=[...base,...klant.map(c=>({...c,type:'klant'}))]; let cur=UI.chCur||'uitv'; let ch=all.find(c=>c.id===cur); if(!ch){ cur=UI.chCur='algemeen'; ch=all.find(c=>c.id===cur); }
  const isK=cur.startsWith('klant-'); S.chat.read[cur]=chMsgs(cur).length; const msgs=chMsgs(cur); const thr=UI.chThread&&S.chat.msgs.find(m=>m.id===UI.chThread);
  const f=UI.waF||'alle', q=(UI.waQ||'').toLowerCase();
  const list=all.filter(c=>(f==='alle'||(f==='ongelezen'?unread(c.id):f==='projecten'?c.type==='project':f==='klanten'?c.type==='klant':c.type==='team'||c.type==='algemeen'||c.type==='afdeling'))&&(!q||c.naam.toLowerCase().includes(q)||chMsgs(c.id).some(m=>String(m.txt).toLowerCase().includes(q))))
    .map(c=>({c,p:waPreview(c.id)})).sort((a,b)=>{ const ka=a.p.m?a.p.m.d+a.p.m.tijd:'', kb=b.p.m?b.p.m.d+b.p.m.tijd:''; return ka<kb?1:-1; });
  let day=''; let prev=null; const body=msgs.map(m=>{ let sep=''; if(m.d!==day){ day=m.d; prev=null; sep=`<div class="wa-day"><span>${m.d===TODAY?'Vandaag':cap(dayName(m.d))+' '+fmtD(m.d)}</span></div>`; } const h=sep+waBubble(m,isK,prev); prev=m; return h; }).join('');
  const rep=UI.waReply&&waFindMsg(UI.waReply); const nSel=UI.waSel?UI.waSel.length:0; const mob=matchMedia('(max-width: 900px)').matches;
  return `<div class="wa ${mob&&!UI.waOpen?'showlist':''} ${thr?'thr':''}">
  <aside class="wa-list"><div class="wa-lh"><h3>Chats</h3><button class="iconbtn" data-act="wa-new" title="Nieuw gesprek" aria-label="Nieuw gesprek">${ic('plus')}</button></div>
    <div class="wa-search">${ic('eye')}<input id="waq" placeholder="Zoek gesprek of bericht" value="${esc(UI.waQ||'')}" aria-label="Zoeken in chats"></div>
    <div class="wa-f">${[['alle','Alles'],['ongelezen','Ongelezen'],['projecten','Projecten'],['teams','Teams'],['klanten','Klanten']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="wa-f" data-f="${k}">${l}</button>`).join('')}</div>
    <div class="wa-items">${list.map(({c,p})=>{ const u=unread(c.id); return `<button class="wa-it ${c.id===cur?'on':''}" data-act="wa-open" data-id="${c.id}">${waAvatar(c)}<span class="wa-itx"><span class="row between"><b>${c.type==='klant'?'':'#'}${esc(c.naam)}</b><small class="${u?'u':''}">${p.d}</small></span><span class="row between"><small>${esc(p.t)}</small>${u?`<span class="wa-u">${u}</span>`:''}</span></span></button>`; }).join('')||'<div class="empty">Geen gesprekken gevonden.</div>'}</div></aside>
  <section class="wa-main">
    <header class="wa-h">${mob?`<button class="iconbtn" data-act="wa-back" aria-label="Terug naar chats">${ic('chevl')}</button>`:''}${waAvatar(ch)}<div class="wa-ht"><b>${ch.type==='klant'?'':'#'}${esc(ch.naam)}</b><small>${esc(isK?'Klantgesprek · zichtbaar in de Service Hub':waMembers(ch,msgs)||ch.oms||'')}</small></div>
      ${ch.pid?`<a class="btn sm" href="/project-${ch.pid.toLowerCase()}">${ic('folder')}<span class="hide-s">${ch.pid}</span></a>`:''}<button class="btn sm" data-act="ch-sum" title="Samenvatten">${ic('spark')}<span class="hide-s">Samenvatten</span></button><button class="btn sm ${UI.waSel?'pri':''}" data-act="wa-selmode">${ic('checksq')}<span class="hide-s">${UI.waSel?'Klaar':'Selecteren'}</span></button></header>
    ${UI.chSum&&UI.chSum.ch===cur?UI.chSum.html:''}
    <div class="wa-msgs" id="chmsgs">${body||'<div class="wa-sys">Nog geen berichten. Zeg hallo 👋</div>'}</div>
    ${UI.waSel?`<div class="wa-selbar"><b>${nSel} geselecteerd</b><span style="flex:1"></span><button class="btn sm" data-act="wa-selx">Annuleren</button><button class="btn sm pri" data-act="wa-taskN" ${nSel?'':'disabled'}>${ic('checksq')}Taak van gesprek</button></div>`
    :`${rep?`<div class="wa-rep" style="--qc:${waCol(rep.van)}"><div><b>${esc(waName(rep))}</b><span>${esc(String(rep.txt).replace(/[*_]/g,'').slice(0,100))}</span></div><button class="iconbtn" data-act="wa-repx" aria-label="Citaat weghalen">${ic('x')}</button></div>`:''}
    <form class="wa-comp" data-form="chat" data-ch="${cur}"><label class="wa-ib" title="Bijlage">${ic('clip2')}<input type="file" hidden id="chfile"></label><textarea class="in" name="txt" id="chtxt" rows="1" placeholder="${isK?'Bericht aan de klant':'Bericht · @naam, PD-nummer'}" aria-label="Bericht"></textarea><button class="wa-send" type="submit" aria-label="Versturen">${ic('send')}</button></form>
    <div id="chatt" class="muted" style="font-size:12px;padding:0 14px 6px">${UI.chAtt?`Bijlage: ${esc(UI.chAtt)} <button class="btn xs ghost" data-act="ch-attx">Verwijderen</button>`:''}</div>`}
  </section>
  ${thr?`<aside class="ch-thread"><div class="ch-head"><h3>Thread</h3><span style="flex:1"></span><button class="iconbtn" data-act="ch-thread-x" aria-label="Thread sluiten">${ic('x')}</button></div><div class="ch-msgs">${chMsgHtml(thr,true)}<div class="ch-day">${thr.replies.length} reacties</div>${thr.replies.map(r=>chMsgHtml({...r,ch:thr.ch},true)).join('')}</div><form class="ch-comp" data-form="chreply" data-id="${thr.id}"><textarea class="in" name="txt" rows="1" placeholder="Reageer…" aria-label="Reactie"></textarea><button class="send" type="submit" aria-label="Versturen">${ic('send')}</button></form></aside>`:''}
  </div>`; };

/* taak uit één of meer berichten */
function waTaskModal(ids){ const ms=ids.map(waFindMsg).filter(Boolean).sort((a,b)=>(a.d+a.tijd)<(b.d+b.tijd)?-1:1); if(!ms.length) return; const ch=S.chat.channels.find(c=>c.id===ms[0].ch); const pid=(ms.map(m=>(String(m.txt).match(/PD-2026-\d{4}/)||[])[0]).find(Boolean))||(ch&&ch.pid)||(ms[0].ch.startsWith('klant-')?ms[0].ch.slice(6):'');
  const mention=(ms.map(m=>(String(m.txt).match(/@([A-Za-zÀ-ÿ]+)/)||[])[1]).find(Boolean)||'').toLowerCase(); const eig=(S.emps.find(e=>e.naam.toLowerCase().startsWith(mention))||{}).id||(ms[ms.length-1].van!==ME&&emp(ms[ms.length-1].van)?ms[ms.length-1].van:'');
  const titel=String(ms[ms.length-1].txt).replace(/[*_]/g,'').replace(/@\w+\s*/g,'').split(/[.!?]/)[0].slice(0,80);
  UI.waTaskIds=ms.map(m=>m.id);
  modal(ms.length>1?`Taak van gesprek (${ms.length} berichten)`:'Taak van bericht',`<form class="fg" data-form="watask"><div class="f full"><label for="wt-t">Taak</label><input class="in" id="wt-t" name="titel" value="${esc(titel)}" required></div>
    <div class="f"><label for="wt-e">Eigenaar</label><select class="in" id="wt-e" name="eig">${S.emps.map(e=>`<option value="${e.id}" ${e.id===eig?'selected':''}>${esc(e.naam)}</option>`).join('')}</select></div><div class="f"><label for="wt-d">Deadline</label><input class="in" type="date" id="wt-d" name="dl" value="${addDays(TODAY,1)}"></div>
    <div class="f"><label for="wt-p">Projectdossier</label><select class="in" id="wt-p" name="pid">${projOpts(pid)}</select></div><div class="f"><label for="wt-pr">Prioriteit</label><select class="in" id="wt-pr" name="prio"><option value="normaal">Normaal</option><option value="hoog">Hoog</option><option value="laag">Laag</option></select></div>
    <div class="f full"><label>Uit het gesprek</label><div class="wa-src">${ms.map(m=>`<div><b style="color:${waCol(m.van)}">${esc(waName(m))}</b> <small class="muted">${m.d===TODAY?'vandaag':fmtD(m.d)} ${m.tijd}</small><div>${esc(String(m.txt).replace(/[*_]/g,''))}</div></div>`).join('')}</div></div></form>`,
    `<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">${ic('checksq')}Taak aanmaken</button>`); }
R2_FORMS.watask=(f,v)=>{ if(!v.titel) return fieldErr(f,'titel','Geef de taak een titel.'); const ms=UI.waTaskIds.map(waFindMsg).filter(Boolean);
  const t={id:uid('t'),titel:v.titel,pid:v.pid,eig:v.eig,dl:v.dl,status:'todo',prio:v.prio,oms:'Uit teamchat:\n'+ms.map(m=>`${waName(m)} (${m.d===TODAY?'vandaag':fmtD(m.d)} ${m.tijd}): ${String(m.txt).replace(/[*_]/g,'')}`).join('\n'),checklist:[],fromChat:ms.map(m=>m.id)};
  S.tasks.push(t); ms.forEach(m=>{ const raw=S.chat.msgs.find(x=>x.id===m.id); if(raw) raw.task=t.id; });
  const ch=ms[0]&&ms[0].ch; if(ch&&!ch.startsWith('klant-')) S.chat.msgs.push({id:uid('m'),ch,van:ME,sys:true,txt:`📌 <b>${esc(empName(ME))}</b> maakte een taak: “${esc(v.titel)}” voor <b>${esc(firstName(v.eig))}</b>${v.dl?' · '+fmtD(v.dl):''}`,d:TODAY,tijd:nowT(),pinned:false,replies:[],att:null});
  if(v.pid&&proj(v.pid)) addActivity(proj(v.pid),`Taak uit teamchat: ${v.titel} (${firstName(v.eig)})`,'blue'); if(S.ai) emit('task.created',{project_id:v.pid,task_id:t.id,titel:v.titel,from_messages:t.fromChat},{actor:'user:'+ME});
  UI.waSel=null; closeModal(); commit('Taak aangemaakt en gekoppeld aan het gesprek'); };

/* citaat koppelen aan verstuurd bericht */
document.addEventListener('submit',e=>{ const f=e.target; if(f.dataset&&f.dataset.form==='chat'&&UI.waReply){ const n=S.chat.msgs.length, rep=UI.waReply; setTimeout(()=>{ const m=S.chat.msgs.slice(n).find(x=>x.ch===f.dataset.ch); if(m){ m.reply=rep; save(); } UI.waReply=null; render(); },0); } },true);

/* acties */
document.addEventListener('click',e=>{ const sel=UI.waSel&&e.target.closest&&e.target.closest('[data-wamsg]'); if(sel&&!e.target.closest('button,a')){ const id=sel.dataset.wamsg; UI.waSel=UI.waSel.includes(id)?UI.waSel.filter(x=>x!==id):[...UI.waSel,id]; render(); return; }
  const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act, d=el.dataset;
  switch(a){
    case 'wa-open': UI.chCur=d.id; UI.chThread=null; UI.waSel=null; UI.waReply=null; UI.waOpen=true; save(); render(); setTimeout(()=>{ const b=$('#chmsgs'); if(b) b.scrollTop=b.scrollHeight; },0); break;
    case 'wa-back': UI.waOpen=false; render(); break;
    case 'wa-f': UI.waF=d.f; render(); break;
    case 'wa-reply': UI.waReply=d.id; render(); setTimeout(()=>$('#chtxt')?.focus(),0); break;
    case 'wa-repx': UI.waReply=null; render(); break;
    case 'wa-react': { const m=S.chat.msgs.find(x=>x.id===d.id); if(!m) break; m.reacts=m.reacts||{}; const a2=m.reacts[d.e]=m.reacts[d.e]||[]; const i=a2.indexOf(ME); if(i>=0) a2.splice(i,1); else a2.push(ME); save(); render(); break; }
    case 'wa-task1': waTaskModal([d.id]); break;
    case 'wa-selmode': UI.waSel=UI.waSel?null:[]; render(); break;
    case 'wa-selx': UI.waSel=null; render(); break;
    case 'wa-taskN': waTaskModal(UI.waSel||[]); break;
    case 'wa-taskopen': { const t=S.tasks.find(x=>x.id===d.id); if(t) mTask(t); break; }
    case 'wa-new': modal('Nieuw gesprek',`<p class="muted" style="margin-top:0">In het prototype starten gesprekken per kanaal, project of team. Kies een bestaand kanaal of open een projectdossier om het projectkanaal te gebruiken.</p>`,`<button class="btn pri" data-act="mclose">Oké</button>`); break;
  } });
document.addEventListener('input',e=>{ if(e.target.id==='waq'){ UI.waQ=e.target.value; clearTimeout(UI._waT); UI._waT=setTimeout(()=>{ render(); const i=$('#waq'); if(i){ i.focus(); i.setSelectionRange(i.value.length,i.value.length); } },250); }
  if(e.target.id==='chtxt'){ const t=e.target; t.style.height='auto'; t.style.height=Math.min(140,t.scrollHeight)+'px'; } });
document.addEventListener('keydown',e=>{ if(e.target.id==='chtxt'&&e.key==='Enter'&&!e.shiftKey&&!matchMedia('(pointer: coarse)').matches){ e.preventDefault(); e.target.form.requestSubmit(); } });
/* lang indrukken op telefoon: selecteren */
(function(){ let t=null; document.addEventListener('touchstart',e=>{ const b=e.target.closest&&e.target.closest('[data-wamsg]'); if(!b||UI.waSel) return; t=setTimeout(()=>{ UI.waSel=[b.dataset.wamsg]; try{ navigator.vibrate&&navigator.vibrate(10); }catch(_){} render(); },450); },{passive:true}); ['touchend','touchmove','touchcancel'].forEach(k=>document.addEventListener(k,()=>clearTimeout(t),{passive:true})); })();
/* na render naar onder scrollen */
const _renderR15w=render; render=function(...a){ const r=_renderR15w.apply(this,a); if(route()==='teamchat'){ const b=$('#chmsgs'); if(b&&!UI.waSel) b.scrollTop=b.scrollHeight; } return r; };
R2_ROUTES.teamchat=vTeamchat;


/* ---------- Ronde 15 · Onderaannemers: bedrijfsdossier op orde, kaarten, aanmeldlink ---------- */
function ensureR15s(st){ if(!st||!st.subs) return st; if(!st.r15s){ st.r15s=1; const pl={Rotterdam:['Kralingseweg 88','3062 CB'],Amsterdam:['Kollenbergweg 12','1101 AR'],'Den Haag':['Binckhorstlaan 140','2516 BE'],Haarlem:['Waarderweg 52','2031 BP']};
    st.subs.forEach((s,i)=>{ const a=pl[s.regio]||['Industrieweg '+(10+i),'1000 AA']; Object.assign(s,{btw:`NL${String(800000000+i*37311).slice(0,9)}B01`,adres:a[0],postcode:a[1],plaats:s.regio,sinds:String(2008+i*2),tel:`06 ${String(41000000+i*1234567).slice(0,8).replace(/(\d{2})(\d{2})(\d{2})(\d{2})/,'$1 $2 $3 $4')}`,web:s.naam.toLowerCase().replace(/[^a-z]+/g,'')+'.nl',medewerkers:1+i%4,
      idCheck:s.docs.find(d=>d.t==='Identiteit gecontroleerd'&&d.ok)?{door:'Klaas Dekker',d:'2026-06-03',type:i%2?'Rijbewijs':'Paspoort',nr4:String(1000+i*731).slice(-4)}:null,
      signed:[['Modelovereenkomst (DBA)','2026.1'],['Raamovereenkomst onderaanneming','v3'],['Verwerkersovereenkomst (AVG)','v2'],['V&G-instructie Renovion gelezen','2026']].filter((_,k)=>s.keurmerk==='goedgekeurd'||k<2).map(([t,v],k)=>({t,v,d:addDays('2026-06-04',k*2+i),door:s.contact,sim:true}))}); }); }
  return st; }
/* demomigratie overgeslagen: de structuur staat in de fabrieksstaat */ const _seedR15s=ensureR2; ensureR2=function(st){ return ensureR15s(_seedR15s(st)); };

const SIGN_REQ=['Modelovereenkomst (DBA)','Raamovereenkomst onderaanneming','Verwerkersovereenkomst (AVG)','V&G-instructie Renovion gelezen'];
function subDossier(s){ const doc=t=>s.docs.find(d=>d.t===t); const st=d=>d?docState(d):'ontbreekt'; const sg=t=>(s.signed||[]).find(x=>x.t===t);
  const items=[['KvK','KvK-uittreksel',st(doc('KvK-uittreksel'))],['ID','Legitimatie gecontroleerd',s.idCheck?'ok':'ontbreekt'],['VCA','VCA-certificaat',st(doc('VCA-certificaat'))],['AVB','Aansprakelijkheidsverzekering',st(doc('Aansprakelijkheidsverzekering'))],['G','G-rekening',st(doc('G-rekening'))],
    ...SIGN_REQ.map((t,i)=>[['DBA','RAAM','AVG','V&G'][i],t,sg(t)?'ok':'ontbreekt'])];
  const open=items.filter(x=>x[2]!=='ok'); return {items,open,ok:!open.length}; }
const DSTC={ok:'ok',binnenkort:'warn',verlopen:'bad',ontbreekt:'bad'};
function subCard(s){ const dz=subDossier(s); const inv=s.inv&&!s.inv.done; const col=waCol?waCol(s.id):'#3E6BA8';
  return `<div class="card scard" data-act="sub-open" data-id="${s.id}"><div class="sc-h"><span class="sc-logo" style="--ac:${col}">${esc(s.naam.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div style="min-width:0;flex:1"><b>${esc(s.naam)}</b><small>${esc(s.vak)} · ${esc(s.plaats||s.regio)}${s.sinds?' · sinds '+s.sinds:''}</small></div>${inv?'<span class="pill vio">Uitgenodigd</span>':keurPill(s)}</div>
   ${inv?`<div class="sc-inv"><div class="row between"><small>Aanmelding via link · ${esc(s.inv.kanaal)}</small><small>${s.inv.stap}/6</small></div><div class="bar" style="margin-top:4px"><i style="width:${s.inv.stap/6*100}%"></i></div><small class="muted">Verstuurd ${fmtD(s.inv.d)} naar ${esc(s.contact)}</small></div>`
   :`<div class="sc-kv"><span>KvK</span><b>${esc(s.kvk)}</b><span>Btw</span><b>${esc(s.btw||'—')}</b><span>Contact</span><b>${esc(s.contact)}</b></div>
   <div class="sc-dz ${dz.ok?'ok':'open'}">${ic(dz.ok?'check':'alert')}<b>${dz.ok?'Dossier op orde':dz.open.length+' '+(dz.open.length===1?'punt':'punten')+' open'}</b><span>${dz.items.filter(x=>x[2]==='ok').length}/${dz.items.length}</span></div>
   <div class="sc-ic">${dz.items.map(([k,t,v])=>`<span class="dz ${DSTC[v]}" title="${esc(t)}: ${v==='ok'?'in orde':v==='binnenkort'?'verloopt binnenkort':v}">${k}</span>`).join('')}</div>`}
   <div class="sc-f"><span>${s.rating?stars(s.rating):'<span class="muted">Nog geen beoordeling</span>'}</span><span class="muted">${eur(s.tarief||0)}/${esc(s.eenheid||'uur')} · ${s.opdrachten||0} opdr.</span></div></div>`; }
/* lijst → kaarten */
const _vOndR15=vOnderaannemers; vOnderaannemers=function(){ let h=_vOndR15(); if((UI.subView||'kaart')==='lijst') return h.replace('<div class="tabs">',`<div class="row between wrap" style="gap:8px">${subViewSeg()}</div><div class="tabs">`);
  const f=UI.subFilter||'alle'; const list=S.subs.filter(s=>f==='alle'||subStatus(s)===f||(f==='nieuw'&&s.inv&&!s.inv.done));
  return h.replace(/<div class="card tw"><table class="t">[\s\S]*<\/table><\/div>/,`<div class="grid g3 scards">${list.map(subCard).join('')}</div>`).replace('<div class="tabs">',`<div class="row between wrap" style="gap:8px">${subViewSeg()}<span class="muted" style="font-size:12.5px">Iconen: ${['KvK','ID','VCA','AVB','G','DBA','RAAM','AVG','V&G'].join(' · ')} · groen = in orde</span></div><div class="tabs">`); };
const subViewSeg=()=>`<div class="seg"><button class="${(UI.subView||'kaart')==='kaart'?'on':''}" data-act="sub-view" data-v="kaart">Kaarten</button><button class="${UI.subView==='lijst'?'on':''}" data-act="sub-view" data-v="lijst">Lijst</button></div>`;
/* profiel: bedrijf, legitimatie en getekende documenten bovenaan */
const _mSubR15=mSub; mSub=function(id){ _mSubR15(id); const s=sub(id); const dz=subDossier(s); const mb=document.querySelector('#layer .mb'); if(!mb) return;
  const inv=s.inv&&!s.inv.done;
  mb.insertAdjacentHTML('afterbegin',`${inv?`<div class="alert info">${ic('mail')}<div class="grow"><b>Uitgenodigd ${fmtD(s.inv.d)}</b> via ${esc(s.inv.kanaal)} · aanmelding staat op stap ${s.inv.stap} van 6.<div class="mono" style="margin-top:4px">${esc(s.inv.link)}</div></div><button class="btn sm" data-act="inv-copy" data-l="${esc(s.inv.link)}">Link kopiëren</button></div>`:''}
  <div class="sp-h"><span class="sc-logo lg" style="--ac:${waCol(s.id)}">${esc(s.naam.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div><b>${esc(s.naam)}</b><small>${esc(s.vak)} · ${esc(s.medewerkers||1)} ${s.medewerkers>1?'medewerkers':'medewerker'}${s.sinds?' · actief sinds '+s.sinds:''}</small></div><div class="sc-dz ${dz.ok?'ok':'open'}" style="margin-left:auto">${ic(dz.ok?'check':'alert')}<b>${dz.ok?'Dossier op orde':dz.open.length+' open'}</b></div></div>
  <div class="grid g2" style="gap:14px"><div><span class="lbl">Bedrijfsgegevens</span><div class="kv"><span>KvK</span><b>${esc(s.kvk)}</b><span>Btw-nummer</span><b>${esc(s.btw||'—')}</b><span>Adres</span><b>${esc([s.adres,s.postcode,s.plaats].filter(Boolean).join(', ')||'—')}</b><span>Telefoon</span><b>${esc(s.tel||'—')}</b><span>Website</span><b>${esc(s.web||'—')}</b></div></div>
  <div><span class="lbl">Legitimatie</span>${s.idCheck?`<div class="idc">${ic('check')}<div><b>${esc(s.idCheck.type)} gecontroleerd</b><small>door ${esc(s.idCheck.door)} op ${fmtDY(s.idCheck.d)} · documentnr. eindigt op ••${esc(s.idCheck.nr4)}</small><small class="muted">Er wordt geen kopie bewaard; alleen de controle is vastgelegd.</small></div></div>`:`<div class="idc no">${ic('alert')}<div><b>Nog niet gecontroleerd</b><small>Controleer bij de eerste opdracht op de bouwplaats.</small></div><button class="btn xs" data-act="sub-id" data-id="${s.id}">Controle vastleggen</button></div>`}
   <span class="lbl" style="margin-top:12px;display:block">Getekende documenten</span>${SIGN_REQ.map(t=>{ const x=(s.signed||[]).find(y=>y.t===t); return `<div class="check-row">${ic(x?'check':'clock')}<div class="grow"><b>${esc(t)}</b><small>${x?`versie ${esc(x.v)} · getekend door ${esc(x.door)} op ${fmtDY(x.d)}${x.vastgelegd?', vastgelegd door '+esc(x.vastgelegd):''}`:'nog niet getekend'}</small></div>${x?`<span class="pill ok">Getekend</span>`:`<button class="btn xs" data-act="sub-sign" data-id="${s.id}" data-t="${esc(t)}">Ter ondertekening</button>`}</div>`; }).join('')}</div></div>`); };

/* aanmelden: kiezen tussen link sturen en zelf invullen */
function mInvite(){ modal('Partner aanmelden',`<div class="onb-choice"><button class="oc on" data-act="inv-mode" data-v="link">${ic('send')}<b>Aanmeldlink sturen</b><small>De partner vult zelf gegevens, documenten en handtekeningen in. Jij krijgt een melding als hij klaar is.</small></button><button class="oc" data-act="inv-self">${ic('edit')}<b>Zelf invullen</b><small>Je hebt de gegevens al en vult het stappenplan nu in.</small></button></div>
  <form class="fg" data-form="invite"><div class="f"><label for="iv-b">Bedrijfsnaam</label><input class="in" id="iv-b" name="bedrijf" required></div><div class="f"><label for="iv-c">Contactpersoon</label><input class="in" id="iv-c" name="contact" required></div><div class="f"><label for="iv-m">E-mail</label><input class="in" id="iv-m" name="mail" type="email"></div><div class="f"><label for="iv-t">Mobiel (voor WhatsApp)</label><input class="in" id="iv-t" name="tel" type="tel" inputmode="tel"></div><div class="f full"><label for="iv-v">Vakgebied</label><select class="in" id="iv-v" name="vak">${['Tegelzetter','Schilder','Timmerman','Elektricien','Installateur','Stukadoor','Dakdekker','Grondwerker','Sloper','Stratenmaker'].map(v=>`<option>${v}</option>`).join('')}</select></div></form>
  <div class="onb-steps-preview"><span class="lbl">Wat de partner doorloopt</span>${stepper(-1)}</div>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">${ic('send')}Aanmeldlink maken</button>`); }
function stepper(cur){ return `<ol class="stp">${ONB_STEPS.map((t,i)=>`<li class="${i<cur?'done':i===cur?'on':''}"><span>${i<cur?ic('check'):i+1}</span><small>${t}</small></li>`).join('')}</ol>`; }
R2_FORMS.invite=(f,v)=>{ if(!v.bedrijf) return fieldErr(f,'bedrijf','Vul de bedrijfsnaam in.'); if(!v.contact) return fieldErr(f,'contact','Vul de contactpersoon in.'); if(!v.mail&&!v.tel) return fieldErr(f,'mail','Vul een e-mailadres of mobiel nummer in.');
  const tok=uid('').slice(-6)+Math.random().toString(36).slice(2,6); const link=`${location.origin}/inloggen`; const id='s'+(S.subs.length+1)+tok.slice(0,3);
  S.subs.push({id,naam:v.bedrijf,contact:v.contact,empId:'',vak:v.vak,regio:'—',plaats:'',kvk:'—',tarief:0,eenheid:'uur',rating:0,keurmerk:'nieuw',blocked:false,opdrachten:0,mail:v.mail,tel:v.tel,docs:['KvK-uittreksel','Aansprakelijkheidsverzekering','VCA-certificaat','G-rekening','Identiteit gecontroleerd','Modelovereenkomst (DBA)'].map(t=>({t,g:null,ok:false})),checks:[],signed:[],idCheck:null,inv:{token:tok,link,d:TODAY,kanaal:'nog niet verstuurd',stap:0,done:false}});
  UI.invId=id; save(); mInviteShare(id); };
function mInviteShare(id){ const s=sub(id); const txt=`Hoi ${s.contact.split(' ')[0]}, via deze link meld je ${s.naam} aan als partner van Renovion Groep. Het duurt ongeveer 10 minuten: gegevens, specialismen, documenten en de modelovereenkomst. ${s.inv.link}`;
  modal('Aanmeldlink delen',`<div class="inv-ok">${ic('check')}<div><b>Aanmeldlink voor ${esc(s.naam)} staat klaar</b><small>Geldig tot ${fmtD(addDays(TODAY,14))}. ${esc(s.naam)} staat in de lijst als “Uitgenodigd”.</small></div></div>
    <div class="inv-link"><span class="mono">${esc(s.inv.link)}</span><button class="btn sm" data-act="inv-copy" data-l="${esc(s.inv.link)}">${ic('clip2')}Kopiëren</button></div>
    <div class="inv-share"><button class="ish" data-act="inv-send" data-id="${id}" data-k="mail" ${s.mail?'':'disabled'}><span style="--ac:#3E6BA8">${ic('mail')}</span><b>E-mail</b><small>${esc(s.mail||'geen adres')}</small></button><a class="ish" href="https://wa.me/${(s.tel||'').replace(/\D/g,'').replace(/^0/,'31')}?text=${encodeURIComponent(txt)}" target="_blank" rel="noopener" data-act="inv-send" data-id="${id}" data-k="WhatsApp"><span style="--ac:#1E8A5A">${ic('chat')}</span><b>WhatsApp</b><small>${esc(s.tel||'kies contact')}</small></a><button class="ish" data-act="inv-send" data-id="${id}" data-k="delen"><span style="--ac:#7C5CD6">${ic('upload')}</span><b>Delen</b><small>via je telefoon</small></button></div>
    <span class="lbl">Bericht</span><div class="inv-msg">${esc(txt)}</div>
    <span class="lbl">Stappen voor de partner</span>${stepper(0)}`,`<button class="btn" data-act="mclose">Klaar</button>`); }
document.addEventListener('click',async e=>{ const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act, d=el.dataset;
  if(a==='pp-onboard'){ e.stopImmediatePropagation(); e.preventDefault(); UI.onb=null; mInvite(); return; }
  switch(a){
    case 'inv-self': closeModal(); UI.onb=null; mOnboard(); break;
    case 'inv-copy': try{ await navigator.clipboard.writeText(d.l); toast('Link gekopieerd'); }catch(_){ toast('Kopiëren niet toegestaan in deze weergave; selecteer de link handmatig','warn'); } break;
    case 'inv-send': { const s=sub(d.id); if(d.k==='delen'&&navigator.share){ try{ await navigator.share({title:'Aanmelden als Renovion-partner',url:s.inv.link}); }catch(_){} } s.inv.kanaal=d.k==='mail'?'e-mail':d.k; s.inv.d=TODAY; if(d.k==='mail') S.outbox.push({d:TODAY,aan:s.mail,onderwerp:`Aanmelden als partner van Renovion Groep`}); save(); toast(d.k==='mail'?'Uitnodiging in de outbox':`Gedeeld via ${d.k}`); render(); break; }
    case 'inv-done': { const s=sub(d.id); Object.assign(s,{kvk:String(70000000+Math.floor(Math.random()*9999999)),btw:'NL'+String(Math.floor(Math.random()*1e9)).padStart(9,'0')+'B01',adres:'Havenweg 4',postcode:'3542 AD',plaats:'Utrecht',regio:'Utrecht',tarief:52,sinds:'2019',keurmerk:'beoordeling',
        docs:[{t:'KvK-uittreksel',g:addDays(TODAY,365),ok:true},{t:'Aansprakelijkheidsverzekering',g:addDays(TODAY,300),ok:true},{t:'VCA-certificaat',g:addDays(TODAY,2000),ok:true},{t:'G-rekening',g:null,ok:true},{t:'Identiteit gecontroleerd',g:null,ok:false},{t:'Modelovereenkomst (DBA)',g:addDays(TODAY,700),ok:true}],
        signed:SIGN_REQ.slice(0,3).map(t=>({t,v:'2026.1',d:TODAY,door:s.contact,sim:true})),checks:[{t:'KvK-inschrijving gecontroleerd',door:'—',d:'',ok:false}]}); s.inv.stap=6; s.inv.done=true; S.notifs.unshift({t:`${s.naam} heeft de aanmelding afgerond`,d:TODAY}); closeModal(); commit(`${s.naam} heeft zich aangemeld (simulatie). Legitimatie en V&G-instructie staan nog open.`); mSub(s.id); break; }
    case 'sub-view': UI.subView=d.v; render(); break;
    case 'sub-id': { const s=sub(d.id); s.idCheck={door:myName(),d:TODAY,type:'Paspoort',nr4:'4821'}; const dd=s.docs.find(x=>x.t==='Identiteit gecontroleerd'); if(dd) dd.ok=true; else s.docs.push({t:'Identiteit gecontroleerd',g:null,ok:true}); closeModal(); commit('Legitimatiecontrole vastgelegd (geen kopie bewaard)'); mSub(s.id); break; }
    case 'sub-sign': { const s=sub(d.id); s.signed=s.signed||[]; s.signed.push({t:d.t,v:YEAR+'.1',d:TODAY,door:s.contact,vastgelegd:myName()}); closeModal(); commit(`${d.t}: ondertekening vastgelegd`); mSub(s.id); break; }
  } },true);
/* stappenplan met namen in de zelf-invullen-wizard */
const _modalR15s=modal; modal=function(...a){ _modalR15s(...a); const ws=document.querySelector('#layer .wsteps'); if(ws&&UI.onb){ ws.outerHTML=stepper(UI.onb.step); const b=document.querySelector('#layer .mb > .row.between b'); if(b&&/^Stap/.test(b.textContent)) b.parentElement.remove(); } };
/* workforce: partner-vakmannen tonen hun bedrijf en dossierstatus */
const _renderR15s=render; render=function(...a){ const r=_renderR15s.apply(this,a); if(route()==='workforce') document.querySelectorAll('#view .card.person').forEach(cd=>{ const e=emp(cd.dataset.id); if(!e||e.type!=='partner'||cd.querySelector('.sc-via')) return; const s=S.subs.find(x=>x.empId===e.id); if(!s) return; const dz=subDossier(s); cd.querySelector('.ptop')?.insertAdjacentHTML('afterend',`<button class="sc-via ${dz.ok?'ok':'open'}" data-act="sub-open" data-id="${s.id}">${ic('handshake')}<span>via <b>${esc(s.naam)}</b></span><span>${dz.ok?'dossier op orde':dz.open.length+' open'}</span></button>`); }); return r; };
R2_ROUTES.onderaannemers=vOnderaannemers;


/* ---------- Ronde 15 · Benodigde documenten per doelgroep: versturen en opvragen ---------- */
const REQ_DOCS={
  organisatie:{l:'Organisatie',s:'Eigen bedrijfsdocumenten die klanten en partners kunnen vragen',d:[
    ['uit','Algemene voorwaarden Renovion',/Algemene voorwaarden/,'Bij elke offerte'],['uit','KvK-uittreksel Renovion Groep',/KvK-uittreksel Renovion/,'Max. 6 maanden oud'],['uit','CAR- en AVB-polis Renovion',/polis Renovion/,'Bewijs van verzekering'],['uit','VCA**-certificaat Renovion',/VCA\*\*/,'Voor zakelijke opdrachtgevers'],
    ['uit','Privacyverklaring (AVG)',/Privacyverklaring/,'Op website en in portaal'],['uit','Organogram en bevoegdheden',/Organogram/,'Wie mag tekenen'],['uit','Generieke Poortinstructie (GPI)',/Poortinstructie/,'Bouwplaatsregels'],['uit','Garantieboek Renovion',/Garantieboek/,'Na oplevering']]},
  klant:{l:'Klant',s:'Wat een klant van ons krijgt',d:[
    ['uit','Offerte + algemene voorwaarden',/Algemene voorwaarden/,'Samen versturen'],['uit','Aannemingsovereenkomst',/aannemingsovereenkomst/i,'Na akkoord, ter ondertekening'],['uit','Betalingsschema',/Betalingsschema/,'Uit offerte'],['uit','Bouwplaats- en veiligheidsinformatie',/Veiligheidsinstructie/,'Vóór start'],
    ['uit','Opleverformulier',/Opleverformulier/,'Bij oplevering'],['uit','Garantieboek Renovion',/Garantieboek/,'Na oplevering'],['uit','Onderhoudsadvies',/Onderhoudsadvies/,'Na oplevering'],['uit','Consumentendossier (Wkb)',/Consumentendossier/,'Bij oplevering · juridisch laten bevestigen']]},
  onderaannemer:{l:'Onderaannemer',s:'Wat we sturen en wat we moeten ontvangen',d:[
    ['uit','Modelovereenkomst (DBA)',/onderaannemersovereenkomst \(DBA\)/i,'Ter ondertekening'],['uit','Raamovereenkomst onderaanneming',/Raamovereenkomst/,'Ter ondertekening'],['uit','Verwerkersovereenkomst (AVG)',/Verwerkersovereenkomst/,'Ter ondertekening'],['uit','V&G-plan uitvoeringsfase',/V&G-plan/,'Per project'],['uit','Generieke Poortinstructie (GPI)',/Poortinstructie/,'Vóór start'],
    ['in','KvK-uittreksel','KvK','Max. 12 maanden oud'],['in','Aansprakelijkheidsverzekering','AVB','Geldige polis'],['in','VCA-certificaat','VCA','Geldig'],['in','G-rekening','G','Ketenaansprakelijkheid'],['in','Legitimatiecontrole','ID','Alleen controle, geen kopie']]},
  personeel:{l:'Eigen personeel',s:'Voor medewerkers in dienst',d:[
    ['uit','Personeelshandboek',/Personeelshandboek/,'Bij indiensttreding'],['uit','Veiligheidsinstructie bouwplaats',/Veiligheidsinstructie/,'Jaarlijks'],['uit','Generieke Poortinstructie (GPI)',/Poortinstructie/,'Vóór eerste bouwplaats'],
    ['in','VCA-certificaat','VCA-basis','Geldig'],['in','BHV of EHBO (indien rol)','EHBO','Per rol'],['in','Legitimatiecontrole','ID','Alleen controle, geen kopie'],['in','Loonheffingsverklaring','LH','Bij indiensttreding']]}};
function rdStatus(g,row){ const [dir,naam,m]=row; if(dir==='uit'){ const d=allDocs().find(x=>m.test(x.naam)); return d?{ok:true,t:`In bibliotheek · v${d.versie}`,doc:d}:{ok:false,t:'Ontbreekt in bibliotheek'}; }
  if(g==='onderaannemer'){ const subs=S.subs.filter(s=>!(s.inv&&!s.inv.done)); const ok=subs.filter(s=>subDossier(s).items.some(x=>x[0]===m&&x[2]==='ok')).length; return {ok:ok===subs.length,t:`${ok} van ${subs.length} onderaannemers compleet`,n:subs.length-ok}; }
  const ppl=S.emps.filter(e=>e.type==='intern'); if(m==='ID'||m==='LH') return {ok:true,t:`${ppl.length} van ${ppl.length} vastgelegd`}; const ok=ppl.filter(e=>(e.certs||[]).some(c=>c.t.startsWith(m)&&certState(c)!=='verlopen')).length; return {ok:ok===ppl.length,t:`${ok} van ${ppl.length} medewerkers geldig`,n:ppl.length-ok}; }
function mReqDocs(){ const g=UI.rdG||'onderaannemer', G=REQ_DOCS[g]; UI.rdSel=UI.rdSel||[];
  const rec=g==='klant'?S.clients.map(c=>[c.id,c.naam+(c.plaats?' · '+c.plaats:'')]):g==='onderaannemer'?S.subs.map(s=>[s.id,s.naam]):g==='personeel'?S.emps.filter(e=>e.type!=='partner').map(e=>[e.id,e.naam]):[['ext','Externe partij (e-mailadres)']];
  const rows=G.d.map((r,i)=>{ const st=rdStatus(g,r); const k=g+':'+i; return `<label class="rd ${UI.rdSel.includes(k)?'on':''}"><input type="checkbox" data-rd="${k}" ${UI.rdSel.includes(k)?'checked':''}><span class="rd-dir ${r[0]}">${r[0]==='uit'?'↗':'↙'}</span><span class="rd-t"><b>${esc(r[1])}</b><small>${esc(r[3])}</small></span><span class="pill ${st.ok?'ok':r[0]==='uit'?'bad':'warn'}">${esc(st.t)}</span></label>`; }).join('');
  const sends=(S.docSends||[]).slice(0,4);
  modal('Benodigde documenten',`<div class="rd-tabs">${Object.entries(REQ_DOCS).map(([k,v])=>`<button class="${g===k?'on':''}" data-act="rd-g" data-g="${k}">${v.l}</button>`).join('')}</div><p class="muted" style="margin:6px 0 10px">${esc(G.s)}. <b>↗</b> wij versturen · <b>↙</b> wij vragen op.</p>
    <div class="rd-list">${rows}</div>
    <div class="rd-send"><div class="f"><label for="rd-to">Aan</label><select class="in" id="rd-to">${rec.map(([id,n])=>`<option value="${id}">${esc(n)}</option>`).join('')}</select></div>${g==='organisatie'?`<div class="f"><label for="rd-mail">E-mailadres</label><input class="in" id="rd-mail" type="email" placeholder="naam@bedrijf.nl"></div>`:''}
      <div class="f"><label for="rd-k">Via</label><select class="in" id="rd-k"><option value="e-mail">E-mail</option><option value="portaal">Portaal (klant/partner)</option><option value="WhatsApp">WhatsApp-link</option></select></div></div>
    ${sends.length?`<span class="lbl">Recent</span>${sends.map(x=>`<div class="sumrow"><span>${x.richting==='uit'?'↗ Verstuurd':'↙ Opgevraagd'} aan ${esc(x.aan)} · ${x.n} ${x.n===1?'document':'documenten'} via ${esc(x.kanaal)}</span><span class="muted">${fmtD(x.d)} ${x.t}</span></div>`).join('')}`:''}
    <p class="muted" style="font-size:12px;margin:8px 0 0">De e-mail komt in de outbox; er is nog geen mailserver gekoppeld. Opgevraagde documenten komen binnen via het partner- of klantportaal.</p>`,
    `<button class="btn" data-act="mclose">Sluiten</button><button class="btn" data-act="rd-all">Alles selecteren</button><button class="btn pri" data-act="rd-go" ${UI.rdSel.length?'':'disabled'}>${ic('send')}${UI.rdSel.length?`${UI.rdSel.length} versturen / opvragen`:'Selecteer documenten'}</button>`,true); }
document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act, d=el.dataset;
  if(a==='rd-open'){ UI.rdSel=[]; mReqDocs(); }
  else if(a==='rd-g'){ UI.rdG=d.g; UI.rdSel=[]; mReqDocs(); }
  else if(a==='rd-all'){ const g=UI.rdG||'onderaannemer'; UI.rdSel=REQ_DOCS[g].d.map((_,i)=>g+':'+i); mReqDocs(); }
  else if(a==='rd-go'){ const g=UI.rdG||'onderaannemer'; const to=$('#rd-to'); const k=$('#rd-k').value; const mail=$('#rd-mail'); const aan=g==='organisatie'?(mail&&mail.value||'externe partij'):to.options[to.selectedIndex].text.split(' · ')[0];
    if(g==='organisatie'&&!(mail&&/\S+@\S+\.\S+/.test(mail.value))){ toast('Vul een geldig e-mailadres in','warn'); return; }
    const rows=UI.rdSel.map(x=>REQ_DOCS[g].d[+x.split(':')[1]]); const uit=rows.filter(r=>r[0]==='uit'), inn=rows.filter(r=>r[0]==='in'); const miss=uit.filter(r=>!rdStatus(g,r).ok);
    S.docSends=S.docSends||[]; if(uit.length) S.docSends.unshift({d:TODAY,t:nowT(),aan,n:uit.length,kanaal:k,richting:'uit',docs:uit.map(r=>r[1])}); if(inn.length) S.docSends.unshift({d:TODAY,t:nowT(),aan,n:inn.length,kanaal:k,richting:'in',docs:inn.map(r=>r[1])});
    if(k==='e-mail') S.outbox.push({d:TODAY,aan,onderwerp:`${uit.length?'Documenten van Renovion':''}${uit.length&&inn.length?' + ':''}${inn.length?'Verzoek om documenten':''}`});
    if(k==='WhatsApp'){ const txt=`Hoi, hierbij ${uit.length?'de documenten: '+uit.map(r=>r[1]).join(', '):''}${inn.length?(uit.length?'. En we hebben nog nodig: ':'we hebben nog nodig: ')+inn.map(r=>r[1]).join(', '):''}. Upload of bekijk via https://portaal.renovion.nl/d/${uid('').slice(-6)}`; window.open('https://wa.me/?text='+encodeURIComponent(txt),'_blank','noopener'); }
    if(g==='onderaannemer'&&to){ const s=sub(to.value); if(s&&inn.length) S.notifs.unshift({t:`Documenten opgevraagd bij ${s.naam}: ${inn.map(r=>r[1]).join(', ')}`,d:TODAY}); }
    UI.rdSel=[]; closeModal(); commit(`${uit.length?uit.length+' verstuurd':''}${uit.length&&inn.length?', ':''}${inn.length?inn.length+' opgevraagd':''} · ${aan}${miss.length?` · let op: ${miss.length} nog niet in bibliotheek`:''}`,miss.length?'warn':'ok'); } });
document.addEventListener('change',e=>{ const t=e.target; if(t.dataset&&t.dataset.rd){ UI.rdSel=UI.rdSel||[]; if(t.checked) UI.rdSel.push(t.dataset.rd); else UI.rdSel=UI.rdSel.filter(x=>x!==t.dataset.rd); t.closest('.rd').classList.toggle('on',t.checked); const b=document.querySelector('[data-act="rd-go"]'); if(b){ b.disabled=!UI.rdSel.length; b.innerHTML=`${ic('send')}${UI.rdSel.length?`${UI.rdSel.length} versturen / opvragen`:'Selecteer documenten'}`; } } });
const _renderR15d=render; render=function(...a){ const r=_renderR15d.apply(this,a); if(routeKey(route())==='documenten'&&!$('#rdbtn')){ const btn=`<button class="btn" id="rdbtn" data-act="rd-open">${ic('checksq')}Benodigde documenten</button>`; const up=[...document.querySelectorAll('#view label.btn.pri')].find(x=>x.textContent.includes('Uploaden')); if(up) up.insertAdjacentHTML('beforebegin',btn); else { const ph=document.querySelector('#view .page > .ph'); if(ph) (ph.querySelector('.acts')||ph).insertAdjacentHTML('beforeend',btn); } } return r; };


/* ---------- Ronde 16 · Projectcockpit en portfolio-overzicht ---------- */
const LV={g:{c:'ok',l:'Op koers'},o:{c:'warn',l:'Aandacht'},r:{c:'bad',l:'Actie nodig'},n:{c:'mut',l:'Nog niet van toepassing'}};
const LV_RANK={r:3,o:2,g:1,n:0};
const worst=(...a)=>a.reduce((w,x)=>LV_RANK[x]>LV_RANK[w]?x:w,'n');
const dagen=(a,b)=>Math.round((D(b)-D(a))/864e5);
function ensureR16(st){ if(!st) return st; if(!st.r16){ st.r16=1; st.risks=st.risks||{};
  const add=(pid,t,eig,impact,maat)=>{ (st.risks[pid]=st.risks[pid]||[]).push({id:'rk'+Math.random().toString(36).slice(2,8),t,eig,impact,maat,status:'open',d:'2026-10-26'}); };
  add('PD-2026-0039','Vochtig metselwerk achtergevel: mogelijk extra herstel','klaas','hoog','Vochtmeting laten doen vóór stucwerk');
  add('PD-2026-0039','Levertijd kozijnen 6 weken: oplevering schuift als bestelling later dan 6 nov','thomas','midden','Bestelling deze week vastzetten');
  add('PD-2026-0041','Bestaande leidingen in vloer onbekend: risico op lekkage bij sloop','mehmet','midden','Leidingdetector inzetten');
  add('PD-2026-0038','Weersverwachting: regen week 45 kan dakwerk vertragen','bram','midden','Noodafdekking klaarzetten');
  for(const p of st.projects){ if(p.phase>=4&&p.id!=='PD-2026-0039'){ p.docs=p.docs||[]; if(!p.docs.some(d=>/overeenkomst/i.test(d.naam+' '+(d.cat||'')))) p.docs.push({naam:'Aannemingsovereenkomst ondertekend.pdf',cat:'Overeenkomst',datum:(p.offerte&&p.offerte.accepted)||'2026-09-01'}); }
    if(p.id==='PD-2026-0038'&&!p.docs.some(d=>/V&G/.test(d.naam))) p.docs.push({naam:'V&G-plan uitvoeringsfase.pdf',cat:'Veiligheid',datum:'2026-08-25'}); if(p.id==='PD-2026-0038'||p.id==='PD-2026-0036') if(!p.docs.some(d=>/vergunning/i.test(d.naam))) p.docs.push({naam:'Omgevingsvergunning.pdf',cat:'Vergunning',datum:'2026-07-14'}); }
  add('PD-2026-0036','Gereedmelding gemeente nog niet ingediend','klaas','hoog','Uiterlijk 2 weken vóór oplevering indienen'); }
  return st; }
/* demomigratie overgeslagen: de structuur staat in de fabrieksstaat */ { const _seedR16=ensureR2; ensureR2=function(st){ return ensureR16(_seedR16(st)); }; }

/* ---- afgeleide projectgegevens ---- */
function pContact(p){ const ds=[...(S.klantBerichten||[]).filter(m=>m.pid===p.id).map(m=>m.d),...(p.activity||[]).filter(a=>/klant|mail|gebeld|bezoek|portaal|akkoord|ondertekend|offerte|betaald|opgeleverd|factuur|meerwerk/i.test(a.t)).map(a=>a.d),...(S.outbox||[]).filter(o=>o.aan&&o.aan===client(p.clientId).mail).map(o=>o.d)].filter(Boolean).sort();
  const last=ds[ds.length-1]||null; const msgs=(S.klantBerichten||[]).filter(m=>m.pid===p.id).sort((a,b)=>(a.d+(a.tijd||''))<(b.d+(b.tijd||''))?-1:1); const lm=msgs[msgs.length-1];
  const unans=lm&&lm.van==='klant'?lm:null; const vragen=(S.klantVerzoeken||[]).filter(v=>v.pid===p.id&&v.status!=='afgerond'&&v.status!=='gedaan');
  return {last,days:last?dagen(last,TODAY):null,unans,vragen,notes:(S.klantNotities||[]).filter(n=>n.pid===p.id)}; }
function pMat(p){ const pos=(S.pos||[]).filter(o=>o.pid===p.id); const sum=o=>(o.regels||[]).reduce((a,r)=>a+(+r.q||0)*(+r.p||0),0);
  const st=o=>o.status==='geleverd'||o.status==='ontvangen'?'geleverd':(o.levering&&o.levering<TODAY)?'te laat':(o.levering&&dagen(TODAY,o.levering)<=3)?'onderweg':'besteld';
  return pos.map(o=>({...o,st:st(o),som:sum(o)})); }
function pTeamWeek(p){ const m=monday(TODAY), e=addDays(m,6); const bl=S.blocks.filter(b=>b.pid===p.id&&b.start<=e&&b.end>=m); const by={}; for(const b of bl){ (by[b.emp]=by[b.emp]||[]).push(b); }
  const subs=(S.rfqs||[]).filter(r=>r.pid===p.id&&r.awardedTo&&(r.status==='gegund'||r.status==='afgerond')).map(r=>({s:sub(r.awardedTo),r})).filter(x=>x.s);
  return {emps:Object.entries(by).map(([id,b])=>({e:emp(id),b})),subs}; }
function pMoney(p){ const val=projectValue(p); const basis=p.offerte?(+p.offerte.basis||val):val; const inv=S.invoices.filter(i=>i.pid===p.id&&i.status!=='concept');
  const ter=(p.termijnen||[]).map((t,i)=>{ const f=inv.find(x=>x.termijn===i); const st=!f?'niet gefactureerd':f.status==='betaald'?'betaald':(f.verval&&f.verval<TODAY)?'vervallen':'verzonden'; return {...t,bedrag:basis*(+t.pct||0)/100,st,f}; });
  const opts=p.begroting?(p.begroting.options||[]):[]; const mwA=opts.filter(o=>o.s==='akkoord'), mwO=opts.filter(o=>o.s&&!['akkoord','afgewezen','vervallen'].includes(o.s));
  const k=p.begroting?calcB(p.begroting):null; const mwSum=k?k.meerwerk:0; const minder=(p.minderwerk||[]).filter(m=>m.status==='akkoord').reduce((s,m)=>s+(+m.bedrag||0),0);
  const over=inv.filter(i=>i.status!=='betaald'&&i.verval&&i.verval<TODAY); return {ter,mwA,mwO,mwSum,minder,over,fin:projectFin(p)}; }
function pDossier(p){ const t=(p.type||'').toLowerCase(); const bouw=/aanbouw|nieuwbouw|dakkapel|uitbouw/.test(t); const docs=[...(p.docs||[]),...allDocs().filter(d=>d.pid===p.id)]; const has=re=>docs.some(d=>re.test(d.naam)||re.test(d.cat||''));
  const k=S.kwal[p.id]; const out=[];
  if(p.phase>=4) out.push(['Aannemingsovereenkomst getekend',has(/overeenkomst/i)]);
  if(bouw&&p.phase>=3) out.push(['Omgevingsvergunning',has(/vergunning/i)||!!p.vergunning]);
  if(p.phase>=5) out.push(['V&G-plan uitvoering',has(/V&G/i)||!bouw]);
  if(k&&k.wkb) out.push(['Wkb-borgingsplan',!!(k.wkbChecks||[]).find(c=>/Borgingsplan/.test(c.t)&&c.ok)]);
  if(p.phase>=7) out.push(['Kwaliteitscontroles afgevinkt',!!(k&&k.checks.length&&k.checks.every(c=>c.ok))]);
  if(p.phase>=7){ out.push(['Opleverformulier getekend',!!(k&&k.getekend)]); out.push(['Garantie- en onderhoudsinfo',has(/garantie|onderhoud/i)]); }
  const punten=k?(k.punten||[]).filter(x=>x.status==='open'):[]; const sm=(S.service||[]).filter(s=>s.pid===p.id&&!['afgerond','gesloten'].includes(s.status));
  return {items:out,missing:out.filter(x=>!x[1]),punten,sm}; }
function pMilestones(p){ const ms=[]; const k=S.kwal[p.id];
  if(p.offerte&&p.offerte.accepted) ms.push({l:'Akkoord',d:p.offerte.accepted}); else if(p.offerte&&p.offerte.sent) ms.push({l:'Offerte verstuurd',d:p.offerte.sent});
  if(p.start) ms.push({l:'Start uitvoering',d:p.start});
  if(p.start&&p.eind){ const mid=addDays(p.start,Math.round(dagen(p.start,p.eind)*0.55)); ms.push({l:k&&k.wkb?'Tussentijdse Wkb-borging':'Tussencontrole',d:mid,done:p.progress>=55}); }
  if(p.eind){ if(k&&k.wkb) ms.push({l:'Gereedmelding gemeente',d:addDays(p.eind,-14),done:!!(k.wkbChecks||[]).find(c=>/Gereedmelding/.test(c.t)&&c.ok)}); ms.push({l:'Oplevering',d:p.eind,done:p.phase>=7}); ms.push({l:'Einde onderhoudstermijn',d:addDays(p.eind,90),done:p.phase>=8&&addDays(p.eind,90)<=TODAY}); }
  return ms.map(m=>({...m,done:m.done!==undefined?m.done:m.d<=TODAY})).sort((a,b)=>a.d<b.d?-1:1); }

/* kosten: nacalculatie als er een begroting is, anders de projectadministratie */
function pCost(p){ if(p.phase<4||p.lost) return null; if(p.begroting&&typeof nacalc==='function'){ const n=nacalc(p); if(n) return n; }
  const f=projectFin(p); const tb=f.begroot, tw=(f.werkelijk||0), tv=f.verwacht||tb; if(!tb) return null; const val=f.val||1;
  return {tb,tw,tv,afw:(tv-tb)/tb*100,margeB:(val-tb)/val*100,margeV:f.marge,bron:'administratie'}; }
/* ---- stoplichten ---- */
function health(p){ const H={};
  if(p.phase<4||p.lost) H.plan={s:'n',d:'Nog geen uitvoering gepland'};
  else{ const gap=(p.planned||0)-(p.progress||0); const late=p.eind&&p.eind<TODAY&&p.phase<7; const nb=S.blocks.filter(b=>b.pid===p.id&&b.end>=TODAY).length;
    if(p.phase>=7) H.plan={s:'g',d:p.phase===7?'In oplevering':'Opgeleverd'+(p.eind?' '+fmtD(p.eind):'')};
    else if(late) H.plan={s:'r',d:`Opleverdatum ${fmtD(p.eind)} verstreken`};
    else if(p.phase===6&&gap>=10) H.plan={s:'r',d:`${gap}% achter op planning`};
    else if(p.phase===6&&gap>=5) H.plan={s:'o',d:`${gap}% achter op planning`};
    else if(p.phase<=5&&p.start&&dagen(TODAY,p.start)<=10&&!nb) H.plan={s:'o',d:`Start ${fmtD(p.start)}, team nog niet ingepland`};
    else H.plan={s:'g',d:p.phase===6?`${p.progress}% gereed, plan ${p.planned}%`:(p.start?`Start ${fmtD(p.start)}`:'Op schema')}; }
  const nc=pCost(p);
  if(!nc) H.budget={s:'n',d:'Nog niet in opdracht'};
  else{ const a=nc.afw; H.budget={s:a>5||nc.margeV<5?'r':a>1?'o':'g',d:`Verwachte kosten ${a>0?'+':''}${NUM.format(Math.round(a*10)/10)}% · marge ${NUM.format(Math.round(nc.margeV))}%`,nc}; }
  const dz=pDossier(p); const k=S.kwal[p.id];
  if(p.phase<5&&!dz.sm.length) H.kwal={s:dz.missing.length?'o':'n',d:dz.missing.length?`${dz.missing.length} dossierstuk${dz.missing.length===1?'':'ken'} ontbreekt`:'Nog geen uitvoering'};
  else{ const afw=k?(k.afw||[]).filter(x=>x.status!=='gesloten').length:0; const n=dz.punten.length+dz.sm.length;
    H.kwal={s:afw||n>3||dz.missing.length>1?'r':n||dz.missing.length?'o':'g',d:[n?`${n} open restpunt${n===1?'':'en'}/meldingen`:'',dz.missing.length?`${dz.missing.length} dossierstuk${dz.missing.length===1?'':'ken'} ontbreekt`:'',afw?`${afw} afwijking${afw===1?'':'en'}`:''].filter(Boolean).join(' · ')||'Controles op orde'}; }
  const c=pContact(p);
  if(p.lost) H.klant={s:'n',d:'Verloren'};
  else{ const wait=c.unans?dagen(c.unans.d,TODAY):0;
    H.klant={s:wait>=2?'r':(c.vragen.length||c.unans||c.days===null||c.days>14)?'o':'g',d:c.unans?`Klantvraag ${wait?wait+' dag'+(wait===1?'':'en'):'vandaag'} onbeantwoord`:c.vragen.length?`${c.vragen.length} open verzoek${c.vragen.length===1?'':'en'} aan klant`:c.days!==null?(c.days>14?`${c.days} dagen geen klantcontact`:`Laatste contact ${c.days===0?'vandaag':c.days+' dagen geleden'}`):'Geen klantcontact vastgelegd'}; }
  const mon=pMoney(p); if(mon.over.length&&H.budget.s!=='r') H.budget={...H.budget,s:worst(H.budget.s,'o'),d:H.budget.d+` · ${mon.over.length} factuur vervallen`};
  H.all=worst(H.plan.s,H.budget.s,H.kwal.s,H.klant.s); return H; }
const dot=(s,t)=>`<span class="hl hl-${s}" title="${esc(t||LV[s].l)}"></span>`;
function lightsMini(p){ const H=health(p); return `<span class="hls">${[['plan','Planning'],['budget','Budget'],['kwal','Kwaliteit'],['klant','Klant']].map(([k,l])=>dot(H[k].s,`${l}: ${H[k].d}`)).join('')}</span>`; }

/* ---- blokkades en volgende acties ---- */
function pBlockers(p){ const b=[]; const mon=pMoney(p), c=pContact(p), mat=pMat(p), dz=pDossier(p);
  if(c.unans) b.push({t:`Klantvraag onbeantwoord: “${c.unans.txt.slice(0,70)}${c.unans.txt.length>70?'…':''}”`,eig:p.leider,k:'bad',i:'chat',act:`data-act="pdtab" data-t="klant" data-pid="${p.id}"`});
  for(const v of c.vragen) b.push({t:`Wacht op klant: ${v.titel}`,eig:'klant',k:'warn',i:'clock'});
  for(const o of mat.filter(x=>x.st==='te laat')) b.push({t:`Levering te laat: ${o.nr} ${o.lev} (was ${fmtD(o.levering)})`,eig:p.leider,k:'bad',i:'cart'});
  for(const i of mon.over) b.push({t:`Factuur ${i.nr} vervallen sinds ${fmtD(i.verval)} (${eur0(i.bedrag)})`,eig:'boekhouding',k:'bad',i:'euro'});
  for(const [l] of dz.missing) b.push({t:`Ontbreekt: ${l}`,eig:p.leider,k:'warn',i:'file'});
  for(const {s} of pTeamWeek(p).subs){ if(typeof subDossier==='function'){ const sd=subDossier(s); if(sd.open.length) b.push({t:`${s.naam}: ${sd.open.length} dossierpunt${sd.open.length===1?'':'en'} open`,eig:p.leider,k:'warn',i:'users'}); } }
  return b; }
function pNext(p){ return S.tasks.filter(t=>t.pid===p.id&&t.status!=='afgerond').sort((a,b)=>(a.dl||'9')<(b.dl||'9')?-1:1); }
const eigNm=id=>id==='klant'?'Klant':id==='boekhouding'?'Boekhouding':firstName(id);

/* ---- cockpit-HTML ---- */
function cockpit(p){ const H=health(p); const ms=pMilestones(p); const mon=pMoney(p); const mat=pMat(p); const tw=pTeamWeek(p); const c=pContact(p); const dz=pDossier(p);
  const rk=(S.risks[p.id]||[]).filter(r=>r.status==='open').sort((a,b)=>({hoog:0,midden:1,laag:2})[a.impact]-({hoog:0,midden:1,laag:2})[b.impact]); const nx=pNext(p).slice(0,5); const bl=pBlockers(p);
  const tile=(k,l,i)=>`<div class="ck-t ck-${H[k].s}"><span class="ck-i">${ic(i)}</span><div><span>${l}</span><b>${LV[H[k].s].l}</b><small>${esc(H[k].d)}</small></div></div>`;
  /* tijdlijn */
  let tl=''; if(ms.length>1){ const a=ms[0].d, z=ms[ms.length-1].d, span=Math.max(1,dagen(a,z)); const pos=d=>Math.max(0,Math.min(100,dagen(a,d)/span*100)); const tp=pos(TODAY);
    tl=`<div class="ck-tl"><div class="ck-line"><i style="width:${tp}%"></i></div>${TODAY>=a&&TODAY<=z?`<span class="ck-now" style="left:${tp}%"><b>Vandaag</b></span>`:''}${ms.map((m,i)=>`<div class="ck-ms ${m.done?'done':m.d<TODAY?'late':''} ${i%2?'dn2':''} ${i===0?'first':i===ms.length-1?'last':''}" style="left:${pos(m.d)}%"><span class="ck-pt">${m.done?ic('check'):''}</span><div><b>${esc(m.l)}</b><small>${fmtD(m.d)}</small></div></div>`).join('')}</div>`; }
  /* budget vs voortgang */
  const nc=H.budget.nc; const burn=nc?Math.round(nc.tw/Math.max(1,nc.tb)*100):0; const prog=p.progress||0;
  const bud=nc?`<div class="ck-bv"><div><div class="row between"><span>Voortgang</span><b>${prog}%</b></div><div class="bar"><i style="width:${prog}%"></i></div></div>
    <div><div class="row between"><span>Budget verbruikt</span><b class="${burn>prog+10?'dn':''}">${burn}%</b></div><div class="bar ck-burn ${burn>prog+10?'over':burn>prog?'warn':''}"><i style="width:${Math.min(100,burn)}%"></i></div></div>
    <div class="sumrow"><span class="muted">Begroot · werkelijk · prognose</span><span class="num">${eur0(nc.tb)} · ${eur0(nc.tw)} · <b>${eur0(nc.tv)}</b></span></div>
    <div class="sumrow"><span class="muted">Marge begroot → verwacht</span><span class="num">${NUM.format(Math.round(nc.margeB))}% → <b class="${nc.margeV<nc.margeB-2?'dn':'up'}">${NUM.format(Math.round(nc.margeV))}%</b></span></div></div>`:`<p class="muted">Nog geen kosten om te vergelijken.</p>`;
  const stPill={'betaald':'ok','verzonden':'blue','vervallen':'bad','niet gefactureerd':'mut','geleverd':'ok','onderweg':'blue','besteld':'mut','te laat':'bad'};
  const geld=`${mon.ter.length?mon.ter.map(t=>`<div class="sumrow"><span>${esc(t.oms)} <small class="muted">${t.pct}%</small></span><span class="row" style="gap:6px"><span class="num">${eur0(t.bedrag)}</span><span class="pill ${stPill[t.st]}">${t.st}</span></span></div>`).join(''):'<p class="muted">Geen termijnen afgesproken.</p>'}
    <div class="sumrow sub"><span>Meerwerk akkoord</span><span class="num">${mon.mwSum?'+ '+eur0(mon.mwSum):'—'}</span></div>${mon.mwO.length?`<div class="sumrow"><span class="muted">Meerwerk wacht op akkoord</span><span class="pill warn">${mon.mwO.length}</span></div>`:''}${mon.minder?`<div class="sumrow"><span class="muted">Minderwerk akkoord</span><span class="num">− ${eur0(mon.minder)}</span></div>`:''}
    <div class="sumrow"><span class="muted">Betaald / gefactureerd</span><span class="num"><b class="up">${eur0(mon.fin.betaald)}</b> / ${eur0(mon.fin.gefact)}</span></div>`;
  const matH=mat.length?`<div class="ck-cnt">${['besteld','onderweg','geleverd','te laat'].map(s=>`<span class="pill ${stPill[s]}">${mat.filter(o=>o.st===s).length} ${s}</span>`).join('')}</div>${mat.slice(0,4).map(o=>`<div class="li"><span class="ic ${o.st==='te laat'?'bad':o.st==='geleverd'?'ok':'blue'}">${ic('cart')}</span><div class="tx"><b>${esc(o.lev)}</b><small>${o.nr} · levering ${fmtD(o.levering)} · ${eur0(o.som)}</small></div><span class="pill ${stPill[o.st]}">${o.st}</span></div>`).join('')}`:`<div class="empty sm">Nog geen inkooporders.<a class="btn sm" href="/inkoop">Inkoop</a></div>`;
  const team=tw.emps.length||tw.subs.length?`${tw.emps.map(({e,b})=>`<div class="li">${avatar(e.naam,'sm')}<div class="tx"><b>${esc(e.naam)}</b><small>${b.map(x=>`${esc(x.titel)} ${fmtD(x.start<monday(TODAY)?monday(TODAY):x.start)}${x.end!==x.start?'–'+fmtD(x.end):''}`).join(' · ')}</small></div>${(e.certs||[]).length&&typeof certChip==='function'?`<span class="cdots">${e.certs.slice(0,3).map(cc=>certChip(cc,true)).join('')}</span>`:''}</div>`).join('')}${tw.subs.map(({s,r})=>`<div class="li"><span class="sc-logo sm" style="--ac:${typeof waCol==='function'?waCol(s.naam):'#3E6BA8'}">${esc(s.naam.split(' ').map(w=>w[0]).join('').slice(0,2))}</span><div class="tx"><b>${esc(s.naam)}</b><small>Onderaannemer · ${esc(r.titel)}</small></div></div>`).join('')}`:`<div class="empty sm">Deze week niemand ingepland.<button class="btn sm" data-act="newblock" data-pid="${p.id}">Inplannen</button></div>`;
  const risks=`${rk.length?rk.map(r=>`<div class="li"><span class="ic ${r.impact==='hoog'?'bad':r.impact==='midden'?'warn':'blue'}">${ic('alert')}</span><div class="tx"><b>${esc(r.t)}</b><small>${esc(r.maat||'')}${r.maat?' · ':''}eigenaar ${esc(eigNm(r.eig))}</small></div><button class="btn xs ghost" data-act="rk-close" data-pid="${p.id}" data-id="${r.id}" title="Risico afsluiten">${ic('check')}</button></div>`).join(''):'<p class="muted" style="margin:6px 0">Geen open risico’s.</p>'}`;
  const klant=`<div class="sumrow"><span class="muted">Laatste contact</span><b class="${c.days>10?'dn':''}">${c.last?(c.days===0?'Vandaag':c.days===1?'Gisteren':c.days+' dagen geleden'):'—'}</b></div>
    ${c.unans?`<div class="ck-q bad">${ic('chat')}<div><b>${esc(c.unans.naam||'Klant')} wacht op antwoord</b><small>“${esc(c.unans.txt)}” · ${fmtD(c.unans.d)}</small></div></div>`:''}
    ${c.vragen.map(v=>`<div class="ck-q">${ic('clock')}<div><b>${esc(v.titel)}</b><small>Wacht op klant${v.oms?' · '+esc(v.oms):''}</small></div></div>`).join('')}
    ${c.notes.slice(-1).map(n=>`<div class="ck-q mut">${ic('pen')}<div><b>Nog navragen</b><small>${esc(n.txt)}</small></div></div>`).join('')}
    <div class="row" style="margin-top:8px"><button class="btn sm" data-act="mailklant" data-pid="${p.id}">${ic('mail')}Klant informeren</button></div>`;
  const dos=`${dz.items.length?dz.items.map(([l,ok])=>`<div class="ck-dz ${ok?'ok':'no'}">${ic(ok?'check':'x')}<span>${esc(l)}</span></div>`).join(''):'<p class="muted">Nog geen verplichte stukken in deze fase.</p>'}
    ${dz.punten.length||dz.sm.length?`<div class="sumrow sub"><span>Restpunten en meldingen</span><span class="pill warn">${dz.punten.length+dz.sm.length} open</span></div>${[...dz.punten.map(x=>x.t||x.oms||'Restpunt'),...dz.sm.map(s=>s.nr+' '+s.titel)].slice(0,3).map(t=>`<small class="muted" style="display:block">• ${esc(t)}</small>`).join('')}`:''}`;
  const acts=`${bl.length?`<span class="lbl" style="color:var(--bad)">Blokkades</span>${bl.slice(0,4).map(b=>`<div class="li"><span class="ic ${b.k==='bad'?'bad':'warn'}">${ic(b.i)}</span><div class="tx"><b>${esc(b.t)}</b><small>Eigenaar: ${esc(eigNm(b.eig))}</small></div>${b.act?`<button class="btn xs" ${b.act}>Open</button>`:''}</div>`).join('')}`:''}
    <span class="lbl" style="margin-top:${bl.length?10:0}px">Volgende acties</span>${nx.length?nx.map(t=>`<div class="li"><span class="ic ${t.dl&&t.dl<TODAY?'bad':t.dl===TODAY?'warn':'blue'}">${ic('checksq')}</span><div class="tx"><b>${esc(t.titel)}</b><small>${esc(eigNm(t.eig))} · ${t.dl?(t.dl<TODAY?'te laat, was '+fmtD(t.dl):t.dl===TODAY?'vandaag':fmtD(t.dl)):'geen datum'}</small></div></div>`).join(''):'<p class="muted" style="margin:6px 0">Geen open taken.</p>'}
    <button class="btn sm" data-act="newtask" data-pid="${p.id}" style="margin-top:8px">${ic('plus')}Taak</button>`;
  return `<section class="ck" id="ck-${p.id}">
    <div class="ck-head"><div><span class="eyebrow">Projectcockpit</span><h3>In één oogopslag</h3></div><span class="pill ${LV[H.all].c} ck-all">${dot(H.all)}${H.all==='r'?'Actie nodig':H.all==='o'?'Aandacht nodig':H.all==='g'?'Alles op koers':'Nog in voorbereiding'}</span></div>
    <div class="ck-tiles">${tile('plan','Planning','cal')}${tile('budget','Budget','euro')}${tile('kwal','Kwaliteit','checksq')}${tile('klant','Klant','chat')}</div>
    ${tl?`<div class="card ck-c ck-wide"><div class="card-h"><h3>Mijlpalen</h3><small class="muted">${p.start?fmtDY(p.start):''}${p.eind?' → '+fmtDY(p.eind):''}</small></div><div class="card-b">${tl}</div></div>`:''}
    <div class="ck-grid">
      <div class="card ck-c"><div class="card-h"><h3>Acties en blokkades</h3>${bl.length?`<span class="pill bad">${bl.length}</span>`:''}</div><div class="card-b">${acts}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Budget tegenover voortgang</h3><button class="btn xs ghost" data-act="pdtab" data-t="nacalculatie" data-pid="${p.id}">Nacalculatie</button></div><div class="card-b">${bud}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Termijnen en meerwerk</h3><button class="btn xs ghost" data-act="pdtab" data-t="financien" data-pid="${p.id}">Financiën</button></div><div class="card-b">${geld}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Team deze week</h3><small class="muted">wk ${typeof wkNo==='function'?wkNo(TODAY):''}</small></div><div class="card-b" style="padding-block:4px">${team}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Materiaal</h3><button class="btn xs ghost" data-act="pdtab" data-t="inkoop" data-pid="${p.id}">Inkoop</button></div><div class="card-b" style="padding-block:4px">${matH}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Risico’s</h3><button class="btn xs" data-act="rk-new" data-pid="${p.id}">${ic('plus')}Risico</button></div><div class="card-b" style="padding-block:4px">${risks}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Klant</h3><small class="muted">${esc(client(p.clientId).naam)}</small></div><div class="card-b">${klant}</div></div>
      <div class="card ck-c"><div class="card-h"><h3>Dossier en restpunten</h3>${dz.missing.length?`<span class="pill warn">${dz.missing.length} ontbreekt</span>`:'<span class="pill ok">Compleet</span>'}</div><div class="card-b">${dos}</div></div>
    </div>
    <div class="ck-sep"><span>Projectgegevens</span></div></section>`; }

const _pdTabR16=pdTab; pdTab=function(p,tab){ const h=_pdTabR16(p,tab); if(tab!=='overzicht'||p.lost||p.closed) return h; return cockpit(p)+h; };

/* ---- risico toevoegen / sluiten ---- */
function mRisk(pid){ const p=proj(pid); modal('Risico toevoegen',`<form class="fg" data-form="risk" data-pid="${pid}"><div class="f full"><label for="rk-t">Risico of issue</label><input class="in" id="rk-t" name="t" required placeholder="Bijv. levertijd kozijnen loopt uit"></div>
  <div class="f"><label for="rk-i">Impact</label><select class="in" id="rk-i" name="impact"><option value="hoog">Hoog</option><option value="midden" selected>Midden</option><option value="laag">Laag</option></select></div>
  <div class="f"><label for="rk-e">Eigenaar</label><select class="in" id="rk-e" name="eig">${S.emps.filter(e=>e.type!=='partner').map(e=>`<option value="${e.id}" ${e.id===p.leider?'selected':''}>${esc(e.naam)}</option>`).join('')}</select></div>
  <div class="f full"><label for="rk-m">Maatregel</label><input class="in" id="rk-m" name="maat" placeholder="Wat doen we om het te voorkomen?"></div></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Opslaan</button>`); }
R2_FORMS.risk=(f,v)=>{ if(!v.t) return fieldErr(f,'t','Beschrijf het risico.'); const pid=f.dataset.pid; (S.risks[pid]=S.risks[pid]||[]).unshift({id:'rk'+uid('').slice(-6),t:v.t,impact:v.impact,eig:v.eig,maat:v.maat,status:'open',d:TODAY});
  const p=proj(pid); p.activity.unshift({d:TODAY,t:`Risico vastgelegd: ${v.t}`,k:'warn'}); closeModal(); commit('Risico toegevoegd'); };
document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const d=el.dataset;
  if(d.act==='rk-new') mRisk(d.pid);
  else if(d.act==='rk-close'){ const r=(S.risks[d.pid]||[]).find(x=>x.id===d.id); if(r){ r.status='gesloten'; r.closed=TODAY; proj(d.pid).activity.unshift({d:TODAY,t:`Risico afgesloten: ${r.t}`,k:'ok'}); commit('Risico afgesloten'); } }
  else if(d.act==='pf-f'){ UI.pfF=d.v; render(); }
  else if(d.act==='pf-sort'){ UI.pfSort=d.v; render(); } });

/* ---- portfolio ---- */
function vPortfolio(){ const all=S.projects.filter(p=>!p.lost&&!p.closed&&p.phase>=4); const f=UI.pfF||'alle';
  const rows=all.map(p=>({p,H:health(p),ms:pMilestones(p).find(m=>!m.done),fin:projectFin(p),nc:pCost(p),bl:pBlockers(p)}));
  const cnt=s=>rows.filter(r=>r.H.all===s).length; const list=rows.filter(r=>f==='alle'||(f==='rood'&&r.H.all==='r')||(f==='aandacht'&&r.H.all!=='g')||(f==='uitv'&&r.p.phase===6));
  const so=UI.pfSort||'ernst'; list.sort((a,b)=>so==='ernst'?(LV_RANK[b.H.all]-LV_RANK[a.H.all])||(b.bl.length-a.bl.length):so==='oplevering'?((a.p.eind||'9')<(b.p.eind||'9')?-1:1):so==='waarde'?b.fin.val-a.fin.val:((b.p.planned||0)-(b.p.progress||0))-((a.p.planned||0)-(a.p.progress||0)));
  const voorraad=rows.reduce((s,r)=>s+Math.max(0,r.fin.val*(1-(r.p.progress||0)/100)),0); const open=rows.reduce((s,r)=>s+r.fin.open,0);
  const cell=(H,k)=>`<td class="pf-l" data-k="${k}">${dot(H[k].s,H[k].d)}<small>${esc(H[k].d)}</small></td>`;
  return `<div class="page"><div class="ph"><div><h1>Project<em>portfolio</em></h1><p>Alle lopende projecten met stoplichten voor planning, budget, kwaliteit en klant. Rood staat bovenaan.</p></div></div>
  <div class="grid g4 pf-kpi"><button class="card kpi dark" data-act="pf-f" data-v="alle"><span class="lbl">Projecten in opdracht</span><span class="v num">${rows.length}</span><span class="s">${heur(voorraad)} werkvoorraad</span></button>
    <button class="card kpi pf-r ${f==='rood'?'on':''}" data-act="pf-f" data-v="rood"><span class="lbl">${dot('r')} Actie nodig</span><span class="v num">${cnt('r')}</span><span class="s">minstens één rood stoplicht</span></button>
    <button class="card kpi pf-o ${f==='aandacht'?'on':''}" data-act="pf-f" data-v="aandacht"><span class="lbl">${dot('o')} Aandacht</span><span class="v num">${cnt('o')}</span><span class="s">oranje, nog geen rood</span></button>
    <div class="card kpi"><span class="lbl">${dot('g')} Op koers</span><span class="v num">${cnt('g')}</span><span class="s">${eur0(open)} openstaand gefactureerd</span></div></div>
  <div class="row between wrap pf-bar"><div class="seg">${[['alle','Alle'],['rood','Rood'],['aandacht','Rood + oranje'],['uitv','In uitvoering']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="pf-f" data-v="${k}">${l}</button>`).join('')}</div>
    <label class="row" style="gap:6px;font-size:13px">Sorteer <select class="in sm" data-pfsort="1">${[['ernst','Ernst'],['oplevering','Oplevering'],['achterstand','Achterstand'],['waarde','Waarde']].map(([k,l])=>`<option value="${k}" ${so===k?'selected':''}>${l}</option>`).join('')}</select></label></div>
  <div class="card pf-tbl"><table class="t"><thead><tr><th>Project</th><th>Planning</th><th>Budget</th><th>Kwaliteit</th><th>Klant</th><th>Voortgang</th><th>Volgende mijlpaal</th><th>Grootste blokkade</th></tr></thead><tbody>
  ${list.map(({p,H,ms,nc,bl})=>`<tr class="pf-row hl-row-${H.all}" data-go="project-${p.id.toLowerCase()}"><td><div class="pf-p">${dot(H.all)}<div><b>${esc(p.naam)}</b><small>${p.id} · ${esc(client(p.clientId).naam)} · ${esc(firstName(p.leider))}</small></div></div></td>
    ${cell(H,'plan')}${cell(H,'budget')}${cell(H,'kwal')}${cell(H,'klant')}
    <td><div class="pf-pg"><div class="bar"><i style="width:${p.progress||0}%"></i>${p.phase===6?`<u style="left:${p.planned||0}%" title="Planning ${p.planned}%"></u>`:''}</div><small>${p.phase===6?`${p.progress}% · plan ${p.planned}%`:PHASES[p.phase]}</small>${nc?`<small class="${nc.tw/Math.max(1,nc.tb)*100>(p.progress||0)+10?'dn':'muted'}">budget ${Math.round(nc.tw/Math.max(1,nc.tb)*100)}% verbruikt</small>`:''}</div></td>
    <td>${ms?`<b>${esc(ms.l)}</b><small class="${ms.d<TODAY?'dn':'muted'}" style="display:block">${fmtD(ms.d)}${ms.d<TODAY?' · verlopen':` · over ${dagen(TODAY,ms.d)} d`}</small>`:'—'}</td>
    <td>${bl[0]?`<span class="pf-bl ${bl[0].k}">${esc(bl[0].t)}</span>${bl.length>1?`<small class="muted"> +${bl.length-1}</small>`:''}`:'<span class="muted">Geen</span>'}</td></tr>`).join('')||`<tr><td colspan="8"><div class="empty">Geen projecten in dit filter.</div></td></tr>`}
  </tbody></table></div>
  <p class="muted" style="font-size:12px;margin-top:10px">Stoplichten worden berekend uit planning (voortgang tegenover plan, opleverdatum), nacalculatie (verwachte kosten en marge), kwaliteit (restpunten, meldingen, ontbrekende dossierstukken) en klantcontact (onbeantwoorde vragen, open verzoeken, dagen sinds contact).</p></div>`; }
Object.assign(R2_ROUTES,{portfolio:()=>vPortfolio()});
{ const s=SECTIONS.find(x=>x.id==='projecten'); if(s&&!s.r.some(r=>r[0]==='portfolio')) s.r.splice(1,0,['portfolio','Portfolio']); }
for(const rol in PERM){ const a=PERM[rol]; if(Array.isArray(a)&&a.includes('projecten')&&!a.includes('portfolio')) a.push('portfolio'); }
NAV.find(g=>(g.items||[]).some(i=>i[0]==='projecten'))?.items.push(['portfolio','Portfolio','chart']);
document.addEventListener('click',e=>{ const tr=e.target.closest&&e.target.closest('tr.pf-row[data-go]'); if(tr&&!e.target.closest('a,button')){ go(tr.dataset.go); } });

/* stoplichten op projectkaarten */
const _renderR16=render; render=function(...a){ const r=_renderR16.apply(this,a); if(route()==='projecten') document.querySelectorAll('#view .pcard[data-go^="project-"]').forEach(cd=>{ if(cd.querySelector('.hls')) return; const p=proj(cd.dataset.go.slice(8).toUpperCase()); if(!p||p.phase<4||p.lost||p.closed) return; const row=cd.querySelector('.row.between'); row&&row.insertAdjacentHTML('afterend',`<div class="row between pc-h"><span class="muted" style="font-size:12px">Planning · budget · kwaliteit · klant</span>${lightsMini(p)}</div>`); });
  if(route()==='projecten'&&!$('#pfbtn')){ const ph=document.querySelector('#view .page > .ph'); ph&&ph.lastElementChild&&ph.lastElementChild.insertAdjacentHTML('beforebegin',`<a class="btn" id="pfbtn" href="/portfolio">${ic('chart')}Portfolio met stoplichten</a>`); }
  return r; };

/* Nova */
const _novaR2R16=novaR2; novaR2=function(t){ if(/(portfolio|stoplicht|welke projecten.*(rood|achter|aandacht)|projecten.*rood)/.test(t)){ const rs=S.projects.filter(p=>!p.lost&&!p.closed&&p.phase>=4).map(p=>({p,H:health(p)})).filter(x=>x.H.all==='r');
  novaSay(`<b>${rs.length} ${rs.length===1?'project staat':'projecten staan'} op rood</b><br>${rs.map(({p,H})=>`• ${esc(p.naam)}: ${esc([['plan','planning'],['budget','budget'],['kwal','kwaliteit'],['klant','klant']].filter(([k])=>H[k].s==='r').map(([k,l])=>l+' ('+H[k].d+')').join(', '))}`).join('<br>')||'Geen rode projecten.'}<br><a href="/portfolio" data-act="nclose">Naar portfolio</a>`); return true; } return _novaR2R16(t); };


