function crTasks(){ const R=UI.callRep; const on=[...document.querySelectorAll('[data-cra]')].filter(x=>x.checked).map(x=>+x.dataset.cra); const acts=R.notes.filter(n=>n.k==='actie'); let n=0;
  on.forEach(i=>{ const a=acts[i]; if(!a) return; S.tasks.push({id:uid('t'),titel:a.t,pid:R.pid||'',eig:emp(a.eig)?a.eig:ME,dl:a.dl||addWd(TODAY,2),status:'open',prio:'normaal',oms:`Uit gesprek ${R.klant?'':'#'}${R.chNaam} op ${fmtD(R.d)}`,checklist:[],fromCall:true}); n++; }); return n; }
