document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act^="call-"],[data-act^="cr-"]'); if(!el) return; const a=el.dataset.act;
  if(a==='call-video'||a==='call-audio'){ e.stopPropagation(); callStart(el.dataset.ch,a==='call-video'); return; }
  if(!CALL&&a.startsWith('call-')) return; const C=CALL;
  if(a==='call-mic'){ C.mic=!C.mic; C.stream&&C.stream.getAudioTracks().forEach(t=>t.enabled=C.mic); if(!C.mic){ try{ C.rx&&C.rx.stop(); }catch(_){} } else if(C.rec&&C.srOn){ try{ C.rx.start(); }catch(_){} } callRender(); }
  else if(a==='call-cam'){ C.cam=!C.cam; C.stream&&C.stream.getVideoTracks().forEach(t=>t.enabled=C.cam); callRender(); }
  else if(a==='call-share'){ if(navigator.mediaDevices&&navigator.mediaDevices.getDisplayMedia) navigator.mediaDevices.getDisplayMedia({video:true}).then(s=>{ toast('Je deelt je scherm'); s.getVideoTracks()[0].onended=()=>toast('Scherm delen gestopt'); C.share=s; }).catch(()=>toast('Scherm delen is in deze weergave niet toegestaan','warn')); else toast('Scherm delen wordt hier niet ondersteund','warn'); }
  else if(a==='call-side'){ C.side=!C.side; callRender(); }
  else if(a==='call-rec'){ C.rec=!C.rec; if(C.rec){ C.side=true; C.srOn=recStartSR(); C.lines.push({wie:'Nova',id:'nova',t:cNow(),txt:'Opname en notulen gestart. Alle deelnemers zijn geïnformeerd.'});  } else { try{ C.rx&&C.rx.stop(); }catch(_){} C.lines.push({wie:'Nova',id:'nova',t:cNow(),txt:'Opname gestopt.'}); } callRender(); }
  else if(a==='call-link'){ const link=`https://meet.renovion.nl/${(C.ch.pid||'gesprek').toLowerCase()}-${uid('').slice(-5)}`; try{ navigator.clipboard.writeText(link); toast('Uitnodigingslink gekopieerd'); }catch(_){ toast(link); } }
  else if(a==='call-end'){ const ended=callStop(); if(ended) callReport(ended); }
  else if(a==='cr-save'){ const R=UI.callRep; const n=crTasks(); if(!R.klant) S.chat.msgs.push({id:uid('m'),ch:R.ch,van:'nova',txt:`**Gespreksverslag ${fmtD(R.d)} (${R.dur})**\n${R.sum}${R.notes.filter(x=>x.k==='actie').length?'\nActies: '+R.notes.filter(x=>x.k==='actie').map(x=>x.t+' ('+(firstName(x.eig)||'—')+')').join('; '):''}`,d:R.d,tijd:R.t,pinned:false,replies:[],att:{naam:`Transcript ${fmtD(R.d)}.txt`}}); crDossier();
    closeModal(); commit(`Verslag opgeslagen${n?` · ${n} ${n===1?'taak':'taken'} aangemaakt`:''}`); }
  else if(a==='cr-dossier'){ crDossier(); toast('Verslag toegevoegd aan het projectdossier'); el.disabled=true; } },true);
document.addEventListener('keydown',e=>{ if(CALL&&e.key==='Escape'){ e.stopPropagation(); } },true);

