{ const _m=menuAt; menuAt=function(el,html,...r){ if(html.includes('data-act="newlead"')&&!html.includes('mr-open')) html=html.replace('<hr>',`<button data-act="mr-open">${ic('rec')}Meeting opnemen (Nova)</button><button data-act="ncal-open">${ic('spark')}Calculatie met Nova</button><hr>`); return _m(el,html,...r); }; }
{ const _r=render; render=function(...a){ const r=_r.apply(this,a); if(route().startsWith('project-')){ const acts=document.querySelector('#view .band .acts'); if(acts&&!acts.querySelector('[data-act="mr-open"]')){ const pid=(acts.querySelector('[data-pid]')||{}).dataset?.pid; acts.insertAdjacentHTML('afterbegin',`<button class="btn onnavy" data-act="mr-open" data-pid="${pid||''}">${ic('rec')}Opnemen</button>`); } } if(MR&&!$('#mrec')) mrRender(); return r; }; }
{ const _n=novaR2; novaR2=function(t){ if(/(neem .*op|opnemen|opname|meeting|vergadering|notuleer|transcribeer)/.test(t)&&!/videobel|beeldbel/.test(t)){ setTimeout(()=>{ try{ closeNova(); }catch(_){} mMeetStart(); },50); novaSay('Ik start de meeting-opname. Vink aan wie er bij zijn en bevestig dat iedereen akkoord is.'); return true; } return _n(t); }; }


