 sloop:[['Leidingen en elektra veilig afsluiten','Water dicht, groep uit, gas afgesloten waar nodig',true],['Slopen volgens tekening','Alleen wat op de werkomschrijving staat',false],['Asbestverdacht materiaal? Stop en meld','Twijfel = niet doorwerken, maak een melding',false],['Afval scheiden en in container','Puin, hout en restafval apart',false]],
 tegel:[['Ondergrond controleren','Vlak, droog en draagkrachtig; maak een foto',true],['Waterdichting en kitband aanbrengen','Hoeken en doorvoeren; foto verplicht (Wkb)',true],['Afschot vloer meten','Naar de goot, minimaal 1%; foto met waterpas',true],['Tegels zetten volgens legplan','Startlijn en verdeling volgens tekening',false],['Voegen en kitten','Sanitairkit in hoeken en bij aansluitingen',false]],
 elektra:[['Groep spanningsloos en gemeten','Foto van de meetwaarde',true],['Kabels trekken en dozen plaatsen','Volgens installatietekening',false],['Aardlek testen','Foto van de testwaarde',true],['Meetrapport invullen','Isolatieweerstand en aardlek',false],['Afmonteren schakelaars en wcd’s','Recht en strak tegen de wand',false]],
