 schilder:[['Ondergrond voorbereiden','Schuren, ontvetten, stofvrij',false],['Plamuren en bijwerken','Gaten en naden',false],['Grondlaag aanbrengen','',false],['Aflakken in twee lagen','Droogtijd tussen de lagen aanhouden',false]],
 ruwbouw:[['Maatvoering controleren','Met tekening en peil',false],['Wapening controleren vóór storten','Foto verplicht (Wkb)',true],['Storten of metselen','Volgens bestek',false],['Eindcontrole maat en peil','Afwijkingen melden',true]],
