function ktFor(titel,p){ const t=((titel||'')+' '+((p&&p.type)||'')).toLowerCase(); const keys=[];
  if(/sloop/.test(t)) keys.push('sloop'); if(/tegel/.test(t)) keys.push('tegel'); if(/elektra|elektr/.test(t)) keys.push('elektra'); if(/afvoer|douchegoot|leiding|installatie|sanitair/.test(t)) keys.push('leiding');
  if(/voorzet|plafond|timmer|wand|interieur/.test(t)&&!keys.includes('tegel')) keys.push('timmer'); if(/kozijn/.test(t)) keys.push('kozijn'); if(/schilder|afwerking/.test(t)) keys.push('schilder'); if(/ruwbouw|fundering|metsel/.test(t)) keys.push('ruwbouw');
  if(/dak/.test(t)) keys.push('dak'); if(/bestrating|tuin/.test(t)) keys.push('bestrating'); if(/toezicht|inventarisatie/.test(t)) keys.push('toezicht'); if(!keys.length) keys.push(/badkamer/.test(t)?'timmer':'toezicht');
  return [['Aanmelden bij klant of bouwplaats','Stel je voor en vraag naar bijzonderheden',false],['Werkplek beschermen','Vloeren en looproute afdekken; foto',true],...keys.slice(0,2).flatMap(k=>KT[k]),['Opruimen en afval afvoeren','Werkplek bezemschoon achterlaten',false],['Eindfoto’s maken','Overzicht van het resultaat',true],['Kort afstemmen met de klant','Laat zien wat er gedaan is',false]].map(([t,h,f])=>({t,h,f,done:false,fotos:[],note:''})); }
const LMRA=['Ik weet wat ik moet doen en hoe','Gereedschap en persoonlijke beschermingsmiddelen zijn in orde','De werkplek is veilig (stroom, gas, water, valgevaar)','Ik weet wie ik bel bij nood','Geen onbekende risico’s (asbest, instabiele constructie)'];
const MELD=[['probleem','Probleem of afwijking','alert','bad'],['meerwerk','Klant vraagt meerwerk','euro','vio'],['materiaal','Materiaal tekort of fout','cart','warn'],['schade','Schade','hammer','bad'],['onveilig','Onveilige situatie','flag','bad'],['vraag','Vraag aan uitvoerder','chat','blue']];
