/* ---------- Ronde 27 · Beweging: pagina's bouwen zich op, cijfers tellen op, pillen schuiven, kaarten zoomen open ---------- */
const MO={last:null,zoom:null,pills:{}};
const moPref=()=>{ try{ return localStorage.getItem('rn-motion')!=='uit'; }catch(e){ return true; } };
const moOn=()=>moPref()&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
document.documentElement.classList.toggle('os-motion-off',!moPref());
const MO_BLOCK='.band,.stepper,.ac-welcome,.novaline,.kpi,.card,.uv-card,.kb-col,.ck-t,.scard,.ac-tc,.ks,.alert,.kl-card';
function moStagger(){
  const v=$('#view'); if(!v) return; const H=innerHeight+80;
  const all=[...v.querySelectorAll(MO_BLOCK)].filter(e=>!e.parentElement.closest(MO_BLOCK.replace(/,\.kpi|,\.uv-card|,\.ck-t|,\.kb-col/g,''))||e.matches('.kpi,.uv-card,.ck-t'));
  let i=0;
  all.forEach(e=>{ const t=e.getBoundingClientRect().top; if(t>H||i>12) return;
    const sib=[...e.parentElement.children].filter(x=>x.matches(MO_BLOCK)); const n=sib.length, k=sib.indexOf(e);
    const fan=e.matches('.kpi,.uv-card,.ck-t,.kb-col')&&n>1;
    e.style.setProperty('--mo-d',(i++*28)+'ms'); e.style.setProperty('--mo-r',fan?((k-(n-1)/2)*2.4)+'deg':'0deg'); e.style.setProperty('--mo-y',fan?(28+Math.abs(k-(n-1)/2)*10)+'px':'14px');
    e.classList.add('mo-in'); e.addEventListener('animationend',()=>e.classList.remove('mo-in'),{once:true}); });
}
function moCount(){
  document.querySelectorAll('#view .kpi .v, #view .ck-big').forEach((el,ix)=>{
    const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT); let n; while((n=w.nextNode())&&!/\d/.test(n.nodeValue));
    if(!n) return; const m=n.nodeValue.match(/\d[\d.]*(,\d+)?/); if(!m||/:/.test(n.nodeValue)) return;
    const raw=m[0], dec=m[1]?m[1].length-1:0, grp=raw.includes('.'), val=parseFloat(raw.replace(/\./g,'').replace(',','.')); if(!isFinite(val)||val===0) return;
    const pre=n.nodeValue.slice(0,m.index), post=n.nodeValue.slice(m.index+raw.length), fmt=x=>x.toLocaleString('nl-NL',{minimumFractionDigits:dec,maximumFractionDigits:dec,useGrouping:grp});
    const T=550+Math.min(ix,4)*60, t0=performance.now()+60+ix*40, node=n;
    node.nodeValue=pre+fmt(0)+post;
    const step=t=>{ const p=Math.max(0,Math.min(1,(t-t0)/T)), e=1-Math.pow(1-p,4); node.nodeValue=pre+fmt(p<1?val*e:val)+post; if(p<1) requestAnimationFrame(step); };
    requestAnimationFrame(step); });
}
function moPillKey(c){ return c.className.split(' ')[0]+'|'+[...c.children].map(x=>x.textContent.trim().slice(0,14)).join('|'); }
function moPillSnap(){ MO.pills={}; document.querySelectorAll('#view .sectabs, #view .seg, #view .tabs').forEach(c=>{ const on=c.querySelector('.on,[aria-current="page"]'); if(!on) return; const cr=c.getBoundingClientRect(), r=on.getBoundingClientRect(); MO.pills[moPillKey(c)]={x:r.left-cr.left+c.scrollLeft,w:r.width}; }); }
function moPillSlide(){
  document.querySelectorAll('#view .sectabs, #view .seg, #view .tabs').forEach(c=>{ const on=c.querySelector('.on,[aria-current="page"]'); const old=MO.pills[moPillKey(c)]; if(!on||!old) return;
    const cs=getComputedStyle(on); let bg=cs.backgroundColor; const bw=parseFloat(cs.borderBottomWidth)||0; const line=(!bg||bg==='rgba(0, 0, 0, 0)'||bg==='transparent');
    if(line){ if(!bw) return; bg=cs.borderBottomColor; }
    const cr=c.getBoundingClientRect(), r=on.getBoundingClientRect(), nx=r.left-cr.left+c.scrollLeft; if(Math.abs(nx-old.x)<2) return;
    if(getComputedStyle(c).position==='static') c.style.position='relative';
    const p=document.createElement('span'); p.className='mo-pill'+(line?' mo-line':''); Object.assign(p.style,{left:old.x+'px',width:old.w+'px',top:(line?r.bottom-cr.top-bw:r.top-cr.top)+'px',height:(line?bw:r.height)+'px',background:bg,borderRadius:line?'2px':cs.borderRadius});
    c.prepend(p); on.classList.add('mo-ghost'); p.getBoundingClientRect();
    requestAnimationFrame(()=>{ p.style.left=nx+'px'; p.style.width=r.width+'px'; });
    setTimeout(()=>{ on.classList.remove('mo-ghost'); p.remove(); },360); });
}
function moZoom(){
  MO.zoom=null; return; /* geen uitrekkende zoom van kaart naar pagina */
  const z=MO.zoom; if(!z||performance.now()-z.t>900) return;
  const tg=$('#view .band')||$('#view .card'); if(!tg) return; const r=tg.getBoundingClientRect(); if(!r.width) return;
  tg.style.transformOrigin='0 0'; tg.style.transition='none';
  tg.style.transform=`translate(${z.r.left-r.left}px,${z.r.top-r.top}px) scale(${z.r.width/r.width},${Math.max(.05,z.r.height/r.height)})`; tg.style.opacity='.5'; tg.classList.remove('mo-in');
  tg.getBoundingClientRect();
  requestAnimationFrame(()=>{ tg.style.transition='transform .5s cubic-bezier(.2,.8,.2,1),opacity .35s'; tg.style.transform=''; tg.style.opacity=''; setTimeout(()=>{ tg.style.transition=''; tg.style.transformOrigin=''; },560); });
}
document.addEventListener('click',e=>{ const c=e.target.closest&&e.target.closest('[data-go]'); if(!c) return; const card=c.closest('.uv-card,.kb-card,.pcard,.card,.kpi')||c; const r=card.getBoundingClientRect(); if(r.width>140&&r.height>50) MO.zoom={r,t:performance.now()}; },true);
{ const _r=render; render=function(...x){ const on=moOn(); if(on) moPillSnap(); const res=_r.apply(this,x); if(!on) return res;
  const r=route(); const changed=r!==MO.last; MO.last=r;
  moPillSlide();
  if(changed){ const v=$('#view'); v.classList.remove('mo-run'); void v.offsetWidth; v.classList.add('mo-run'); clearTimeout(MO.tm); MO.tm=setTimeout(()=>v.classList.remove('mo-run'),1800); moStagger(); moCount(); moZoom(); }
  return res; }; }
