addEventListener('keydown',e=>{ if(e.altKey&&e.key.toLowerCase()==='m'){ const aan=!moPref(); try{ localStorage.setItem('rn-motion',aan?'aan':'uit'); }catch(_){} document.documentElement.classList.toggle('os-motion-off',!aan); toast(`Animaties ${aan?'aan':'uit'}`); } });

/* ---------- Ronde 28 · Vangnet: een pagina die faalt, blokkeert nooit meer het menu ---------- */
const GUARD={fails:0};
function guardRepair(){
  // vul ontbrekende onderdelen aan uit verse demodata (opgeslagen data uit oudere versies)
  try{ const fresh=ensureR2(seed()); let n=0;
    for(const k of Object.keys(fresh)){ if(S[k]===undefined||S[k]===null){ S[k]=fresh[k]; n++; }
      else if(Array.isArray(fresh[k])&&!Array.isArray(S[k])){ S[k]=fresh[k]; n++; }
      else if(fresh[k]&&typeof fresh[k]==='object'&&!Array.isArray(fresh[k])&&typeof S[k]==='object'){ for(const j of Object.keys(fresh[k])) if(S[k][j]===undefined){ S[k][j]=fresh[k][j]; n++; } } }
    if(n) save(); return n; }catch(e){ return 0; }
}
{ const _r=render; render=function(...x){
  try{ const res=_r.apply(this,x); GUARD.fails=0; return res; }
  catch(err){
    console.error('[Renovion] pagina faalde:',route(),err);
    if(GUARD.fails++===0&&guardRepair()){ try{ const res=_r.apply(this,x); GUARD.fails=0; return res; }catch(e2){ err=e2; } }
    try{ renderSide(); }catch(e){}
    const v=$('#view'); if(v) v.innerHTML=`<div class="card guard"><div class="guard-i">${ic('alert')}</div><div><h3>Deze pagina kon niet laden</h3>
      <p class="muted">Er ging iets mis bij het tekenen van dit scherm. Het menu blijft gewoon werken; je gegevens zijn veilig op de server.</p>
      <p class="muted guard-tech">${esc(String(err&&err.message||err)).slice(0,160)}</p>
      <div class="guard-b"><button class="btn pri" onclick="location.reload()">Opnieuw laden</button><a class="btn" href="/vandaag">Naar Vandaag</a></div></div></div>`;
    GUARD.fails=0; return null; } }; }
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('[data-act="guard-reset"]'); if(!b) return; e.stopPropagation();
  try{ localStorage.removeItem(STORE_KEY); }catch(_){} const s=ensureR2(seed()); Object.keys(S).forEach(k=>delete S[k]); Object.assign(S,s); save(); render(); toast('Demodata hersteld'); },true);
