const ofTitle2=s=>{ const w=String(s).trim().split(/\s+/); const l=w.pop(); return `${w.length?esc(w.join(' '))+' ':''}<em>${esc(l)}</em>`; };
const of2T=t=>{ const x=OF_TITLE[t]; if(!x) return esc(obName(t)); return x[2]?`${esc(x[0])}<em>${esc(x[1])}</em>`:`${x[0]?esc(x[0])+' ':''}<em>${esc(x[1])}</em>`; };
const ofList=s=>{ const L=String(s||'').split('\n'); let h='', ul=false; for(const l of L){ const m=l.match(/^\s*[•\-–]\s*(.*)$/); if(m){ if(!ul){ h+='<ul class="of-ul">'; ul=true; } h+=`<li>${esc(m[1])}</li>`; } else { if(ul){ h+='</ul>'; ul=false; } if(l.trim()) h+=`<p>${esc(l)}</p>`; } } return h+(ul?'</ul>':''); };
const ofGeldig=p=>addDays(p.offerte.sent||TODAY,30);
