{ const _r=render; render=function(...a){ const res=_r.apply(this,a); if(route().startsWith('offerte-')){ const p=proj(route().slice(8).toUpperCase()); const sel=p&&p.offerte&&obBlocks(p).find(b=>b.id===UI.obSel); const box=document.querySelector('.mb-side .card .lbl'); if(sel&&OF_FIXED.includes(sel.type)&&box){ const c=box.parentElement; c.querySelector('.muted')&&(c.querySelector('.muted').textContent='Vast blok met het beeld van Renovion Groep. Het staat in elke offerte; je kunt het verplaatsen, niet verwijderen.'); } if(sel&&sel.type==='afspraken'){ const ta=$('#ob-txt'); ta&&ta.insertAdjacentHTML('beforebegin','<small class="muted">Eén afspraak per regel: titel | omschrijving | status (Akkoord, In uitwerking of Nog in te dienen).</small>'); } } return res; }; }

/* ---------- Ronde 30 · Offerteblokken bewerken, verschuiven en met Nova aanvullen ---------- */
OB_TYPES.push(['eigen','Eigen blok']);
['voorwaarden','meerwerk'].forEach(t=>{ if(!OB_EDIT.includes(t)&&t==='voorwaarden') OB_EDIT.push(t); });
const OBE_NOTXT=['cover','merk','reviews','samenvatting','begroting','planning','werkzaamheden','termijnen','meerwerk','bijlagen','ondertekening','afbeeldingen'];
