  const pal=document.querySelector('.mb-pal'); if(pal&&!document.querySelector('.obe-new')) pal.insertAdjacentHTML('beforebegin',`<div class="obe-new"><button class="btn sm" data-act="obe-eigen" ${locked?'disabled':''}>${ic('plus')}Eigen blok</button><button class="btn sm pri" data-act="obe-nova-new" ${locked?'disabled':''}>${ic('spark')}Blok met Nova</button></div>`);
