function obeAddAfter(p,nb){ const bl=obBlocks(p); const s=bl.findIndex(b=>b.id===UI.obSel); let at=s>=0?s+1:bl.findIndex(b=>b.type==='ondertekening'); if(at<0) at=bl.length; bl.splice(at,0,nb); UI.obSel=nb.id; }
