/* ---------- Ronde 31e · aanvraag@ met mailbot, klant schiet opdracht in, aanmelding bouw, certificaten, raamovereenkomst, WKA, fotoplicht ---------- */
function ensureR31e(st){ if(!st||st.r31e) return st; st.r31e=1;
  st.mailIn=[{id:'mi1',van:'i.brouwer@bergstraat-demo.nl',naam:'Ilse Brouwer',d:'2026-10-30',t:'08:12',ond:'Nieuwe opdracht: 3 portiekwoningen stucwerk + schilderwerk',body:'Goedemorgen,\n\nGraag zouden wij de volgende opdracht bij jullie neerleggen voor het complex aan de Bergstraat 12-18 in Den Haag:\n- Stucwerk wanden behangklaar, ca. 260 m2\n- Plafonds gladpleisterwerk, ca. 95 m2\n- Schilderwerk kozijnen binnen\n\nDeadline oplevering: 15 december 2026. Sleutels liggen bij de beheerder.\n\nMet vriendelijke groet,\nIlse Brouwer\nWoningstichting Bergstraat',status:'nieuw'},
    {id:'mi2',van:'info@vastgoedkoster-demo.nl',naam:'M. Koster',d:'2026-10-29',t:'16:40',ond:'Aanvraag offerte badkamer huurwoning',body:'Beste,\n\nVoor onze huurwoning aan de Kerkstraat 9 in Arnhem zoeken wij een aannemer voor het vernieuwen van de badkamer. Graag een offerte. Uitvoering liefst in januari.\n\nGroet, M. Koster',status:'nieuw'}];
  for(const p of st.projects||[]) p.bouw=p.bouw||{gpi:false,kantoor:false,klus:false,contact:'',pakket:null};
  const sb=st.subs||[]; if(sb[1]) sb[1].raam=sb[1].raam||{start:'2026-05-25',eind:'2026-11-25'}; if(sb[0]) sb[0].raam=sb[0].raam||{start:'2026-09-01',eind:'2027-03-01'};
  const r=(st.rfqs||[]).find(x=>x.status==='gegund'); if(r&&!(st.inkoop||[]).some(i=>i.oa)){ const s=sb.find(x=>x.id===r.awardedTo); st.inkoop=st.inkoop||[]; st.inkoop.push({nr:'INK-24871',lev:s?s.naam:'Partner',pid:r.pid,po:r.orderNr,datum:'2026-10-29',verval:'2026-11-28',bedrag:Math.round((r.bids.find(b=>b.sub===r.awardedTo)||{prijs:2400}).prijs*0.4*100)/100,status:'ontvangen',oa:true}); }
  return st; }
/* demomigratie overgeslagen: de structuur staat in de fabrieksstaat */ { const _s=ensureR2; ensureR2=function(st){ return ensureR31e(_s(st)); }; }
/* ---- mailbot ---- */
function mbParse(m){ const b=m.body; const dl=(b.match(/deadline[^:]*:\s*([^\n.]+)/i)||b.match(/(liefst in [a-z]+|uiterlijk [^\n.]+)/i)||[])[1]||''; const adr=(b.match(/aan de ([A-Z][^\n,]+?\d+[a-z0-9-]*)(?: in ([A-Z][a-z]+(?: [A-Z][a-z]+)*))?/)||[]); const regels=b.split('\n').filter(l=>/^\s*[-•]/.test(l)).map(l=>l.replace(/^\s*[-•]\s*/,''));
  const dom=(m.van.split('@')[1]||'').toLowerCase(); const c=S.clients.find(x=>(x.mail||'').toLowerCase().endsWith('@'+dom))||S.clients.find(x=>m.body.includes(x.naam));
  return {dl,adres:adr[1]||'',plaats:adr[2]||'',regels:regels.length?regels:[m.ond.replace(/^.*?:\s*/,'')],client:c}; }
function vAanvraagmail(){ const L=S.mailIn.slice().sort((a,b)=>(a.status==='nieuw'?0:1)-(b.status==='nieuw'?0:1)||(a.d<b.d?1:-1));
  return `<div class="page"><div class="ph"><div><h1>aanvraag<em>@renoviongroep.nl</em></h1><p>Centrale mailbox. Nova leest elke mail, haalt werk, adres en deadline eruit en vraagt aan welke klant hij hoort. Bestaande klanten gaan direct door naar de offerte (Rob/Don).</p></div><button class="btn" data-act="mb-portal">${ic('home')}Klantportaal: opdracht inschieten</button></div>
  <div class="mb-list">${L.map(m=>{ const r=mbParse(m); const c=m.cid?client(m.cid):r.client; return `<div class="card mb-mail ${m.status}"><div class="mb-top"><div class="row" style="gap:10px">${avatar(m.naam,'sm')}<div><b>${esc(m.ond)}</b><small>${esc(m.naam)} &lt;${esc(m.van)}&gt; · ${fmtD(m.d)} ${esc(m.t||'')}${m.bron==='portaal'?' · via klantportaal':''}</small></div></div><span class="pill ${m.status==='nieuw'?'or':m.status==='gekoppeld'?'blue':'ok'}">${({nieuw:'Nieuw',gekoppeld:'Gekoppeld',uitgezet:'Uitgezet'})[m.status]}</span></div>
    <details class="mb-body"><summary>Mail lezen</summary><pre>${esc(m.body)}</pre></details>
    <div class="mb-bot"><span class="novaav sm">${ic('spark')}</span><div class="grow"><b>Nova heeft gelezen</b><div class="mb-kv"><span>Werk</span><div>${r.regels.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>${r.adres?`<span>Adres</span><div>${esc(r.adres)}${r.plaats?', '+esc(r.plaats):''}</div>`:''}${r.dl?`<span>Deadline</span><div>${esc(r.dl)}</div>`:''}<span>Klant</span><div>${c?`<b>${esc(c.naam)}</b> <span class="pill ${segOf(c)==='zakelijk'?'blue':'mut'}">${segOf(c)==='zakelijk'?'Zakelijk':'Particulier'}</span> <span class="code">${esc(c.nr||'')}</span>`:'<span class="dn">Geen bekende klant gevonden</span>'}</div></div></div></div>
    <div class="mb-acts">${m.status==='nieuw'?`${c?`<button class="btn pri sm" data-act="mb-link" data-id="${m.id}" data-c="${c.id}">${ic('check')}Koppelen aan ${esc(c.naam)}</button>`:''}<select class="in sm" data-mbsel="${m.id}" aria-label="Andere klant"><option value="">${c?'Andere klant…':'Kies klant…'}</option>${S.clients.map(x=>`<option value="${x.id}">${esc(x.naam)}</option>`).join('')}</select><button class="btn sm" data-act="mb-new" data-id="${m.id}">${ic('plus')}Nieuwe klant</button>`:m.status==='gekoppeld'?`<button class="btn pri sm" data-act="mb-out" data-id="${m.id}">${ic('send')}Opdracht uitzetten in de flow</button>`:`<a class="btn sm" href="/project-${(m.pid||'').toLowerCase()}">Naar ${esc(m.pid)}</a>`}</div></div>`; }).join('')}</div></div>`; }
Object.assign(R2_ROUTES,{aanvraagmail:()=>vAanvraagmail()});
{ const s=SECTIONS.find(x=>x.r&&x.r.some(r=>r[0]==='sales')); if(s&&!s.r.some(r=>r[0]==='aanvraagmail')) s.r.splice(1,0,['aanvraagmail','Aanvraagmail']); }
for(const rol in PERM){ const a=PERM[rol]; if(Array.isArray(a)&&a.includes('sales')&&!a.includes('aanvraagmail')) a.push('aanvraagmail'); }
{ const _a=attention; attention=function(){ const it=_a(); const n=(S.mailIn||[]).filter(m=>m.status==='nieuw').length; if(n) it.unshift({k:'or',icon:'mail',t:`${n} nieuwe ${n===1?'mail':'mails'} op aanvraag@`,s:'Nova heeft ze gelezen en stelt een klant voor.',btn:'Bekijken',go:'aanvraagmail'}); return it; }; }
function mbOut(m){ const r=mbParse(m); const c=client(m.cid); const bestaand=S.projects.some(p=>p.clientId===c.id); const id=newPD();
  const p={id,naam:(m.ond.replace(/^.*?:\s*/,'')||'Nieuwe opdracht').slice(0,40),clientId:c.id,adres:r.adres||'',plaats:r.plaats||c.plaats||'',type:'Opdracht',phase:bestaand?2:0,waarde:0,leider:osPL(),progress:0,planned:0,kleur:S.projects.length%6,begroting:null,offerte:null,kosten:0,start:null,eind:null,termijnen:[{oms:'Bij opdracht',pct:40},{oms:'Bij start uitvoering',pct:40},{oms:'Bij oplevering',pct:20}],docs:[],activity:[],intake:{wensen:r.regels.join('; '),startWens:r.dl||''},bron:'aanvraag@',deadline:r.dl,uren:[],regieMat:[],mw:[],contract:'aangenomen',regieTarief:55,bouw:{gpi:false,kantoor:false,klus:false,contact:'',pakket:null}};
  S.projects.unshift(p); m.status='uitgezet'; m.pid=id;
  S.tasks.push({id:uid('t'),titel:`Offerte maken: ${p.naam}`,pid:id,eig:osCalc(),dl:addDays(TODAY,2),status:'todo',prio:'hoog',oms:`${bestaand?'Bestaande klant: productieflow, direct naar calculatie.':'Nieuwe klant: eerst intake.'} Rob/Don maken de offerte. Werk: ${r.regels.join(', ')}${r.dl?' · deadline '+r.dl:''}`,checklist:[]});
  addActivity(p,`Aangemaakt uit aanvraag@ (${m.naam}), ${bestaand?'bestaande klant: direct naar calculatie':'nieuwe klant'}`,'blue'); return p; }
document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act; if(!/^mb-(link|new|out|portal|portal-go)$/.test(a)) return; /* prototype ving hier ook alle knoppen van de Mailbuilder af */ e.stopPropagation(); e.preventDefault(); const m=S.mailIn.find(x=>x.id===el.dataset.id);
  if(a==='mb-link'){ m.cid=el.dataset.c; m.status='gekoppeld'; commit(`Mail gekoppeld aan ${client(m.cid).naam}`); }
  if(a==='mb-new'){ const id='c'+(S.clients.length+1)+'x'; S.clients.push({id,naam:m.naam,soort:'Particulier',contact:m.naam,tel:'',mail:m.van,plaats:'',nr:'K-'+(1001+S.clients.length),betaal:14,herinnering:true,token:Math.random().toString(36).slice(2,10)}); m.cid=id; m.status='gekoppeld'; commit(`Nieuwe klant ${m.naam} aangemaakt en gekoppeld`); }
  if(a==='mb-out'){ const p=mbOut(m); commit(`${p.id} aangemaakt en uitgezet. Taak "Offerte maken" staat bij Rob.`); }
  if(a==='mb-portal'){ const zk=S.clients.filter(c=>segOf(c)==='zakelijk'); modal('Klantportaal · opdracht inschieten',`<div class="alert info">${ic('home')}<div class="grow">Zo ziet een zakelijke opdrachtgever het via zijn persoonlijke link. De opdracht komt binnen in aanvraag@ en wordt herkend aan het klantnummer.</div></div><form class="fg" data-form="mbp"><div class="f"><label for="mbp-c">Klantnummer</label><select class="in" id="mbp-c">${zk.map(c=>`<option value="${c.id}">${esc(c.nr)} · ${esc(c.naam)}</option>`).join('')}</select></div><div class="f"><label for="mbp-dl">Datum of deadline</label><input class="in" type="date" id="mbp-dl" value="${addDays(TODAY,30)}"></div><div class="f full"><label for="mbp-a">Uitvoeradres</label><input class="in" id="mbp-a" placeholder="Straat en huisnummer, plaats"></div><div class="f full"><label for="mbp-w">Werkzaamheden (één per regel)</label><textarea class="in" id="mbp-w" rows="4" placeholder="Stucwerk wanden behangklaar ca. 120 m2&#10;Plafond gladpleisterwerk"></textarea></div><div class="f full"><label for="mbp-o">Opmerking</label><input class="in" id="mbp-o" placeholder="Bijv. sleutel bij beheerder"></div></form>`,`<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="mb-portal-go">${ic('send')}Opdracht inschieten</button>`); }
  if(a==='mb-portal-go'){ const c=client($('#mbp-c').value); const w=$('#mbp-w').value.split('\n').map(x=>x.trim()).filter(Boolean); if(!w.length) return toast('Vul minstens één werkzaamheid in.','warn'); const adr=$('#mbp-a').value.trim(); const dl=$('#mbp-dl').value;
    S.mailIn.push({id:uid('mi'),van:c.mail||'portaal',naam:c.contact||c.naam,d:TODAY,t:'nu',ond:`Opdracht via klantportaal (${c.nr})`,body:`Opdracht via persoonlijke link.\n\nUitvoerwerk:\n${w.map(x=>'- '+x).join('\n')}\n\n${adr?'Adres: aan de '+adr+'\n':''}Deadline: ${fmtDY(dl)}\n${$('#mbp-o').value}`,status:'gekoppeld',cid:c.id,bron:'portaal'}); closeModal(); UI.mbFrom='portaal'; go('aanvraagmail'); commit('Opdracht ontvangen en herkend aan het klantnummer.'); }
},true);
document.addEventListener('change',e=>{ const t=e.target; if(!t.dataset||!t.dataset.mbsel||!t.value) return; const m=S.mailIn.find(x=>x.id===t.dataset.mbsel); m.cid=t.value; m.status='gekoppeld'; commit(`Mail gekoppeld aan ${client(m.cid).naam}`); },true);
/* ---- aanmelding bouw + overeenkomsten per project ---- */
PD_TABS.splice(PD_TABS.findIndex(t=>t[0]==='documenten'),0,['bouw','Aanmelding & overeenkomsten']);
function bouwTab(p){ const b=p.bouw; const c=client(p.clientId); const gun=S.rfqs.filter(r=>r.pid===p.id&&r.awardedTo); p.ovk=p.ovk||{};
  const docs=[...(p.docs||[]).map(d=>d.naam),'V&G-plan '+p.id+'.pdf','Planning '+p.id+'.pdf','Contactlijst bouwplaats.pdf','Algemene voorwaarden Renovion 2026.pdf'];
  const step=(k,t,s)=>`<label class="bw-step ${b[k]?'on':''}"><input type="checkbox" data-bw="${k}" data-pid="${p.id}" ${b[k]?'checked':''}><span>${ic(b[k]?'check':'clock')}</span><div><b>${t}</b><small>${s}</small></div></label>`;
  return `<div class="grid g2"><div class="card"><div class="card-h"><h3>Aanmelding <em>bouw</em></h3><span class="pill ${b.gpi&&b.kantoor&&b.klus?'ok':'warn'}">${[b.gpi,b.kantoor,b.klus].filter(Boolean).length}/3</span></div><div class="card-b stack">
    ${step('gpi','GPI Grootwerk: vooraanmelding','Project vooraf aangemeld bij GPI Grootwerk')}${step('kantoor','Kantoor aangemeld','Kantoor heeft de aanmelding verwerkt en bevestigd')}${step('klus','Aanmelden op de klus','Ploeg meldt zich op de eerste dag aan bij de uitvoerder/opdrachtgever')}
    <div class="f"><label for="bw-c">Contactpersoon voor het mailpakket</label><input class="in" id="bw-c" data-bwc="${p.id}" value="${esc(b.contact||c.contact||'')}" placeholder="Naam en e-mail"></div>
    <div><span class="lbl">Mailpakket met alle documentatie</span>${docs.map(d=>`<div class="docrow">${ic('file')}${esc(d)}</div>`).join('')}</div>
    ${b.pakket?`<div class="alert ok" style="margin:0">${ic('check')}<div class="grow">Mailpakket klaargezet voor ${esc(b.pakket.aan)} op ${fmtDY(b.pakket.d)} (in de outbox).</div></div>`:''}<button class="btn pri sm" data-act="bw-mail" data-pid="${p.id}" style="justify-self:start">${ic('send')}Mailpakket versturen</button></div></div>
  <div class="card"><div class="card-h"><h3>Overeenkomst <em>per project</em></h3></div><div class="card-b stack"><small class="muted">Bij iedere klus wordt het werk opnieuw aangeboden en per project een overeenkomst vastgelegd, zodat dit bij een audit te verklaren is.</small>
    ${gun.length?gun.map(r=>{ const s=sub(r.awardedTo); const o=p.ovk[r.id]; return `<div class="li"><span class="ic ${o?'ok':'warn'}">${ic(o?'check':'file')}</span><div class="tx"><b>${esc(s.naam)} · ${esc(r.titel)}</b><small>${r.orderNr} · ${eur(awardPrice(r))}${o?` · vastgelegd ${fmtD(o.d)}`:' · nog vast te leggen'}${s.raam?` · raamovereenkomst t/m ${fmtD(s.raam.eind)}`:''}</small></div>${o?'':`<button class="btn xs" data-act="bw-ovk" data-pid="${p.id}" data-r="${r.id}">Vastleggen</button>`}</div>`; }).join(''):'<div class="empty">Nog geen gegunde onderaannemers op dit project.</div>'}
    <div class="alert info" style="margin:0">${ic('mail')}<div class="grow">WKA-gegevens en het WKA-protocol lopen via <b>WKA@renoviongroep.nl</b>.</div></div></div></div></div>`; }
{ const _t=pdTab; pdTab=function(p,tab){ if(tab==='bouw'){ p.bouw=p.bouw||{}; return bouwTab(p); } return _t(p,tab); }; }
document.addEventListener('change',e=>{ const t=e.target; if(!t.dataset) return; if(t.dataset.bw){ const p=proj(t.dataset.pid); p.bouw[t.dataset.bw]=t.checked; if(t.checked) addActivity(p,`Aanmelding bouw: ${({gpi:'GPI vooraanmelding',kantoor:'kantoor aangemeld',klus:'aangemeld op de klus'})[t.dataset.bw]}`,'ok'); commit(); } if(t.dataset.bwc){ const p=proj(t.dataset.bwc); p.bouw.contact=t.value; commit(); } },true);
document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act]'); if(!el) return; const a=el.dataset.act; if(!/^bw-/.test(a)) return; e.stopPropagation(); const p=proj(el.dataset.pid);
  if(a==='bw-mail'){ const aan=p.bouw.contact||client(p.clientId).contact||'contactpersoon'; S.outbox.push({d:TODAY,aan,onderwerp:`Documentatie bouw ${p.id} · ${p.naam} (mailpakket)`}); p.bouw.pakket={aan,d:TODAY}; addActivity(p,`Mailpakket documentatie klaargezet voor ${aan}`,'blue'); commit('Mailpakket in de outbox gezet (niet echt verstuurd).'); }
  if(a==='bw-ovk'){ const r=pa(el.dataset.r); p.ovk=p.ovk||{}; p.ovk[r.id]={d:TODAY}; const s=sub(r.awardedTo); s.log=s.log||[]; s.log.unshift({d:TODAY,t:`Overeenkomst vastgelegd voor ${p.id} · ${r.titel}`,pid:p.id}); addActivity(p,`Overeenkomst ${s.naam} vastgelegd (${r.orderNr})`,'ok'); commit('Overeenkomst vastgelegd en in het partnerdossier gezet.'); }
},true);
