  const pers=b.txt==null&&wens?`<p class="of-pers">Wat u ons vertelde, is bij ons blijven hangen: <em>${esc(wens)}</em>. Precies daar hebben we deze offerte omheen gebouwd. ${esc(nm)} begeleidt uw project van begin tot eind, dus u heeft één vast gezicht en één telefoonnummer.</p>`:'';
  h=h.replace(/<p class="of-groet">[\s\S]*?<\/p>/,pers+`<p class="of-groet">Met hartelijke groet,</p>`+ofSignature(p));
