function showAccounts(list,title){
  modal(title||(list.length===1?'Account aangemaakt':'Accounts aangemaakt'),`<p style="margin:0">Geef ${list.length===1?'dit wachtwoord':'deze wachtwoorden'} persoonlijk door. Het staat nergens anders en verschijnt maar één keer; daarna kun je in Teambeheer een nieuw wachtwoord maken.</p>${list.map(a=>{ const msg=`Hoi ${String(a.naam).split(' ')[0]}, je account voor Renovion OS staat klaar. Log in op ${location.origin}/inloggen met ${a.mail} en wachtwoord ${a.wachtwoord}`; const tel=(osPeople().concat(S.subs||[]).find(x=>String(x.mail||'').toLowerCase()===String(a.mail).toLowerCase())||{}).tel||''; return `<div class="stack" style="gap:6px"><div><b>${esc(a.naam)}</b><div class="muted" style="font-size:12.5px">Inloggen op ${esc(location.host)} met ${esc(a.mail)}</div></div><div class="pw-box"><code>${esc(a.wachtwoord)}</code><button class="btn xs" data-act="pw-copy" data-pw="${esc(a.wachtwoord)}">${ic('clip')}Kopiëren</button></div><div class="row" style="gap:6px;flex-wrap:wrap"><a class="btn sm" href="mailto:${esc(a.mail)}?subject=${encodeURIComponent('Je account voor Renovion OS')}&body=${encodeURIComponent(msg)}">${ic('mail')}Per mail sturen</a><a class="btn sm" target="_blank" rel="noopener" href="https://wa.me/${tel.replace(/D/g,'').replace(/^0/,'31')}?text=${encodeURIComponent(msg)}">${ic('chat')}Via WhatsApp</a></div></div>`; }).join('')}`,'<button class="btn pri" data-act="mclose">Ik heb het genoteerd</button>');
}
document.addEventListener('click',e=>{ const el=e.target.closest&&e.target.closest('[data-act="pw-copy"],[data-act="u-pw"],[data-act="os-motion"]'); if(!el) return; e.preventDefault(); e.stopPropagation();
  if(el.dataset.act==='os-motion'){ closeMenus(); const aan=!moPref(); try{ localStorage.setItem('rn-motion',aan?'aan':'uit'); }catch(_){} document.documentElement.classList.toggle('os-motion-off',!aan); toast(`Animaties ${aan?'aan':'uit'}`); return; }
  if(el.dataset.act==='pw-copy'){ try{ navigator.clipboard.writeText(el.dataset.pw); toast('Wachtwoord gekopieerd'); }catch(err){ toast('Kopiëren lukt niet; selecteer het wachtwoord en kopieer het zelf.','warn'); } return; }
  const id=el.dataset.id; const u=emp(id)||S.extraUsers.find(x=>x.id===id); if(!u) return;
  mConfirm('Nieuw wachtwoord',`${esc(u.naam)} krijgt een nieuw wachtwoord. Het oude werkt daarna niet meer.`,'Nieuw wachtwoord maken',async()=>{ await OSB.flush(); try{ const r=await OSB.api(OSB.urls.password.replace('__ID__',encodeURIComponent(id)),{method:'POST',body:{}}); showAccounts([r],'Nieuw wachtwoord'); }catch(err){ toast(err.message||'Dat lukte niet.','warn'); } });
},true);
OSB.hooks.idle=()=>{ if(document.querySelector('#layer .modal-bg, #call, #popmenu, .sheet.open')) return false; const a=document.activeElement; if(a&&a!==document.body&&a.matches&&a.matches('input,textarea,select,[contenteditable="true"]')&&!(a.id&&a.closest('#view'))) return false; return true; };
OSB.hooks.remote=()=>{ const a=document.activeElement; const keep=a&&a.id&&a.matches&&a.matches('input,textarea')?{id:a.id,v:a.value,s:a.selectionStart,e:a.selectionEnd}:null; const y=window.scrollY; render(); if(window.scrollY!==y) window.scrollTo(0,y); if(keep){ const n=document.getElementById(keep.id); if(n&&n!==document.activeElement){ n.value=keep.v; n.focus(); try{ n.setSelectionRange(keep.s,keep.e); }catch(err){} } } };
