document.addEventListener('change',e=>{ if(e.target&&e.target.id==='paperfile') UI._paperFile=e.target.files&&e.target.files[0]; UI._paperAi=null; },true);
paperForm=function(name,src){ const p=S.projects.find(x=>x.phase===6)||S.projects[0]; const c=p?client(p.clientId):{};
  $('#paperprev').innerHTML=`<div class="extract" id="pp-status">${OSB.ai?'<span class="nv-typing" style="display:inline-flex;vertical-align:middle"><i></i><i></i><i></i></span> <b>Nova leest '+esc(name)+'</b>, even geduld':'<b>'+esc(name)+'</b>: vul de velden in vanaf het papier'}</div>${src?`<img src="${src}" alt="" style="max-height:160px;border-radius:10px;border:1px solid var(--border)">`:''}
  <form class="fg" data-form="paper"><div class="f full"><label for="pp-titel">Werkzaamheden</label><input class="in" id="pp-titel" name="titel" required></div>
  <div class="f"><label for="pp-pid">Projectdossier</label><select class="in" id="pp-pid" name="pid">${S.projects.length?projOpts(p.id,false):'<option value="">Nog geen projecten</option>'}</select></div><div class="f"><label for="pp-emp">Vakman</label><select class="in" id="pp-emp" name="emp">${empOpts(osField(),e=>e.type!=='kantoor')}</select></div>
  <div class="f"><label for="pp-d">Datum</label><input class="in" type="date" id="pp-d" name="datum" value="${TODAY}"></div><div class="f"><label for="pp-u">Gewerkte uren</label><input class="in" type="number" step="0.5" id="pp-u" name="uren"></div>
  <div class="f full"><label for="pp-opm">Opmerkingen</label><textarea class="in" id="pp-opm" name="opm"></textarea></div>
  <div class="f full"><label for="pp-sig">Afgetekend door</label><input class="in" id="pp-sig" name="getekend" value="${esc(c.contact||'')}"></div><div class="f full" id="pp-matbox" hidden><label>Materialen</label><div id="pp-mat" class="muted" style="font-size:13px"></div></div></form>`;
  document.querySelector('#layer .mf').innerHTML='<button class="btn" data-act="mclose">Annuleren</button><button class="btn pri" data-act="submit">Werkbon aanmaken (ter controle)</button>';
  if(OSB.ai&&UI._paperFile) osReadPaper(UI._paperFile);
};
async function osReadPaper(file){ const st=()=>document.getElementById('pp-status');
  try{ let type=file.type||'image/jpeg', data='';
    if(type==='application/pdf'){ data=await new Promise((ok,no)=>{ const r=new FileReader(); r.onload=()=>ok(String(r.result).split(',')[1]); r.onerror=no; r.readAsDataURL(file); }); }
    else { data=await new Promise((ok,no)=>{ const r=new FileReader(); r.onload=()=>{ const img=new Image(); img.onload=()=>{ const s=Math.min(1,1600/Math.max(img.width,img.height)); const cv=document.createElement('canvas'); cv.width=Math.round(img.width*s); cv.height=Math.round(img.height*s); cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height); ok(cv.toDataURL('image/jpeg',.85).split(',')[1]); }; img.onerror=no; img.src=r.result; }; r.onerror=no; r.readAsDataURL(file); }); type='image/jpeg'; }
    const res=await OSB.api(OSB.urls.workOrderRead,{method:'POST',body:{type,data}});
    if(!document.querySelector('[data-form="paper"]')) return;
    const set=(id,v)=>{ const el=document.getElementById(id); if(el&&v!=null&&v!=='') el.value=v; };
    set('pp-titel',res.titel); set('pp-pid',res.project_id); set('pp-emp',res.medewerker_id); set('pp-d',res.datum); set('pp-u',res.uren); set('pp-opm',res.opmerkingen);
    if(res.getekend===false) set('pp-sig','');
    UI._paperAi={materialen:(res.materialen||[]).map(m=>({t:m.omschrijving,q:+m.aantal||0,u:m.eenheid||''}))};
    if(UI._paperAi.materialen.length){ document.getElementById('pp-matbox').hidden=false; document.getElementById('pp-mat').innerHTML=UI._paperAi.materialen.map(m=>esc(`${NUM.format(m.q)} ${m.u} ${m.t}`)).join('<br>'); }
    if(st()) st().innerHTML='<b>Door Nova uitgelezen.</b> Controleer alle velden voordat je opslaat.'+(res.twijfel?'<br><span style="color:var(--warn)">Let op: '+esc(res.twijfel)+'</span>':'')+(!res.project_id?'<br>Het project stond er niet duidelijk op: kies het zelf.':'');
  }catch(err){ if(st()) st().innerHTML='<b>Uitlezen lukte niet.</b> '+esc(err.message||'')+' Vul de velden zelf in.'; } }
{ const _pp=R2_FORMS.paper; R2_FORMS.paper=(f,v)=>{ const n=S.werkbonnen.length; const r=_pp(f,v); const w=S.werkbonnen[S.werkbonnen.length-1];
  if(S.werkbonnen.length>n&&w){ if(UI._paperAi&&UI._paperAi.materialen.length) w.materialen=UI._paperAi.materialen; (w.log||[]).forEach(l=>{ l.t=String(l.t).replace(/, gesimuleerde uitlezing gecontroleerd/,UI._paperAi?', uitgelezen door Nova en gecontroleerd':', handmatig ingevoerd'); }); UI._paperAi=null; UI._paperFile=null; save(); }
  return r; }; }
/* ---------- Offertebuilder: Nova schrijft met Claude. Draait vóór de oude regelgebaseerde afhandeling (window, capture). ---------- */
function osOfferWrite(p,modus,opdracht,tekst,blok){ return OSB.api(OSB.urls.offerWrite,{method:'POST',body:{project:p.id,modus,opdracht,tekst,blok}}); }
const OS_WRITING='<div class="prop"><div class="ph2">'+ic('spark')+'Nova schrijft…</div><div class="pb"><span class="sk sk-line w70"></span><span class="sk sk-line w60" style="margin-top:8px"></span><span class="sk sk-line w40" style="margin-top:8px"></span></div></div>';
window.addEventListener('click',e=>{ if(!OSB.ai) return; const el=e.target.closest&&e.target.closest('[data-act="obe-ai"],[data-act="obe-pi"],[data-act="obe-nq-go"]'); if(!el) return; const p=obeP(); if(!p) return; e.stopPropagation(); e.preventDefault(); const a=el.dataset.act;
  if(a==='obe-nq-go'){ const q=($('#obe-nq')||{}).value||''; if(!q.trim()) return toast('Beschrijf kort waar het blok over gaat.','warn'); const label=el.innerHTML; el.disabled=true; el.innerHTML=ic('spark')+'Nova schrijft…';
    osOfferWrite(p,'nieuw',q,'','nieuw blok').then(r=>{ closeModal(); obeAddAfter(p,{id:uid('ob'),type:'eigen',title:r.title,txt:r.txt,nova:1}); commit(`Nova heeft het blok “${r.title}” toegevoegd. Controleer de tekst.`); obeScroll(); })
      .catch(err=>{ el.disabled=false; el.innerHTML=label; toast(err.message||'Nova kon nu niet schrijven.','warn'); }); return; }
  const pi=a==='obe-pi'; const b=pi?obBlocks(p).find(x=>x.id===UI.obePop):obeSel(p); if(!b) return; const box=pi?el.closest('.obe-pop'):document;
  const m=el.dataset.m; const q=((pi?box.querySelector('#obe-pi-q'):$('#obe-ai'))||{}).value||''; if(m==='toevoegen'&&!q.trim()) return toast('Typ eerst wat Nova moet toevoegen of veranderen.','warn');
  const target=OBE_NOTXT.includes(b.type)?'note':'txt'; const cur=target==='note'?(b.note||''):(b.txt!=null?b.txt:obText(p,b)); const out=pi?box.querySelector('.obe-pi-prop'):$('#obe-prop'); if(!out) return;
  out.innerHTML=OS_WRITING;
  osOfferWrite(p,m==='toevoegen'?'add':m,q,cur,obName(b.type)).then(r=>{ UI._obeProp={id:b.id,target,txt:r.txt};
    out.innerHTML=`<div class="prop"><div class="ph2">${ic('spark')}Voorstel</div><div class="pb"><div><span class="k">Begrepen</span><div>${esc(r.what)}${target==='note'?' (in de inleidende tekst)':''}</div></div><div><span class="k">Nieuwe tekst</span><div style="white-space:pre-wrap;max-height:200px;overflow:auto">${esc(r.txt)}</div></div></div><div class="pf"><button class="btn pri sm" data-act="${pi?'obe-pi-ok':'obe-ok'}">Toepassen</button><button class="btn sm ghost" data-act="${pi?'obe-pi-no':'obe-x'}">Niet nu</button></div></div>`; })
    .catch(err=>{ out.innerHTML='<div class="prop"><div class="pb"><span class="nv-err">'+esc(err.message||'Nova kon nu niet schrijven.')+'</span></div></div>'; });
},true);
